class SecurityLevel(Enum):
    """Security validation levels."""
    LOW = "low"              # Basic checks only
    MEDIUM = "medium"        # Standard validation
    HIGH = "high"           # Comprehensive security
    PARANOID = "paranoid"   # Maximum security


class ThreatLevel(Enum):
    """Threat severity levels."""
    NONE = "none"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class ViolationType(Enum):
    """Types of security violations."""
    MALWARE = "malware"
    VIRUS = "virus"
    SUSPICIOUS_CONTENT = "suspicious_content"
    PII_EXPOSURE = "pii_exposure"
    COPYRIGHT_VIOLATION = "copyright_violation"
    INAPPROPRIATE_CONTENT = "inappropriate_content"
    DATA_LEAK = "data_leak"
    PRIVACY_VIOLATION = "privacy_violation"
    COMPLIANCE_VIOLATION = "compliance_violation"
    UNAUTHORIZED_ACCESS = "unauthorized_access"
    SUSPICIOUS_METADATA = "suspicious_metadata"
    SECURITY_RISK = "security_risk"


class ComplianceStandard(Enum):
    """Compliance standards to validate against."""
    GDPR = "gdpr"           # General Data Protection Regulation
    CCPA = "ccpa"           # California Consumer Privacy Act
    HIPAA = "hipaa"         # Health Insurance Portability and Accountability Act
    COPPA = "coppa"         # Children's Online Privacy Protection Act
    SOX = "sox"             # Sarbanes-Oxley Act
    DMCA = "dmca"           # Digital Millennium Copyright Act
    ISO27001 = "iso27001"   # ISO 27001 Information Security
    NIST = "nist"           # NIST Cybersecurity Framework


@dataclass
class SecurityViolation:
    """Security violation details."""
    violation_type: ViolationType
    threat_level: ThreatLevel
    description: str
    location: Optional[str] = None
    evidence: Optional[Dict[str, Any]] = None
    remediation: Optional[str] = None
    compliance_impact: List[ComplianceStandard] = field(default_factory=list)
    timestamp: datetime = field(default_factory=lambda: datetime.now(timezone.utc))


@dataclass
class SecurityScanResult:
    """Results of security scanning."""
    file_path: str
    security_level: SecurityLevel
    is_safe: bool
    threat_level: ThreatLevel
    violations: List[SecurityViolation] = field(default_factory=list)
    scan_duration: float = 0.0
    scan_timestamp: datetime = field(default_factory=lambda: datetime.now(timezone.utc))
    file_hash: str = ""
    file_size: int = 0
    media_type: MediaType = MediaType.UNKNOWN
    
    # Detailed results
    malware_scan_result: Optional[Dict[str, Any]] = None
    content_scan_result: Optional[Dict[str, Any]] = None
    privacy_scan_result: Optional[Dict[str, Any]] = None
    compliance_scan_result: Optional[Dict[str, Any]] = None
    metadata_scan_result: Optional[Dict[str, Any]] = None
    
    # Recommendations
    recommendations: List[str] = field(default_factory=list)
    required_actions: List[str] = field(default_factory=list)


@dataclass
class ValidationConfig:
    """Security validation configuration."""
    security_level: SecurityLevel = SecurityLevel.MEDIUM
    enable_malware_scanning: bool = True
    enable_content_scanning: bool = True
    enable_privacy_scanning: bool = True
    enable_compliance_checking: bool = True
    enable_metadata_scanning: bool = True
    
    # File size limits (bytes)
    max_file_size: int = 100 * 1024 * 1024  # 100MB
    
    # Allowed file types
    allowed_extensions: Set[str] = field(default_factory=lambda: {
        'mp3', 'wav', 'flac', 'aac', 'm4a',  # Audio
        'mp4', 'avi', 'mov', 'wmv', 'mkv',   # Video
        'jpg', 'jpeg', 'png', 'gif', 'bmp',  # Images
        'txt', 'md', 'pdf', 'docx'           # Documents
    })
    
    # Compliance standards to check
    compliance_standards: Set[ComplianceStandard] = field(default_factory=lambda: {
        ComplianceStandard.GDPR,
        ComplianceStandard.DMCA
    })
    
    # Custom validation rules
    custom_rules: List[Dict[str, Any]] = field(default_factory=list)


class SecurityValidator:
    """Comprehensive security validation engine."""
    
    def __init__(self, config: Optional[ValidationConfig] = None):
        """Initialize the security validator."""
        self.config = config or ValidationConfig()
        
        # Initialize security components
        self.malware_scanner = MalwareScanner()
        self.content_scanner = ContentScanner()
        self.privacy_scanner = PrivacyScanner()
        self.compliance_checker = ComplianceChecker()
        self.metadata_scanner = MetadataScanner()
        
        # Load security patterns and rules
        self._load_security_patterns()
        self._load_threat_intelligence()
        
        # Initialize encryption if available
        if CRYPTO_AVAILABLE:
            self._init_encryption()
        
        logger.info(f"Security validator initialized with {self.config.security_level.value} level")
    
    def _load_security_patterns(self):
        """Load security patterns for threat detection."""
        self.security_patterns = {
            'suspicious_urls': [
                re.compile(r'https?://(?:bit\.ly|tinyurl|t\.co|goo\.gl|ow\.ly|is\.gd|buff\.ly)/', re.IGNORECASE),
                re.compile(r'https?://[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}', re.IGNORECASE),
                re.compile(r'(?:malware|virus|trojan|backdoor|rootkit)', re.IGNORECASE)
            ],
            'suspicious_content': [
                re.compile(r'(?:password|passwd|pwd)\s*[:=]\s*\S+', re.IGNORECASE),
                re.compile(r'(?:api_key|apikey|api-key)\s*[:=]\s*\S+', re.IGNORECASE),
                re.compile(r'(?:secret|token|auth)\s*[:=]\s*\S+', re.IGNORECASE),
                re.compile(r'BEGIN\s+(?:RSA\s+)?PRIVATE\s+KEY', re.IGNORECASE)
            ],
            'pii_patterns': [
                re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'),  # Email
                re.compile(r'\b\d{3}-?\d{2}-?\d{4}\b'),                                  # SSN
                re.compile(r'\b(?:\d{4}[-\s]?){3}\d{4}\b'),                            # Credit card
                re.compile(r'\b(?:\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}\b')  # Phone
            ]
        }
    
    def _load_threat_intelligence(self):
        """Load threat intelligence data."""
        # This would typically load from external threat intelligence feeds
        self.threat_intelligence = {
            'known_malware_hashes': set(),
            'suspicious_domains': set(),
            'blacklisted_ips': set(),
            'malicious_patterns': []
        }
    
    def _init_encryption(self):
        """Initialize encryption capabilities."""



        try:
            # Generate a key for session encryption
            password = os.environ.get('SECURITY_KEY', 'default-key').encode()
            salt = os.urandom(16)
            kdf = PBKDF2HMAC(
                algorithm=hashes.SHA256(),
                length=32,
                salt=salt,
                iterations=100000,
            )
            key = base64.urlsafe_b64encode(kdf.derive(password))
            self.fernet = Fernet(key)
            self.encryption_available = True
        except Exception as e:
            logger.warning(f"Encryption initialization failed: {e}")
            self.encryption_available = False
    
    async def validate_file(self, file_path: str, user_context: Optional[Dict[str, Any]] = None) -> SecurityScanResult:
        """
        Perform comprehensive security validation on a file.
        
        Args:
            file_path: Path to the file to validate
            user_context: Additional context about the user and upload
            
        Returns:
            Detailed security scan results
        """
        start_time = asyncio.get_event_loop().time()
        
        try:
            # Initialize result
            result = SecurityScanResult(
                file_path=file_path,
                security_level=self.config.security_level
            )
            
            # Basic file validation
            if not await self._validate_basic_file_properties(file_path, result):
                result.is_safe = False
                result.threat_level = ThreatLevel.HIGH
                return result
            
            # Calculate file hash and get metadata
            result.file_hash = await self._calculate_file_hash(file_path)
            result.file_size = Path(file_path).stat().st_size
            
            # Determine media type
            extension = Path(file_path).suffix.lower().lstrip('.')
            result.media_type = get_media_type_by_extension(extension)
            
            # Perform security scans based on configuration
            scan_tasks = []
            
            if self.config.enable_malware_scanning:
                scan_tasks.append(self._scan_malware(file_path, result))
            
            if self.config.enable_content_scanning:
                scan_tasks.append(self._scan_content(file_path, result))
            
            if self.config.enable_privacy_scanning:
                scan_tasks.append(self._scan_privacy(file_path, result))
            
            if self.config.enable_compliance_checking:
                scan_tasks.append(self._check_compliance(file_path, result, user_context))
            
            if self.config.enable_metadata_scanning:
                scan_tasks.append(self._scan_metadata(file_path, result))
            
            # Execute all scans concurrently
            if scan_tasks:
                await asyncio.gather(*scan_tasks, return_exceptions=True)
            
            # Analyze results and determine overall safety
            result.is_safe, result.threat_level = self._analyze_scan_results(result)
            
            # Generate recommendations
            self._generate_recommendations(result)
            
            # Calculate scan duration
            result.scan_duration = asyncio.get_event_loop().time() - start_time
            
            logger.info(f"Security validation completed for {file_path}: {'SAFE' if result.is_safe else 'UNSAFE'}")
            
            return result
            
        except Exception as e:
            logger.error(f"Security validation failed for {file_path}: {e}")
            
            # Return unsafe result on error
            result = SecurityScanResult(
                file_path=file_path,
                security_level=self.config.security_level,
                is_safe=False,
                threat_level=ThreatLevel.HIGH,
                scan_duration=asyncio.get_event_loop().time() - start_time
            )
            
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.HIGH,
                description=f"Security validation error: {str(e)}"
            ))
            
            return result
    
    async def _validate_basic_file_properties(self, file_path: str, result: SecurityScanResult) -> bool:
        """Validate basic file properties."""



        try:
            file_path_obj = Path(file_path)
            
            # Check if file exists
            if not file_path_obj.exists():
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.SECURITY_RISK,
                    threat_level=ThreatLevel.HIGH,
                    description="File does not exist"
                ))
                return False
            
            # Check file size
            file_size = file_path_obj.stat().st_size
            if file_size > self.config.max_file_size:
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.SECURITY_RISK,
                    threat_level=ThreatLevel.MEDIUM,
                    description=f"File size ({file_size} bytes) exceeds limit ({self.config.max_file_size} bytes)"
                ))
                return False
            
            # Check file extension
            extension = file_path_obj.suffix.lower().lstrip('.')
            if extension not in self.config.allowed_extensions:
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.SECURITY_RISK,
                    threat_level=ThreatLevel.MEDIUM,
                    description=f"File extension '{extension}' not allowed"
                ))
                return False
            
            # Check for suspicious file names
            suspicious_patterns = [
                r'\.exe$', r'\.scr$', r'\.bat$', r'\.cmd$', r'\.com$',
                r'\.pif$', r'\.vbs$', r'\.js$', r'\.jar$'
            ]
            
            filename_lower = file_path_obj.name.lower()
            for pattern in suspicious_patterns:
                if re.search(pattern, filename_lower):
                    result.violations.append(SecurityViolation(
                        violation_type=ViolationType.SUSPICIOUS_CONTENT,
                        threat_level=ThreatLevel.HIGH,
                        description=f"Suspicious file extension in filename: {filename_lower}"
                    ))
                    return False
            
            return True
            
        except Exception as e:
            logger.error(f"Basic file validation failed: {e}")
            return False
    
    async def _calculate_file_hash(self, file_path: str) -> str:
        """Calculate SHA-256 hash of the file."""
        hash_sha256 = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(4096), b""):
                    hash_sha256.update(chunk)
            return hash_sha256.hexdigest()
        except Exception as e:
            logger.warning(f"File hash calculation failed: {e}")
            return ""
    
    async def _scan_malware(self, file_path: str, result: SecurityScanResult):
        """Scan for malware and viruses."""



        try:
            malware_result = await self.malware_scanner.scan(file_path)
            result.malware_scan_result = malware_result
            
            if malware_result.get('threats_found', 0) > 0:
                for threat in malware_result.get('threats', []):
                    result.violations.append(SecurityViolation(
                        violation_type=ViolationType.MALWARE,
                        threat_level=ThreatLevel.CRITICAL,
                        description=f"Malware detected: {threat.get('name', 'Unknown')}",
                        evidence=threat
                    ))
            
        except Exception as e:
            logger.error(f"Malware scanning failed: {e}")
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.MEDIUM,
                description=f"Malware scan error: {str(e)}"
            ))
    
    async def _scan_content(self, file_path: str, result: SecurityScanResult):
        """Scan file content for security issues."""



        try:
            content_result = await self.content_scanner.scan(file_path, result.media_type)
            result.content_scan_result = content_result
            
            # Check for suspicious content patterns
            for pattern_type, matches in content_result.get('pattern_matches', {}).items():
                if matches:
                    threat_level = ThreatLevel.HIGH if pattern_type in ['suspicious_content', 'credentials'] else ThreatLevel.MEDIUM
                    
                    result.violations.append(SecurityViolation(
                        violation_type=ViolationType.SUSPICIOUS_CONTENT,
                        threat_level=threat_level,
                        description=f"Suspicious {pattern_type} patterns detected",
                        evidence={'matches': matches[:5]}  # Limit evidence for privacy
                    ))
            
        except Exception as e:
            logger.error(f"Content scanning failed: {e}")
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.MEDIUM,
                description=f"Content scan error: {str(e)}"
            ))
    
    async def _scan_privacy(self, file_path: str, result: SecurityScanResult):
        """Scan for privacy violations and PII exposure."""



        try:
            privacy_result = await self.privacy_scanner.scan(file_path, result.media_type)
            result.privacy_scan_result = privacy_result
            
            if privacy_result.get('pii_found', False):
                pii_types = privacy_result.get('pii_types', [])
                
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.PII_EXPOSURE,
                    threat_level=ThreatLevel.HIGH,
                    description=f"PII detected: {', '.join(pii_types)}",
                    evidence={'pii_types': pii_types},
                    compliance_impact=[ComplianceStandard.GDPR, ComplianceStandard.CCPA]
                ))
            
            if privacy_result.get('location_data', False):
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.PRIVACY_VIOLATION,
                    threat_level=ThreatLevel.MEDIUM,
                    description="Location data found in file metadata",
                    compliance_impact=[ComplianceStandard.GDPR]
                ))
            
        except Exception as e:
            logger.error(f"Privacy scanning failed: {e}")
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.MEDIUM,
                description=f"Privacy scan error: {str(e)}"
            ))
    
    async def _check_compliance(self, file_path: str, result: SecurityScanResult, user_context: Optional[Dict[str, Any]]):
        """Check compliance with various standards."""



        try:
            compliance_result = await self.compliance_checker.check(
                file_path, 
                result.media_type, 
                self.config.compliance_standards,
                user_context
            )
            result.compliance_scan_result = compliance_result
            
            for standard, violations in compliance_result.get('violations', {}).items():
                for violation in violations:
                    result.violations.append(SecurityViolation(
                        violation_type=ViolationType.COMPLIANCE_VIOLATION,
                        threat_level=ThreatLevel.HIGH,
                        description=f"{standard.upper()} violation: {violation['description']}",
                        evidence=violation,
                        compliance_impact=[ComplianceStandard(standard)]
                    ))
            
        except Exception as e:
            logger.error(f"Compliance checking failed: {e}")
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.MEDIUM,
                description=f"Compliance check error: {str(e)}"
            ))
    
    async def _scan_metadata(self, file_path: str, result: SecurityScanResult):
        """Scan file metadata for security issues."""



        try:
            metadata_result = await self.metadata_scanner.scan(file_path)
            result.metadata_scan_result = metadata_result
            
            if metadata_result.get('suspicious_metadata', False):
                suspicious_fields = metadata_result.get('suspicious_fields', [])
                
                result.violations.append(SecurityViolation(
                    violation_type=ViolationType.SUSPICIOUS_METADATA,
                    threat_level=ThreatLevel.MEDIUM,
                    description=f"Suspicious metadata fields: {', '.join(suspicious_fields)}",
                    evidence={'fields': suspicious_fields}
                ))
            
        except Exception as e:
            logger.error(f"Metadata scanning failed: {e}")
            result.violations.append(SecurityViolation(
                violation_type=ViolationType.SECURITY_RISK,
                threat_level=ThreatLevel.LOW,
                description=f"Metadata scan error: {str(e)}"
            ))
    
    def _analyze_scan_results(self, result: SecurityScanResult) -> Tuple[bool, ThreatLevel]:
        """Analyze all scan results to determine overall safety."""
        if not result.violations:
            return True, ThreatLevel.NONE
        
        # Find highest threat level
        threat_levels = [v.threat_level for v in result.violations]
        highest_threat = max(threat_levels, key=lambda x: ['none', 'low', 'medium', 'high', 'critical'].index(x.value))
        
        # Determine if file is safe based on security level and threats
        critical_violations = [v for v in result.violations if v.threat_level == ThreatLevel.CRITICAL]
        high_violations = [v for v in result.violations if v.threat_level == ThreatLevel.HIGH]
        
        if critical_violations:
            return False, ThreatLevel.CRITICAL
        
        if high_violations:
            if self.config.security_level in [SecurityLevel.HIGH, SecurityLevel.PARANOID]:
                return False, highest_threat
            elif len(high_violations) > 2:  # Multiple high-risk violations
                return False, highest_threat
        
        # For medium and low threats, allow based on security level
        if self.config.security_level == SecurityLevel.PARANOID:
            medium_violations = [v for v in result.violations if v.threat_level == ThreatLevel.MEDIUM]
            if medium_violations:
                return False, highest_threat
        
        # File is considered safe with warnings
        return True, highest_threat
    
    def _generate_recommendations(self, result: SecurityScanResult):
        """Generate security recommendations based on scan results."""
        if not result.violations:
            result.recommendations.append("File passed all security checks")
            return
        
        violation_types = set(v.violation_type for v in result.violations)
        
        if ViolationType.MALWARE in violation_types:
            result.required_actions.append("IMMEDIATE: Quarantine file - malware detected")
            result.recommendations.append("Run additional antivirus scans")
            result.recommendations.append("Report to security team")
        
        if ViolationType.PII_EXPOSURE in violation_types:
            result.required_actions.append("Remove or redact PII before processing")
            result.recommendations.append("Implement data anonymization")
            result.recommendations.append("Review privacy policies")
        
        if ViolationType.SUSPICIOUS_CONTENT in violation_types:
            result.recommendations.append("Manual review required")
            result.recommendations.append("Content sanitization recommended")
        
        if ViolationType.COMPLIANCE_VIOLATION in violation_types:
            result.required_actions.append("Address compliance violations before proceeding")
            result.recommendations.append("Consult legal team")
        
        if ViolationType.PRIVACY_VIOLATION in violation_types:
            result.recommendations.append("Strip location and device metadata")
            result.recommendations.append("Review data processing consent")
        
        # General recommendations
        if not result.is_safe:
            result.recommendations.append("Consider rejecting file upload")
            result.recommendations.append("Implement additional security controls")
        else:
            result.recommendations.append("Monitor file for anomalous behavior")
            result.recommendations.append("Regular security re-validation recommended")


class MalwareScanner:
    """Malware and virus scanning component."""
    
    async def scan(self, file_path: str) -> Dict[str, Any]:
        """Scan file for malware."""
        result = {
            'scan_completed': True,
            'threats_found': 0,
            'threats': [],
            'scan_engine': 'builtin',
            'definitions_version': '1.0'
        }
        
        try:
            # Basic signature-based detection
            with open(file_path, 'rb') as f:
                content = f.read(1024 * 1024)  # Read first 1MB
            
            # Known malware signatures (simplified)
            malware_signatures = [
                b'X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*',  # EICAR test
                b'MZ\x90',  # PE executable header
                b'\x7fELF',     # ELF executable header
            ]
            
            for i, signature in enumerate(malware_signatures):
                if signature in content:
                    result['threats_found'] += 1
                    result['threats'].append({
                        'name': f'Signature_{i}',
                        'type': 'signature_match',
                        'severity': 'high'
                    })
            
            # YARA rules scanning if available
            if YARA_AVAILABLE:
                yara_result = await self._yara_scan(file_path)
                if yara_result['matches']:
                    result['threats_found'] += len(yara_result['matches'])
                    result['threats'].extend(yara_result['matches'])
            
        except Exception as e:
            logger.error(f"Malware scan error: {e}")
            result['scan_completed'] = False
            result['error'] = str(e)
        
        return result
    
