@dataclass
class SecurityContext:
    """Security context information"""
    user_id: str
    session_id: str
    ip_address: str
    user_agent: str
    timestamp: datetime
    permissions: List[str]
    risk_score: float


class SecurityService:
    """
    Advanced Security Service for Creator Workflow
    
    Provides comprehensive security management including threat detection,
    access control, encryption, compliance monitoring, and incident response.
    """
    
    def __init__(self):
        self.redis_client = None
        self.cache = CacheManager()
        
        # Security clients
        self.waf_client = WAFClient()
        self.siem_client = SIEMClient()
        self.security_monitor = SecurityMonitor()
        
        # Compliance handlers
        self.gdpr_compliance = GDPRCompliance()
        
        # Encryption setup
        self.fernet_key = self._generate_encryption_key()
        self.fernet = Fernet(self.fernet_key)
        
        # Security thresholds
        self.risk_thresholds = {
            'low': 0.3,
            'medium': 0.6,
            'high': 0.8,
            'critical': 0.95
        }
        
        # Rate limiting configurations
        self.rate_limits = {
            'login_attempts': {'limit': 5, 'window': 900},  # 5 attempts per 15 min
            'api_requests': {'limit': 1000, 'window': 3600},  # 1000 req per hour
            'password_resets': {'limit': 3, 'window': 3600}  # 3 resets per hour
        }
        
        # Security patterns for detection
        self.threat_patterns = {
            'sql_injection': [
                r'(\%27)|(\')|(\-\-)|(\%23)|(#)',
                r'((\%3D)|(=))[^\n]*((\%27)|(\')|(\-\-)|(\%3B)|(;))',
                r'\w*((\%27)|(\'))((\%6F)|o|(\%4F))((\%72)|r|(\%52))'
            ],
            'xss': [
                r'<[^>]*script[^>]*>.*?</script>',
                r'javascript:',
                r'on\w+\s*=',
                r'<iframe[^>]*>.*?</iframe>'
            ],
            'directory_traversal': [
                r'\.\./|\.\.\/',
                r'%2e%2e%2f',
                r'%252e%252e%252f'
            ]
        }
    
    async def initialize(self):
        """Initialize security service components"""



        try:
            self.redis_client = await aioredis.from_url(
                settings.REDIS_URL,
                encoding="utf-8",
                decode_responses=True
            )
            
            await self.waf_client.initialize()
            await self.siem_client.initialize()
            await self.security_monitor.initialize()
            
            # Load security policies
            await self._load_security_policies()
            
            # Start background security monitoring
            asyncio.create_task(self._start_security_monitoring())
            
            logger.info("SecurityService initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize SecurityService: {e}")
            raise SecurityServiceError(f"Service initialization failed: {e}")
    
    async def authenticate_user(
        self,
        username: str,
        password: str,
        security_context: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Authenticate user with advanced security checks
        
        Args:
            username: User identifier
            password: User password
            security_context: Request context information
            
        Returns:
            Authentication result with security assessment
        """



        try:
            # Create security context
            context = SecurityContext(
                user_id=username,
                session_id=str(uuid.uuid4()),
                ip_address=security_context.get('ip_address', ''),
                user_agent=security_context.get('user_agent', ''),
                timestamp=datetime.utcnow(),
                permissions=[],
                risk_score=0.0
            )
            
            # Check rate limiting
            if not await self._check_rate_limit(
                f"login:{context.ip_address}", 
                self.rate_limits['login_attempts']
            ):
                await self._log_security_event(
                    SecurityEventType.AUTHENTICATION_FAILURE,
                    ThreatLevel.MEDIUM,
                    context,
                    {"reason": "rate_limit_exceeded"}
                )
                raise AuthenticationError("Too many login attempts")
            
            # Analyze request for threats
            threat_analysis = await self._analyze_authentication_request(context)
            
            if threat_analysis['risk_score'] > self.risk_thresholds['high']:
                await self._handle_high_risk_authentication(context, threat_analysis)
                raise AuthenticationError("Authentication blocked due to security concerns")
            
            # Verify credentials
            user_data = await self._verify_user_credentials(username, password)
            if not user_data:
                await self._handle_failed_authentication(context)
                raise AuthenticationError("Invalid credentials")
            
            # Load user permissions
            permissions = await self._load_user_permissions(user_data['user_id'])
            context.permissions = permissions
            
            # Generate secure session
            session_token = await self._generate_secure_session(user_data, context)
            
            # Update risk assessment
            final_risk_score = await self._calculate_authentication_risk(
                context, user_data
            )
            
            # Log successful authentication
            await self._log_security_event(
                SecurityEventType.AUTHENTICATION_FAILURE,
                ThreatLevel.LOW,
                context,
                {
                    "user_id": user_data['user_id'],
                    "success": True,
                    "risk_score": final_risk_score
                }
            )
            
            # Store session
            await self._store_secure_session(session_token, user_data, context)
            
            return {
                "success": True,
                "user_id": user_data['user_id'],
                "session_token": session_token,
                "permissions": permissions,
                "risk_score": final_risk_score,
                "session_expires": (datetime.utcnow() + timedelta(hours=24)).isoformat(),
                "security_recommendations": await self._get_security_recommendations(
                    final_risk_score
                )
            }
            
        except Exception as e:
            logger.error(f"Authentication failed: {e}")
            raise AuthenticationError(f"Authentication failed: {e}")
    
    async def authorize_access(
        self,
        user_id: str,
        resource: str,
        action: str,
        security_context: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Authorize user access with comprehensive security checks
        
        Args:
            user_id: User identifier
            resource: Resource being accessed
            action: Action being performed
            security_context: Security context
            
        Returns:
            Authorization result and security assessment
        """



        try:
            # Create security context
            context = SecurityContext(
                user_id=user_id,
                session_id=security_context.get('session_id', ''),
                ip_address=security_context.get('ip_address', ''),
                user_agent=security_context.get('user_agent', ''),
                timestamp=datetime.utcnow(),
                permissions=[],
                risk_score=0.0
            )
            
            # Validate session
            session_valid = await self._validate_user_session(
                user_id, context.session_id
            )
            if not session_valid:
                raise AuthorizationError("Invalid or expired session")
            
            # Load user permissions
            permissions = await self._load_user_permissions(user_id)
            context.permissions = permissions
            
            # Check resource access permissions
            access_allowed = await self._check_resource_permissions(
                user_id, resource, action, permissions
            )
            
            if not access_allowed:
                await self._log_security_event(
                    SecurityEventType.AUTHORIZATION_VIOLATION,
                    ThreatLevel.MEDIUM,
                    context,
                    {
                        "resource": resource,
                        "action": action,
                        "reason": "insufficient_permissions"
                    }
                )
                raise AuthorizationError("Insufficient permissions")
            
            # Analyze request for suspicious patterns
            threat_analysis = await self._analyze_authorization_request(
                context, resource, action
            )
            
            # Check for privilege escalation attempts
            escalation_risk = await self._detect_privilege_escalation(
                user_id, resource, action, permissions
            )
            
            # Calculate overall risk score
            risk_score = max(threat_analysis['risk_score'], escalation_risk)
            context.risk_score = risk_score
            
            # Handle high-risk requests
            if risk_score > self.risk_thresholds['high']:
                await self._handle_high_risk_authorization(context, threat_analysis)
                
                # Still allow if not critical, but with additional monitoring
                if risk_score < self.risk_thresholds['critical']:
                    await self._enable_enhanced_monitoring(user_id, resource)
                else:
                    raise AuthorizationError("Access denied due to security concerns")
            
            # Log successful authorization
            await self._log_security_event(
                SecurityEventType.AUTHORIZATION_VIOLATION,
                ThreatLevel.LOW,
                context,
                {
                    "resource": resource,
                    "action": action,
                    "success": True,
                    "risk_score": risk_score
                }
            )
            
            # Update access tracking
            await self._update_access_tracking(user_id, resource, action)
            
            return {
                "authorized": True,
                "user_id": user_id,
                "resource": resource,
                "action": action,
                "permissions": permissions,
                "risk_score": risk_score,
                "monitoring_level": "enhanced" if risk_score > self.risk_thresholds['medium'] else "normal",
                "access_expires": (datetime.utcnow() + timedelta(hours=1)).isoformat()
            }
            
        except Exception as e:
            logger.error(f"Authorization failed: {e}")
            raise AuthorizationError(f"Authorization failed: {e}")
    
    async def detect_threats(
        self,
        request_data: Dict[str, Any],
        security_context: Dict[str, Any]
    ) -> Dict[str, Any]:
        """
        Advanced threat detection and analysis
        
        Args:
            request_data: Request data to analyze
            security_context: Security context information
            
        Returns:
            Threat analysis results
        """



        try:
            threats_detected = []
            risk_score = 0.0
            
            # Analyze request patterns
            pattern_threats = await self._analyze_threat_patterns(request_data)
            threats_detected.extend(pattern_threats)
            
            # Check for malicious payloads
            payload_threats = await self._detect_malicious_payloads(request_data)
            threats_detected.extend(payload_threats)
            
            # Analyze behavioral patterns
            behavioral_threats = await self._analyze_behavioral_patterns(
                security_context
            )
            threats_detected.extend(behavioral_threats)
            
            # Check IP reputation
            ip_threats = await self._check_ip_reputation(
                security_context.get('ip_address', '')
            )
            threats_detected.extend(ip_threats)
            
            # Calculate overall risk score
            if threats_detected:
                risk_score = max(threat['risk_score'] for threat in threats_detected)
            
            # Determine threat level
            threat_level = self._calculate_threat_level(risk_score)
            
            # Log threat detection
            if threats_detected:
                await self._log_threat_detection(
                    threat_level, threats_detected, security_context
                )
            
            # Trigger automated response if high risk
            if risk_score > self.risk_thresholds['high']:
                await self._trigger_automated_response(
                    threats_detected, security_context
                )
            
            return {
                "threats_detected": len(threats_detected),
                "threat_details": threats_detected,
                "risk_score": risk_score,
                "threat_level": threat_level.value,
                "automated_response_triggered": risk_score > self.risk_thresholds['high'],
                "recommendations": await self._get_threat_recommendations(threats_detected)
            }
            
        except Exception as e:
            logger.error(f"Threat detection failed: {e}")
            raise SecurityServiceError(f"Threat detection failed: {e}")
    
    async def encrypt_sensitive_data(
        self,
        data: Union[str, Dict[str, Any]],
        encryption_level: str = "standard"
    ) -> Dict[str, Any]:
        """
        Encrypt sensitive data with appropriate security level
        
        Args:
            data: Data to encrypt
            encryption_level: Encryption strength level
            
        Returns:
            Encryption result with metadata
        """



        try:
            # Convert data to string if needed
            if isinstance(data, dict):
                data_string = json.dumps(data)
            else:
                data_string = str(data)
            
            # Generate encryption metadata
            encryption_id = str(uuid.uuid4())
            timestamp = datetime.utcnow()
            
            # Apply encryption based on level
            if encryption_level == "high":
                encrypted_data, key_info = await self._high_level_encryption(data_string)
            elif encryption_level == "military":
                encrypted_data, key_info = await self._military_grade_encryption(data_string)
            else:
                encrypted_data = self.fernet.encrypt(data_string.encode())
                key_info = {"key_id": "default", "algorithm": "Fernet"}
            
            # Store encryption metadata
            metadata = {
                "encryption_id": encryption_id,
                "timestamp": timestamp.isoformat(),
                "encryption_level": encryption_level,
                "key_info": key_info,
                "data_hash": hashlib.sha256(data_string.encode()).hexdigest()
            }
            
            await self._store_encryption_metadata(encryption_id, metadata)
            
            return {
                "encrypted_data": base64.b64encode(encrypted_data).decode(),
                "encryption_id": encryption_id,
                "metadata": metadata
            }
            
        except Exception as e:
            logger.error(f"Data encryption failed: {e}")
            raise SecurityServiceError(f"Data encryption failed: {e}")
    
    async def decrypt_sensitive_data(
        self,
        encrypted_data: str,
        encryption_id: str
    ) -> Dict[str, Any]:
        """
        Decrypt sensitive data using stored metadata
        
        Args:
            encrypted_data: Encrypted data to decrypt
            encryption_id: Encryption identifier
            
        Returns:
            Decrypted data
        """



        try:
            # Retrieve encryption metadata
            metadata = await self._get_encryption_metadata(encryption_id)
            if not metadata:
                raise SecurityServiceError("Encryption metadata not found")
            
            # Decode encrypted data
            encrypted_bytes = base64.b64decode(encrypted_data.encode())
            
            # Decrypt based on encryption level
            encryption_level = metadata['encryption_level']
            
            if encryption_level == "high":
                decrypted_data = await self._high_level_decryption(
                    encrypted_bytes, metadata['key_info']
                )
            elif encryption_level == "military":
                decrypted_data = await self._military_grade_decryption(
                    encrypted_bytes, metadata['key_info']
                )
            else:
                decrypted_data = self.fernet.decrypt(encrypted_bytes).decode()
            
            # Verify data integrity
            data_hash = hashlib.sha256(decrypted_data.encode()).hexdigest()
            if data_hash != metadata['data_hash']:
                raise SecurityServiceError("Data integrity check failed")
            
            # Try to parse as JSON if possible
            try:
                parsed_data = json.loads(decrypted_data)
            except json.JSONDecodeError:
                parsed_data = decrypted_data
            
            return {
                "decrypted_data": parsed_data,
                "metadata": metadata,
                "integrity_verified": True
            }
            
        except Exception as e:
            logger.error(f"Data decryption failed: {e}")
            raise SecurityServiceError(f"Data decryption failed: {e}")
    
    async def generate_compliance_report(
        self,
        standards: List[ComplianceStandard],
        period_start: datetime,
        period_end: datetime
    ) -> Dict[str, Any]:
        """
        Generate comprehensive compliance report
        
        Args:
            standards: Compliance standards to check
            period_start: Report period start
            period_end: Report period end
            
        Returns:
            Detailed compliance report
        """



        try:
            compliance_results = {}
            
            for standard in standards:
                if standard == ComplianceStandard.GDPR:
                    results = await self._generate_gdpr_report(period_start, period_end)
                elif standard == ComplianceStandard.PCI_DSS:
                    results = await self._generate_pci_report(period_start, period_end)
                elif standard == ComplianceStandard.ISO27001:
                    results = await self._generate_iso27001_report(period_start, period_end)
                else:
                    results = await self._generate_generic_compliance_report(
                        standard, period_start, period_end
                    )
                
                compliance_results[standard.value] = results
            
            # Calculate overall compliance score
            overall_score = await self._calculate_overall_compliance_score(
                compliance_results
            )
            
            # Generate recommendations
            recommendations = await self._generate_compliance_recommendations(
                compliance_results
            )
            
            # Create report summary
            report = {
                "report_id": str(uuid.uuid4()),
                "generated_at": datetime.utcnow().isoformat(),
                "period": {
                    "start": period_start.isoformat(),
                    "end": period_end.isoformat()
                },
                "standards_evaluated": [s.value for s in standards],
                "overall_compliance_score": overall_score,
                "compliance_results": compliance_results,
                "recommendations": recommendations,
                "critical_issues": await self._identify_critical_compliance_issues(
                    compliance_results
                )
            }
            
            # Store report
            await self._store_compliance_report(report)
            
            return report
            
        except Exception as e:
            logger.error(f"Compliance report generation failed: {e}")
            raise SecurityServiceError(f"Compliance report generation failed: {e}")
    
    # Private helper methods
    
    async def _analyze_threat_patterns(
        self, request_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Analyze request data for known threat patterns"""
        threats = []
        
        # Convert request data to searchable string
        search_string = json.dumps(request_data).lower()
        
        for threat_type, patterns in self.threat_patterns.items():
            for pattern in patterns:
                if re.search(pattern, search_string, re.IGNORECASE):
                    threats.append({
                        "threat_type": threat_type,
                        "pattern_matched": pattern,
                        "risk_score": 0.8,
                        "description": f"Detected {threat_type} pattern"
                    })
        
        return threats
    
    async def _detect_malicious_payloads(
        self, request_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Detect malicious payloads in request data"""
        threats = []
        
        # Check for oversized payloads
        payload_size = len(json.dumps(request_data))
        if payload_size > 1024 * 1024:  # 1MB threshold
            threats.append({
                "threat_type": "oversized_payload",
                "risk_score": 0.6,
                "description": f"Payload size {payload_size} exceeds threshold"
            })
        
        # Check for suspicious file types
        for key, value in request_data.items():
            if isinstance(value, str):
                if any(ext in value.lower() for ext in ['.exe', '.bat', '.sh', '.ps1']):
                    threats.append({
                        "threat_type": "suspicious_file_reference",
                        "risk_score": 0.9,
                        "description": f"Suspicious file reference in {key}"
                    })
        
        return threats
    
    async def _generate_encryption_key(self) -> bytes:
        """Generate encryption key"""



        return Fernet.generate_key()
    
    async def _high_level_encryption(self, data: str) -> Tuple[bytes, Dict[str, Any]]:
        """Apply high-level encryption"""
        # This would implement more advanced encryption
        encrypted = self.fernet.encrypt(data.encode())
        key_info = {"key_id": "high_security", "algorithm": "Advanced_Fernet"}
        return encrypted, key_info
    
    async def _military_grade_encryption(self, data: str) -> Tuple[bytes, Dict[str, Any]]:
        """Apply military-grade encryption"""
        # This would implement military-grade encryption algorithms
        encrypted = self.fernet.encrypt(data.encode())
        key_info = {"key_id": "military_grade", "algorithm": "AES-256-GCM"}
        return encrypted, key_info
    
    def _calculate_threat_level(self, risk_score: float) -> ThreatLevel:
        """Calculate threat level from risk score"""
        if risk_score >= self.risk_thresholds['critical']:
            return ThreatLevel.CRITICAL
        elif risk_score >= self.risk_thresholds['high']:
            return ThreatLevel.HIGH
        elif risk_score >= self.risk_thresholds['medium']:
            return ThreatLevel.MEDIUM
        else:
            return ThreatLevel.LOW
    
