"""
Security Alert Handler Module

This module provides specialized handlers for security-related alerts in the
blockchain consensus monitoring system. It focuses on attack detection,
anomaly identification, and security threat assessment.

Author: Fahed Mlaiel <mlaiel@live.de>
 STRICT COPYRIGHT WARNING - Unauthorized use prohibited 

Business Context:
- Part of Spotify AI Agent + Protection system
- Handles security monitoring for content creator protection workflow  
- Protects blockchain integrity for creator rights management
- Integrates with AI-powered attack detection systems
- Ensures security of multi-format content upload and processing
"""

import asyncio
import logging
from datetime import datetime, timezone, timedelta
from typing import Dict, List, Optional, Any, Union, Tuple
from dataclasses import dataclass, asdict
from enum import Enum
import statistics
import hashlib
import json

from ..models.alert import Alert, AlertSeverity
from ..alert_manager import AlertManager


class SecurityThreatLevel(Enum):
    """Security threat levels."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"
    EMERGENCY = "emergency"


class AttackType(Enum):
    """Types of detected attacks."""
    DDOS = "ddos"
    SYBIL = "sybil_attack"
    ECLIPSE = "eclipse_attack"
    LONG_RANGE = "long_range_attack"
    NOTHING_AT_STAKE = "nothing_at_stake"
    DOUBLE_SPEND = "double_spend"
    FINALITY_REVERSION = "finality_reversion"
    CONSENSUS_MANIPULATION = "consensus_manipulation"
    VALIDATOR_COLLUSION = "validator_collusion"
    MALICIOUS_FORK = "malicious_fork"
    SPAM_ATTACK = "spam_attack"
    ROUTING_ATTACK = "routing_attack"


class AnomalyType(Enum):
    """Types of detected anomalies."""
    UNUSUAL_TRAFFIC = "unusual_traffic"
    ABNORMAL_BEHAVIOR = "abnormal_behavior"
    SUSPICIOUS_PATTERNS = "suspicious_patterns"
    UNEXPECTED_CONSENSUS = "unexpected_consensus"
    ANOMALOUS_VALIDATOR = "anomalous_validator"
    IRREGULAR_TIMING = "irregular_timing"
    STATISTICAL_OUTLIER = "statistical_outlier"


@dataclass
class SecurityMetrics:
    """Security monitoring metrics."""
    threat_level: SecurityThreatLevel
    anomaly_score: float
    attack_probability: float
    suspicious_activity_count: int
    malicious_behavior_detected: bool
    network_integrity_score: float
    validator_reputation_avg: float
    transaction_spam_rate: float
    consensus_manipulation_risk: float
    timestamp: datetime
    
    @property
    def overall_security_score(self) -> float:
        """Calculate overall security score (0-100)."""
        base_score = 100.0
        base_score -= self.anomaly_score * 10
        base_score -= self.attack_probability * 50
        base_score -= (100 - self.network_integrity_score)
        return max(0.0, min(100.0, base_score))


@dataclass
class SecurityIncident:
    """Security incident record."""
    incident_id: str
    attack_type: AttackType
    threat_level: SecurityThreatLevel
    confidence_score: float
    detection_time: datetime
    source_ips: List[str]
    affected_validators: List[str]
    attack_vectors: List[str]
    evidence_hash: str
    mitigation_applied: bool
    investigation_status: str
    
    def __post_init__(self):
        if not self.incident_id:
            # Generate unique incident ID
            content = f"{self.attack_type.value}_{self.detection_time.isoformat()}_{self.confidence_score}"
            self.incident_id = hashlib.sha256(content.encode()).hexdigest()[:16]


@dataclass
class AttackPattern:
    """Attack pattern definition."""
    pattern_id: str
    attack_type: AttackType
    indicators: List[str]
    thresholds: Dict[str, float]
    confidence_weight: float
    description: str
    mitigation_strategies: List[str]


class SecurityAlertHandler:
    """
    Specialized handler for blockchain security monitoring alerts.
    
    Features:
    - Real-time attack detection and classification
    - Anomaly detection using statistical analysis
    - Pattern matching for known attack vectors
    - Behavioral analysis of validators and network participants
    - Threat intelligence integration
    - Automated incident response triggers
    - Security metrics collection and analysis
    - Forensic evidence preservation
    - Business impact assessment for creator platform security
    """
    
    def __init__(self, alert_manager: AlertManager):
        """
        Initialize security alert handler.
        
        Args:
            alert_manager: Main alert manager instance
        """
        self.logger = logging.getLogger(__name__)
        self.alert_manager = alert_manager
        
        # Security monitoring state
        self.current_threat_level = SecurityThreatLevel.LOW
        self.security_metrics_history: List[SecurityMetrics] = []
        self.security_incidents: Dict[str, SecurityIncident] = {}
        
        # Attack pattern definitions
        self.attack_patterns = self._load_attack_patterns()
        
        # Security thresholds
        self.thresholds = {
            'anomaly_score_critical': 8.0,      # Above 8.0 = critical anomaly
            'anomaly_score_warning': 5.0,       # Above 5.0 = warning
            'attack_probability_critical': 0.8, # Above 80% = critical
            'attack_probability_warning': 0.5,  # Above 50% = warning
            'spam_rate_critical': 1000,         # 1000+ spam tx/minute = critical
            'spam_rate_warning': 500,           # 500+ spam tx/minute = warning  
            'reputation_critical': 0.3,         # Below 30% avg reputation = critical
            'reputation_warning': 0.5,          # Below 50% avg reputation = warning
            'consensus_manipulation_critical': 0.7,  # Above 70% risk = critical
            'suspicious_activity_critical': 50,      # 50+ suspicious events = critical
        }
        
        # Behavioral baselines (learned over time)
        self.behavioral_baselines = {
            'normal_transaction_rate': 100.0,
            'normal_validator_behavior': {},
            'normal_network_patterns': {},
            'baseline_consensus_timing': 30.0
        }
        
        # Real-time monitoring state
        self.active_security_alerts: Dict[str, Alert] = {}
        self.investigation_queue: List[SecurityIncident] = []
        self.last_security_scan = datetime.now(timezone.utc)
        
        self.logger.info("Security alert handler initialized")
    
    def _load_attack_patterns(self) -> Dict[str, AttackPattern]:
        """Load predefined attack patterns for detection."""
        patterns = {}
        
        # DDoS attack pattern
        patterns['ddos'] = AttackPattern(
            pattern_id="ddos_001",
            attack_type=AttackType.DDOS,
            indicators=[
                "high_connection_rate",
                "resource_exhaustion",
                "response_time_degradation",
                "unusual_traffic_volume"
            ],
            thresholds={
                "connections_per_second": 1000.0,
                "cpu_usage": 90.0,
                "memory_usage": 85.0,
                "response_time_ms": 5000.0
            },
            confidence_weight=0.8,
            description="Distributed Denial of Service attack targeting network availability",
            mitigation_strategies=[
                "rate_limiting",
                "traffic_filtering", 
                "load_balancing",
                "blacklist_ips"
            ]
        )
        
        # Sybil attack pattern
        patterns['sybil'] = AttackPattern(
            pattern_id="sybil_001",
            attack_type=AttackType.SYBIL,
            indicators=[
                "rapid_validator_creation",
                "low_stake_validators",
                "coordinated_behavior",
                "identity_clustering"
            ],
            thresholds={
                "new_validators_per_hour": 10.0,
                "average_stake_ratio": 0.01,
                "behavior_correlation": 0.8,
                "ip_clustering_score": 0.7
            },
            confidence_weight=0.9,
            description="Sybil attack attempting to gain disproportionate network influence",
            mitigation_strategies=[
                "stake_requirements",
                "identity_verification",
                "behavior_analysis",
                "reputation_system"
            ]
        )
        
        # Eclipse attack pattern
        patterns['eclipse'] = AttackPattern(
            pattern_id="eclipse_001", 
            attack_type=AttackType.ECLIPSE,
            indicators=[
                "peer_isolation",
                "routing_manipulation",
                "selective_message_dropping",
                "network_partition_attempt"
            ],
            thresholds={
                "peer_connectivity_drop": 0.5,
                "message_drop_rate": 0.3,
                "routing_anomaly_score": 7.0,
                "isolation_indicator": 0.8
            },
            confidence_weight=0.85,
            description="Eclipse attack isolating nodes from the honest network",
            mitigation_strategies=[
                "diverse_peer_selection",
                "routing_verification",
                "connectivity_monitoring",
                "peer_reputation"
            ]
        )
        
        # Double spend attack pattern
        patterns['double_spend'] = AttackPattern(
            pattern_id="double_spend_001",
            attack_type=AttackType.DOUBLE_SPEND,
            indicators=[
                "conflicting_transactions",
                "rapid_finality_reversions",
                "fork_creation_attempts",
                "stake_concentration"
            ],
            thresholds={
                "conflicting_tx_rate": 5.0,
                "reversion_frequency": 3.0,
                "fork_attempts_per_hour": 2.0,
                "stake_concentration_ratio": 0.4
            },
            confidence_weight=0.95,
            description="Double spend attack attempting to reverse finalized transactions",
            mitigation_strategies=[
                "finality_confirmation",
                "stake_slashing",
                "fork_detection",
                "transaction_monitoring"
            ]
        )
        
        return patterns
    
    async def process_security_metrics(self, metrics: Dict[str, Any]) -> List[Alert]:
        """
        Process incoming security metrics and generate alerts.
        
        Args:
            metrics: Raw security metrics from monitoring systems
            
        Returns:
            List[Alert]: Generated security alerts
        """



        try:
            # Parse and validate metrics
            security_metrics = self._parse_security_metrics(metrics)
            
            # Store metrics history
            self.security_metrics_history.append(security_metrics)
            self._cleanup_old_metrics()
            
            # Analyze metrics and generate alerts
            alerts = []
            
            # Check for high anomaly scores
            anomaly_alerts = await self._check_anomaly_scores(security_metrics)
            alerts.extend(anomaly_alerts)
            
            # Check attack probability
            attack_probability_alerts = await self._check_attack_probability(security_metrics)
            alerts.extend(attack_probability_alerts)
            
            # Check for specific attack patterns
            pattern_alerts = await self._check_attack_patterns(security_metrics, metrics)
            alerts.extend(pattern_alerts)
            
            # Check validator reputation
            reputation_alerts = await self._check_validator_reputation(security_metrics)
            alerts.extend(reputation_alerts)
            
            # Check for spam attacks
            spam_alerts = await self._check_spam_attacks(security_metrics)
            alerts.extend(spam_alerts)
            
            # Check consensus manipulation
            manipulation_alerts = await self._check_consensus_manipulation(security_metrics)
            alerts.extend(manipulation_alerts)
            
            # Update threat level
            self._update_threat_level(security_metrics)
            
            # Assess business security impact
            await self._assess_security_business_impact(security_metrics, alerts)
            
            self.logger.debug(f"Processed security metrics, generated {len(alerts)} alerts")
            
            return alerts
            
        except Exception as e:
            self.logger.error(f"Failed to process security metrics: {e}")
            return []
    
    def _parse_security_metrics(self, raw_metrics: Dict[str, Any]) -> SecurityMetrics:
        """
        Parse raw security metrics into structured SecurityMetrics object.
        
        Args:
            raw_metrics: Raw metrics from security monitoring systems
            
        Returns:  
            SecurityMetrics: Parsed metrics
        """



        return SecurityMetrics(
            threat_level=SecurityThreatLevel(raw_metrics.get('threat_level', 'low')),
            anomaly_score=float(raw_metrics.get('anomaly_score', 0.0)),
            attack_probability=float(raw_metrics.get('attack_probability', 0.0)),
            suspicious_activity_count=int(raw_metrics.get('suspicious_activity_count', 0)),
            malicious_behavior_detected=bool(raw_metrics.get('malicious_behavior_detected', False)),
            network_integrity_score=float(raw_metrics.get('network_integrity_score', 100.0)),
            validator_reputation_avg=float(raw_metrics.get('validator_reputation_avg', 1.0)),
            transaction_spam_rate=float(raw_metrics.get('transaction_spam_rate', 0.0)),
            consensus_manipulation_risk=float(raw_metrics.get('consensus_manipulation_risk', 0.0)),
            timestamp=datetime.now(timezone.utc)
        )
    
    def _cleanup_old_metrics(self):
        """Clean up old security metrics to prevent memory bloat."""
        cutoff_time = datetime.now(timezone.utc) - timedelta(hours=72)  # Keep 3 days
        self.security_metrics_history = [
            m for m in self.security_metrics_history 
            if m.timestamp > cutoff_time
        ]
    
    async def _check_anomaly_scores(self, metrics: SecurityMetrics) -> List[Alert]:
        """
        Check for high anomaly scores indicating potential security issues.
        
        Args:
            metrics: Current security metrics
            
        Returns:
            List[Alert]: Anomaly-related alerts
        """
        alerts = []
        anomaly_score = metrics.anomaly_score
        
        # Critical anomaly threshold
        if anomaly_score >= self.thresholds['anomaly_score_critical']:
            alert = Alert(
                alert_type="security_anomaly_critical",
                title=f"Critical Security Anomaly Detected (Score: {anomaly_score:.1f})",
                description=(
                    f"A critical security anomaly has been detected with a score of {anomaly_score:.1f}, "
                    f"which exceeds the critical threshold of {self.thresholds['anomaly_score_critical']}. "
                    f"This indicates potential malicious activity or a serious security threat. "
                    f"Immediate investigation and response are required. "
                    f"Network integrity score: {metrics.network_integrity_score:.1f}%."
                ),
                severity=AlertSeverity.CRITICAL,
                source="security_monitor",
                metadata={
                    'anomaly_score': anomaly_score,
                    'threshold': self.thresholds['anomaly_score_critical'],
                    'network_integrity_score': metrics.network_integrity_score,
                    'overall_security_score': metrics.overall_security_score,
                    'security_incident': True,
                    'investigation_required': True,
                    'business_impact': 'critical',
                    'creator_platform_security_risk': True
                }
            )
            alerts.append(alert)
            
        # Warning anomaly threshold
        elif anomaly_score >= self.thresholds['anomaly_score_warning']:
            alert = Alert(
                alert_type="security_anomaly_warning",
                title=f"Security Anomaly Warning (Score: {anomaly_score:.1f})",
                description=(
                    f"A security anomaly has been detected with a score of {anomaly_score:.1f}, "
                    f"which exceeds the warning threshold of {self.thresholds['anomaly_score_warning']}. "
                    f"This may indicate suspicious activity that requires monitoring. "
                    f"Consider investigating the source of this anomaly."
                ),
                severity=AlertSeverity.HIGH,
                source="security_monitor",
                metadata={
                    'anomaly_score': anomaly_score,
                    'threshold': self.thresholds['anomaly_score_warning'],
                    'network_integrity_score': metrics.network_integrity_score,
                    'monitoring_required': True,
                    'business_impact': 'medium'
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_attack_probability(self, metrics: SecurityMetrics) -> List[Alert]:
        """
        Check attack probability scores for potential threats.
        
        Args:
            metrics: Current security metrics
            
        Returns:
            List[Alert]: Attack probability alerts
        """
        alerts = []
        attack_prob = metrics.attack_probability
        
        # Critical attack probability
        if attack_prob >= self.thresholds['attack_probability_critical']:
            alert = Alert(
                alert_type="attack_probability_critical",
                title=f"High Attack Probability: {attack_prob*100:.1f}%",
                description=(
                    f"The system has detected a high probability ({attack_prob*100:.1f}%) of an active attack. "
                    f"This assessment is based on multiple security indicators including anomaly scores, "
                    f"behavioral patterns, and threat intelligence. Immediate security measures should be activated. "
                    f"Consider implementing emergency protocols and isolating potentially compromised components."
                ),
                severity=AlertSeverity.CRITICAL,
                source="security_monitor",
                metadata={
                    'attack_probability': attack_prob,
                    'attack_probability_percentage': attack_prob * 100,
                    'threshold': self.thresholds['attack_probability_critical'],
                    'active_attack_suspected': True,
                    'emergency_protocols_recommended': True,
                    'security_isolation_required': True,
                    'business_impact': 'critical',
                    'creator_content_at_risk': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_attack_patterns(self, metrics: SecurityMetrics, raw_metrics: Dict[str, Any]) -> List[Alert]:
        """
        Check for specific attack patterns using pattern matching.
        
        Args:
            metrics: Current security metrics
            raw_metrics: Raw metrics for detailed pattern analysis
            
        Returns:
            List[Alert]: Pattern-based attack alerts
        """
        alerts = []
        
        try:
            # Check each attack pattern
            for pattern_id, pattern in self.attack_patterns.items():
                confidence = await self._calculate_pattern_confidence(pattern, raw_metrics)
                
                if confidence >= 0.8:  # High confidence threshold
                    alert = Alert(
                        alert_type=f"attack_pattern_{pattern.attack_type.value}",
                        title=f"Attack Pattern Detected: {pattern.attack_type.value.replace('_', ' ').title()}",
                        description=(
                            f"Security analysis has detected a {pattern.attack_type.value.replace('_', ' ')} attack pattern "
                            f"with {confidence*100:.1f}% confidence. {pattern.description}. "
                            f"Recommended mitigation strategies: {', '.join(pattern.mitigation_strategies)}. "
                            f"Immediate security response is required."
                        ),
                        severity=AlertSeverity.CRITICAL if confidence >= 0.9 else AlertSeverity.HIGH,
                        source="security_pattern_analyzer",
                        metadata={
                            'attack_type': pattern.attack_type.value,
                            'pattern_id': pattern.pattern_id,
                            'confidence_score': confidence,
                            'indicators_matched': pattern.indicators,
                            'mitigation_strategies': pattern.mitigation_strategies,
                            'pattern_based_detection': True,
                            'automated_response_available': True,
                            'business_impact': 'critical' if confidence >= 0.9 else 'high'
                        }
                    )
                    alerts.append(alert)
                    
                    # Create security incident
                    incident = SecurityIncident(
                        incident_id="",  # Will be auto-generated
                        attack_type=pattern.attack_type,
                        threat_level=SecurityThreatLevel.CRITICAL if confidence >= 0.9 else SecurityThreatLevel.HIGH,
                        confidence_score=confidence,
                        detection_time=datetime.now(timezone.utc),
                        source_ips=raw_metrics.get('source_ips', []),
                        affected_validators=raw_metrics.get('affected_validators', []),
                        attack_vectors=pattern.indicators,
                        evidence_hash=self._generate_evidence_hash(raw_metrics),
                        mitigation_applied=False,
                        investigation_status="pending"
                    )
                    self.security_incidents[incident.incident_id] = incident
                    self.investigation_queue.append(incident)
            
            return alerts
            
        except Exception as e:
            self.logger.error(f"Failed to check attack patterns: {e}")
            return []
    
    async def _calculate_pattern_confidence(self, pattern: AttackPattern, metrics: Dict[str, Any]) -> float:
        """
        Calculate confidence score for attack pattern match.
        
        Args:
            pattern: Attack pattern to check
            metrics: Raw metrics data
            
        Returns:
            float: Confidence score (0.0 to 1.0)
        """



        try:
            confidence = 0.0
            indicators_matched = 0
            total_indicators = len(pattern.indicators)
            
            # Check each indicator
            for indicator in pattern.indicators:
                if indicator in metrics:
                    # Check if indicator exceeds threshold
                    threshold_key = indicator
                    if threshold_key in pattern.thresholds:
                        metric_value = float(metrics[indicator])
                        threshold_value = pattern.thresholds[threshold_key]
                        
                        if metric_value >= threshold_value:
                            indicators_matched += 1
                            confidence += pattern.confidence_weight / total_indicators
            
            # Apply bonus for multiple indicators
            if indicators_matched >= total_indicators * 0.75:
                confidence *= 1.2  # 20% bonus for high indicator match rate
            
            return min(1.0, confidence)
            
        except Exception as e:
            self.logger.error(f"Failed to calculate pattern confidence: {e}")
            return 0.0
    
    def _generate_evidence_hash(self, metrics: Dict[str, Any]) -> str:
        """Generate hash of evidence for forensic purposes."""



        try:
            evidence_data = json.dumps(metrics, sort_keys=True, default=str)
            return hashlib.sha256(evidence_data.encode()).hexdigest()
        except Exception:
            return hashlib.sha256(str(datetime.now()).encode()).hexdigest()
    
    async def _check_validator_reputation(self, metrics: SecurityMetrics) -> List[Alert]:
        """
        Check validator reputation scores for potential security issues.
        
        Args:
            metrics: Current security metrics
            
        Returns:
            List[Alert]: Validator reputation alerts
        """
        alerts = []
        avg_reputation = metrics.validator_reputation_avg
        
        # Critical reputation threshold
        if avg_reputation < self.thresholds['reputation_critical']:
            alert = Alert(
                alert_type="validator_reputation_critical",
                title=f"Critical: Low Validator Reputation ({avg_reputation*100:.1f}%)",
                description=(
                    f"The average validator reputation score has dropped to {avg_reputation*100:.1f}%, "
                    f"which is below the critical threshold of {self.thresholds['reputation_critical']*100:.1f}%. "
                    f"This indicates potential validator misbehavior, network compromise, or reputation system attack. "
                    f"Investigate validator behavior and consider implementing reputation-based penalties."
                ),
                severity=AlertSeverity.CRITICAL,
                source="validator_reputation_monitor",
                metadata={
                    'validator_reputation_avg': avg_reputation,
                    'reputation_percentage': avg_reputation * 100,
                    'threshold': self.thresholds['reputation_critical'],
                    'validator_misbehavior_suspected': True,
                    'reputation_system_compromised': True,
                    'business_impact': 'critical',
                    'validator_penalties_recommended': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_spam_attacks(self, metrics: SecurityMetrics) -> List[Alert]:
        """
        Check for transaction spam attacks.
        
        Args:
            metrics: Current security metrics
            
        Returns:
            List[Alert]: Spam attack alerts
        """
        alerts = []
        spam_rate = metrics.transaction_spam_rate
        
        # Critical spam rate threshold
        if spam_rate >= self.thresholds['spam_rate_critical']:
            alert = Alert(
                alert_type="transaction_spam_critical",
                title=f"Critical: High Transaction Spam Rate ({spam_rate:.0f}/min)",
                description=(
                    f"A high transaction spam rate of {spam_rate:.0f} transactions per minute has been detected, "
                    f"exceeding the critical threshold of {self.thresholds['spam_rate_critical']}. "
                    f"This indicates a potential spam attack attempting to congest the network or exploit resources. "
                    f"Implement rate limiting and spam filtering measures immediately."
                ),
                severity=AlertSeverity.CRITICAL,
                source="spam_detector",
                metadata={
                    'spam_rate': spam_rate,
                    'threshold': self.thresholds['spam_rate_critical'],
                    'spam_attack_detected': True,
                    'network_congestion_risk': True,
                    'rate_limiting_required': True,
                    'business_impact': 'high',
                    'creator_transaction_delays': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    async def _check_consensus_manipulation(self, metrics: SecurityMetrics) -> List[Alert]:
        """
        Check for consensus manipulation attempts.
        
        Args:
            metrics: Current security metrics
            
        Returns:
            List[Alert]: Consensus manipulation alerts
        """
        alerts = []
        manipulation_risk = metrics.consensus_manipulation_risk
        
        # Critical manipulation risk threshold
        if manipulation_risk >= self.thresholds['consensus_manipulation_critical']:
            alert = Alert(
                alert_type="consensus_manipulation_critical", 
                title=f"CRITICAL: Consensus Manipulation Risk ({manipulation_risk*100:.1f}%)",
                description=(
                    f" SECURITY EMERGENCY: HIGH CONSENSUS MANIPULATION RISK \n"
                    f"The system has detected a {manipulation_risk*100:.1f}% risk of consensus manipulation, "
                    f"exceeding the critical threshold of {self.thresholds['consensus_manipulation_critical']*100:.1f}%. "
                    f"This indicates potential attempts to manipulate the blockchain consensus mechanism, "
                    f"which could lead to double-spending, transaction reversals, or network compromise. "
                    f"IMMEDIATE EMERGENCY RESPONSE REQUIRED."
                ),
                severity=AlertSeverity.EMERGENCY,
                source="consensus_security_monitor",
                metadata={
                    'consensus_manipulation_risk': manipulation_risk,
                    'manipulation_risk_percentage': manipulation_risk * 100,
                    'threshold': self.thresholds['consensus_manipulation_critical'],
                    'consensus_attack_detected': True,
                    'emergency_response_required': True,
                    'network_integrity_compromised': True,
                    'business_impact': 'emergency',
                    'creator_funds_at_risk': True,
                    'blockchain_integrity_threatened': True
                }
            )
            alerts.append(alert)
        
        return alerts
    
    def _update_threat_level(self, metrics: SecurityMetrics):
        """
        Update current threat level based on security metrics.
        
        Args:
            metrics: Current security metrics
        """
        # Determine threat level based on multiple factors
        if (metrics.attack_probability >= 0.8 or 
            metrics.consensus_manipulation_risk >= 0.7 or
            metrics.malicious_behavior_detected):
            self.current_threat_level = SecurityThreatLevel.EMERGENCY
            
        elif (metrics.anomaly_score >= 8.0 or
              metrics.attack_probability >= 0.5 or
              metrics.validator_reputation_avg < 0.3):
            self.current_threat_level = SecurityThreatLevel.CRITICAL
            
        elif (metrics.anomaly_score >= 5.0 or
              metrics.suspicious_activity_count >= 20 or
              metrics.transaction_spam_rate >= 500):
            self.current_threat_level = SecurityThreatLevel.HIGH
            
        elif (metrics.anomaly_score >= 2.0 or
              metrics.suspicious_activity_count >= 10):
            self.current_threat_level = SecurityThreatLevel.MEDIUM
            
        else:
            self.current_threat_level = SecurityThreatLevel.LOW
    
    async def _assess_security_business_impact(self, metrics: SecurityMetrics, alerts: List[Alert]):
        """
        Assess security business impact on creator platform.
        
        Args:
            metrics: Current security metrics
            alerts: Generated alerts
        """



        try:
            # Calculate business impact based on security state
            business_impact = {
                'creator_funds_at_risk': False,
                'content_integrity_compromised': False,
                'platform_trust_affected': False,
                'regulatory_compliance_risk': False,
                'revenue_loss_estimated': 0.0,
                'reputation_damage_risk': 'low'
            }
            
            # Assess impact based on threat level
            if self.current_threat_level == SecurityThreatLevel.EMERGENCY:
                business_impact.update({
                    'creator_funds_at_risk': True,
                    'content_integrity_compromised': True,
                    'platform_trust_affected': True,
                    'regulatory_compliance_risk': True,
                    'revenue_loss_estimated': 50000.0,  # $50k/hour estimate
                    'reputation_damage_risk': 'critical'
                })
                
            elif self.current_threat_level == SecurityThreatLevel.CRITICAL:
                business_impact.update({
                    'content_integrity_compromised': True,
                    'platform_trust_affected': True,
                    'regulatory_compliance_risk': True,
                    'revenue_loss_estimated': 20000.0,  # $20k/hour estimate
                    'reputation_damage_risk': 'high'
                })
            
            # Add business impact to high-severity alerts
            for alert in alerts:
                if alert.severity in [AlertSeverity.EMERGENCY, AlertSeverity.CRITICAL]:
                    alert.metadata.update(business_impact)
                    alert.metadata.update({
                        'spotify_ai_security_impact': True,
                        'creator_protection_compromised': self.current_threat_level != SecurityThreatLevel.LOW,
                        'content_rights_at_risk': self.current_threat_level in [
                            SecurityThreatLevel.CRITICAL, SecurityThreatLevel.EMERGENCY
                        ]
                    })
            
        except Exception as e:
            self.logger.error(f"Failed to assess security business impact: {e}")
    
    def get_security_status_summary(self) -> Dict[str, Any]:
        """
        Get comprehensive security status summary.
        
        Returns:
            Dict[str, Any]: Security status summary
        """
        if not self.security_metrics_history:
            return {"status": "no_data", "error": "No security metrics available"}
        
        latest_metrics = self.security_metrics_history[-1]
        
        return {
            "threat_level": self.current_threat_level.value,
            "overall_security_score": latest_metrics.overall_security_score,
            "anomaly_score": latest_metrics.anomaly_score,
            "attack_probability": latest_metrics.attack_probability,
            "attack_probability_percentage": latest_metrics.attack_probability * 100,
            "network_integrity_score": latest_metrics.network_integrity_score,
            "validator_reputation_avg": latest_metrics.validator_reputation_avg,
            "suspicious_activity_count": latest_metrics.suspicious_activity_count,
            "malicious_behavior_detected": latest_metrics.malicious_behavior_detected,
            "active_security_incidents": len(self.security_incidents),
            "incidents_under_investigation": len(self.investigation_queue),
            "active_security_alerts": len(self.active_security_alerts),
            "last_updated": latest_metrics.timestamp.isoformat(),
            "security_posture": "compromised" if self.current_threat_level in [
                SecurityThreatLevel.CRITICAL, SecurityThreatLevel.EMERGENCY
            ] else "monitoring" if self.current_threat_level == SecurityThreatLevel.HIGH else "normal"
        }


