"""
Advanced User Feature Extraction Module

This module provides comprehensive user behavior analysis and feature extraction
for the Spotify AI Agent, including listening patterns, preferences, engagement
metrics, and demographic modeling.
"""

import asyncio
import numpy as np
import pandas as pd
from typing import Dict, List, Optional, Union, Tuple, Any, Set
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from abc import ABC, abstractmethod
import logging
from collections import defaultdict, Counter
from scipy import stats
from sklearn.cluster import KMeans
from sklearn.preprocessing import StandardScaler
import json

logger = logging.getLogger(__name__)


@dataclass
class UserConfig:
    """Configuration for user feature extraction"""
    session_timeout_minutes: int = 30
    min_interactions_for_analysis: int = 10
    lookback_days: int = 90
    demographic_anonymization: bool = True
    privacy_mode: bool = True
    feature_cache_ttl: int = 3600  # 1 hour


@dataclass
class UserInteraction:
    """Represents a single user interaction"""
    user_id: str
    track_id: str
    action: str  # play, skip, like, dislike, share, etc.
    timestamp: datetime
    duration_seconds: float
    device_type: str
    location: Optional[str] = None
    context: Optional[str] = None  # playlist, radio, search, etc.
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class UserSession:
    """Represents a listening session"""
    session_id: str
    user_id: str
    start_time: datetime
    end_time: datetime
    interactions: List[UserInteraction]
    device_type: str
    total_duration: float
    tracks_played: int
    skips: int
    likes: int


class BaseUserExtractor(ABC):
    """Base class for user feature extractors"""
    
    def __init__(self, config: Optional[UserConfig] = None):
        self.config = config or UserConfig()
        
    @abstractmethod
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract features from user interactions"""
        pass


class UserBehaviorExtractor(BaseUserExtractor):
    """Extract behavioral pattern features"""
    
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract comprehensive behavioral features"""
        if not interactions:
            return self._get_empty_behavior_features()
        
        features = {}
        
        features.update(await self._extract_session_patterns(interactions))
        features.update(await self._extract_interaction_patterns(interactions))
        features.update(await self._extract_temporal_patterns(interactions))
        features.update(await self._extract_engagement_patterns(interactions))
        
        return features
    
    async def _extract_session_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract session-based behavioral patterns"""
        # Group interactions into sessions
        sessions = self._group_into_sessions(interactions)
        
        if not sessions:
            return self._get_empty_session_features()
        
        session_durations = [s.total_duration for s in sessions]
        session_track_counts = [s.tracks_played for s in sessions]
        session_skip_rates = [s.skips / max(s.tracks_played, 1) for s in sessions]
        
        # Device usage patterns
        device_counts = Counter([s.device_type for s in sessions])
        primary_device = device_counts.most_common(1)[0][0] if device_counts else "unknown"
        device_diversity = len(device_counts) / max(len(sessions), 1)
        
        return {
            'avg_session_duration': np.mean(session_durations),
            'session_duration_std': np.std(session_durations),
            'median_session_duration': np.median(session_durations),
            'max_session_duration': np.max(session_durations),
            'sessions_per_day': len(sessions) / max(self.config.lookback_days, 1),
            'avg_tracks_per_session': np.mean(session_track_counts),
            'avg_session_skip_rate': np.mean(session_skip_rates),
            'session_skip_rate_std': np.std(session_skip_rates),
            'primary_device_usage_ratio': device_counts[primary_device] / len(sessions),
            'device_diversity_score': device_diversity,
            'session_consistency': 1.0 / (1.0 + np.std(session_durations) / np.mean(session_durations))
        }
    
    async def _extract_interaction_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract interaction-level behavioral patterns"""
        # Categorize interactions
        play_interactions = [i for i in interactions if i.action == 'play']
        skip_interactions = [i for i in interactions if i.action == 'skip']
        like_interactions = [i for i in interactions if i.action == 'like']
        dislike_interactions = [i for i in interactions if i.action == 'dislike']
        
        total_interactions = len(interactions)
        
        # Calculate rates
        skip_rate = len(skip_interactions) / max(len(play_interactions), 1)
        like_rate = len(like_interactions) / max(total_interactions, 1)
        dislike_rate = len(dislike_interactions) / max(total_interactions, 1)
        
        # Listen completion rates
        completion_rates = []
        for interaction in play_interactions:
            if 'track_duration' in interaction.metadata:
                track_duration = interaction.metadata['track_duration']
                completion_rate = interaction.duration_seconds / max(track_duration, 1)
                completion_rates.append(min(completion_rate, 1.0))
        
        avg_completion_rate = np.mean(completion_rates) if completion_rates else 0.0
        
        # Interaction frequency patterns
        interaction_intervals = []
        sorted_interactions = sorted(interactions, key=lambda x: x.timestamp)
        for i in range(1, len(sorted_interactions)):
            interval = (sorted_interactions[i].timestamp - sorted_interactions[i-1].timestamp).total_seconds()
            interaction_intervals.append(interval)
        
        return {
            'skip_rate': skip_rate,
            'like_rate': like_rate,
            'dislike_rate': dislike_rate,
            'avg_completion_rate': avg_completion_rate,
            'completion_rate_std': np.std(completion_rates) if completion_rates else 0.0,
            'interaction_frequency': len(interactions) / max(self.config.lookback_days, 1),
            'avg_interaction_interval': np.mean(interaction_intervals) if interaction_intervals else 0.0,
            'interaction_regularity': 1.0 / (1.0 + np.std(interaction_intervals) / max(np.mean(interaction_intervals), 1)) if interaction_intervals else 0.0,
            'engagement_consistency': avg_completion_rate * (1.0 - skip_rate)
        }
    
    async def _extract_temporal_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract temporal listening patterns"""
        if not interactions:
            return self._get_empty_temporal_features()
        
        # Extract hour of day patterns
        hours = [i.timestamp.hour for i in interactions]
        hour_distribution = np.bincount(hours, minlength=24) / len(interactions)
        
        # Extract day of week patterns
        weekdays = [i.timestamp.weekday() for i in interactions]
        weekday_distribution = np.bincount(weekdays, minlength=7) / len(interactions)
        
        # Peak listening times
        peak_hour = np.argmax(hour_distribution)
        peak_weekday = np.argmax(weekday_distribution)
        
        # Listening concentration
        hour_entropy = stats.entropy(hour_distribution + 1e-10)
        weekday_entropy = stats.entropy(weekday_distribution + 1e-10)
        
        # Weekend vs weekday preferences
        weekend_interactions = sum(1 for i in interactions if i.timestamp.weekday() >= 5)
        weekend_preference = weekend_interactions / len(interactions)
        
        # Time consistency
        listening_times = [i.timestamp.hour + i.timestamp.minute/60.0 for i in interactions]
        time_consistency = 1.0 / (1.0 + np.std(listening_times))
        
        return {
            'peak_listening_hour': peak_hour,
            'peak_listening_weekday': peak_weekday,
            'hour_entropy': hour_entropy,
            'weekday_entropy': weekday_entropy,
            'weekend_preference': weekend_preference,
            'time_consistency': time_consistency,
            'morning_preference': sum(hour_distribution[6:12]),
            'afternoon_preference': sum(hour_distribution[12:18]),
            'evening_preference': sum(hour_distribution[18:24]),
            'night_preference': sum(hour_distribution[0:6]),
            'weekday_preference': sum(weekday_distribution[0:5]) / 5,
            'temporal_diversity': hour_entropy + weekday_entropy
        }
    
    async def _extract_engagement_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract engagement and discovery patterns"""
        # Context analysis
        contexts = [i.context for i in interactions if i.context]
        context_counts = Counter(contexts)
        context_diversity = len(context_counts) / max(len(interactions), 1)
        
        # Discovery patterns
        unique_tracks = set([i.track_id for i in interactions])
        track_diversity = len(unique_tracks) / max(len(interactions), 1)
        
        # Repeat listening
        track_plays = Counter([i.track_id for i in interactions if i.action == 'play'])
        repeated_tracks = sum(1 for count in track_plays.values() if count > 1)
        repeat_rate = repeated_tracks / max(len(unique_tracks), 1)
        
        # Exploration vs exploitation
        new_track_ratio = len([i for i in interactions if i.metadata.get('is_new_to_user', False)]) / len(interactions)
        
        return {
            'context_diversity': context_diversity,
            'track_diversity': track_diversity,
            'repeat_listening_rate': repeat_rate,
            'exploration_rate': new_track_ratio,
            'exploitation_rate': 1.0 - new_track_ratio,
            'engagement_breadth': context_diversity * track_diversity,
            'listening_loyalty': repeat_rate / max(track_diversity, 1)
        }
    
    def _group_into_sessions(self, interactions: List[UserInteraction]) -> List[UserSession]:
        """Group interactions into listening sessions"""
        if not interactions:
            return []
        
        sessions = []
        sorted_interactions = sorted(interactions, key=lambda x: x.timestamp)
        
        current_session_interactions = [sorted_interactions[0]]
        session_start = sorted_interactions[0].timestamp
        
        for i in range(1, len(sorted_interactions)):
            current_interaction = sorted_interactions[i]
            prev_interaction = sorted_interactions[i-1]
            
            # Check if this starts a new session
            time_gap = (current_interaction.timestamp - prev_interaction.timestamp).total_seconds() / 60
            
            if time_gap > self.config.session_timeout_minutes:
                # End current session
                if current_session_interactions:
                    session = self._create_session(current_session_interactions, session_start)
                    sessions.append(session)
                
                # Start new session
                current_session_interactions = [current_interaction]
                session_start = current_interaction.timestamp
            else:
                current_session_interactions.append(current_interaction)
        
        # Add final session
        if current_session_interactions:
            session = self._create_session(current_session_interactions, session_start)
            sessions.append(session)
        
        return sessions
    
    def _create_session(self, interactions: List[UserInteraction], start_time: datetime) -> UserSession:
        """Create a UserSession object from interactions"""
        end_time = max(i.timestamp for i in interactions)
        total_duration = sum(i.duration_seconds for i in interactions)
        
        tracks_played = len([i for i in interactions if i.action == 'play'])
        skips = len([i for i in interactions if i.action == 'skip'])
        likes = len([i for i in interactions if i.action == 'like'])
        
        device_types = [i.device_type for i in interactions]
        primary_device = Counter(device_types).most_common(1)[0][0] if device_types else "unknown"
        
        session_id = f"{interactions[0].user_id}_{start_time.isoformat()}"
        
        return UserSession(
            session_id=session_id,
            user_id=interactions[0].user_id,
            start_time=start_time,
            end_time=end_time,
            interactions=interactions,
            device_type=primary_device,
            total_duration=total_duration,
            tracks_played=tracks_played,
            skips=skips,
            likes=likes
        )
    
    def _get_empty_behavior_features(self) -> Dict[str, float]:
        """Return empty behavior features when no data available"""



        return {key: 0.0 for key in [
            'avg_session_duration', 'session_duration_std', 'sessions_per_day',
            'avg_tracks_per_session', 'avg_session_skip_rate', 'skip_rate',
            'like_rate', 'dislike_rate', 'avg_completion_rate', 'interaction_frequency',
            'peak_listening_hour', 'weekend_preference', 'context_diversity',
            'track_diversity', 'repeat_listening_rate', 'exploration_rate'
        ]}
    
    def _get_empty_session_features(self) -> Dict[str, float]:
        """Return empty session features"""



        return {key: 0.0 for key in [
            'avg_session_duration', 'session_duration_std', 'median_session_duration',
            'max_session_duration', 'sessions_per_day', 'avg_tracks_per_session',
            'avg_session_skip_rate', 'session_skip_rate_std', 'primary_device_usage_ratio',
            'device_diversity_score', 'session_consistency'
        ]}
    
    def _get_empty_temporal_features(self) -> Dict[str, float]:
        """Return empty temporal features"""



        return {key: 0.0 for key in [
            'peak_listening_hour', 'peak_listening_weekday', 'hour_entropy',
            'weekday_entropy', 'weekend_preference', 'time_consistency',
            'morning_preference', 'afternoon_preference', 'evening_preference',
            'night_preference', 'weekday_preference', 'temporal_diversity'
        ]}


class ListeningPatternExtractor(BaseUserExtractor):
    """Extract detailed listening pattern features"""
    
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract listening pattern features"""
        if not interactions:
            return {}
        
        features = {}
        
        features.update(await self._extract_genre_patterns(interactions))
        features.update(await self._extract_artist_patterns(interactions))
        features.update(await self._extract_audio_features_patterns(interactions))
        features.update(await self._extract_discovery_patterns(interactions))
        
        return features
    
    async def _extract_genre_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract genre preference patterns"""
        # Extract genres from track metadata
        genres = []
        for interaction in interactions:
            if 'genres' in interaction.metadata:
                genres.extend(interaction.metadata['genres'])
        
        if not genres:
            return {'genre_diversity': 0.0, 'genre_consistency': 0.0}
        
        genre_counts = Counter(genres)
        total_genre_instances = sum(genre_counts.values())
        
        # Genre diversity (normalized entropy)
        genre_probs = [count / total_genre_instances for count in genre_counts.values()]
        genre_entropy = stats.entropy(genre_probs)
        max_entropy = np.log(len(genre_counts))
        genre_diversity = genre_entropy / max_entropy if max_entropy > 0 else 0.0
        
        # Genre consistency (preference for top genres)
        top_genre_ratio = genre_counts.most_common(1)[0][1] / total_genre_instances
        
        # Genre evolution (change over time)
        sorted_interactions = sorted(interactions, key=lambda x: x.timestamp)
        mid_point = len(sorted_interactions) // 2
        
        early_genres = []
        late_genres = []
        
        for i, interaction in enumerate(sorted_interactions):
            if 'genres' in interaction.metadata:
                if i < mid_point:
                    early_genres.extend(interaction.metadata['genres'])
                else:
                    late_genres.extend(interaction.metadata['genres'])
        
        early_genre_set = set(early_genres)
        late_genre_set = set(late_genres)
        
        if early_genre_set and late_genre_set:
            genre_stability = len(early_genre_set & late_genre_set) / len(early_genre_set | late_genre_set)
        else:
            genre_stability = 1.0
        
        return {
            'genre_diversity': genre_diversity,
            'genre_consistency': top_genre_ratio,
            'genre_stability': genre_stability,
            'unique_genres_count': len(genre_counts),
            'genre_concentration': sum((count / total_genre_instances) ** 2 for count in genre_counts.values())
        }
    
    async def _extract_artist_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract artist preference patterns"""
        artists = [i.metadata.get('artist', 'unknown') for i in interactions if 'artist' in i.metadata]
        
        if not artists:
            return {'artist_diversity': 0.0, 'artist_loyalty': 0.0}
        
        artist_counts = Counter(artists)
        unique_artists = len(artist_counts)
        total_plays = len(artists)
        
        # Artist diversity
        artist_diversity = unique_artists / total_plays
        
        # Artist loyalty (Herfindahl index)
        artist_probs = [count / total_plays for count in artist_counts.values()]
        artist_loyalty = sum(p**2 for p in artist_probs)
        
        # New artist discovery rate
        sorted_interactions = sorted([i for i in interactions if 'artist' in i.metadata], key=lambda x: x.timestamp)
        seen_artists = set()
        new_artist_discoveries = 0
        
        for interaction in sorted_interactions:
            artist = interaction.metadata['artist']
            if artist not in seen_artists:
                new_artist_discoveries += 1
                seen_artists.add(artist)
        
        discovery_rate = new_artist_discoveries / len(sorted_interactions) if sorted_interactions else 0.0
        
        return {
            'artist_diversity': artist_diversity,
            'artist_loyalty': artist_loyalty,
            'unique_artists_count': unique_artists,
            'artist_discovery_rate': discovery_rate,
            'top_artist_dominance': artist_counts.most_common(1)[0][1] / total_plays if artist_counts else 0.0
        }
    
    async def _extract_audio_features_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract audio feature preference patterns"""
        audio_features = []
        
        for interaction in interactions:
            if 'audio_features' in interaction.metadata:
                audio_features.append(interaction.metadata['audio_features'])
        
        if not audio_features:
            return {}
        
        # Convert to numpy array for analysis
        features_array = np.array([list(af.values()) for af in audio_features])
        feature_names = list(audio_features[0].keys())
        
        # Calculate preference patterns
        preferences = {}
        
        for i, feature_name in enumerate(feature_names):
            feature_values = features_array[:, i]
            preferences[f'{feature_name}_preference_mean'] = np.mean(feature_values)
            preferences[f'{feature_name}_preference_std'] = np.std(feature_values)
            preferences[f'{feature_name}_preference_range'] = np.max(feature_values) - np.min(feature_values)
        
        # Calculate preference consistency
        overall_std = np.mean([np.std(features_array[:, i]) for i in range(features_array.shape[1])])
        preferences['audio_preference_consistency'] = 1.0 / (1.0 + overall_std)
        
        return preferences
    
    async def _extract_discovery_patterns(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract music discovery patterns"""
        # Track sources (recommendations, search, radio, etc.)
        sources = [i.metadata.get('source', 'unknown') for i in interactions]
        source_counts = Counter(sources)
        
        # Discovery mechanisms
        recommendation_ratio = source_counts.get('recommendation', 0) / len(interactions)
        search_ratio = source_counts.get('search', 0) / len(interactions)
        radio_ratio = source_counts.get('radio', 0) / len(interactions)
        playlist_ratio = source_counts.get('playlist', 0) / len(interactions)
        
        # Exploration depth
        unique_sources = len(source_counts)
        source_diversity = unique_sources / len(interactions)
        
        return {
            'recommendation_usage': recommendation_ratio,
            'search_usage': search_ratio,
            'radio_usage': radio_ratio,
            'playlist_usage': playlist_ratio,
            'discovery_source_diversity': source_diversity,
            'primary_discovery_method': source_counts.most_common(1)[0][0] if source_counts else 'unknown'
        }


class PreferenceFeatureExtractor(BaseUserExtractor):
    """Extract user preference features using ML techniques"""
    
    def __init__(self, config: Optional[UserConfig] = None):
        super().__init__(config)
        self.scaler = StandardScaler()
        self.preference_model = None
    
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract ML-based preference features"""
        if len(interactions) < self.config.min_interactions_for_analysis:
            return {}
        
        features = {}
        
        features.update(await self._extract_clustering_features(interactions))
        features.update(await self._extract_preference_vectors(interactions))
        features.update(await self._extract_taste_profile(interactions))
        
        return features
    
    async def _extract_clustering_features(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract features using clustering analysis"""
        # Prepare data for clustering
        feature_vectors = []
        
        for interaction in interactions:
            if 'audio_features' in interaction.metadata and interaction.action == 'play':
                vector = []
                audio_features = interaction.metadata['audio_features']
                
                # Standard audio features
                vector.extend([
                    audio_features.get('danceability', 0.0),
                    audio_features.get('energy', 0.0),
                    audio_features.get('valence', 0.0),
                    audio_features.get('acousticness', 0.0),
                    audio_features.get('instrumentalness', 0.0),
                    audio_features.get('speechiness', 0.0),
                    audio_features.get('liveness', 0.0),
                    audio_features.get('tempo', 120.0) / 200.0,  # normalize tempo
                    audio_features.get('loudness', -10.0) / -60.0  # normalize loudness
                ])
                
                # Interaction features
                completion_rate = interaction.duration_seconds / max(interaction.metadata.get('track_duration', 1), 1)
                vector.append(min(completion_rate, 1.0))
                
                feature_vectors.append(vector)
        
        if len(feature_vectors) < 3:
            return {'preference_clusters': 0, 'preference_consistency': 0.0}
        
        # Perform clustering
        X = np.array(feature_vectors)
        X_scaled = self.scaler.fit_transform(X)
        
        # Determine optimal number of clusters
        max_clusters = min(10, len(feature_vectors) // 3)
        if max_clusters >= 2:
            kmeans = KMeans(n_clusters=max_clusters, random_state=42, n_init=10)
            cluster_labels = kmeans.fit_predict(X_scaled)
            
            # Calculate clustering metrics
            unique_clusters = len(set(cluster_labels))
            cluster_counts = Counter(cluster_labels)
            
            # Preference consistency (how concentrated user is in clusters)
            cluster_probs = [count / len(cluster_labels) for count in cluster_counts.values()]
            preference_consistency = sum(p**2 for p in cluster_probs)
            
            # Dominant cluster preference
            dominant_cluster_ratio = cluster_counts.most_common(1)[0][1] / len(cluster_labels)
            
            return {
                'preference_clusters': unique_clusters,
                'preference_consistency': preference_consistency,
                'dominant_cluster_ratio': dominant_cluster_ratio,
                'preference_diversity': 1.0 - preference_consistency
            }
        
        return {'preference_clusters': 1, 'preference_consistency': 1.0}
    
    async def _extract_preference_vectors(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract user preference vectors"""
        # Aggregate audio features across all listened tracks
        audio_features_sum = defaultdict(list)
        
        for interaction in interactions:
            if 'audio_features' in interaction.metadata and interaction.action == 'play':
                features = interaction.metadata['audio_features']
                weight = min(interaction.duration_seconds / interaction.metadata.get('track_duration', 1), 1.0)
                
                for feature, value in features.items():
                    audio_features_sum[feature].append(value * weight)
        
        # Calculate weighted preferences
        preferences = {}
        for feature, values in audio_features_sum.items():
            if values:
                preferences[f'pref_{feature}_mean'] = np.mean(values)
                preferences[f'pref_{feature}_std'] = np.std(values)
        
        return preferences
    
    async def _extract_taste_profile(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract high-level taste profile characteristics"""
        # Analyze listening patterns for taste profiling
        genres = []
        energy_levels = []
        valence_levels = []
        danceability_levels = []
        
        for interaction in interactions:
            if interaction.action == 'play':
                if 'genres' in interaction.metadata:
                    genres.extend(interaction.metadata['genres'])
                
                if 'audio_features' in interaction.metadata:
                    af = interaction.metadata['audio_features']
                    energy_levels.append(af.get('energy', 0.5))
                    valence_levels.append(af.get('valence', 0.5))
                    danceability_levels.append(af.get('danceability', 0.5))
        
        # Calculate taste characteristics
        taste_profile = {}
        
        if energy_levels:
            taste_profile['taste_energy_preference'] = np.mean(energy_levels)
            taste_profile['taste_mood_preference'] = np.mean(valence_levels)
            taste_profile['taste_danceability_preference'] = np.mean(danceability_levels)
            
            # Taste complexity
            taste_profile['taste_complexity'] = np.mean([
                np.std(energy_levels),
                np.std(valence_levels),
                np.std(danceability_levels)
            ])
        
        # Genre sophistication
        if genres:
            genre_counts = Counter(genres)
            mainstream_genres = {'pop', 'rock', 'hip-hop', 'electronic'}
            mainstream_ratio = sum(genre_counts[g] for g in mainstream_genres if g in genre_counts) / len(genres)
            taste_profile['taste_mainstream_ratio'] = mainstream_ratio
            taste_profile['taste_genre_sophistication'] = 1.0 - mainstream_ratio
        
        return taste_profile


class DemographicFeatureExtractor(BaseUserExtractor):
    """Extract demographic and contextual features (privacy-safe)"""
    
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract privacy-safe demographic features"""
        if not interactions:
            return {}
        
        features = {}
        
        features.update(await self._extract_temporal_demographics(interactions))
        features.update(await self._extract_device_demographics(interactions))
        features.update(await self._extract_contextual_demographics(interactions))
        features.update(await self._extract_usage_demographics(interactions))
        
        return features
    
    async def _extract_temporal_demographics(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract temporal usage patterns (age-group indicators)"""
        # Different age groups have different listening patterns
        hours = [i.timestamp.hour for i in interactions]
        hour_distribution = np.bincount(hours, minlength=24) / len(interactions)
        
        # Young adults tend to listen late at night
        night_listening = sum(hour_distribution[22:24]) + sum(hour_distribution[0:6])
        
        # Working age adults listen during commute times
        commute_listening = sum(hour_distribution[7:9]) + sum(hour_distribution[17:19])
        
        # Older adults tend to listen during traditional hours
        traditional_listening = sum(hour_distribution[9:17])
        
        # Weekend vs weekday patterns
        weekdays = [i.timestamp.weekday() for i in interactions]
        weekend_ratio = sum(1 for w in weekdays if w >= 5) / len(interactions)
        
        return {
            'demo_night_listening_ratio': night_listening,
            'demo_commute_listening_ratio': commute_listening,
            'demo_traditional_listening_ratio': traditional_listening,
            'demo_weekend_ratio': weekend_ratio,
            'demo_schedule_regularity': 1.0 / (1.0 + np.std(hours))
        }
    
    async def _extract_device_demographics(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract device usage patterns"""
        devices = [i.device_type for i in interactions]
        device_counts = Counter(devices)
        
        # Device preferences can indicate demographics
        mobile_ratio = device_counts.get('mobile', 0) / len(interactions)
        desktop_ratio = device_counts.get('desktop', 0) / len(interactions)
        smart_speaker_ratio = device_counts.get('smart_speaker', 0) / len(interactions)
        
        return {
            'demo_mobile_preference': mobile_ratio,
            'demo_desktop_preference': desktop_ratio,
            'demo_smart_speaker_preference': smart_speaker_ratio,
            'demo_device_diversity': len(device_counts) / len(interactions)
        }
    
    async def _extract_contextual_demographics(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract contextual usage patterns"""
        contexts = [i.context for i in interactions if i.context]
        
        if not contexts:
            return {}
        
        context_counts = Counter(contexts)
        
        # Different contexts can indicate lifestyle
        playlist_ratio = context_counts.get('playlist', 0) / len(contexts)
        radio_ratio = context_counts.get('radio', 0) / len(contexts)
        search_ratio = context_counts.get('search', 0) / len(contexts)
        recommendation_ratio = context_counts.get('recommendation', 0) / len(contexts)
        
        return {
            'demo_playlist_preference': playlist_ratio,
            'demo_radio_preference': radio_ratio,
            'demo_search_preference': search_ratio,
            'demo_recommendation_preference': recommendation_ratio,
            'demo_context_diversity': len(context_counts) / len(contexts)
        }
    
    async def _extract_usage_demographics(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract usage intensity patterns"""
        # Usage patterns can indicate user type
        total_listening_time = sum(i.duration_seconds for i in interactions if i.action == 'play')
        avg_daily_usage = total_listening_time / (self.config.lookback_days * 3600)  # hours per day
        
        # Session patterns
        sessions = self._group_into_sessions(interactions)
        avg_session_duration = np.mean([s.total_duration for s in sessions]) / 3600 if sessions else 0  # hours
        
        # Engagement intensity
        skip_rate = len([i for i in interactions if i.action == 'skip']) / len([i for i in interactions if i.action == 'play'])
        
        return {
            'demo_usage_intensity': avg_daily_usage,
            'demo_session_intensity': avg_session_duration,
            'demo_engagement_level': 1.0 - skip_rate,
            'demo_power_user_score': min(avg_daily_usage * (1.0 - skip_rate), 1.0)
        }
    
    def _group_into_sessions(self, interactions: List[UserInteraction]) -> List[UserSession]:
        """Group interactions into sessions (simplified version)"""
        # Reuse the session grouping logic from UserBehaviorExtractor
        if not interactions:
            return []
        
        sessions = []
        sorted_interactions = sorted(interactions, key=lambda x: x.timestamp)
        
        current_session_interactions = [sorted_interactions[0]]
        
        for i in range(1, len(sorted_interactions)):
            current_interaction = sorted_interactions[i]
            prev_interaction = sorted_interactions[i-1]
            
            time_gap = (current_interaction.timestamp - prev_interaction.timestamp).total_seconds() / 60
            
            if time_gap > self.config.session_timeout_minutes:
                if current_session_interactions:
                    session_duration = sum(i.duration_seconds for i in current_session_interactions)
                    session = type('Session', (), {
                        'total_duration': session_duration,
                        'interactions': current_session_interactions
                    })()
                    sessions.append(session)
                
                current_session_interactions = [current_interaction]
            else:
                current_session_interactions.append(current_interaction)
        
        # Add final session
        if current_session_interactions:
            session_duration = sum(i.duration_seconds for i in current_session_interactions)
            session = type('Session', (), {
                'total_duration': session_duration,
                'interactions': current_session_interactions
            })()
            sessions.append(session)
        
        return sessions


class EngagementFeatureExtractor(BaseUserExtractor):
    """Extract user engagement and retention features"""
    
    async def extract_features(self, interactions: List[UserInteraction]) -> Dict[str, Any]:
        """Extract engagement features"""
        if not interactions:
            return {}
        
        features = {}
        
        features.update(await self._extract_engagement_intensity(interactions))
        features.update(await self._extract_retention_features(interactions))
        features.update(await self._extract_social_engagement(interactions))
        features.update(await self._extract_content_engagement(interactions))
        
        return features
    
    async def _extract_engagement_intensity(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract engagement intensity metrics"""
        # Active vs passive listening
        active_actions = ['like', 'share', 'add_to_playlist', 'repeat']
        passive_actions = ['play', 'skip']
        
        active_count = len([i for i in interactions if i.action in active_actions])
        passive_count = len([i for i in interactions if i.action in passive_actions])
        
        total_interactions = active_count + passive_count
        active_ratio = active_count / max(total_interactions, 1)
        
        # Engagement depth
        likes = len([i for i in interactions if i.action == 'like'])
        shares = len([i for i in interactions if i.action == 'share'])
        playlist_adds = len([i for i in interactions if i.action == 'add_to_playlist'])
        
        # Time-based engagement
        play_interactions = [i for i in interactions if i.action == 'play']
        if play_interactions:
            avg_listen_duration = np.mean([i.duration_seconds for i in play_interactions])
            completion_rates = []
            
            for interaction in play_interactions:
                if 'track_duration' in interaction.metadata:
                    completion_rate = interaction.duration_seconds / interaction.metadata['track_duration']
                    completion_rates.append(min(completion_rate, 1.0))
            
            avg_completion_rate = np.mean(completion_rates) if completion_rates else 0.0
        else:
            avg_listen_duration = 0.0
            avg_completion_rate = 0.0
        
        return {
            'engagement_active_ratio': active_ratio,
            'engagement_like_rate': likes / max(len(interactions), 1),
            'engagement_share_rate': shares / max(len(interactions), 1),
            'engagement_playlist_rate': playlist_adds / max(len(interactions), 1),
            'engagement_avg_completion': avg_completion_rate,
            'engagement_depth_score': (likes + shares * 2 + playlist_adds * 3) / max(len(interactions), 1),
            'engagement_consistency': avg_completion_rate * active_ratio
        }
    
    async def _extract_retention_features(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract user retention indicators"""
        # Sort interactions by time
        sorted_interactions = sorted(interactions, key=lambda x: x.timestamp)
        
        if len(sorted_interactions) < 2:
            return {'retention_score': 0.0}
        
        # Calculate return patterns
        first_interaction = sorted_interactions[0].timestamp
        last_interaction = sorted_interactions[-1].timestamp
        total_span_days = (last_interaction - first_interaction).days + 1
        
        # Active days
        active_dates = set(i.timestamp.date() for i in interactions)
        active_days = len(active_dates)
        retention_ratio = active_days / max(total_span_days, 1)
        
        # Interaction frequency consistency
        daily_interactions = defaultdict(int)
        for interaction in interactions:
            daily_interactions[interaction.timestamp.date()] += 1
        
        daily_counts = list(daily_interactions.values())
        interaction_consistency = 1.0 / (1.0 + np.std(daily_counts) / max(np.mean(daily_counts), 1))
        
        # Recent activity
        recent_cutoff = datetime.now() - timedelta(days=7)
        recent_interactions = [i for i in interactions if i.timestamp >= recent_cutoff]
        recent_activity_ratio = len(recent_interactions) / max(len(interactions), 1)
        
        # Engagement trend
        mid_point = len(sorted_interactions) // 2
        early_period = sorted_interactions[:mid_point]
        late_period = sorted_interactions[mid_point:]
        
        early_engagement = len([i for i in early_period if i.action == 'like']) / max(len(early_period), 1)
        late_engagement = len([i for i in late_period if i.action == 'like']) / max(len(late_period), 1)
        
        engagement_trend = late_engagement - early_engagement
        
        return {
            'retention_ratio': retention_ratio,
            'retention_consistency': interaction_consistency,
            'retention_recent_activity': recent_activity_ratio,
            'retention_engagement_trend': engagement_trend,
            'retention_total_span_days': total_span_days,
            'retention_active_days': active_days,
            'retention_score': retention_ratio * interaction_consistency * (1.0 + engagement_trend)
        }
    
    async def _extract_social_engagement(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract social engagement features"""
        # Social actions
        shares = len([i for i in interactions if i.action == 'share'])
        social_listens = len([i for i in interactions if i.metadata.get('source') == 'social'])
        
        # Playlist interactions
        playlist_creates = len([i for i in interactions if i.action == 'create_playlist'])
        playlist_follows = len([i for i in interactions if i.action == 'follow_playlist'])
        
        # Social discovery
        friend_recommendations = len([i for i in interactions if i.metadata.get('source') == 'friend'])
        
        total_interactions = len(interactions)
        
        return {
            'social_share_rate': shares / max(total_interactions, 1),
            'social_listen_rate': social_listens / max(total_interactions, 1),
            'social_playlist_activity': (playlist_creates + playlist_follows) / max(total_interactions, 1),
            'social_discovery_rate': friend_recommendations / max(total_interactions, 1),
            'social_engagement_score': (shares * 2 + social_listens + playlist_creates * 3) / max(total_interactions, 1)
        }
    
    async def _extract_content_engagement(self, interactions: List[UserInteraction]) -> Dict[str, float]:
        """Extract content-specific engagement features"""
        # Track repeat behavior
        track_plays = defaultdict(int)
        for interaction in interactions:
            if interaction.action == 'play':
                track_plays[interaction.track_id] += 1
        
        # Repeat listening patterns
        repeated_tracks = sum(1 for count in track_plays.values() if count > 1)
        total_unique_tracks = len(track_plays)
        repeat_ratio = repeated_tracks / max(total_unique_tracks, 1)
        
        # Discovery vs familiarity
        new_tracks = len([i for i in interactions if i.metadata.get('is_new_to_user', False)])
        discovery_ratio = new_tracks / max(len(interactions), 1)
        
        # Content depth
        liked_tracks = set([i.track_id for i in interactions if i.action == 'like'])
        played_tracks = set([i.track_id for i in interactions if i.action == 'play'])
        
        like_to_play_ratio = len(liked_tracks) / max(len(played_tracks), 1)
        
        return {
            'content_repeat_ratio': repeat_ratio,
            'content_discovery_ratio': discovery_ratio,
            'content_like_ratio': like_to_play_ratio,
            'content_exploration_depth': len(played_tracks) / max(len(interactions), 1),
            'content_engagement_quality': like_to_play_ratio * (1.0 - discovery_ratio + repeat_ratio)
        }


# Export main classes
__all__ = [
    'UserBehaviorExtractor',
    'ListeningPatternExtractor',
    'PreferenceFeatureExtractor',
    'DemographicFeatureExtractor',
    'EngagementFeatureExtractor',
    'UserConfig',
    'UserInteraction',
    'UserSession'
]

