"""
Security Metrics and Monitoring System.

This module provides comprehensive security metrics collection,
analysis, and real-time monitoring capabilities for the Spotify AI Agent platform.

Created by: Fahed Mlaiel
"""

import asyncio
import logging
import json
import time
from datetime import datetime, timedelta
from typing import Dict, Any, List, Optional, Tuple, Set
from dataclasses import dataclass, asdict
from enum import Enum
from collections import defaultdict, deque
import statistics
import hashlib
import threading
from concurrent.futures import ThreadPoolExecutor

logger = logging.getLogger(__name__)


class MetricType(str, Enum):
    """Security metric types."""
    COUNTER = "counter"
    GAUGE = "gauge"
    HISTOGRAM = "histogram"
    RATE = "rate"
    PERCENTAGE = "percentage"


class AlertSeverity(str, Enum):
    """Alert severity levels."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class SecurityEvent(str, Enum):
    """Security event types."""
    LOGIN_SUCCESS = "login_success"
    LOGIN_FAILURE = "login_failure"
    LOGIN_BLOCKED = "login_blocked"
    LOGOUT = "logout"
    PERMISSION_DENIED = "permission_denied"
    DATA_ACCESS = "data_access"
    DATA_EXPORT = "data_export"
    POLICY_VIOLATION = "policy_violation"
    THREAT_DETECTED = "threat_detected"
    ANOMALY_DETECTED = "anomaly_detected"
    ENCRYPTION_FAILURE = "encryption_failure"
    KEY_ROTATION = "key_rotation"
    CONFIG_CHANGE = "config_change"
    AUDIT_LOG_ACCESS = "audit_log_access"


@dataclass
class SecurityMetric:
    """Security metric data structure."""
    name: str
    type: MetricType
    value: float
    timestamp: datetime
    labels: Dict[str, str]
    description: str
    tenant_id: Optional[str] = None
    user_id: Optional[str] = None


@dataclass
class SecurityAlert:
    """Security alert data structure."""
    alert_id: str
    name: str
    severity: AlertSeverity
    message: str
    timestamp: datetime
    tenant_id: str
    user_id: Optional[str]
    event_type: SecurityEvent
    source_ip: Optional[str]
    metadata: Dict[str, Any]
    resolved: bool = False
    resolved_at: Optional[datetime] = None
    resolved_by: Optional[str] = None


@dataclass
class MetricThreshold:
    """Metric threshold configuration."""
    metric_name: str
    warning_threshold: float
    critical_threshold: float
    evaluation_window: int  # seconds
    evaluation_method: str  # "average", "max", "min", "sum"


class SecurityMetricsCollector:
    """Advanced security metrics collector."""
    
    def __init__(self, retention_days: int = 30):
        """Initialize metrics collector."""
        self.retention_days = retention_days
        self.metrics: Dict[str, deque] = defaultdict(lambda: deque(maxlen=10000))
        self.events: deque = deque(maxlen=50000)
        self.tenant_metrics: Dict[str, Dict[str, deque]] = defaultdict(
            lambda: defaultdict(lambda: deque(maxlen=5000))
        )
        self.lock = threading.RLock()
        
        # Real-time counters
        self.counters: Dict[str, int] = defaultdict(int)
        self.gauges: Dict[str, float] = defaultdict(float)
        self.rates: Dict[str, deque] = defaultdict(lambda: deque(maxlen=100))
        
        # Performance tracking
        self.operation_timings: Dict[str, deque] = defaultdict(lambda: deque(maxlen=1000))
        
        # Security specific metrics
        self.login_attempts: Dict[str, deque] = defaultdict(lambda: deque(maxlen=1000))
        self.failed_logins: Dict[str, deque] = defaultdict(lambda: deque(maxlen=1000))
        self.blocked_ips: Set[str] = set()
        self.suspicious_activities: deque = deque(maxlen=10000)
        
        # Start cleanup task
        self._cleanup_task = None
        self._start_cleanup_task()
    
    def record_metric(self, metric: SecurityMetric):
        """Record a security metric."""
        with self.lock:
            # Store in main metrics
            self.metrics[metric.name].append(metric)
            
            # Store in tenant-specific metrics if applicable
            if metric.tenant_id:
                self.tenant_metrics[metric.tenant_id][metric.name].append(metric)
            
            # Update real-time counters/gauges
            if metric.type == MetricType.COUNTER:
                self.counters[metric.name] += metric.value
            elif metric.type == MetricType.GAUGE:
                self.gauges[metric.name] = metric.value
            elif metric.type == MetricType.RATE:
                self.rates[metric.name].append((metric.timestamp, metric.value))
    
    def record_security_event(self, event_type: SecurityEvent, **kwargs):
        """Record a security event and generate metrics."""
        timestamp = datetime.utcnow()
        tenant_id = kwargs.get('tenant_id')
        user_id = kwargs.get('user_id')
        source_ip = kwargs.get('source_ip')
        
        # Record event
        event_data = {
            'type': event_type.value,
            'timestamp': timestamp,
            'tenant_id': tenant_id,
            'user_id': user_id,
            'source_ip': source_ip,
            'metadata': kwargs
        }
        
        with self.lock:
            self.events.append(event_data)
        
        # Generate specific metrics based on event type
        labels = {
            'event_type': event_type.value,
            'tenant_id': tenant_id or 'unknown',
            'source_ip': source_ip or 'unknown'
        }
        
        # General event counter
        self.record_metric(SecurityMetric(
            name=f"security_events_total",
            type=MetricType.COUNTER,
            value=1,
            timestamp=timestamp,
            labels=labels,
            description=f"Total security events of type {event_type.value}",
            tenant_id=tenant_id,
            user_id=user_id
        ))
        
        # Specific event metrics
        self._handle_specific_event_metrics(event_type, timestamp, **kwargs)
    
    def _handle_specific_event_metrics(self, event_type: SecurityEvent, timestamp: datetime, **kwargs):
        """Handle metrics for specific event types."""
        tenant_id = kwargs.get('tenant_id')
        user_id = kwargs.get('user_id')
        source_ip = kwargs.get('source_ip')
        
        if event_type == SecurityEvent.LOGIN_SUCCESS:
            with self.lock:
                self.login_attempts[source_ip or 'unknown'].append(timestamp)
            
            self.record_metric(SecurityMetric(
                name="login_success_total",
                type=MetricType.COUNTER,
                value=1,
                timestamp=timestamp,
                labels={'tenant_id': tenant_id or 'unknown', 'source_ip': source_ip or 'unknown'},
                description="Successful login attempts",
                tenant_id=tenant_id,
                user_id=user_id
            ))
        
        elif event_type == SecurityEvent.LOGIN_FAILURE:
            with self.lock:
                self.failed_logins[source_ip or 'unknown'].append(timestamp)
            
            self.record_metric(SecurityMetric(
                name="login_failure_total",
                type=MetricType.COUNTER,
                value=1,
                timestamp=timestamp,
                labels={'tenant_id': tenant_id or 'unknown', 'source_ip': source_ip or 'unknown'},
                description="Failed login attempts",
                tenant_id=tenant_id,
                user_id=user_id
            ))
            
            # Check for brute force
            self._check_brute_force_attack(source_ip, timestamp)
        
        elif event_type == SecurityEvent.PERMISSION_DENIED:
            self.record_metric(SecurityMetric(
                name="permission_denied_total",
                type=MetricType.COUNTER,
                value=1,
                timestamp=timestamp,
                labels={'tenant_id': tenant_id or 'unknown', 'resource': kwargs.get('resource', 'unknown')},
                description="Permission denied events",
                tenant_id=tenant_id,
                user_id=user_id
            ))
        
        elif event_type == SecurityEvent.THREAT_DETECTED:
            threat_type = kwargs.get('threat_type', 'unknown')
            confidence = kwargs.get('confidence', 0.5)
            
            self.record_metric(SecurityMetric(
                name="threats_detected_total",
                type=MetricType.COUNTER,
                value=1,
                timestamp=timestamp,
                labels={'threat_type': threat_type, 'tenant_id': tenant_id or 'unknown'},
                description="Detected security threats",
                tenant_id=tenant_id,
                user_id=user_id
            ))
            
            self.record_metric(SecurityMetric(
                name="threat_confidence_score",
                type=MetricType.GAUGE,
                value=confidence,
                timestamp=timestamp,
                labels={'threat_type': threat_type, 'tenant_id': tenant_id or 'unknown'},
                description="Threat detection confidence score",
                tenant_id=tenant_id,
                user_id=user_id
            ))
        
        elif event_type == SecurityEvent.DATA_EXPORT:
            data_size = kwargs.get('data_size', 0)
            
            self.record_metric(SecurityMetric(
                name="data_exports_total",
                type=MetricType.COUNTER,
                value=1,
                timestamp=timestamp,
                labels={'tenant_id': tenant_id or 'unknown'},
                description="Data export operations",
                tenant_id=tenant_id,
                user_id=user_id
            ))
            
            self.record_metric(SecurityMetric(
                name="data_exported_bytes",
                type=MetricType.COUNTER,
                value=data_size,
                timestamp=timestamp,
                labels={'tenant_id': tenant_id or 'unknown'},
                description="Total bytes exported",
                tenant_id=tenant_id,
                user_id=user_id
            ))
    
    def _check_brute_force_attack(self, source_ip: str, timestamp: datetime):
        """Check for potential brute force attacks."""
        if not source_ip:
            return
        
        with self.lock:
            failed_attempts = self.failed_logins[source_ip]
            
            # Check attempts in last 5 minutes
            recent_failures = [
                t for t in failed_attempts 
                if (timestamp - t).total_seconds() <= 300
            ]
            
            if len(recent_failures) >= 5:  # 5 failures in 5 minutes
                self.blocked_ips.add(source_ip)
                
                # Record brute force detection
                self.record_metric(SecurityMetric(
                    name="brute_force_detected_total",
                    type=MetricType.COUNTER,
                    value=1,
                    timestamp=timestamp,
                    labels={'source_ip': source_ip},
                    description="Brute force attacks detected",
                    tenant_id=None,
                    user_id=None
                ))
    
    def record_operation_timing(self, operation: str, duration: float, **labels):
        """Record operation timing metrics."""
        timestamp = datetime.utcnow()
        
        with self.lock:
            self.operation_timings[operation].append(duration)
        
        self.record_metric(SecurityMetric(
            name=f"{operation}_duration_seconds",
            type=MetricType.HISTOGRAM,
            value=duration,
            timestamp=timestamp,
            labels=labels,
            description=f"Duration of {operation} operations",
            tenant_id=labels.get('tenant_id'),
            user_id=labels.get('user_id')
        ))
    
    def get_metric_summary(self, metric_name: str, window_minutes: int = 60) -> Dict[str, float]:
        """Get summary statistics for a metric."""
        cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
        
        with self.lock:
            metrics = [
                m for m in self.metrics[metric_name]
                if m.timestamp >= cutoff_time
            ]
        
        if not metrics:
            return {}
        
        values = [m.value for m in metrics]
        
        return {
            'count': len(values),
            'sum': sum(values),
            'average': statistics.mean(values),
            'median': statistics.median(values),
            'min': min(values),
            'max': max(values),
            'std_dev': statistics.stdev(values) if len(values) > 1 else 0
        }
    
    def get_tenant_metrics(self, tenant_id: str, window_minutes: int = 60) -> Dict[str, Dict[str, float]]:
        """Get metrics summary for a specific tenant."""
        result = {}
        
        with self.lock:
            tenant_data = self.tenant_metrics.get(tenant_id, {})
            
            for metric_name, metric_deque in tenant_data.items():
                cutoff_time = datetime.utcnow() - timedelta(minutes=window_minutes)
                
                metrics = [
                    m for m in metric_deque
                    if m.timestamp >= cutoff_time
                ]
                
                if metrics:
                    values = [m.value for m in metrics]
                    result[metric_name] = {
                        'count': len(values),
                        'sum': sum(values),
                        'average': statistics.mean(values),
                        'latest': values[-1] if values else 0
                    }
        
        return result
    
    def get_security_dashboard_data(self) -> Dict[str, Any]:
        """Get comprehensive security dashboard data."""
        now = datetime.utcnow()
        hour_ago = now - timedelta(hours=1)
        day_ago = now - timedelta(days=1)
        
        with self.lock:
            # Recent events
            recent_events = [
                e for e in self.events
                if e['timestamp'] >= hour_ago
            ]
            
            # Event counts by type
            event_counts = defaultdict(int)
            for event in recent_events:
                event_counts[event['type']] += 1
            
            # Failed login analysis
            recent_failures = []
            for ip, failures in self.failed_logins.items():
                recent = [f for f in failures if f >= hour_ago]
                if recent:
                    recent_failures.append({
                        'ip': ip,
                        'count': len(recent),
                        'blocked': ip in self.blocked_ips
                    })
            
            # Top metrics
            top_metrics = {}
            for metric_name in ['login_success_total', 'login_failure_total', 'threats_detected_total']:
                summary = self.get_metric_summary(metric_name, 60)
                top_metrics[metric_name] = summary
        
        return {
            'timestamp': now.isoformat(),
            'summary': {
                'total_events_last_hour': len(recent_events),
                'unique_ips_last_hour': len(set(e.get('source_ip') for e in recent_events if e.get('source_ip'))),
                'blocked_ips_count': len(self.blocked_ips),
                'active_threats': len([e for e in recent_events if e['type'] == SecurityEvent.THREAT_DETECTED.value])
            },
            'event_counts': dict(event_counts),
            'failed_login_analysis': sorted(recent_failures, key=lambda x: x['count'], reverse=True)[:10],
            'metric_summaries': top_metrics,
            'blocked_ips': list(self.blocked_ips)[:20]  # Limit for display
        }
    
    def cleanup_old_data(self):
        """Clean up old metrics and events."""
        cutoff_time = datetime.utcnow() - timedelta(days=self.retention_days)
        
        with self.lock:
            # Clean main metrics
            for metric_name, metric_deque in self.metrics.items():
                # Remove old metrics
                while metric_deque and metric_deque[0].timestamp < cutoff_time:
                    metric_deque.popleft()
            
            # Clean tenant metrics
            for tenant_id, tenant_data in self.tenant_metrics.items():
                for metric_name, metric_deque in tenant_data.items():
                    while metric_deque and metric_deque[0].timestamp < cutoff_time:
                        metric_deque.popleft()
            
            # Clean events
            while self.events and self.events[0]['timestamp'] < cutoff_time:
                self.events.popleft()
            
            # Clean login attempts
            for ip, attempts in self.login_attempts.items():
                while attempts and attempts[0] < cutoff_time:
                    attempts.popleft()
            
            for ip, failures in self.failed_logins.items():
                while failures and failures[0] < cutoff_time:
                    failures.popleft()
    
    def _start_cleanup_task(self):
        """Start background cleanup task."""
        def cleanup_worker():
            while True:
                try:
                    time.sleep(3600)  # Run every hour
                    self.cleanup_old_data()
                except Exception as e:
                    logger.error(f"Error in cleanup task: {e}")
        
        self._cleanup_task = threading.Thread(target=cleanup_worker, daemon=True)
        self._cleanup_task.start()


class SecurityAlertsManager:
    """Advanced security alerts management system."""
    
    def __init__(self, metrics_collector: SecurityMetricsCollector):
        """Initialize alerts manager."""
        self.metrics_collector = metrics_collector
        self.alerts: deque = deque(maxlen=10000)
        self.alert_rules: List[MetricThreshold] = []
        self.active_alerts: Dict[str, SecurityAlert] = {}
        self.lock = threading.RLock()
        
        # Configure default alert rules
        self._setup_default_alert_rules()
        
        # Start monitoring task
        self._monitoring_task = None
        self._start_monitoring_task()
    
    def _setup_default_alert_rules(self):
        """Setup default security alert rules."""
        self.alert_rules = [
            MetricThreshold(
                metric_name="login_failure_total",
                warning_threshold=10,
                critical_threshold=25,
                evaluation_window=300,  # 5 minutes
                evaluation_method="sum"
            ),
            MetricThreshold(
                metric_name="threats_detected_total",
                warning_threshold=1,
                critical_threshold=5,
                evaluation_window=300,
                evaluation_method="sum"
            ),
            MetricThreshold(
                metric_name="permission_denied_total",
                warning_threshold=20,
                critical_threshold=50,
                evaluation_window=600,  # 10 minutes
                evaluation_method="sum"
            ),
            MetricThreshold(
                metric_name="brute_force_detected_total",
                warning_threshold=1,
                critical_threshold=3,
                evaluation_window=3600,  # 1 hour
                evaluation_method="sum"
            )
        ]
    
    def create_alert(
        self,
        name: str,
        severity: AlertSeverity,
        message: str,
        tenant_id: str,
        event_type: SecurityEvent,
        **kwargs
    ) -> SecurityAlert:
        """Create a new security alert."""
        alert_id = hashlib.sha256(
            f"{name}_{tenant_id}_{datetime.utcnow().isoformat()}".encode()
        ).hexdigest()[:16]
        
        alert = SecurityAlert(
            alert_id=alert_id,
            name=name,
            severity=severity,
            message=message,
            timestamp=datetime.utcnow(),
            tenant_id=tenant_id,
            user_id=kwargs.get('user_id'),
            event_type=event_type,
            source_ip=kwargs.get('source_ip'),
            metadata=kwargs
        )
        
        with self.lock:
            self.alerts.append(alert)
            
            # Track active alerts for critical/high severity
            if severity in [AlertSeverity.CRITICAL, AlertSeverity.HIGH]:
                self.active_alerts[alert_id] = alert
        
        logger.warning(f"Security alert created: {severity.value.upper()} - {message}")
        return alert
    
    def resolve_alert(self, alert_id: str, resolved_by: str) -> bool:
        """Resolve an active alert."""
        with self.lock:
            if alert_id in self.active_alerts:
                alert = self.active_alerts[alert_id]
                alert.resolved = True
                alert.resolved_at = datetime.utcnow()
                alert.resolved_by = resolved_by
                
                del self.active_alerts[alert_id]
                
                logger.info(f"Alert {alert_id} resolved by {resolved_by}")
                return True
        
        return False
    
    def evaluate_alert_rules(self):
        """Evaluate all alert rules against current metrics."""
        for rule in self.alert_rules:
            try:
                self._evaluate_single_rule(rule)
            except Exception as e:
                logger.error(f"Error evaluating alert rule {rule.metric_name}: {e}")
    
    def _evaluate_single_rule(self, rule: MetricThreshold):
        """Evaluate a single alert rule."""
        summary = self.metrics_collector.get_metric_summary(
            rule.metric_name,
            rule.evaluation_window // 60  # Convert to minutes
        )
        
        if not summary:
            return
        
        # Get evaluation value based on method
        if rule.evaluation_method == "sum":
            value = summary.get('sum', 0)
        elif rule.evaluation_method == "average":
            value = summary.get('average', 0)
        elif rule.evaluation_method == "max":
            value = summary.get('max', 0)
        elif rule.evaluation_method == "min":
            value = summary.get('min', 0)
        else:
            value = summary.get('sum', 0)  # Default to sum
        
        # Check thresholds
        if value >= rule.critical_threshold:
            self._create_threshold_alert(rule, value, AlertSeverity.CRITICAL)
        elif value >= rule.warning_threshold:
            self._create_threshold_alert(rule, value, AlertSeverity.HIGH)
    
    def _create_threshold_alert(self, rule: MetricThreshold, value: float, severity: AlertSeverity):
        """Create an alert for threshold violation."""
        # Check if similar alert is already active
        alert_key = f"{rule.metric_name}_{severity.value}"
        
        with self.lock:
            # Don't create duplicate alerts within a time window
            recent_similar = [
                a for a in self.alerts
                if (a.name == alert_key and
                    (datetime.utcnow() - a.timestamp).total_seconds() < 300)  # 5 minutes
            ]
            
            if recent_similar:
                return
        
        message = (
            f"Metric {rule.metric_name} exceeded {severity.value} threshold. "
            f"Current value: {value:.2f}, Threshold: {rule.critical_threshold if severity == AlertSeverity.CRITICAL else rule.warning_threshold}"
        )
        
        self.create_alert(
            name=alert_key,
            severity=severity,
            message=message,
            tenant_id="system",  # System-level alert
            event_type=SecurityEvent.ANOMALY_DETECTED,
            metric_name=rule.metric_name,
            metric_value=value,
            threshold=rule.critical_threshold if severity == AlertSeverity.CRITICAL else rule.warning_threshold
        )
    
    def get_active_alerts(self, tenant_id: Optional[str] = None) -> List[SecurityAlert]:
        """Get active alerts, optionally filtered by tenant."""
        with self.lock:
            alerts = list(self.active_alerts.values())
            
            if tenant_id:
                alerts = [a for a in alerts if a.tenant_id == tenant_id]
            
            return sorted(alerts, key=lambda x: x.timestamp, reverse=True)
    
    def get_alert_statistics(self, hours: int = 24) -> Dict[str, Any]:
        """Get alert statistics for the specified time period."""
        cutoff_time = datetime.utcnow() - timedelta(hours=hours)
        
        with self.lock:
            recent_alerts = [
                a for a in self.alerts
                if a.timestamp >= cutoff_time
            ]
        
        if not recent_alerts:
            return {
                'total_alerts': 0,
                'by_severity': {},
                'by_event_type': {},
                'by_tenant': {},
                'resolution_rate': 0
            }
        
        # Count by severity
        by_severity = defaultdict(int)
        for alert in recent_alerts:
            by_severity[alert.severity.value] += 1
        
        # Count by event type
        by_event_type = defaultdict(int)
        for alert in recent_alerts:
            by_event_type[alert.event_type.value] += 1
        
        # Count by tenant
        by_tenant = defaultdict(int)
        for alert in recent_alerts:
            by_tenant[alert.tenant_id] += 1
        
        # Calculate resolution rate
        resolved_count = len([a for a in recent_alerts if a.resolved])
        resolution_rate = (resolved_count / len(recent_alerts)) * 100 if recent_alerts else 0
        
        return {
            'total_alerts': len(recent_alerts),
            'by_severity': dict(by_severity),
            'by_event_type': dict(by_event_type),
            'by_tenant': dict(by_tenant),
            'resolution_rate': round(resolution_rate, 2),
            'active_alerts_count': len(self.active_alerts)
        }
    
    def _start_monitoring_task(self):
        """Start background monitoring task."""
        def monitoring_worker():
            while True:
                try:
                    time.sleep(60)  # Evaluate every minute
                    self.evaluate_alert_rules()
                except Exception as e:
                    logger.error(f"Error in monitoring task: {e}")
        
        self._monitoring_task = threading.Thread(target=monitoring_worker, daemon=True)
        self._monitoring_task.start()


class SecurityReportGenerator:
    """Advanced security reporting system."""
    
    def __init__(self, metrics_collector: SecurityMetricsCollector, alerts_manager: SecurityAlertsManager):
        """Initialize report generator."""
        self.metrics_collector = metrics_collector
        self.alerts_manager = alerts_manager
    
    def generate_security_summary_report(self, tenant_id: Optional[str] = None, hours: int = 24) -> Dict[str, Any]:
        """Generate comprehensive security summary report."""
        cutoff_time = datetime.utcnow() - timedelta(hours=hours)
        
        # Get dashboard data
        dashboard_data = self.metrics_collector.get_security_dashboard_data()
        
        # Get alert statistics
        alert_stats = self.alerts_manager.get_alert_statistics(hours)
        
        # Get tenant-specific metrics if requested
        tenant_metrics = {}
        if tenant_id:
            tenant_metrics = self.metrics_collector.get_tenant_metrics(tenant_id, hours * 60)
        
        # Calculate security score
        security_score = self._calculate_security_score(dashboard_data, alert_stats)
        
        # Generate recommendations
        recommendations = self._generate_security_recommendations(dashboard_data, alert_stats)
        
        return {
            'report_metadata': {
                'generated_at': datetime.utcnow().isoformat(),
                'report_period_hours': hours,
                'tenant_id': tenant_id,
                'report_type': 'security_summary'
            },
            'security_score': security_score,
            'dashboard_summary': dashboard_data['summary'],
            'event_analysis': {
                'total_events': dashboard_data['summary']['total_events_last_hour'] * hours,  # Approximation
                'event_breakdown': dashboard_data['event_counts'],
                'top_source_ips': dashboard_data['failed_login_analysis'][:5]
            },
            'alert_analysis': alert_stats,
            'tenant_metrics': tenant_metrics,
            'security_recommendations': recommendations,
            'threat_landscape': {
                'blocked_ips': len(dashboard_data['blocked_ips']),
                'active_threats': dashboard_data['summary']['active_threats'],
                'risk_level': self._assess_risk_level(dashboard_data, alert_stats)
            }
        }
    
    def generate_compliance_report(self, tenant_id: str, framework: str = "GDPR") -> Dict[str, Any]:
        """Generate compliance report for specific framework."""
        # Get tenant metrics
        tenant_metrics = self.metrics_collector.get_tenant_metrics(tenant_id, 24 * 60)
        
        # Get tenant alerts
        tenant_alerts = [
            a for a in self.alerts_manager.get_active_alerts(tenant_id)
        ]
        
        # Framework-specific compliance checks
        compliance_checks = self._perform_compliance_checks(tenant_id, framework, tenant_metrics, tenant_alerts)
        
        return {
            'report_metadata': {
                'generated_at': datetime.utcnow().isoformat(),
                'tenant_id': tenant_id,
                'compliance_framework': framework,
                'report_type': 'compliance'
            },
            'compliance_score': compliance_checks['overall_score'],
            'compliance_status': compliance_checks['status'],
            'findings': compliance_checks['findings'],
            'recommendations': compliance_checks['recommendations'],
            'metrics_summary': tenant_metrics,
            'active_violations': len(tenant_alerts)
        }
    
    def _calculate_security_score(self, dashboard_data: Dict[str, Any], alert_stats: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate overall security score."""
        base_score = 100
        
        # Deduct for active threats
        threat_penalty = dashboard_data['summary']['active_threats'] * 10
        
        # Deduct for critical alerts
        critical_alerts = alert_stats.get('by_severity', {}).get('critical', 0)
        critical_penalty = critical_alerts * 15
        
        # Deduct for high alerts
        high_alerts = alert_stats.get('by_severity', {}).get('high', 0)
        high_penalty = high_alerts * 8
        
        # Deduct for blocked IPs (indicates attacks)
        blocked_ips_penalty = min(dashboard_data['summary']['blocked_ips_count'] * 2, 20)
        
        # Bonus for alert resolution rate
        resolution_bonus = alert_stats.get('resolution_rate', 0) * 0.2
        
        final_score = max(0, base_score - threat_penalty - critical_penalty - high_penalty - blocked_ips_penalty + resolution_bonus)
        
        # Determine grade
        if final_score >= 95:
            grade = "A+"
        elif final_score >= 90:
            grade = "A"
        elif final_score >= 85:
            grade = "A-"
        elif final_score >= 80:
            grade = "B+"
        elif final_score >= 75:
            grade = "B"
        elif final_score >= 70:
            grade = "B-"
        elif final_score >= 60:
            grade = "C"
        else:
            grade = "D"
        
        return {
            'score': round(final_score, 2),
            'grade': grade,
            'breakdown': {
                'base_score': base_score,
                'threat_penalty': threat_penalty,
                'critical_alert_penalty': critical_penalty,
                'high_alert_penalty': high_penalty,
                'blocked_ips_penalty': blocked_ips_penalty,
                'resolution_bonus': round(resolution_bonus, 2)
            }
        }
    
    def _generate_security_recommendations(self, dashboard_data: Dict[str, Any], alert_stats: Dict[str, Any]) -> List[str]:
        """Generate security recommendations based on data."""
        recommendations = []
        
        # Check for high number of failed logins
        if dashboard_data['summary']['total_events_last_hour'] > 100:
            recommendations.append("High activity detected - consider implementing additional rate limiting")
        
        # Check for critical alerts
        critical_alerts = alert_stats.get('by_severity', {}).get('critical', 0)
        if critical_alerts > 0:
            recommendations.append(f"Address {critical_alerts} critical security alerts immediately")
        
        # Check for blocked IPs
        if dashboard_data['summary']['blocked_ips_count'] > 10:
            recommendations.append("High number of blocked IPs - review network security controls")
        
        # Check alert resolution rate
        if alert_stats.get('resolution_rate', 100) < 80:
            recommendations.append("Improve alert response times - current resolution rate below 80%")
        
        # Check for active threats
        if dashboard_data['summary']['active_threats'] > 0:
            recommendations.append("Active threats detected - initiate incident response procedures")
        
        # Default recommendations
        if not recommendations:
            recommendations.append("Security posture is good - continue monitoring and maintain current controls")
        
        return recommendations
    
    def _assess_risk_level(self, dashboard_data: Dict[str, Any], alert_stats: Dict[str, Any]) -> str:
        """Assess overall security risk level."""
        risk_score = 0
        
        # Factor in active threats
        risk_score += dashboard_data['summary']['active_threats'] * 3
        
        # Factor in critical alerts
        risk_score += alert_stats.get('by_severity', {}).get('critical', 0) * 4
        
        # Factor in high alerts
        risk_score += alert_stats.get('by_severity', {}).get('high', 0) * 2
        
        # Factor in blocked IPs
        risk_score += min(dashboard_data['summary']['blocked_ips_count'], 10)
        
        if risk_score >= 15:
            return "CRITICAL"
        elif risk_score >= 10:
            return "HIGH"
        elif risk_score >= 5:
            return "MEDIUM"
        else:
            return "LOW"
    
    def _perform_compliance_checks(self, tenant_id: str, framework: str, metrics: Dict[str, Any], alerts: List[SecurityAlert]) -> Dict[str, Any]:
        """Perform compliance checks for specific framework."""
        findings = []
        recommendations = []
        score = 100
        
        if framework == "GDPR":
            # Check for data access logging
            if 'data_access_total' not in metrics:
                findings.append("Data access logging not implemented")
                recommendations.append("Implement comprehensive data access logging")
                score -= 20
            
            # Check for data export monitoring
            if 'data_exports_total' not in metrics:
                findings.append("Data export monitoring not implemented")
                recommendations.append("Implement data export monitoring and controls")
                score -= 15
            
            # Check for policy violations
            policy_violations = [a for a in alerts if a.event_type == SecurityEvent.POLICY_VIOLATION]
            if policy_violations:
                findings.append(f"Active policy violations detected: {len(policy_violations)}")
                recommendations.append("Address policy violations to ensure GDPR compliance")
                score -= len(policy_violations) * 5
        
        elif framework == "SOX":
            # Check for audit logging
            if 'audit_log_access_total' not in metrics:
                findings.append("Audit log access monitoring not implemented")
                recommendations.append("Implement audit log access monitoring")
                score -= 25
            
            # Check for unauthorized access
            if 'permission_denied_total' in metrics:
                denials = metrics['permission_denied_total'].get('sum', 0)
                if denials > 50:
                    findings.append(f"High number of permission denials: {denials}")
                    recommendations.append("Review access controls and user permissions")
                    score -= 10
        
        # Determine status
        if score >= 95:
            status = "COMPLIANT"
        elif score >= 80:
            status = "MOSTLY_COMPLIANT"
        elif score >= 60:
            status = "PARTIALLY_COMPLIANT"
        else:
            status = "NON_COMPLIANT"
        
        return {
            'overall_score': max(0, score),
            'status': status,
            'findings': findings,
            'recommendations': recommendations
        }


