@dataclass
class CryptographicKey:
    """Représentation d'une clé cryptographique."""
    key_id: str
    algorithm: str
    key_type: str  # 'symmetric', 'asymmetric_public', 'asymmetric_private'
    key_material: bytes
    created_at: datetime
    expires_at: Optional[datetime]
