class PasswordPolicy:
    """Password policy configuration."""
    
    def __init__(self):
        """Initialize password policy with secure defaults."""
        self.min_length = 12
        self.max_length = 128
        self.require_uppercase = True
        self.require_lowercase = True
        self.require_digits = True
        self.require_special_chars = True
        self.max_age_days = 90
        self.history_count = 12
        self.lockout_attempts = 5
        self.lockout_duration_minutes = 30
        
        self.forbidden_patterns = [
            r"password",
            r"123456",
            r"qwerty",
            r"admin",
            r"spotify",
            r"(\w)\1{3,}",  # Repeated characters
        ]
    
    def validate_password(self, password: str, username: str = "") -> Tuple[bool, List[str]]:
        """Validate password against policy."""
        errors = []
        
        # Length check
        if len(password) < self.min_length:
            errors.append(f"Password must be at least {self.min_length} characters long")
        
        if len(password) > self.max_length:
            errors.append(f"Password must not exceed {self.max_length} characters")
        
        # Character requirements
        if self.require_uppercase and not re.search(r'[A-Z]', password):
            errors.append("Password must contain at least one uppercase letter")
        
        if self.require_lowercase and not re.search(r'[a-z]', password):
            errors.append("Password must contain at least one lowercase letter")
        
        if self.require_digits and not re.search(r'\d', password):
            errors.append("Password must contain at least one digit")
        
        if self.require_special_chars and not re.search(r'[!@#$%^&*(),.?":{}|<>]', password):
            errors.append("Password must contain at least one special character")
        
        # Forbidden patterns
        for pattern in self.forbidden_patterns:
            if re.search(pattern, password.lower()):
                errors.append("Password contains forbidden patterns")
                break
        
        # Username similarity
        if username and username.lower() in password.lower():
            errors.append("Password must not contain username")
        
        return len(errors) == 0, errors


class MFAManager:
    """Multi-Factor Authentication manager."""
    
    def __init__(self):
        """Initialize MFA manager."""
        self.totp_window = 30  # seconds
        self.backup_codes_count = 10
        
    def generate_mfa_secret(self) -> str:
        """Generate MFA secret for TOTP."""



        return base64.b32encode(secrets.token_bytes(20)).decode('utf-8').rstrip('=')
    
    def generate_backup_codes(self) -> List[str]:
        """Generate backup codes for MFA recovery."""



        return [secrets.token_hex(4).upper() for _ in range(self.backup_codes_count)]
    
    def verify_totp_code(self, secret: str, code: str, current_time: Optional[datetime] = None) -> bool:
        """Verify TOTP code against secret."""
        import hmac
        import struct
        import time
        
        if current_time is None:
            current_time = datetime.utcnow()
        
        timestamp = int(current_time.timestamp()) // self.totp_window
        
        # Check current window and adjacent windows
        for window in [-1, 0, 1]:
            test_timestamp = timestamp + window
            
            # Convert timestamp to bytes
            timestamp_bytes = struct.pack('>Q', test_timestamp)
            
            # Generate HMAC
            secret_bytes = base64.b32decode(secret.upper() + '=' * (-len(secret) % 8))
            hmac_hash = hmac.new(secret_bytes, timestamp_bytes, hashlib.sha1).digest()
            
            # Extract dynamic binary code
            offset = hmac_hash[19] & 0xf
            code_bytes = hmac_hash[offset:offset + 4]
            dynamic_code = struct.unpack('>I', code_bytes)[0] & 0x7fffffff
            
            # Generate 6-digit code
            generated_code = str(dynamic_code % 1000000).zfill(6)
            
            if generated_code == code:
                return True
        
        return False
    
    def generate_qr_code(self, secret: str, username: str, issuer: str = "Spotify AI Agent") -> bytes:
        """Generate QR code for TOTP setup."""
        totp_uri = f"otpauth://totp/{issuer}:{username}?secret={secret}&issuer={issuer}"
        
        qr = qrcode.QRCode(version=1, box_size=10, border=5)
        qr.add_data(totp_uri)
        qr.make(fit=True)
        
        img = qr.make_image(fill_color="black", back_color="white")
        img_buffer = BytesIO()
        img.save(img_buffer, format='PNG')
        return img_buffer.getvalue()


class AdvancedEncryptionManager:
    """Advanced encryption management for sensitive data."""
    
    def __init__(self, master_key: Optional[bytes] = None):
        """Initialize encryption manager."""
        if master_key is None:
            master_key = os.environ.get('ENCRYPTION_MASTER_KEY', '').encode()
            if not master_key:
                master_key = Fernet.generate_key()
        
        self.master_key = master_key
        self.fernet = Fernet(self.master_key)
        
        # Generate RSA key pair for asymmetric encryption
        self.private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048
        )
        self.public_key = self.private_key.public_key()
    
    def encrypt_data(self, data: str) -> str:
        """Encrypt data using Fernet symmetric encryption."""



        return self.fernet.encrypt(data.encode()).decode()
    
    def decrypt_data(self, encrypted_data: str) -> str:
        """Decrypt data using Fernet symmetric encryption."""



        return self.fernet.decrypt(encrypted_data.encode()).decode()
    
    def encrypt_with_password(self, data: str, password: str) -> str:
        """Encrypt data with password-based key derivation."""
        salt = os.urandom(16)
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(password.encode()))
        fernet = Fernet(key)
        
        encrypted = fernet.encrypt(data.encode())
        return base64.b64encode(salt + encrypted).decode()
    
    def decrypt_with_password(self, encrypted_data: str, password: str) -> str:
        """Decrypt data with password-based key derivation."""
        data = base64.b64decode(encrypted_data.encode())
        salt = data[:16]
        encrypted = data[16:]
        
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        key = base64.urlsafe_b64encode(kdf.derive(password.encode()))
        fernet = Fernet(key)
        
        return fernet.decrypt(encrypted).decode()
    
    def rsa_encrypt(self, data: str) -> str:
        """Encrypt data using RSA public key."""
        encrypted = self.public_key.encrypt(
            data.encode(),
            padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            )
        )
        return base64.b64encode(encrypted).decode()
    
    def rsa_decrypt(self, encrypted_data: str) -> str:
        """Decrypt data using RSA private key."""
        encrypted = base64.b64decode(encrypted_data.encode())
        decrypted = self.private_key.decrypt(
            encrypted,
            padding.OAEP(
                mgf=padding.MGF1(algorithm=hashes.SHA256()),
                algorithm=hashes.SHA256(),
                label=None
            )
        )
        return decrypted.decode()
    
    def get_public_key_pem(self) -> str:
        """Get public key in PEM format."""



        return self.public_key.public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo
        ).decode()
    
    def get_private_key_pem(self) -> str:
        """Get private key in PEM format."""



        return self.private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.PKCS8,
            encryption_algorithm=serialization.NoEncryption()
        ).decode()


class SecurityAuditLogger:
    """Advanced security audit logging system."""
    
    def __init__(self, redis_client: Optional[aioredis.Redis] = None):
        """Initialize audit logger."""
        self.redis_client = redis_client
        self.audit_events: List[Dict[str, Any]] = []
        self.max_events = 10000
        
    async def log_authentication_event(
        self,
        user_id: str,
        tenant_id: str,
        event_type: str,
        success: bool,
        method: AuthenticationMethod,
        ip_address: Optional[str] = None,
        user_agent: Optional[str] = None,
        additional_data: Optional[Dict[str, Any]] = None
    ):
        """Log authentication event."""
        event = {
            "event_id": str(uuid.uuid4()),
            "timestamp": datetime.utcnow().isoformat(),
            "event_type": "authentication",
            "event_subtype": event_type,
            "user_id": user_id,
            "tenant_id": tenant_id,
            "success": success,
            "authentication_method": method.value,
            "ip_address": ip_address,
            "user_agent": user_agent,
            "additional_data": additional_data or {}
        }
        
        await self._store_audit_event(event)
        logger.info(f"Authentication event logged: {event_type} for user {user_id} ({'success' if success else 'failure'})")
    
    async def log_authorization_event(
        self,
        user_id: str,
        tenant_id: str,
        resource: str,
        action: str,
        permission: str,
        granted: bool,
        ip_address: Optional[str] = None,
        additional_data: Optional[Dict[str, Any]] = None
    ):
        """Log authorization event."""
        event = {
            "event_id": str(uuid.uuid4()),
            "timestamp": datetime.utcnow().isoformat(),
            "event_type": "authorization",
            "user_id": user_id,
            "tenant_id": tenant_id,
            "resource": resource,
            "action": action,
            "permission": permission,
            "granted": granted,
            "ip_address": ip_address,
            "additional_data": additional_data or {}
        }
        
        await self._store_audit_event(event)
        logger.info(f"Authorization event logged: {action} on {resource} for user {user_id} ({'granted' if granted else 'denied'})")
    
    async def log_security_event(
        self,
        event_type: str,
        severity: str,
        description: str,
        user_id: Optional[str] = None,
        tenant_id: Optional[str] = None,
        ip_address: Optional[str] = None,
        additional_data: Optional[Dict[str, Any]] = None
    ):
        """Log general security event."""
        event = {
            "event_id": str(uuid.uuid4()),
            "timestamp": datetime.utcnow().isoformat(),
            "event_type": "security",
            "event_subtype": event_type,
            "severity": severity,
            "description": description,
            "user_id": user_id,
            "tenant_id": tenant_id,
            "ip_address": ip_address,
            "additional_data": additional_data or {}
        }
        
        await self._store_audit_event(event)
        logger.warning(f"Security event logged: {event_type} - {description}")
    
    async def _store_audit_event(self, event: Dict[str, Any]):
        """Store audit event in storage."""
        # Store in memory
        self.audit_events.append(event)
        if len(self.audit_events) > self.max_events:
            self.audit_events = self.audit_events[-self.max_events:]
        
        # Store in Redis if available
        if self.redis_client:
            try:
                key = f"audit_event:{event['event_id']}"
                await self.redis_client.setex(key, 86400 * 30, json.dumps(event))  # 30 days retention
                
                # Add to tenant-specific index
                if event.get('tenant_id'):
                    tenant_key = f"audit_events:tenant:{event['tenant_id']}"
                    await self.redis_client.lpush(tenant_key, event['event_id'])
                    await self.redis_client.ltrim(tenant_key, 0, 9999)  # Keep last 10k events
                
            except Exception as e:
                logger.error(f"Failed to store audit event in Redis: {e}")
    
    async def get_audit_events(
        self,
        tenant_id: Optional[str] = None,
        user_id: Optional[str] = None,
        event_type: Optional[str] = None,
        start_time: Optional[datetime] = None,
        end_time: Optional[datetime] = None,
        limit: int = 100
    ) -> List[Dict[str, Any]]:
        """Get audit events with filtering."""
        events = self.audit_events.copy()
        
        # Apply filters
        if tenant_id:
            events = [e for e in events if e.get('tenant_id') == tenant_id]
        
        if user_id:
            events = [e for e in events if e.get('user_id') == user_id]
        
        if event_type:
            events = [e for e in events if e.get('event_type') == event_type]
        
        if start_time:
            events = [e for e in events if datetime.fromisoformat(e['timestamp']) >= start_time]
        
        if end_time:
            events = [e for e in events if datetime.fromisoformat(e['timestamp']) <= end_time]
        
        # Sort by timestamp (newest first)
        events.sort(key=lambda x: x['timestamp'], reverse=True)
        
        return events[:limit]


class SessionManager:
    """Advanced session management with security features."""
    
    def __init__(self, redis_client: Optional[aioredis.Redis] = None):
        """Initialize session manager."""
        self.redis_client = redis_client
        self.sessions: Dict[str, Dict[str, Any]] = {}
        self.session_timeout = 3600  # 1 hour
        self.max_sessions_per_user = 5
        self.concurrent_session_check = True
    
    async def create_session(
        self,
        user_id: str,
        tenant_id: str,
        ip_address: Optional[str] = None,
        user_agent: Optional[str] = None,
        additional_data: Optional[Dict[str, Any]] = None
    ) -> str:
        """Create new session."""
        session_id = str(uuid.uuid4())
        
        # Check concurrent sessions
        if self.concurrent_session_check:
            await self._cleanup_user_sessions(user_id)
        
        session_data = {
            "session_id": session_id,
            "user_id": user_id,
            "tenant_id": tenant_id,
            "created_at": datetime.utcnow().isoformat(),
            "last_activity": datetime.utcnow().isoformat(),
            "ip_address": ip_address,
            "user_agent": user_agent,
            "additional_data": additional_data or {},
            "is_active": True
        }
        
        # Store session
        await self._store_session(session_id, session_data)
        
        logger.info(f"Session created for user {user_id}: {session_id}")
        return session_id
    
    async def get_session(self, session_id: str) -> Optional[Dict[str, Any]]:
        """Get session data."""
        session_data = await self._get_session_data(session_id)
        
        if not session_data:
            return None
        
        # Check if session is expired
        last_activity = datetime.fromisoformat(session_data["last_activity"])
        if (datetime.utcnow() - last_activity).total_seconds() > self.session_timeout:
            await self._invalidate_session(session_id)
            return None
        
        # Update last activity
        session_data["last_activity"] = datetime.utcnow().isoformat()
        await self._store_session(session_id, session_data)
        
        return session_data
    
    async def invalidate_session(self, session_id: str) -> bool:
        """Invalidate session."""



        return await self._invalidate_session(session_id)
    
    async def invalidate_user_sessions(self, user_id: str) -> int:
        """Invalidate all sessions for a user."""
        count = 0
        
        if self.redis_client:
            try:
                # Get all session IDs for user
                pattern = f"session_user:{user_id}:*"
                async for key in self.redis_client.scan_iter(match=pattern):
                    session_id = key.decode().split(':')[-1]
                    if await self._invalidate_session(session_id):
                        count += 1
            except Exception as e:
                logger.error(f"Failed to invalidate user sessions: {e}")
        else:
            # Memory-based sessions
            sessions_to_remove = []
            for session_id, session_data in self.sessions.items():
                if session_data.get('user_id') == user_id:
                    sessions_to_remove.append(session_id)
            
            for session_id in sessions_to_remove:
                if await self._invalidate_session(session_id):
                    count += 1
        
        logger.info(f"Invalidated {count} sessions for user {user_id}")
        return count
    
    async def _store_session(self, session_id: str, session_data: Dict[str, Any]):
        """Store session data."""
        if self.redis_client:
            try:
                # Store session data
                session_key = f"session:{session_id}"
                await self.redis_client.setex(session_key, self.session_timeout, json.dumps(session_data))
                
                # Store user session mapping
                user_session_key = f"session_user:{session_data['user_id']}:{session_id}"
                await self.redis_client.setex(user_session_key, self.session_timeout, "1")
                
            except Exception as e:
                logger.error(f"Failed to store session in Redis: {e}")
                # Fallback to memory
                self.sessions[session_id] = session_data
        else:
            self.sessions[session_id] = session_data
    
    async def _get_session_data(self, session_id: str) -> Optional[Dict[str, Any]]:
        """Get session data from storage."""
        if self.redis_client:
            try:
                session_key = f"session:{session_id}"
                data = await self.redis_client.get(session_key)
                if data:
                    return json.loads(data)
            except Exception as e:
                logger.error(f"Failed to get session from Redis: {e}")
        
        return self.sessions.get(session_id)
    
    async def _invalidate_session(self, session_id: str) -> bool:
        """Invalidate session in storage."""
        session_data = await self._get_session_data(session_id)
        if not session_data:
            return False
        
        if self.redis_client:
            try:
                # Remove session data
                session_key = f"session:{session_id}"
                await self.redis_client.delete(session_key)
                
                # Remove user session mapping
                user_session_key = f"session_user:{session_data['user_id']}:{session_id}"
                await self.redis_client.delete(user_session_key)
                
            except Exception as e:
                logger.error(f"Failed to invalidate session in Redis: {e}")
        
        # Remove from memory
        self.sessions.pop(session_id, None)
        
        return True
    
    async def _cleanup_user_sessions(self, user_id: str):
        """Cleanup old sessions for user to enforce limits."""
        user_sessions = []
        
        if self.redis_client:
            try:
                pattern = f"session_user:{user_id}:*"
                async for key in self.redis_client.scan_iter(match=pattern):
                    session_id = key.decode().split(':')[-1]
                    session_data = await self._get_session_data(session_id)
                    if session_data:
                        user_sessions.append((session_id, session_data))
            except Exception as e:
                logger.error(f"Failed to cleanup user sessions: {e}")
        else:
            user_sessions = [
                (sid, data) for sid, data in self.sessions.items()
                if data.get('user_id') == user_id
            ]
        
        # Sort by creation time and remove oldest if exceeding limit
        user_sessions.sort(key=lambda x: x[1]['created_at'])
        
        if len(user_sessions) >= self.max_sessions_per_user:
            sessions_to_remove = user_sessions[:-self.max_sessions_per_user + 1]
            for session_id, _ in sessions_to_remove:
                await self._invalidate_session(session_id)
                return True
        
        return False
    
    def generate_qr_code_url(self, secret: str, username: str, issuer: str = "Spotify AI Agent") -> str:
        """Generate QR code URL for authenticator apps."""
        import urllib.parse
        
        label = f"{issuer}:{username}"
        params = {
            'secret': secret,
            'issuer': issuer,
            'algorithm': 'SHA1',
            'digits': '6',
            'period': str(self.totp_window)
        }
        
        query_string = urllib.parse.urlencode(params)
        return f"otpauth://totp/{urllib.parse.quote(label)}?{query_string}"


class JWTManager:
    """JWT token manager for authentication."""
    
    def __init__(self, secret_key: Optional[str] = None):
        """Initialize JWT manager."""
        self.secret_key = secret_key or os.getenv("JWT_SECRET_KEY") or secrets.token_urlsafe(64)
        self.algorithm = "HS256"
        self.access_token_lifetime = timedelta(hours=1)
        self.refresh_token_lifetime = timedelta(days=7)
    
    def generate_access_token(self, user: User) -> str:
        """Generate JWT access token for user."""
        now = datetime.utcnow()
        payload = {
            "user_id": user.user_id,
            "username": user.username,
            "tenant_id": user.tenant_id,
            "roles": [role.value for role in user.roles],
            "permissions": [perm.value for perm in user.permissions],
            "iat": now,
            "exp": now + self.access_token_lifetime,
            "type": "access"
        }
        
        return jwt.encode(payload, self.secret_key, algorithm=self.algorithm)
    
    def generate_refresh_token(self, user: User) -> str:
        """Generate JWT refresh token for user."""
        now = datetime.utcnow()
        payload = {
            "user_id": user.user_id,
            "tenant_id": user.tenant_id,
            "iat": now,
            "exp": now + self.refresh_token_lifetime,
            "type": "refresh"
        }
        
        return jwt.encode(payload, self.secret_key, algorithm=self.algorithm)
    
    def verify_token(self, token: str) -> Optional[Dict[str, Any]]:
        """Verify and decode JWT token."""



        try:
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
            return payload
        except jwt.ExpiredSignatureError:
            logger.warning("JWT token expired")
            return None
        except jwt.InvalidTokenError as e:
            logger.warning(f"Invalid JWT token: {e}")
            return None
    
    def refresh_access_token(self, refresh_token: str) -> Optional[str]:
        """Generate new access token from refresh token."""
        payload = self.verify_token(refresh_token)
        
        if not payload or payload.get("type") != "refresh":
            return None
        
        # In production, fetch updated user data from database
        # For now, create minimal payload
        now = datetime.utcnow()
        new_payload = {
            "user_id": payload["user_id"],
            "tenant_id": payload["tenant_id"],
            "iat": now,
            "exp": now + self.access_token_lifetime,
            "type": "access"
        }
        
        return jwt.encode(new_payload, self.secret_key, algorithm=self.algorithm)


class AuthenticationManager:
    """Main authentication manager."""
    
    def __init__(self):
        """Initialize authentication manager."""
        self.password_policy = PasswordPolicy()
        self.mfa_manager = MFAManager()
        self.jwt_manager = JWTManager()
        self.users: Dict[str, User] = {}  # In production, use database
        self.active_sessions: Dict[str, Dict[str, Any]] = {}
        self.redis_client: Optional[aioredis.Redis] = None
        
        # Rate limiting
        self.login_attempts: Dict[str, List[datetime]] = {}
        self.max_attempts_per_hour = 10
    
    async def initialize(self, redis_url: str = "redis://localhost:6379"):
        """Initialize authentication manager with Redis."""



        try:
            self.redis_client = aioredis.from_url(redis_url)
            logger.info("Authentication manager initialized with Redis")
        except Exception as e:
            logger.error(f"Failed to connect to Redis: {e}")
    
    def hash_password(self, password: str) -> str:
        """Hash password using bcrypt."""
        salt = bcrypt.gensalt()
        return bcrypt.hashpw(password.encode('utf-8'), salt).decode('utf-8')
    
    def verify_password(self, password: str, password_hash: str) -> bool:
        """Verify password against hash."""



        return bcrypt.checkpw(password.encode('utf-8'), password_hash.encode('utf-8'))
    
    async def create_user(
        self,
        username: str,
        email: str,
        password: str,
        tenant_id: str,
        roles: Optional[Set[UserRole]] = None
    ) -> Tuple[bool, Union[User, List[str]]]:
        """Create new user account."""
        # Validate password
        is_valid, errors = self.password_policy.validate_password(password, username)
        if not is_valid:
            return False, errors
        
        # Check if user exists
        user_key = f"{tenant_id}:{username}"
        if user_key in self.users:
            return False, ["User already exists"]
        
        # Create user
        user = User(
            user_id=str(uuid.uuid4()),
            username=username,
            email=email,
            tenant_id=tenant_id,
            roles=roles or {UserRole.VIEWER},
            password_hash=self.hash_password(password),
            password_expires_at=datetime.utcnow() + timedelta(days=self.password_policy.max_age_days)
        )
        
        # Assign default permissions based on roles
        user.permissions = self._get_permissions_for_roles(user.roles)
        
        # Store user
        self.users[user_key] = user
        
        logger.info(f"Created user {username} for tenant {tenant_id}")
        return True, user
    
    def _get_permissions_for_roles(self, roles: Set[UserRole]) -> Set[Permission]:
        """Get permissions for given roles."""
        permissions = set()
        
        for role in roles:
            if role == UserRole.SUPER_ADMIN:
                permissions.update(Permission)  # All permissions
            elif role == UserRole.TENANT_ADMIN:
                permissions.update([
                    Permission.USER_CREATE, Permission.USER_READ, Permission.USER_UPDATE, Permission.USER_DELETE,
                    Permission.TENANT_READ, Permission.TENANT_UPDATE,
                    Permission.ANALYTICS_READ, Permission.ANALYTICS_WRITE, Permission.ANALYTICS_EXECUTE,
                    Permission.ML_READ, Permission.ML_WRITE, Permission.ML_EXECUTE,
                    Permission.MONITORING_READ, Permission.MONITORING_WRITE
                ])
            elif role == UserRole.SECURITY_ADMIN:
                permissions.update([
                    Permission.SECURITY_READ, Permission.SECURITY_WRITE, Permission.SECURITY_ADMIN,
                    Permission.USER_READ, Permission.MONITORING_READ
                ])
            elif role == UserRole.DATA_SCIENTIST:
                permissions.update([
                    Permission.ANALYTICS_READ, Permission.ANALYTICS_WRITE, Permission.ANALYTICS_EXECUTE,
                    Permission.ML_READ, Permission.ML_WRITE, Permission.ML_EXECUTE,
                    Permission.MONITORING_READ
                ])
            elif role == UserRole.ML_ENGINEER:
                permissions.update([
                    Permission.ML_READ, Permission.ML_WRITE, Permission.ML_EXECUTE, Permission.ML_DEPLOY,
                    Permission.ANALYTICS_READ, Permission.MONITORING_READ
                ])
            elif role == UserRole.ANALYST:
                permissions.update([
                    Permission.ANALYTICS_READ, Permission.ANALYTICS_WRITE,
                    Permission.MONITORING_READ
                ])
            elif role == UserRole.VIEWER:
                permissions.update([
                    Permission.ANALYTICS_READ, Permission.MONITORING_READ
                ])
        
        return permissions
    
    async def authenticate(self, request: AuthenticationRequest) -> AuthenticationResponse:
        """Authenticate user based on request."""
        # Rate limiting check
        if not await self._check_rate_limit(request.username, request.ip_address):
            return AuthenticationResponse(
                success=False,
                error_message="Too many login attempts. Please try again later."
            )
        
        # Find user
        user_key = f"{request.tenant_id}:{request.username}"
        user = self.users.get(user_key)
        
        if not user or not user.is_active:
            await self._record_failed_attempt(request.username, request.ip_address)
            return AuthenticationResponse(
                success=False,
                error_message="Invalid credentials"
            )
        
        # Check if account is locked
        if user.locked_until and user.locked_until > datetime.utcnow():
            return AuthenticationResponse(
                success=False,
                error_message="Account is temporarily locked",
                locked_until=user.locked_until
            )
        
        # Authenticate based on method
        auth_success = False
        
        if request.method == AuthenticationMethod.PASSWORD:
            if request.password and self.verify_password(request.password, user.password_hash):
                auth_success = True
        
        elif request.method == AuthenticationMethod.API_KEY:
            if request.api_key and request.api_key in user.api_keys:
                auth_success = True
        
        elif request.method == AuthenticationMethod.JWT_TOKEN:
            if request.jwt_token:
                payload = self.jwt_manager.verify_token(request.jwt_token)
                if payload and payload.get("user_id") == user.user_id:
                    auth_success = True
        
        if not auth_success:
            await self._handle_failed_login(user)
            return AuthenticationResponse(
                success=False,
                error_message="Invalid credentials"
            )
        
        # Check MFA if enabled
        if user.mfa_enabled and request.method == AuthenticationMethod.PASSWORD:
            if not request.mfa_code:
                return AuthenticationResponse(
                    success=False,
                    requires_mfa=True,
                    error_message="MFA code required"
                )
            
            if not self.mfa_manager.verify_totp_code(user.mfa_secret, request.mfa_code):
                await self._handle_failed_login(user)
                return AuthenticationResponse(
                    success=False,
                    error_message="Invalid MFA code"
                )
        
        # Successful authentication
        await self._handle_successful_login(user, request)
        
        # Generate tokens
        access_token = self.jwt_manager.generate_access_token(user)
        refresh_token = self.jwt_manager.generate_refresh_token(user)
        
        return AuthenticationResponse(
            success=True,
            user=user,
            access_token=access_token,
            refresh_token=refresh_token,
            expires_at=datetime.utcnow() + self.jwt_manager.access_token_lifetime
        )
    
    async def _check_rate_limit(self, username: str, ip_address: Optional[str]) -> bool:
        """Check if user/IP is within rate limits."""
        now = datetime.utcnow()
        hour_ago = now - timedelta(hours=1)
        
        # Check username rate limit
        if username in self.login_attempts:
            recent_attempts = [
                attempt for attempt in self.login_attempts[username]
                if attempt > hour_ago
            ]
            self.login_attempts[username] = recent_attempts
            
            if len(recent_attempts) >= self.max_attempts_per_hour:
                return False
        
        # Check IP rate limit if provided
        if ip_address and ip_address in self.login_attempts:
            recent_attempts = [
                attempt for attempt in self.login_attempts[ip_address]
                if attempt > hour_ago
            ]
            self.login_attempts[ip_address] = recent_attempts
            
            if len(recent_attempts) >= self.max_attempts_per_hour:
                return False
        
        return True
    
    async def _record_failed_attempt(self, identifier: str, ip_address: Optional[str]):
        """Record failed login attempt."""
        now = datetime.utcnow()
        
        if identifier not in self.login_attempts:
            self.login_attempts[identifier] = []
        self.login_attempts[identifier].append(now)
        
        if ip_address:
            if ip_address not in self.login_attempts:
                self.login_attempts[ip_address] = []
            self.login_attempts[ip_address].append(now)
    
    async def _handle_failed_login(self, user: User):
        """Handle failed login attempt for user."""
        user.login_attempts += 1
        
        if user.login_attempts >= self.password_policy.lockout_attempts:
            user.locked_until = datetime.utcnow() + timedelta(
                minutes=self.password_policy.lockout_duration_minutes
            )
            logger.warning(f"User {user.username} account locked due to failed attempts")
    
    async def _handle_successful_login(self, user: User, request: AuthenticationRequest):
        """Handle successful login."""
        user.last_login = datetime.utcnow()
        user.login_attempts = 0
        user.locked_until = None
        
        # Create session
        session_id = str(uuid.uuid4())
        self.active_sessions[session_id] = {
            "user_id": user.user_id,
            "tenant_id": user.tenant_id,
            "ip_address": request.ip_address,
            "user_agent": request.user_agent,
            "created_at": datetime.utcnow(),
            "last_activity": datetime.utcnow()
        }
        
        logger.info(f"User {user.username} authenticated successfully")
    
    def enable_mfa(self, user_id: str) -> Tuple[str, List[str]]:
        """Enable MFA for user and return secret and backup codes."""
        # Find user by ID
        user = None
        for u in self.users.values():
            if u.user_id == user_id:
                user = u
                break
        
        if not user:
            raise ValueError("User not found")
        
        secret = self.mfa_manager.generate_mfa_secret()
        backup_codes = self.mfa_manager.generate_backup_codes()
        
        user.mfa_enabled = True
        user.mfa_secret = secret
        user.metadata["mfa_backup_codes"] = backup_codes
        
        return secret, backup_codes
    
    def disable_mfa(self, user_id: str) -> bool:
        """Disable MFA for user."""
        # Find user by ID
        user = None
        for u in self.users.values():
            if u.user_id == user_id:
                user = u
                break
        
        if not user:
            return False
        
        user.mfa_enabled = False
        user.mfa_secret = None
        user.metadata.pop("mfa_backup_codes", None)
        
        return True


class AuthorizationManager:
    """Authorization manager for access control."""
    
    def __init__(self):
        """Initialize authorization manager."""
        self.authorization_model = AuthorizationModel.RBAC
        self.resource_policies: Dict[str, Dict[str, Any]] = {}
        
        # Initialize default resource policies
        self._initialize_default_policies()
    
    def _initialize_default_policies(self):
        """Initialize default authorization policies."""
        self.resource_policies = {
            "analytics": {
                "read": [Permission.ANALYTICS_READ],
                "write": [Permission.ANALYTICS_WRITE],
                "execute": [Permission.ANALYTICS_EXECUTE],
                "export": [Permission.ANALYTICS_EXPORT]
            },
            "ml": {
                "read": [Permission.ML_READ],
                "write": [Permission.ML_WRITE],
                "execute": [Permission.ML_EXECUTE],
                "deploy": [Permission.ML_DEPLOY],
                "delete": [Permission.ML_DELETE]
            },
            "user": {
                "create": [Permission.USER_CREATE],
                "read": [Permission.USER_READ],
                "update": [Permission.USER_UPDATE],
                "delete": [Permission.USER_DELETE]
            },
            "tenant": {
                "create": [Permission.TENANT_CREATE],
                "read": [Permission.TENANT_READ],
                "update": [Permission.TENANT_UPDATE],
                "delete": [Permission.TENANT_DELETE]
            },
            "security": {
                "read": [Permission.SECURITY_READ],
                "write": [Permission.SECURITY_WRITE],
                "admin": [Permission.SECURITY_ADMIN]
            },
            "monitoring": {
                "read": [Permission.MONITORING_READ],
                "write": [Permission.MONITORING_WRITE],
                "admin": [Permission.MONITORING_ADMIN]
            }
        }
    
    async def authorize(self, user: User, request: AuthorizationRequest) -> AuthorizationResponse:
        """Authorize user request."""
        # Check if user belongs to the same tenant (tenant isolation)
        if user.tenant_id != request.tenant_id and Permission.SYSTEM_ADMIN not in user.permissions:
            return AuthorizationResponse(
                allowed=False,
                reason="Access denied: Cross-tenant access not permitted"
            )
        
        # Check resource-action permissions
        resource_policy = self.resource_policies.get(request.resource, {})
        required_permissions = resource_policy.get(request.action, [])
        
        if not required_permissions:
            return AuthorizationResponse(
                allowed=False,
                reason=f"Unknown resource/action: {request.resource}:{request.action}"
            )
        
        # Check if user has any of the required permissions
        has_permission = any(perm in user.permissions for perm in required_permissions)
        
        if not has_permission:
            return AuthorizationResponse(
                allowed=False,
                reason=f"Insufficient permissions for {request.resource}:{request.action}"
            )
        
        # Additional context-based checks can be added here
        # For example, data ownership, time-based access, etc.
        
        return AuthorizationResponse(
            allowed=True,
            reason="Access granted",
            context={"permissions_used": [perm.value for perm in required_permissions if perm in user.permissions]}
        )
    
    def add_resource_policy(self, resource: str, actions: Dict[str, List[Permission]]):
        """Add custom resource policy."""
        self.resource_policies[resource] = actions
        logger.info(f"Added resource policy for {resource}")
    
    def get_user_permissions(self, user: User) -> Dict[str, List[str]]:
        """Get formatted user permissions by resource."""
        user_perms = {}
        
        for resource, actions in self.resource_policies.items():
            allowed_actions = []
            for action, required_perms in actions.items():
                if any(perm in user.permissions for perm in required_perms):
                    allowed_actions.append(action)
            
            if allowed_actions:
                user_perms[resource] = allowed_actions
        
        return user_perms


# Global instances
_auth_manager: Optional[AuthenticationManager] = None
_authz_manager: Optional[AuthorizationManager] = None


async def get_auth_manager() -> AuthenticationManager:
    """Get initialized authentication manager."""
    global _auth_manager
    if _auth_manager is None:
        _auth_manager = AuthenticationManager()
        await _auth_manager.initialize()
    return _auth_manager


def get_authz_manager() -> AuthorizationManager:
    """Get authorization manager."""
    global _authz_manager
    if _authz_manager is None:
        _authz_manager = AuthorizationManager()
    return _authz_manager


async def authenticate_user(
    username: str,
    password: str,
    tenant_id: str,
    mfa_code: Optional[str] = None,
    ip_address: Optional[str] = None,
    user_agent: Optional[str] = None
) -> AuthenticationResponse:
    """Authenticate user with username/password."""
    auth_manager = await get_auth_manager()
    
    request = AuthenticationRequest(
        username=username,
        password=password,
        tenant_id=tenant_id,
        method=AuthenticationMethod.PASSWORD,
        mfa_code=mfa_code,
        ip_address=ip_address,
        user_agent=user_agent
    )
    
    return await auth_manager.authenticate(request)


async def authorize_user_action(
    user: User,
    resource: str,
    action: str,
    tenant_id: str,
    context: Optional[Dict[str, Any]] = None
) -> AuthorizationResponse:
    """Authorize user action on resource."""
    authz_manager = get_authz_manager()
    
    request = AuthorizationRequest(
        user_id=user.user_id,
        tenant_id=tenant_id,
        resource=resource,
        action=action,
        context=context or {}
    )
    
    return await authz_manager.authorize(user, request)

