        """Run all security validation tests."""
        logger.info("Starting comprehensive security validation suite...")
        
        start_time = time.time()
        
        # Run tests by category
        await self._run_authentication_tests()
        await self._run_authorization_tests()
        await self._run_encryption_tests()
        await self._run_policy_enforcement_tests()
        await self._run_threat_detection_tests()
        await self._run_audit_logging_tests()
        await self._run_configuration_tests()
        await self._run_performance_tests()
        
        execution_time = time.time() - start_time
        
        # Generate summary report
        summary = self._generate_test_summary(execution_time)
        
        logger.info(f"Security validation completed in {execution_time:.2f}s")
        return summary
    
