    async def _test_password_validation(self):
        """Test password policy validation."""
        start_time = time.time()
        
        try:
            from .auth_manager import PasswordPolicy
            
            policy = PasswordPolicy()
            
            # Test weak passwords
            weak_passwords = [
                "123456",
                "password",
                "qwerty",
                "short",
                "NoSpecialChars123",
                "nouppercasehere123!",
                "NOLOWERCASEHERE123!",
                "NoNumbers!"
            ]
            
            weak_results = []
            for pwd in weak_passwords:
                is_valid, errors = policy.validate_password(pwd)
                weak_results.append((pwd, is_valid, errors))
            
            # Test strong passwords
            strong_passwords = [
                "StrongPassword123!",
                "C0mpl3x@P@ssw0rd",
                "SecureTest789#"
            ]
            
            strong_results = []
            for pwd in strong_passwords:
                is_valid, errors = policy.validate_password(pwd)
                strong_results.append((pwd, is_valid, errors))
            
            # Validate results
            weak_rejected = all(not result[1] for result in weak_results)
            strong_accepted = all(result[1] for result in strong_results)
            
            passed = weak_rejected and strong_accepted
            
            self.test_results.append(TestResult(
                test_name="password_validation",
                category=TestCategory.AUTHENTICATION,
                severity=TestSeverity.ERROR if not passed else TestSeverity.INFO,
                passed=passed,
                message="Password validation working correctly" if passed else "Password validation failed",
                details={
                    "weak_passwords_rejected": weak_rejected,
                    "strong_passwords_accepted": strong_accepted,
                    "weak_results": weak_results,
                    "strong_results": strong_results
                },
                execution_time=time.time() - start_time,
                timestamp=datetime.utcnow()
            ))
            
        except Exception as e:
            self.test_results.append(TestResult(
                test_name="password_validation",
                category=TestCategory.AUTHENTICATION,
                severity=TestSeverity.CRITICAL,
                passed=False,
                message=f"Password validation test failed: {e}",
                details={"error": str(e)},
                execution_time=time.time() - start_time,
                timestamp=datetime.utcnow()
            ))
    
