"""
Tenant Security Manager - Enterprise Zero-Trust Security Controller
=================================================================

Advanced multi-tenant security management with zero-trust architecture,
comprehensive threat protection, and real-time security orchestration.

Features:
- Zero-Trust access controls
- Multi-factor authentication
- Role-based access control (RBAC)
- Attribute-based access control (ABAC)
- Real-time threat assessment
- Security policy enforcement
- Tenant isolation controls
- Compliance monitoring
"""

import asyncio
import logging
from typing import Dict, List, Optional, Any, Set
from datetime import datetime, timedelta
from dataclasses import dataclass, field
from enum import Enum
import hashlib
import secrets
import jwt
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
import redis.asyncio as redis

logger = logging.getLogger(__name__)

class SecurityLevel(Enum):
    """Security levels for tenant operations."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"
    MAXIMUM = "maximum"

class AccessDecision(Enum):
    """Access control decisions."""
    ALLOW = "allow"
    DENY = "deny"
    CHALLENGE = "challenge"
    MONITOR = "monitor"

@dataclass
class SecurityContext:
    """Security context for tenant operations."""
    tenant_id: str
    user_id: str
    session_id: str
    ip_address: str
    user_agent: str
    security_level: SecurityLevel
    permissions: Set[str] = field(default_factory=set)
    attributes: Dict[str, Any] = field(default_factory=dict)
    risk_score: float = 0.0
    last_activity: datetime = field(default_factory=datetime.utcnow)
    mfa_verified: bool = False
    device_trusted: bool = False

@dataclass
class SecurityPolicy:
    """Security policy definition."""
    name: str
    conditions: Dict[str, Any]
    actions: List[str]
    priority: int
    enabled: bool = True
    created_at: datetime = field(default_factory=datetime.utcnow)

class TenantSecurityManager:
    """
    Enterprise Tenant Security Manager
    
    Provides comprehensive zero-trust security controls for multi-tenant
    Spotify AI Agent deployments with advanced threat protection.
    """
    
    def __init__(self, config: Dict[str, Any]):
        """Initialize security manager with tenant-specific configuration."""
        self.config = config
        self.tenant_id = config.get('tenant_id')
        self.security_level = SecurityLevel(config.get('security_level', 'high'))
        
        # Redis for session and security state management
        self.redis_client = None
        self._initialize_redis()
        
        # Security policies and rules
        self.security_policies: Dict[str, SecurityPolicy] = {}
        self.access_rules: Dict[str, Any] = {}
        
        # Encryption and signing keys
        self.encryption_key = self._derive_encryption_key()
        self.jwt_secret = config.get('jwt_secret', secrets.token_urlsafe(32))
        
        # Security metrics
        self.metrics = {
            'access_attempts': 0,
            'access_denied': 0,
            'threats_detected': 0,
            'policy_violations': 0
        }
        
        logger.info(f"Security Manager initialized for tenant: {self.tenant_id}")
    
    async def _initialize_redis(self):
        """Initialize Redis connection for security state."""



        try:
            redis_config = self.config.get('redis', {})
            self.redis_client = redis.Redis(
                host=redis_config.get('host', 'localhost'),
                port=redis_config.get('port', 6379),
                db=redis_config.get('db', 0),
                password=redis_config.get('password'),
                decode_responses=True
            )
            await self.redis_client.ping()
            logger.info("Redis connection established for security state")
        except Exception as e:
            logger.error(f"Failed to initialize Redis: {str(e)}")
            raise
    
    def _derive_encryption_key(self) -> bytes:
        """Derive encryption key from tenant configuration."""
        password = self.config.get('encryption_password', 'default_password').encode()
        salt = self.tenant_id.encode()
        
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        return kdf.derive(password)
    
    async def create_security_context(self, 
                                    user_id: str,
                                    session_data: Dict[str, Any]) -> SecurityContext:
        """Create comprehensive security context for user session."""



        try:
            session_id = secrets.token_urlsafe(32)
            
            # Extract request metadata
            ip_address = session_data.get('ip_address', '0.0.0.0')
            user_agent = session_data.get('user_agent', 'unknown')
            
            # Calculate initial risk score
            risk_score = await self._calculate_risk_score(user_id, ip_address, user_agent)
            
            # Get user permissions
            permissions = await self._get_user_permissions(user_id)
            
            # Create security context
            context = SecurityContext(
                tenant_id=self.tenant_id,
                user_id=user_id,
                session_id=session_id,
                ip_address=ip_address,
                user_agent=user_agent,
                security_level=self.security_level,
                permissions=permissions,
                risk_score=risk_score
            )
            
            # Store session in Redis
            await self._store_security_context(context)
            
            logger.info(f"Security context created for user: {user_id}, risk: {risk_score}")
            return context
            
        except Exception as e:
            logger.error(f"Failed to create security context: {str(e)}")
            raise
    
    async def authenticate_request(self, 
                                 token: str,
                                 request_data: Dict[str, Any]) -> Optional[SecurityContext]:
        """Authenticate and validate security token."""



        try:
            # Decode JWT token
            payload = jwt.decode(token, self.jwt_secret, algorithms=['HS256'])
            
            session_id = payload.get('session_id')
            if not session_id:
                return None
            
            # Retrieve security context
            context = await self._get_security_context(session_id)
            if not context:
                return None
            
            # Validate session
            if not await self._validate_session(context, request_data):
                return None
            
            # Update activity timestamp
            context.last_activity = datetime.utcnow()
            await self._store_security_context(context)
            
            self.metrics['access_attempts'] += 1
            return context
            
        except jwt.ExpiredSignatureError:
            logger.warning("Expired JWT token")
            return None
        except jwt.InvalidTokenError:
            logger.warning("Invalid JWT token")
            return None
        except Exception as e:
            logger.error(f"Authentication failed: {str(e)}")
            return None
    
    async def authorize_access(self, 
                             context: SecurityContext,
                             resource: str,
                             action: str) -> AccessDecision:
        """Authorize access using zero-trust principles."""



        try:
            # Check basic permissions
            required_permission = f"{resource}:{action}"
            if required_permission not in context.permissions:
                self.metrics['access_denied'] += 1
                return AccessDecision.DENY
            
            # Evaluate security policies
            decision = await self._evaluate_security_policies(context, resource, action)
            if decision != AccessDecision.ALLOW:
                return decision
            
            # Risk-based access control
            if context.risk_score > 0.8:
                if not context.mfa_verified:
                    return AccessDecision.CHALLENGE
            
            # High-security resources require additional verification
            if self._is_high_security_resource(resource):
                if not context.device_trusted:
                    return AccessDecision.CHALLENGE
            
            return AccessDecision.ALLOW
            
        except Exception as e:
            logger.error(f"Authorization failed: {str(e)}")
            return AccessDecision.DENY
    
    async def enforce_mfa(self, 
                         context: SecurityContext,
                         mfa_token: str) -> bool:
        """Enforce multi-factor authentication."""



        try:
            # Validate MFA token (TOTP, SMS, etc.)
            if await self._validate_mfa_token(context.user_id, mfa_token):
                context.mfa_verified = True
                context.risk_score *= 0.5  # Reduce risk score
                await self._store_security_context(context)
                
                logger.info(f"MFA verification successful for user: {context.user_id}")
                return True
            
            logger.warning(f"MFA verification failed for user: {context.user_id}")
            return False
            
        except Exception as e:
            logger.error(f"MFA enforcement failed: {str(e)}")
            return False
    
    async def detect_anomaly(self, 
                           context: SecurityContext,
                           request_data: Dict[str, Any]) -> bool:
        """Detect security anomalies using behavioral analysis."""



        try:
            anomaly_indicators = []
            
            # Geographic anomaly
            if await self._detect_geographic_anomaly(context, request_data):
                anomaly_indicators.append('geographic')
            
            # Temporal anomaly
            if await self._detect_temporal_anomaly(context, request_data):
                anomaly_indicators.append('temporal')
            
            # Behavioral anomaly
            if await self._detect_behavioral_anomaly(context, request_data):
                anomaly_indicators.append('behavioral')
            
            # Device anomaly
            if await self._detect_device_anomaly(context, request_data):
                anomaly_indicators.append('device')
            
            if anomaly_indicators:
                # Update risk score
                context.risk_score = min(1.0, context.risk_score + len(anomaly_indicators) * 0.2)
                await self._store_security_context(context)
                
                self.metrics['threats_detected'] += 1
                logger.warning(f"Security anomalies detected: {anomaly_indicators}")
                return True
            
            return False
            
        except Exception as e:
            logger.error(f"Anomaly detection failed: {str(e)}")
            return False
    
    async def create_security_policy(self, policy: SecurityPolicy) -> bool:
        """Create or update security policy."""



        try:
            # Validate policy
            if not await self._validate_security_policy(policy):
                return False
            
            # Store policy
            self.security_policies[policy.name] = policy
            
            # Persist to Redis
            await self.redis_client.hset(
                f"tenant:{self.tenant_id}:policies",
                policy.name,
                self._serialize_policy(policy)
            )
            
            logger.info(f"Security policy created: {policy.name}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to create security policy: {str(e)}")
            return False
    
    async def get_security_metrics(self) -> Dict[str, Any]:
        """Get comprehensive security metrics."""



        try:
            # Basic metrics
            base_metrics = self.metrics.copy()
            
            # Redis-based metrics
            active_sessions = await self.redis_client.scard(f"tenant:{self.tenant_id}:sessions")
            policy_count = await self.redis_client.hlen(f"tenant:{self.tenant_id}:policies")
            
            # Threat intelligence metrics
            threat_metrics = await self._get_threat_metrics()
            
            return {
                'tenant_id': self.tenant_id,
                'security_level': self.security_level.value,
                'active_sessions': active_sessions,
                'policy_count': policy_count,
                'metrics': base_metrics,
                'threat_intelligence': threat_metrics,
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Failed to get security metrics: {str(e)}")
            return {}
    
    async def _calculate_risk_score(self, user_id: str, ip_address: str, user_agent: str) -> float:
        """Calculate initial risk score for user session."""
        risk_score = 0.0
        
        # IP reputation check
        if await self._is_suspicious_ip(ip_address):
            risk_score += 0.3
        
        # User behavior history
        user_risk = await self._get_user_risk_history(user_id)
        risk_score += user_risk * 0.4
        
        # Device fingerprinting
        device_risk = await self._calculate_device_risk(user_agent)
        risk_score += device_risk * 0.3
        
        return min(1.0, risk_score)
    
    async def _get_user_permissions(self, user_id: str) -> Set[str]:
        """Get user permissions from tenant configuration."""



        try:
            # Get user roles
            roles_key = f"tenant:{self.tenant_id}:user:{user_id}:roles"
            roles = await self.redis_client.smembers(roles_key)
            
            permissions = set()
            for role in roles:
                role_permissions_key = f"tenant:{self.tenant_id}:role:{role}:permissions"
                role_permissions = await self.redis_client.smembers(role_permissions_key)
                permissions.update(role_permissions)
            
            return permissions
            
        except Exception as e:
            logger.error(f"Failed to get user permissions: {str(e)}")
            return set()
    
    async def _store_security_context(self, context: SecurityContext):
        """Store security context in Redis."""



        try:
            context_data = {
                'tenant_id': context.tenant_id,
                'user_id': context.user_id,
                'ip_address': context.ip_address,
                'user_agent': context.user_agent,
                'security_level': context.security_level.value,
                'risk_score': context.risk_score,
                'mfa_verified': context.mfa_verified,
                'device_trusted': context.device_trusted,
                'last_activity': context.last_activity.isoformat(),
                'permissions': list(context.permissions)
            }
            
            # Store with TTL
            await self.redis_client.hset(
                f"tenant:{self.tenant_id}:session:{context.session_id}",
                mapping=context_data
            )
            await self.redis_client.expire(
                f"tenant:{self.tenant_id}:session:{context.session_id}",
                timedelta(hours=24)
            )
            
            # Add to active sessions
            await self.redis_client.sadd(
                f"tenant:{self.tenant_id}:sessions",
                context.session_id
            )
            
        except Exception as e:
            logger.error(f"Failed to store security context: {str(e)}")
            raise
    
    async def _get_security_context(self, session_id: str) -> Optional[SecurityContext]:
        """Retrieve security context from Redis."""



        try:
            context_data = await self.redis_client.hgetall(
                f"tenant:{self.tenant_id}:session:{session_id}"
            )
            
            if not context_data:
                return None
            
            return SecurityContext(
                tenant_id=context_data['tenant_id'],
                user_id=context_data['user_id'],
                session_id=session_id,
                ip_address=context_data['ip_address'],
                user_agent=context_data['user_agent'],
                security_level=SecurityLevel(context_data['security_level']),
                permissions=set(eval(context_data['permissions'])),
                risk_score=float(context_data['risk_score']),
                mfa_verified=context_data['mfa_verified'].lower() == 'true',
                device_trusted=context_data['device_trusted'].lower() == 'true',
                last_activity=datetime.fromisoformat(context_data['last_activity'])
            )
            
        except Exception as e:
            logger.error(f"Failed to get security context: {str(e)}")
            return None
    
    async def _validate_session(self, context: SecurityContext, request_data: Dict[str, Any]) -> bool:
        """Validate security session."""
        # Check session timeout
        if datetime.utcnow() - context.last_activity > timedelta(hours=8):
            return False
        
        # Validate IP consistency
        current_ip = request_data.get('ip_address')
        if current_ip and current_ip != context.ip_address:
            # Allow IP change but increase risk score
            context.risk_score = min(1.0, context.risk_score + 0.2)
        
        return True
    
    async def _evaluate_security_policies(self, 
                                         context: SecurityContext,
                                         resource: str,
                                         action: str) -> AccessDecision:
        """Evaluate security policies for access decision."""
        # Sort policies by priority
        sorted_policies = sorted(
            self.security_policies.values(),
            key=lambda p: p.priority,
            reverse=True
        )
        
        for policy in sorted_policies:
            if not policy.enabled:
                continue
            
            if await self._policy_matches(policy, context, resource, action):
                if 'deny' in policy.actions:
                    self.metrics['policy_violations'] += 1
                    return AccessDecision.DENY
                elif 'challenge' in policy.actions:
                    return AccessDecision.CHALLENGE
                elif 'monitor' in policy.actions:
                    return AccessDecision.MONITOR
        
        return AccessDecision.ALLOW
    
    def _is_high_security_resource(self, resource: str) -> bool:
        """Check if resource requires high security."""
        high_security_resources = [
            'user_data',
            'payment_info',
            'api_keys',
            'ml_models',
            'admin_functions'
        ]
        return any(hsr in resource for hsr in high_security_resources)
    
    async def _validate_mfa_token(self, user_id: str, mfa_token: str) -> bool:
        """Validate MFA token (mock implementation)."""
        # In production, this would integrate with TOTP, SMS, or hardware tokens
        # For now, simple validation
        expected_token = await self.redis_client.get(f"mfa:{user_id}")
        return mfa_token == expected_token
    
