    async def _policy_matches(self, 
                            policy: SecurityPolicy,
                            context: SecurityContext,
                            resource: str,
                            action: str) -> bool:
        """Check if security policy matches current context."""
        conditions = policy.conditions
        
        # Check resource condition
        if 'resource' in conditions:
            if resource not in conditions['resource']:
                return False
        
        # Check action condition
        if 'action' in conditions:
            if action not in conditions['action']:
                return False
        
        # Check security level
        if 'security_level' in conditions:
            if context.security_level.value not in conditions['security_level']:
                return False
        
        # Check risk score threshold
        if 'max_risk_score' in conditions:
            if context.risk_score > conditions['max_risk_score']:
                return False
        
        return True

