import boto3
from azure.keyvault.secrets import SecretClient
from azure.identity import DefaultAzureCredential

from .base import ConfigurationNode, ConfigurationObserver

logger = logging.getLogger(__name__)


class SecurityLevel(Enum):
    """Security levels for configuration"""
    PUBLIC = "public"           # No encryption needed
    INTERNAL = "internal"       # Basic encryption
    CONFIDENTIAL = "confidential"  # Strong encryption
    RESTRICTED = "restricted"   # Maximum encryption + access control
    TOP_SECRET = "top_secret"   # Multi-layer encryption + audit


class EncryptionMethod(Enum):
    """Supported encryption methods"""
    NONE = "none"
    FERNET = "fernet"          # Symmetric encryption
    RSA = "rsa"                # Asymmetric encryption
    AES_GCM = "aes_gcm"        # AES with Galois/Counter Mode
    CHACHA20 = "chacha20"      # ChaCha20-Poly1305


@dataclass
class SecurityPolicy:
    """Security policy for configuration keys"""
    
    key_pattern: str  # Regex pattern for keys
    security_level: SecurityLevel
    encryption_method: EncryptionMethod
    access_roles: List[str] = field(default_factory=list)
    
    # Access control
    read_permissions: List[str] = field(default_factory=list)
    write_permissions: List[str] = field(default_factory=list)
    admin_permissions: List[str] = field(default_factory=lambda: ["admin"])
    
    # Audit and compliance
    audit_required: bool = True
    compliance_tags: List[str] = field(default_factory=list)
    retention_days: Optional[int] = None
    
    # Key rotation
    rotation_enabled: bool = True
    rotation_interval_days: int = 30
    
    # Validation
    value_constraints: Dict[str, Any] = field(default_factory=dict)
    
    def matches_key(self, key: str) -> bool:
        """Check if policy applies to given key"""
        import re
        return bool(re.match(self.key_pattern, key))


@dataclass
class EncryptedConfiguration:
    """Encrypted configuration value with metadata"""
    
    encrypted_value: str
    encryption_method: EncryptionMethod
    key_id: str
    salt: Optional[str] = None
    iv: Optional[str] = None
    
    # Metadata
    created_at: datetime = field(default_factory=datetime.utcnow)
    encrypted_by: str = "system"
    security_level: SecurityLevel = SecurityLevel.CONFIDENTIAL
    
    # Key rotation
    key_version: int = 1
    next_rotation: Optional[datetime] = None
    
    # Integrity verification
    checksum: Optional[str] = None
    signature: Optional[str] = None
    
    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary for storage"""



        return {
            "encrypted_value": self.encrypted_value,
            "encryption_method": self.encryption_method.value,
            "key_id": self.key_id,
            "salt": self.salt,
            "iv": self.iv,
            "created_at": self.created_at.isoformat(),
            "encrypted_by": self.encrypted_by,
            "security_level": self.security_level.value,
            "key_version": self.key_version,
            "checksum": self.checksum,
            "signature": self.signature
        }
    
    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'EncryptedConfiguration':
        """Create from dictionary"""



        return cls(
            encrypted_value=data["encrypted_value"],
            encryption_method=EncryptionMethod(data["encryption_method"]),
            key_id=data["key_id"],
            salt=data.get("salt"),
            iv=data.get("iv"),
            created_at=datetime.fromisoformat(data["created_at"]),
            encrypted_by=data.get("encrypted_by", "system"),
            security_level=SecurityLevel(data.get("security_level", "confidential")),
            key_version=data.get("key_version", 1),
            checksum=data.get("checksum"),
            signature=data.get("signature")
        )


class SecretProvider:
    """Abstract base class for secret providers"""
    
    async def get_secret(self, key: str) -> Optional[str]:
        """Get secret by key"""



        try:
            logger.info(f"Retrieving secret: {key}")
            # Base implementation that logs and returns None
            # Subclasses should override with specific secret provider logic
            logger.warning(f"Base secret provider used for key: {key}")
            return None
        except Exception as e:
            logger.error(f"Error retrieving secret {key}: {str(e)}")
            return None
    
    async def set_secret(self, key: str, value: str, metadata: Dict[str, Any] = None) -> bool:
        """Set secret value"""



        try:
            logger.info(f"Setting secret: {key}")
            # Base implementation that logs the operation
            # Subclasses should override with specific secret provider logic
            logger.warning(f"Base secret provider set operation for key: {key}")
            return True
        except Exception as e:
            logger.error(f"Error setting secret {key}: {str(e)}")
            return False
    
    async def delete_secret(self, key: str) -> bool:
        """Delete secret"""



        try:
            logger.info(f"Deleting secret: {key}")
            # Base implementation that logs the operation
            # Subclasses should override with specific secret provider logic
            logger.warning(f"Base secret provider delete operation for key: {key}")
            return True
        except Exception as e:
            logger.error(f"Error deleting secret {key}: {str(e)}")
            return False
    
    async def list_secrets(self, prefix: str = "") -> List[str]:
        """List secret keys"""



        try:
            logger.info(f"Listing secrets with prefix: {prefix}")
            # Base implementation that returns empty list
            # Subclasses should override with specific secret provider logic
            logger.warning(f"Base secret provider list operation with prefix: {prefix}")
            return []
        except Exception as e:
            logger.error(f"Error listing secrets with prefix {prefix}: {str(e)}")
            return []


class HashiCorpVaultProvider(SecretProvider):
    """HashiCorp Vault secret provider"""
    
    def __init__(self, vault_url: str, vault_token: str = None, mount_point: str = "secret"):
        self.vault_url = vault_url
        self.vault_token = vault_token or os.getenv("VAULT_TOKEN")
        self.mount_point = mount_point
        self.client = None
    
    async def initialize(self):
        """Initialize Vault client"""



        try:
            self.client = hvac.Client(url=self.vault_url, token=self.vault_token)
            
            if not self.client.is_authenticated():
                raise ValueError("Vault authentication failed")
                
            logger.info("HashiCorp Vault provider initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize Vault provider: {e}")
            raise
    
    async def get_secret(self, key: str) -> Optional[str]:
        """Get secret from Vault"""



        try:
            response = self.client.secrets.kv.v2.read_secret_version(
                path=key,
                mount_point=self.mount_point
            )
            
            return response["data"]["data"].get("value")
            
        except Exception as e:
            logger.error(f"Failed to get secret from Vault: {e}")
            return None
    
    async def set_secret(self, key: str, value: str, metadata: Dict[str, Any] = None) -> bool:
        """Set secret in Vault"""



        try:
            secret_data = {"value": value}
            if metadata:
                secret_data.update(metadata)
            
            self.client.secrets.kv.v2.create_or_update_secret(
                path=key,
                secret=secret_data,
                mount_point=self.mount_point
            )
            
            return True
            
        except Exception as e:
            logger.error(f"Failed to set secret in Vault: {e}")
            return False


class AWSSecretsManagerProvider(SecretProvider):
    """AWS Secrets Manager provider"""
    
    def __init__(self, region_name: str = "us-east-1"):
        self.region_name = region_name
        self.client = None
    
    async def initialize(self):
        """Initialize AWS Secrets Manager client"""



        try:
            self.client = boto3.client("secretsmanager", region_name=self.region_name)
            logger.info("AWS Secrets Manager provider initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize AWS Secrets Manager: {e}")
            raise
    
    async def get_secret(self, key: str) -> Optional[str]:
        """Get secret from AWS Secrets Manager"""



        try:
            response = self.client.get_secret_value(SecretId=key)
            return response.get("SecretString")
            
        except Exception as e:
            logger.error(f"Failed to get secret from AWS: {e}")
            return None
    
    async def set_secret(self, key: str, value: str, metadata: Dict[str, Any] = None) -> bool:
        """Set secret in AWS Secrets Manager"""



        try:
            # Try to update existing secret
            try:
                self.client.update_secret(
                    SecretId=key,
                    SecretString=value
                )
            except self.client.exceptions.ResourceNotFoundException:
                # Create new secret
                create_params = {
                    "Name": key,
                    "SecretString": value
                }
                
                if metadata:
                    create_params["Description"] = metadata.get("description", "")
                    create_params["Tags"] = [
                        {"Key": k, "Value": str(v)} 
                        for k, v in metadata.items() 
                        if k != "description"
                    ]
                
                self.client.create_secret(**create_params)
            
            return True
            
        except Exception as e:
            logger.error(f"Failed to set secret in AWS: {e}")
            return False


class AzureKeyVaultProvider(SecretProvider):
    """Azure Key Vault provider"""
    
    def __init__(self, vault_url: str):
        self.vault_url = vault_url
        self.client = None
    
    async def initialize(self):
        """Initialize Azure Key Vault client"""



        try:
            credential = DefaultAzureCredential()
            self.client = SecretClient(vault_url=self.vault_url, credential=credential)
            logger.info("Azure Key Vault provider initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize Azure Key Vault: {e}")
            raise
    
    async def get_secret(self, key: str) -> Optional[str]:
        """Get secret from Azure Key Vault"""



        try:
            secret = self.client.get_secret(key)
            return secret.value
            
        except Exception as e:
            logger.error(f"Failed to get secret from Azure: {e}")
            return None
    
    async def set_secret(self, key: str, value: str, metadata: Dict[str, Any] = None) -> bool:
        """Set secret in Azure Key Vault"""



        try:
            self.client.set_secret(key, value)
            return True
            
        except Exception as e:
            logger.error(f"Failed to set secret in Azure: {e}")
            return False


class EncryptionManager:
    """Advanced encryption manager supporting multiple algorithms"""
    
    def __init__(self):
        self.encryption_keys: Dict[str, Any] = {}
        self.key_rotation_schedule: Dict[str, datetime] = {}
        
    def generate_key(self, method: EncryptionMethod) -> Tuple[str, Any]:
        """Generate encryption key for specified method"""
        key_id = str(uuid.uuid4())
        
        if method == EncryptionMethod.FERNET:
            key = Fernet.generate_key()
            self.encryption_keys[key_id] = Fernet(key)
            
        elif method == EncryptionMethod.RSA:
            private_key = rsa.generate_private_key(
                public_exponent=65537,
                key_size=2048,
                backend=default_backend()
            )
            self.encryption_keys[key_id] = private_key
            
        elif method == EncryptionMethod.AES_GCM:
            key = secrets.token_bytes(32)  # 256-bit key
            self.encryption_keys[key_id] = key
            
        else:
            raise ValueError(f"Unsupported encryption method: {method}")
        
        # Schedule key rotation
        self.key_rotation_schedule[key_id] = datetime.utcnow() + timedelta(days=30)
        
        return key_id, self.encryption_keys[key_id]
    
    def encrypt(self, data: str, method: EncryptionMethod, key_id: str = None) -> EncryptedConfiguration:
        """Encrypt data using specified method"""
        if not key_id:
            key_id, _ = self.generate_key(method)
        
        if key_id not in self.encryption_keys:
            raise ValueError(f"Encryption key not found: {key_id}")
        
        key = self.encryption_keys[key_id]
        data_bytes = data.encode('utf-8')
        
        if method == EncryptionMethod.FERNET:
            encrypted_data = key.encrypt(data_bytes)
            encrypted_value = base64.b64encode(encrypted_data).decode('utf-8')
            
        elif method == EncryptionMethod.RSA:
            public_key = key.public_key()
            encrypted_data = public_key.encrypt(
                data_bytes,
                padding.OAEP(
                    mgf=padding.MGF1(algorithm=hashes.SHA256()),
                    algorithm=hashes.SHA256(),
                    label=None
                )
            )
            encrypted_value = base64.b64encode(encrypted_data).decode('utf-8')
            
        elif method == EncryptionMethod.AES_GCM:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            
            aesgcm = AESGCM(key)
            nonce = secrets.token_bytes(12)  # 96-bit nonce
            encrypted_data = aesgcm.encrypt(nonce, data_bytes, None)
            
            # Combine nonce and encrypted data
            combined = nonce + encrypted_data
            encrypted_value = base64.b64encode(combined).decode('utf-8')
            
        else:
            raise ValueError(f"Unsupported encryption method: {method}")
        
        # Calculate checksum
        checksum = hashlib.sha256(data_bytes).hexdigest()
        
        return EncryptedConfiguration(
            encrypted_value=encrypted_value,
            encryption_method=method,
            key_id=key_id,
            checksum=checksum
        )
    
    def decrypt(self, encrypted_config: EncryptedConfiguration) -> str:
        """Decrypt encrypted configuration"""
        key_id = encrypted_config.key_id
        
        if key_id not in self.encryption_keys:
            raise ValueError(f"Decryption key not found: {key_id}")
        
        key = self.encryption_keys[key_id]
        encrypted_data = base64.b64decode(encrypted_config.encrypted_value.encode('utf-8'))
        
        if encrypted_config.encryption_method == EncryptionMethod.FERNET:
            decrypted_data = key.decrypt(encrypted_data)
            
        elif encrypted_config.encryption_method == EncryptionMethod.RSA:
            decrypted_data = key.decrypt(
                encrypted_data,
                padding.OAEP(
                    mgf=padding.MGF1(algorithm=hashes.SHA256()),
                    algorithm=hashes.SHA256(),
                    label=None
                )
            )
            
        elif encrypted_config.encryption_method == EncryptionMethod.AES_GCM:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
            
            # Extract nonce and encrypted data
            nonce = encrypted_data[:12]
            ciphertext = encrypted_data[12:]
            
            aesgcm = AESGCM(key)
            decrypted_data = aesgcm.decrypt(nonce, ciphertext, None)
            
        else:
            raise ValueError(f"Unsupported encryption method: {encrypted_config.encryption_method}")
        
        result = decrypted_data.decode('utf-8')
        
        # Verify checksum if available
        if encrypted_config.checksum:
            actual_checksum = hashlib.sha256(decrypted_data).hexdigest()
            if actual_checksum != encrypted_config.checksum:
                raise ValueError("Data integrity check failed")
        
        return result


class AccessControlManager:
    """Role-based access control for configuration"""
    
    def __init__(self):
        self.users: Dict[str, Dict[str, Any]] = {}
        self.roles: Dict[str, Dict[str, Any]] = {}
        self.permissions: Dict[str, List[str]] = {}
        
        # Setup default roles
        self._setup_default_roles()
    
    def _setup_default_roles(self):
        """Setup default security roles"""
        self.roles = {
            "admin": {
                "permissions": ["read", "write", "delete", "encrypt", "decrypt", "rotate_keys"],
                "description": "Full administrative access"
            },
            "operator": {
                "permissions": ["read", "write"],
                "description": "Operational configuration access"
            },
            "viewer": {
                "permissions": ["read"],
                "description": "Read-only access"
            },
            "security_admin": {
                "permissions": ["read", "write", "encrypt", "decrypt", "rotate_keys", "audit"],
                "description": "Security administration"
            }
        }
    
    def add_user(self, username: str, roles: List[str], metadata: Dict[str, Any] = None):
        """Add user with roles"""
        self.users[username] = {
            "roles": roles,
            "created_at": datetime.utcnow(),
            "metadata": metadata or {}
        }
    
    def has_permission(self, username: str, permission: str, resource: str = None) -> bool:
        """Check if user has specific permission"""
        if username not in self.users:
            return False
        
        user_roles = self.users[username]["roles"]
        
        for role in user_roles:
            if role in self.roles:
                role_permissions = self.roles[role]["permissions"]
                if permission in role_permissions:
                    return True
        
        return False
    
    def get_user_permissions(self, username: str) -> List[str]:
        """Get all permissions for user"""
        if username not in self.users:
            return []
        
        permissions = set()
        user_roles = self.users[username]["roles"]
        
        for role in user_roles:
            if role in self.roles:
                permissions.update(self.roles[role]["permissions"])
        
        return list(permissions)


class SecureConfigManager(ConfigurationObserver):
    """
    Enterprise security configuration manager with encryption,
    access control, secret management, and compliance features.
    """
    
    def __init__(self):
        self.encryption_manager = EncryptionManager()
        self.access_control = AccessControlManager()
        self.security_policies: List[SecurityPolicy] = []
        self.secret_providers: Dict[str, SecretProvider] = {}
        
        # Audit logging
        self.audit_log: List[Dict[str, Any]] = []
        self.audit_enabled = True
        
        # Key rotation
        self.key_rotation_enabled = True
        self.rotation_check_interval = 3600  # 1 hour
        
        # Setup default security policies
        self._setup_default_policies()
    
    async def initialize(self, config: Dict[str, Any]):
        """Initialize secure configuration manager"""



        try:
            # Initialize secret providers
            await self._initialize_secret_providers(config.get("secret_providers", {}))
            
            # Load security policies
            await self._load_security_policies(config.get("security_policies", []))
            
            # Setup access control
            await self._setup_access_control(config.get("access_control", {}))
            
            # Start background tasks
            await self._start_background_tasks()
            
            logger.info("Secure configuration manager initialized")
            
        except Exception as e:
            logger.error(f"Failed to initialize secure config manager: {e}")
            raise
    
    async def encrypt_configuration(self, key: str, value: str, 
                                  security_level: SecurityLevel = None) -> EncryptedConfiguration:
        """Encrypt configuration value"""



        try:
            # Determine security policy
            policy = self._get_security_policy(key)
            
            if not policy:
                # Default policy for unknown keys
                encryption_method = EncryptionMethod.FERNET
                actual_security_level = security_level or SecurityLevel.CONFIDENTIAL
            else:
                encryption_method = policy.encryption_method
                actual_security_level = policy.security_level
            
            # Encrypt the value
            encrypted_config = self.encryption_manager.encrypt(value, encryption_method)
            encrypted_config.security_level = actual_security_level
            
            # Audit log
            await self._audit_log_action("encrypt", key, {"security_level": actual_security_level.value})
            
            return encrypted_config
            
        except Exception as e:
            logger.error(f"Failed to encrypt configuration {key}: {e}")
            raise
    
    async def decrypt_configuration(self, encrypted_config: EncryptedConfiguration, 
                                  requester: str = "system") -> str:
        """Decrypt configuration value with access control"""



        try:
            # Check access permissions
            if not self.access_control.has_permission(requester, "decrypt"):
                raise PermissionError(f"User {requester} lacks decrypt permission")
            
            # Decrypt the value
            decrypted_value = self.encryption_manager.decrypt(encrypted_config)
            
            # Audit log
            await self._audit_log_action("decrypt", encrypted_config.key_id, {
                "requester": requester,
                "security_level": encrypted_config.security_level.value
            })
            
            return decrypted_value
            
        except Exception as e:
            logger.error(f"Failed to decrypt configuration: {e}")
            raise
    
    async def store_secret(self, key: str, value: str, provider: str = "vault",
                          metadata: Dict[str, Any] = None) -> bool:
        """Store secret in external secret provider"""



        try:
            if provider not in self.secret_providers:
                raise ValueError(f"Secret provider not configured: {provider}")
            
            provider_instance = self.secret_providers[provider]
            result = await provider_instance.set_secret(key, value, metadata)
            
            # Audit log
            await self._audit_log_action("store_secret", key, {
                "provider": provider,
                "metadata": metadata or {}
            })
            
            return result
            
        except Exception as e:
            logger.error(f"Failed to store secret {key}: {e}")
            return False
    
    async def retrieve_secret(self, key: str, provider: str = "vault",
                            requester: str = "system") -> Optional[str]:
        """Retrieve secret from external provider"""



        try:
            # Check access permissions
            if not self.access_control.has_permission(requester, "read"):
                raise PermissionError(f"User {requester} lacks read permission")
            
            if provider not in self.secret_providers:
                raise ValueError(f"Secret provider not configured: {provider}")
            
            provider_instance = self.secret_providers[provider]
            value = await provider_instance.get_secret(key)
            
            # Audit log
            await self._audit_log_action("retrieve_secret", key, {
                "provider": provider,
                "requester": requester
            })
            
            return value
            
        except Exception as e:
            logger.error(f"Failed to retrieve secret {key}: {e}")
            return None
    
    async def rotate_encryption_keys(self, force: bool = False):
        """Rotate encryption keys based on schedule"""



        try:
            rotated_keys = []
            current_time = datetime.utcnow()
            
            for key_id, rotation_time in self.encryption_manager.key_rotation_schedule.items():
                if force or current_time >= rotation_time:
                    # Generate new key
                    old_key = self.encryption_manager.encryption_keys.get(key_id)
                    if old_key:
                        # Determine encryption method (this would need to be stored with key)
                        # For now, assume Fernet
                        new_key_id, _ = self.encryption_manager.generate_key(EncryptionMethod.FERNET)
                        rotated_keys.append((key_id, new_key_id))
                        
                        # Update rotation schedule
                        self.encryption_manager.key_rotation_schedule[new_key_id] = (
                            current_time + timedelta(days=30)
                        )
            
            # Audit log
            await self._audit_log_action("rotate_keys", "system", {
                "rotated_keys": len(rotated_keys),
                "force": force
            })
            
            logger.info(f"Rotated {len(rotated_keys)} encryption keys")
            return rotated_keys
            
        except Exception as e:
            logger.error(f"Failed to rotate encryption keys: {e}")
            return []
    
    def add_security_policy(self, policy: SecurityPolicy):
        """Add security policy"""
        self.security_policies.append(policy)
        
        # Sort by specificity (more specific patterns first)
        self.security_policies.sort(key=lambda p: len(p.key_pattern), reverse=True)
    
    def get_audit_log(self, start_time: datetime = None, 
                     end_time: datetime = None) -> List[Dict[str, Any]]:
        """Get audit log entries"""
        if not start_time:
            start_time = datetime.utcnow() - timedelta(days=7)
        if not end_time:
            end_time = datetime.utcnow()
        
        return [
            entry for entry in self.audit_log
            if start_time <= entry["timestamp"] <= end_time
        ]
    
    def _get_security_policy(self, key: str) -> Optional[SecurityPolicy]:
        """Get applicable security policy for key"""
        for policy in self.security_policies:
            if policy.matches_key(key):
                return policy
        return None
    
    def _setup_default_policies(self):
        """Setup default security policies"""
        default_policies = [
            SecurityPolicy(
                key_pattern=r".*password.*",
                security_level=SecurityLevel.RESTRICTED,
                encryption_method=EncryptionMethod.RSA,
                access_roles=["admin", "security_admin"]
            ),
            SecurityPolicy(
                key_pattern=r".*secret.*",
                security_level=SecurityLevel.CONFIDENTIAL,
                encryption_method=EncryptionMethod.FERNET,
                access_roles=["admin", "security_admin"]
            ),
            SecurityPolicy(
                key_pattern=r".*token.*",
                security_level=SecurityLevel.CONFIDENTIAL,
                encryption_method=EncryptionMethod.FERNET,
                access_roles=["admin", "operator"]
            ),
            SecurityPolicy(
                key_pattern=r"database\..*",
                security_level=SecurityLevel.INTERNAL,
                encryption_method=EncryptionMethod.FERNET,
                access_roles=["admin", "operator"]
            )
        ]
        
        for policy in default_policies:
            self.add_security_policy(policy)
    
    async def _audit_log_action(self, action: str, resource: str, metadata: Dict[str, Any]):
        """Log action for audit purposes"""
        if not self.audit_enabled:
            return
        
        audit_entry = {
            "timestamp": datetime.utcnow(),
            "action": action,
            "resource": resource,
            "metadata": metadata,
            "source_ip": self._get_source_ip(),
            "user_agent": self._get_user_agent()
        }
        
        self.audit_log.append(audit_entry)
        
        # Trim old entries (keep last 10000)
        if len(self.audit_log) > 10000:
            self.audit_log = self.audit_log[-10000:]
    
    def _get_source_ip(self) -> str:
        """Get source IP for audit logging"""
        # This would typically come from request context
        return "127.0.0.1"
    
    def _get_user_agent(self) -> str:
        """Get user agent for audit logging"""
        # This would typically come from request context
        return "ConfigurationManager/2.0"
    
    # ConfigurationObserver methods
    async def on_configuration_changed(self, key: str, old_value: Any, new_value: Any):
        """Handle configuration changes for security"""
        await self._audit_log_action("config_changed", key, {
            "old_value_type": type(old_value).__name__,
            "new_value_type": type(new_value).__name__
        })
    
    async def on_configuration_deleted(self, key: str, old_value: Any):
        """Handle configuration deletion for security"""
        await self._audit_log_action("config_deleted", key, {
            "old_value_type": type(old_value).__name__
        })

