class IdentityAccessManagementEngine:
    """
     Advanced Identity & Access Management Engine
    
    Capabilities:
    - Zero-trust identity verification
    - Multi-factor authentication
    - Dynamic access control policies
    - Risk-based authentication
    - Identity federation and SSO
    - Session management and monitoring
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        
        # Identity storage
        self._identities = {}
        self._sessions = {}
        self._access_policies = {}
        
        # Authentication engines
        self._password_engine = PasswordAuthEngine(config)
        self._mfa_engine = MFAAuthEngine(config)
        self._federation_engine = FederationEngine(config)
        
        # Access control engines
        self._rbac_engine = RBACEngine(config)
        self._abac_engine = ABACEngine(config)
        self._policy_engine = PolicyEngine(config)
        
        # Risk and analytics
        self._risk_engine = IdentityRiskEngine(config)
        self._analytics_engine = IdentityAnalyticsEngine(config)
        
        # Session management
        self._session_manager = SessionManager(config)
        
        # Audit logging
        self._audit_logger = IdentityAuditLogger(config)
        
        # Initialize default policies
        self._initialize_default_policies()
    
    def _initialize_default_policies(self):
        """Initialize default access policies"""
        # Admin access policy
        admin_policy = AccessPolicy(
            policy_id="admin_full_access",
            name="Administrator Full Access",
            description="Full access for administrators",
            resource_pattern="*",
            actions={"*"},
            effect=AccessDecision.ALLOW,
            subjects={"admin", "administrators"},
            priority=1
        )
        self._access_policies[admin_policy.policy_id] = admin_policy
        
        # Default deny policy
        deny_policy = AccessPolicy(
            policy_id="default_deny",
            name="Default Deny",
            description="Default deny all access",
            resource_pattern="*",
            actions={"*"},
            effect=AccessDecision.DENY,
            priority=1000
        )
        self._access_policies[deny_policy.policy_id] = deny_policy
        
        self.logger.info("Default access policies initialized")
    
    async def create_identity(
        self,
        username: str,
        email: str,
        identity_type: IdentityType = IdentityType.USER,
        password: Optional[str] = None,
        tenant_id: Optional[str] = None,
        attributes: Optional[Dict[str, Any]] = None
    ) -> Identity:
        """Create new identity"""
        identity_id = f"ID_{int(time.time())}_{hashlib.md5(username.encode()).hexdigest()[:8]}"
        
        # Check if username already exists
        if self._username_exists(username, tenant_id):
            raise ValueError(f"Username {username} already exists")
        
        identity = Identity(
            identity_id=identity_id,
            identity_type=identity_type,
            username=username,
            email=email,
            tenant_id=tenant_id,
            attributes=attributes or {}
        )
        
        # Set password if provided
        if password:
            await self._password_engine.set_password(identity_id, password)
        
        self._identities[identity_id] = identity
        
        # Log identity creation
        await self._audit_logger.log_event(
            "identity_created",
            identity_id=identity_id,
            username=username,
            tenant_id=tenant_id
        )
        
        self.logger.info(f"Created identity: {identity_id} ({username})")
        return identity
    
    def _username_exists(self, username: str, tenant_id: Optional[str]) -> bool:
        """Check if username already exists in tenant"""
        for identity in self._identities.values():
            if (identity.username == username and 
                identity.tenant_id == tenant_id):
                return True
        return False
    
    async def authenticate(
        self,
        username: str,
        password: str,
        tenant_id: Optional[str] = None,
        auth_context: Optional[Dict[str, Any]] = None
    ) -> Tuple[bool, Optional[AuthenticationContext]]:
        """Authenticate user with username/password"""
        # Find identity
        identity = self._find_identity_by_username(username, tenant_id)
        if not identity:
            await self._audit_logger.log_event(
                "authentication_failed",
                username=username,
                reason="identity_not_found",
                tenant_id=tenant_id
            )
            return False, None
        
        # Check if account is locked
        if identity.account_locked:
            await self._audit_logger.log_event(
                "authentication_failed",
                identity_id=identity.identity_id,
                reason="account_locked"
            )
            return False, None
        
        # Verify password
        password_valid = await self._password_engine.verify_password(
            identity.identity_id, password
        )
        
        if not password_valid:
            await self._audit_logger.log_event(
                "authentication_failed",
                identity_id=identity.identity_id,
                reason="invalid_password"
            )
            return False, None
        
        # Create authentication context
        session_id = f"SESS_{int(time.time())}_{secrets.token_hex(16)}"
        auth_context_obj = AuthenticationContext(
            identity_id=identity.identity_id,
            session_id=session_id,
            authentication_methods=[AuthenticationMethod.PASSWORD],
            authentication_time=datetime.utcnow(),
            source_ip=auth_context.get('source_ip') if auth_context else None,
            user_agent=auth_context.get('user_agent') if auth_context else None
        )
        
        # Calculate risk score
        risk_score = await self._risk_engine.calculate_authentication_risk(
            identity, auth_context_obj
        )
        auth_context_obj.risk_factors = {'overall_risk': risk_score}
        
        # Check if MFA is required
        if identity.mfa_enabled or risk_score > 0.7:
            auth_context_obj.step_up_required = True
            await self._audit_logger.log_event(
                "authentication_partial",
                identity_id=identity.identity_id,
                mfa_required=True,
                risk_score=risk_score
            )
        else:
            # Create session
            await self._create_session(identity, auth_context_obj)
            await self._audit_logger.log_event(
                "authentication_success",
                identity_id=identity.identity_id,
                session_id=session_id
            )
        
        return True, auth_context_obj
    
    def _find_identity_by_username(self, username: str, tenant_id: Optional[str]) -> Optional[Identity]:
        """Find identity by username and tenant"""
        for identity in self._identities.values():
            if (identity.username == username and 
                identity.tenant_id == tenant_id):
                return identity
        return None
    
    async def _create_session(self, identity: Identity, auth_context: AuthenticationContext):
        """Create user session"""
        session = Session(
            session_id=auth_context.session_id,
            identity_id=identity.identity_id,
            created_at=auth_context.authentication_time,
            expires_at=auth_context.authentication_time + timedelta(hours=8),
            last_activity=auth_context.authentication_time,
            source_ip=auth_context.source_ip,
            user_agent=auth_context.user_agent,
            mfa_verified=auth_context.mfa_completed,
            risk_score=auth_context.risk_factors.get('overall_risk', 0.0)
        )
        
        self._sessions[session.session_id] = session
        identity.last_login = auth_context.authentication_time
    
    async def verify_mfa(
        self,
        session_id: str,
        mfa_method: AuthenticationMethod,
        mfa_code: str
    ) -> bool:
        """Verify MFA code"""
        # Find authentication context (in production, this would be stored temporarily)
        session = self._sessions.get(session_id)
        if not session:
            return False
        
        identity = self._identities.get(session.identity_id)
        if not identity:
            return False
        
        # Verify MFA code
        mfa_valid = await self._mfa_engine.verify_mfa(
            identity.identity_id, mfa_method, mfa_code
        )
        
        if mfa_valid:
            session.mfa_verified = True
            await self._audit_logger.log_event(
                "mfa_verification_success",
                identity_id=identity.identity_id,
                session_id=session_id,
                method=mfa_method.name
            )
        else:
            await self._audit_logger.log_event(
                "mfa_verification_failed",
                identity_id=identity.identity_id,
                session_id=session_id,
                method=mfa_method.name
            )
        
        return mfa_valid
    
    async def authorize_access(
        self,
        access_request: AccessRequest
    ) -> Tuple[AccessDecision, Optional[str]]:
        """Authorize access request"""
        # Get identity
        identity = self._identities.get(access_request.identity_id)
        if not identity:
            return AccessDecision.DENY, "Identity not found"
        
        # Validate session if provided
        if access_request.session_id:
            session = self._sessions.get(access_request.session_id)
            if not session or not session.active or session.expires_at < datetime.utcnow():
                return AccessDecision.DENY, "Invalid or expired session"
        
        # Evaluate policies
        decision = await self._policy_engine.evaluate_policies(
            access_request, identity, self._access_policies.values()
        )
        
        # Log access decision
        await self._audit_logger.log_event(
            "access_evaluation",
            identity_id=access_request.identity_id,
            resource=access_request.resource,
            action=access_request.action,
            decision=decision.name,
            session_id=access_request.session_id
        )
        
        return decision, None
    
    async def create_access_policy(
        self,
        name: str,
        resource_pattern: str,
        actions: Set[str],
        effect: AccessDecision,
        subjects: Optional[Set[str]] = None,
        conditions: Optional[Dict[str, Any]] = None,
        tenant_id: Optional[str] = None
    ) -> AccessPolicy:
        """Create access control policy"""
        policy_id = f"POL_{int(time.time())}_{hashlib.md5(name.encode()).hexdigest()[:8]}"
        
        policy = AccessPolicy(
            policy_id=policy_id,
            name=name,
            description=f"Access policy: {name}",
            resource_pattern=resource_pattern,
            actions=actions,
            effect=effect,
            subjects=subjects or set(),
            conditions=conditions or {},
            tenant_id=tenant_id
        )
        
        self._access_policies[policy_id] = policy
        
        await self._audit_logger.log_event(
            "policy_created",
            policy_id=policy_id,
            name=name,
            tenant_id=tenant_id
        )
        
        self.logger.info(f"Created access policy: {policy_id}")
        return policy
    
    async def assign_role(
        self,
        identity_id: str,
        role: str,
        tenant_id: Optional[str] = None
    ) -> bool:
        """Assign role to identity"""
        identity = self._identities.get(identity_id)
        if not identity:
            return False
        
        if tenant_id and identity.tenant_id != tenant_id:
            return False
        
        identity.roles.add(role)
        
        await self._audit_logger.log_event(
            "role_assigned",
            identity_id=identity_id,
            role=role,
            tenant_id=tenant_id
        )
        
        return True
    
    async def enable_mfa(
        self,
        identity_id: str,
        mfa_method: AuthenticationMethod
    ) -> Dict[str, Any]:
        """Enable MFA for identity"""
        identity = self._identities.get(identity_id)
        if not identity:
            raise ValueError("Identity not found")
        
        # Setup MFA
        mfa_setup = await self._mfa_engine.setup_mfa(identity_id, mfa_method)
        
        identity.mfa_enabled = True
        identity.mfa_methods.add(mfa_method)
        
        await self._audit_logger.log_event(
            "mfa_enabled",
            identity_id=identity_id,
            method=mfa_method.name
        )
        
        return mfa_setup
    
    async def get_identity_sessions(self, identity_id: str) -> List[Session]:
        """Get active sessions for identity"""
        sessions = []
        current_time = datetime.utcnow()
        
        for session in self._sessions.values():
            if (session.identity_id == identity_id and 
                session.active and 
                session.expires_at > current_time):
                sessions.append(session)
        
        return sessions
    
    async def revoke_session(self, session_id: str) -> bool:
        """Revoke user session"""
        session = self._sessions.get(session_id)
        if not session:
            return False
        
        session.active = False
        
        await self._audit_logger.log_event(
            "session_revoked",
            identity_id=session.identity_id,
            session_id=session_id
        )
        
        return True
    
    async def generate_identity_report(
        self,
        tenant_id: Optional[str] = None
    ) -> Dict[str, Any]:
        """Generate identity management report"""
        identities = [i for i in self._identities.values() 
                     if tenant_id is None or i.tenant_id == tenant_id]
        
        # Statistics
        total_identities = len(identities)
        active_sessions = len([s for s in self._sessions.values() 
                             if s.active and s.expires_at > datetime.utcnow()])
        
        identity_types = defaultdict(int)
        mfa_enabled_count = 0
        
        for identity in identities:
            identity_types[identity.identity_type.name] += 1
            if identity.mfa_enabled:
                mfa_enabled_count += 1
        
        # Risk analysis
        risk_distribution = defaultdict(int)
        for identity in identities:
            if identity.risk_score <= 0.2:
                risk_distribution['Low'] += 1
            elif identity.risk_score <= 0.5:
                risk_distribution['Medium'] += 1
            elif identity.risk_score <= 0.8:
                risk_distribution['High'] += 1
            else:
                risk_distribution['Critical'] += 1
        
        report = {
            'report_id': f"IAM_{int(time.time())}",
            'generated_at': datetime.utcnow().isoformat(),
            'tenant_id': tenant_id,
            'summary': {
                'total_identities': total_identities,
                'active_sessions': active_sessions,
                'mfa_enabled_percentage': (mfa_enabled_count / total_identities * 100) if total_identities > 0 else 0,
                'total_policies': len(self._access_policies)
            },
            'identity_types': dict(identity_types),
            'risk_distribution': dict(risk_distribution),
            'recommendations': await self._generate_iam_recommendations(identities)
        }
        
        return report
    
    async def _generate_iam_recommendations(self, identities: List[Identity]) -> List[str]:
        """Generate IAM recommendations"""
        recommendations = []
        
        mfa_disabled = len([i for i in identities if not i.mfa_enabled])
        if mfa_disabled > 0:
            recommendations.append(f"Enable MFA for {mfa_disabled} identities without MFA")
        
        high_risk_count = len([i for i in identities if i.risk_score > 0.8])
        if high_risk_count > 0:
            recommendations.append(f"Review {high_risk_count} high-risk identities")
        
        recommendations.extend([
            "Implement regular access reviews",
            "Enable just-in-time access for privileged operations",
            "Monitor for unusual authentication patterns",
            "Implement zero-trust access policies"
        ])
        
        return recommendations


class PasswordAuthEngine:
    """Password authentication engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._password_hashes = {}
    
    async def set_password(self, identity_id: str, password: str):
        """Set password for identity"""
        # Hash password with bcrypt
        salt = bcrypt.gensalt()
        password_hash = bcrypt.hashpw(password.encode('utf-8'), salt)
        self._password_hashes[identity_id] = password_hash
    
    async def verify_password(self, identity_id: str, password: str) -> bool:
        """Verify password for identity"""
        stored_hash = self._password_hashes.get(identity_id)
        if not stored_hash:
            return False
        
        return bcrypt.checkpw(password.encode('utf-8'), stored_hash)
    
    async def change_password(
        self, 
        identity_id: str, 
        old_password: str, 
        new_password: str
    ) -> bool:
        """Change password for identity"""
        if not await self.verify_password(identity_id, old_password):
            return False
        
        await self.set_password(identity_id, new_password)
        return True


class MFAAuthEngine:
    """Multi-factor authentication engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._mfa_secrets = {}
    
    async def setup_mfa(
        self, 
        identity_id: str, 
        mfa_method: AuthenticationMethod
    ) -> Dict[str, Any]:
        """Setup MFA for identity"""
        if mfa_method == AuthenticationMethod.MFA_TOTP:
            # Generate TOTP secret
            secret = pyotp.random_base32()
            self._mfa_secrets[identity_id] = {
                'method': mfa_method,
                'secret': secret
            }
            
            # Generate QR code URL
            totp = pyotp.TOTP(secret)
            qr_url = totp.provisioning_uri(
                name=identity_id,
                issuer_name="Spotify AI Agent"
            )
            
            return {
                'method': mfa_method.name,
                'secret': secret,
                'qr_url': qr_url,
                'backup_codes': self._generate_backup_codes()
            }
        
        return {}
    
    def _generate_backup_codes(self) -> List[str]:
        """Generate backup codes for MFA"""



        return [secrets.token_hex(4).upper() for _ in range(10)]
    
    async def verify_mfa(
        self, 
        identity_id: str, 
        mfa_method: AuthenticationMethod, 
        code: str
    ) -> bool:
        """Verify MFA code"""
        mfa_config = self._mfa_secrets.get(identity_id)
        if not mfa_config or mfa_config['method'] != mfa_method:
            return False
        
        if mfa_method == AuthenticationMethod.MFA_TOTP:
            totp = pyotp.TOTP(mfa_config['secret'])
            return totp.verify(code, valid_window=1)
        
        return False


class RBACEngine:
    """Role-based access control engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        
        # Role definitions
        self._roles = {
            'admin': {
                'permissions': {'*'},
                'description': 'Full administrative access'
            },
            'user': {
                'permissions': {'read', 'write_own'},
                'description': 'Standard user access'
            },
            'viewer': {
                'permissions': {'read'},
                'description': 'Read-only access'
            }
        }
    
    def has_permission(self, roles: Set[str], required_permission: str) -> bool:
        """Check if roles have required permission"""
        for role in roles:
            role_config = self._roles.get(role, {})
            permissions = role_config.get('permissions', set())
            
            if '*' in permissions or required_permission in permissions:
                return True
        
        return False


class ABACEngine:
    """Attribute-based access control engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
    
    def evaluate_attributes(
        self, 
        identity: Identity, 
        access_request: AccessRequest
    ) -> bool:
        """Evaluate access based on attributes"""
        # Example attribute-based rules
        
        # Time-based access
        current_hour = datetime.utcnow().hour
        if 'work_hours_only' in identity.attributes:
            if not (9 <= current_hour <= 17):
                return False
        
        # Location-based access
        if 'location_restricted' in identity.attributes:
            allowed_locations = identity.attributes.get('allowed_locations', [])
            current_location = access_request.context.get('location')
            if current_location not in allowed_locations:
                return False
        
        # Department-based access
        user_department = identity.attributes.get('department')
        resource_department = access_request.context.get('resource_department')
        if resource_department and user_department != resource_department:
            return False
        
        return True


class PolicyEngine:
    """Policy evaluation engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
    
    async def evaluate_policies(
        self,
        access_request: AccessRequest,
        identity: Identity,
        policies: List[AccessPolicy]
    ) -> AccessDecision:
        """Evaluate access policies"""
        # Sort policies by priority
        sorted_policies = sorted(policies, key=lambda p: p.priority)
        
        for policy in sorted_policies:
            if not policy.enabled:
                continue
            
            # Check if policy applies
            if not self._policy_applies(policy, access_request, identity):
                continue
            
            # Policy matches, return effect
            if policy.effect in [AccessDecision.ALLOW, AccessDecision.DENY]:
                return policy.effect
        
        # Default deny
        return AccessDecision.DENY
    
    def _policy_applies(
        self,
        policy: AccessPolicy,
        access_request: AccessRequest,
        identity: Identity
    ) -> bool:
        """Check if policy applies to request"""
        # Check resource pattern
        if not self._matches_pattern(policy.resource_pattern, access_request.resource):
            return False
        
        # Check actions
        if policy.actions != {'*'} and access_request.action not in policy.actions:
            return False
        
        # Check subjects
        if policy.subjects:
            subject_match = False
            
            # Check if identity is directly listed
            if identity.identity_id in policy.subjects:
                subject_match = True
            
            # Check roles
            if identity.roles & policy.subjects:
                subject_match = True
            
            # Check groups
            if identity.groups & policy.subjects:
                subject_match = True
            
            if not subject_match:
                return False
        
        # Check conditions
        if policy.conditions:
            if not self._evaluate_conditions(policy.conditions, access_request, identity):
                return False
        
        return True
    
    def _matches_pattern(self, pattern: str, resource: str) -> bool:
        """Check if resource matches pattern"""
        import fnmatch
        return fnmatch.fnmatch(resource, pattern)
    
    def _evaluate_conditions(
        self,
        conditions: Dict[str, Any],
        access_request: AccessRequest,
        identity: Identity
    ) -> bool:
        """Evaluate policy conditions"""
        # Time-based conditions
        if 'time_range' in conditions:
            time_range = conditions['time_range']
            current_hour = datetime.utcnow().hour
            if not (time_range['start'] <= current_hour <= time_range['end']):
                return False
        
        # IP-based conditions
        if 'allowed_ips' in conditions and access_request.source_ip:
            if access_request.source_ip not in conditions['allowed_ips']:
                return False
        
        return True


class IdentityRiskEngine:
    """Identity risk assessment engine"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
    
    async def calculate_authentication_risk(
        self,
        identity: Identity,
        auth_context: AuthenticationContext
    ) -> float:
        """Calculate authentication risk score"""
        risk_factors = []
        
        # Time-based risk
        current_hour = datetime.utcnow().hour
        if current_hour < 6 or current_hour > 22:
            risk_factors.append(0.3)  # Off-hours login
        
        # Location-based risk (simplified)
        if auth_context.source_ip:
            # In production, this would check against known good IPs
            if not auth_context.source_ip.startswith('192.168.'):
                risk_factors.append(0.4)  # External IP
        
        # Device-based risk
        if not auth_context.device_id:
            risk_factors.append(0.2)  # Unknown device
        
        # Calculate overall risk
        base_risk = identity.risk_score
        contextual_risk = sum(risk_factors)
        
        return min(1.0, base_risk + contextual_risk)


class IdentityAnalyticsEngine:
    """Identity analytics and monitoring"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._login_patterns = defaultdict(list)
    
    async def analyze_login_patterns(self, identity_id: str):
        """Analyze login patterns for anomalies"""
        patterns = self._login_patterns.get(identity_id, [])
        
        # Detect unusual login times
        if len(patterns) > 10:
            usual_hours = [p['hour'] for p in patterns[-30:]]  # Last 30 logins
            current_hour = datetime.utcnow().hour
            
            # Simple anomaly detection
            if current_hour not in usual_hours:
                self.logger.warning(f"Unusual login time for identity {identity_id}")
    
    def record_login_pattern(self, identity_id: str, login_time: datetime):
        """Record login pattern"""
        pattern = {
            'timestamp': login_time,
            'hour': login_time.hour,
            'day_of_week': login_time.weekday()
        }
        
        self._login_patterns[identity_id].append(pattern)
        
        # Keep only recent patterns
        if len(self._login_patterns[identity_id]) > 100:
            self._login_patterns[identity_id] = self._login_patterns[identity_id][-100:]


class SessionManager:
    """Session management"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
    
    async def cleanup_expired_sessions(self, sessions: Dict[str, Session]):
        """Cleanup expired sessions"""
        current_time = datetime.utcnow()
        expired_sessions = []
        
        for session_id, session in sessions.items():
            if session.expires_at < current_time:
                expired_sessions.append(session_id)
        
        for session_id in expired_sessions:
            del sessions[session_id]
        
        if expired_sessions:
            self.logger.info(f"Cleaned up {len(expired_sessions)} expired sessions")


