class IdentityAuditLogger:
    """Identity audit logging"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._audit_events = deque(maxlen=100000)
    
    async def log_event(self, event_type: str, **kwargs):
        """Log identity audit event"""
        event = {
            'event_id': f"AUD_{int(time.time())}_{secrets.token_hex(8)}",
            'event_type': event_type,
            'timestamp': datetime.utcnow().isoformat(),
            **kwargs
        }
        
        self._audit_events.append(event)
        
        # Log to system logger for high-severity events
        if event_type in ['authentication_failed', 'authorization_denied', 'policy_violation']:
            self.logger.warning(f"Identity audit event: {event_type} - {kwargs}")
    
    async def get_audit_events(
        self,
        event_types: Optional[List[str]] = None,
        identity_id: Optional[str] = None,
        time_range: Optional[timedelta] = None
    ) -> List[Dict[str, Any]]:
        """Get filtered audit events"""
        events = list(self._audit_events)
        
        if time_range:
            cutoff_time = datetime.utcnow() - time_range
            events = [e for e in events if datetime.fromisoformat(e['timestamp']) >= cutoff_time]
        
        if event_types:
            events = [e for e in events if e['event_type'] in event_types]
        
        if identity_id:
            events = [e for e in events if e.get('identity_id') == identity_id]
        
        return events

