class UnifiedSecurityManager:
    """Unified security management system orchestrating all security components."""
    
    def __init__(self, integration_level: SecurityIntegrationLevel = SecurityIntegrationLevel.ADVANCED):
        """Initialize unified security manager."""
        self.integration_level = integration_level
        self.operation_mode = SecurityOperationMode.NORMAL
        self.initialized = False
        
        # Security components
        self.auth_manager = None
        self.authz_manager = None
        self.policy_engine = None
        self.threat_engine = None
        self.config_manager = None
        self.metrics_collector = None
        self.alerts_manager = None
        self.report_generator = None
        self.validator = None
        
        # Configuration
        self.config = {
            "authentication": {
                "require_mfa_for_admin": True,
                "session_timeout": 3600,
                "max_concurrent_sessions": 5
            },
            "authorization": {
                "strict_rbac": True,
                "resource_isolation": True,
                "audit_all_access": True
            },
            "threat_detection": {
                "real_time_analysis": True,
                "ml_based_detection": True,
                "behavioral_analysis": True
            },
            "policy_enforcement": {
                "auto_remediation": True,
                "compliance_monitoring": True,
                "violation_alerts": True
            },
            "monitoring": {
                "real_time_metrics": True,
                "alert_aggregation": True,
                "dashboard_updates": True
            }
        }
        
        # Security state
        self.security_state = {
            "active_sessions": {},
            "blocked_ips": set(),
            "active_threats": [],
            "policy_violations": [],
            "system_health": "healthy"
        }
    
    async def initialize(self):
        """Initialize all security components."""
        if self.initialized:
            return
        
        logger.info(f"Initializing Unified Security Manager (Level: {self.integration_level.value})")
        
        try:
            # Initialize core components
            self.auth_manager = await get_auth_manager()
            self.authz_manager = get_authz_manager()
            self.policy_engine = get_policy_engine()
            self.threat_engine = await get_threat_engine()
            self.config_manager = get_config_manager()
            
            # Initialize monitoring components
            self.metrics_collector = get_metrics_collector()
            self.alerts_manager = get_alerts_manager()
            self.report_generator = get_report_generator()
            
            # Initialize validator if advanced integration
            if self.integration_level in [SecurityIntegrationLevel.ADVANCED, SecurityIntegrationLevel.MAXIMUM]:
                self.validator = SecurityValidationSuite()
            
            # Run initial security validation
            await self._perform_initialization_checks()
            
            self.initialized = True
            logger.info("Unified Security Manager initialized successfully")
            
            # Record initialization event
            record_security_event(
                SecurityEvent.CONFIG_CHANGE,
                tenant_id="system",
                operation="security_manager_init",
                integration_level=self.integration_level.value
            )
            
        except Exception as e:
            logger.error(f"Failed to initialize Unified Security Manager: {e}")
            raise
    
    async def _perform_initialization_checks(self):
        """Perform security checks during initialization."""
        checks = []
        
        # Check authentication manager
        if self.auth_manager:
            checks.append(" Authentication Manager")
        else:
            checks.append(" Authentication Manager")
        
        # Check authorization manager
        if self.authz_manager:
            checks.append(" Authorization Manager")
        else:
            checks.append(" Authorization Manager")
        
        # Check policy engine
        if self.policy_engine:
            checks.append(" Policy Engine")
        else:
            checks.append(" Policy Engine")
        
        # Check threat intelligence
        if self.threat_engine:
            checks.append(" Threat Intelligence")
        else:
            checks.append(" Threat Intelligence")
        
        logger.info(f"Security components status: {', '.join(checks)}")
        
        # Run quick validation if available
        if self.validator and self.integration_level == SecurityIntegrationLevel.MAXIMUM:
            try:
                validation_result = await self.validator.run_quick_security_check()
                logger.info(f"Quick security validation: {validation_result['summary']['pass_rate']:.1f}% pass rate")
            except Exception as e:
                logger.warning(f"Quick security validation failed: {e}")
    
    async def authenticate_and_authorize(
        self,
        context: SecurityContext,
        required_permissions: Set[str] = None
    ) -> SecurityResult:
        """Perform comprehensive authentication and authorization."""
        start_time = datetime.utcnow()
        
        if not self.initialized:
            await self.initialize()
        
        # Initialize result
        result = SecurityResult(
            allowed=False,
            user=None,
            policies_applied=[],
            threats_detected=[],
            confidence_score=0.0,
            alerts_generated=[],
            recommendations=[],
            execution_time=0.0
        )
        
        try:
            # Step 1: Threat analysis (pre-authentication)
            if self.config["threat_detection"]["real_time_analysis"]:
                threats, anomalies = await self._analyze_threats(context)
                result.threats_detected.extend([t['type'] for t in threats])
                
                # Block if critical threats detected
                critical_threats = [t for t in threats if t.get('severity') == 'critical']
                if critical_threats:
                    await self._handle_critical_threat(context, critical_threats)
                    result.recommendations.append("Access blocked due to critical threat detection")
                    return result
            
            # Step 2: IP and rate limiting checks
            if not await self._check_ip_and_rate_limits(context):
                result.recommendations.append("Access blocked due to rate limiting or IP restrictions")
                return result
            
            # Step 3: Authentication
            user = await self._authenticate_user(context)
            if not user:
                await self._handle_authentication_failure(context)
                result.recommendations.append("Authentication failed")
                return result
            
            result.user = user
            
            # Step 4: Session validation
            if not await self._validate_session(context, user):
                result.recommendations.append("Session validation failed")
                return result
            
            # Step 5: Authorization
            if required_permissions:
                if not await self._authorize_user(context, user, required_permissions):
                    await self._handle_authorization_failure(context, user, required_permissions)
                    result.recommendations.append("Authorization failed - insufficient permissions")
                    return result
            
            # Step 6: Policy enforcement
            policy_result = await self._enforce_policies(context, user)
            result.policies_applied = policy_result['applied_policies']
            
            if not policy_result['compliant']:
                await self._handle_policy_violation(context, user, policy_result)
                result.recommendations.append("Access denied due to policy violations")
                return result
            
            # Step 7: Final security assessment
            result.confidence_score = await self._calculate_confidence_score(context, user, result)
            
            # Success
            result.allowed = True
            
            # Record successful access
            record_security_event(
                SecurityEvent.DATA_ACCESS,
                tenant_id=context.tenant_id,
                user_id=context.user_id,
                source_ip=context.source_ip,
                operation=context.operation,
                resource=context.resource
            )
            
        except Exception as e:
            logger.error(f"Error in authentication/authorization: {e}")
            result.recommendations.append(f"System error: {str(e)}")
            
            # Create alert for system errors
            create_security_alert(
                name="auth_system_error",
                severity=AlertSeverity.HIGH,
                message=f"Authentication system error: {e}",
                tenant_id=context.tenant_id,
                event_type=SecurityEvent.ANOMALY_DETECTED,
                error=str(e),
                operation=context.operation
            )
        
        finally:
            result.execution_time = (datetime.utcnow() - start_time).total_seconds()
        
        return result
    
    async def _analyze_threats(self, context: SecurityContext) -> Tuple[List[Dict], List[Dict]]:
        """Analyze threats for the given context."""
        if not self.threat_engine:
            return [], []
        
        activity = {
            "event_type": context.operation,
            "source_ip": context.source_ip,
            "timestamp": context.timestamp,
            "user_agent": context.user_agent,
            "resource": context.resource
        }
        
        return await self.threat_engine.analyze_activity(
            context.tenant_id,
            context.user_id or "anonymous",
            activity
        )
    
    async def _handle_critical_threat(self, context: SecurityContext, threats: List[Dict]):
        """Handle critical threat detection."""
        for threat in threats:
            # Create critical alert
            create_security_alert(
                name="critical_threat_detected",
                severity=AlertSeverity.CRITICAL,
                message=f"Critical threat detected: {threat.get('type', 'unknown')}",
                tenant_id=context.tenant_id,
                event_type=SecurityEvent.THREAT_DETECTED,
                threat_type=threat.get('type'),
                confidence=threat.get('confidence'),
                source_ip=context.source_ip
            )
            
            # Block IP if configured
            if threat.get('block_ip', False):
                self.security_state['blocked_ips'].add(context.source_ip)
        
        # Record threat event
        record_security_event(
            SecurityEvent.THREAT_DETECTED,
            tenant_id=context.tenant_id,
            source_ip=context.source_ip,
            threat_count=len(threats),
            operation=context.operation
        )
    
    async def _check_ip_and_rate_limits(self, context: SecurityContext) -> bool:
        """Check IP restrictions and rate limits."""
        # Check blocked IPs
        if context.source_ip in self.security_state['blocked_ips']:
            record_security_event(
                SecurityEvent.LOGIN_BLOCKED,
                tenant_id=context.tenant_id,
                source_ip=context.source_ip,
                reason="blocked_ip"
            )
            return False
        
        # Additional rate limiting logic would go here
        return True
    
    async def _authenticate_user(self, context: SecurityContext) -> Optional[User]:
        """Authenticate user based on context."""
        if not self.auth_manager or not context.user_id:
            return None
        
        # For this integration, we'll assume the user is already pre-authenticated
        # In a real implementation, this would validate tokens, passwords, etc.
        try:
            # Simulate user lookup
            user = User(
                user_id=context.user_id,
                username=f"user_{context.user_id}",
                email=f"{context.user_id}@example.com",
                tenant_id=context.tenant_id,
                roles=set()  # Would be populated from database
            )
            return user
        except Exception as e:
            logger.error(f"User authentication failed: {e}")
            return None
    
    async def _handle_authentication_failure(self, context: SecurityContext):
        """Handle authentication failure."""
        record_security_event(
            SecurityEvent.LOGIN_FAILURE,
            tenant_id=context.tenant_id,
            source_ip=context.source_ip,
            operation=context.operation
        )
    
    async def _validate_session(self, context: SecurityContext, user: User) -> bool:
        """Validate user session."""
        if not context.session_id:
            return True  # No session validation required
        
        # Session validation logic would go here
        return True
    
    async def _authorize_user(self, context: SecurityContext, user: User, required_permissions: Set[str]) -> bool:
        """Authorize user for required permissions."""
        if not self.authz_manager:
            return True  # No authorization manager
        
        try:
            return self.authz_manager.check_permissions(user, required_permissions)
        except Exception as e:
            logger.error(f"Authorization check failed: {e}")
            return False
    
    async def _handle_authorization_failure(self, context: SecurityContext, user: User, required_permissions: Set[str]):
        """Handle authorization failure."""
        record_security_event(
            SecurityEvent.PERMISSION_DENIED,
            tenant_id=context.tenant_id,
            user_id=user.user_id,
            source_ip=context.source_ip,
            operation=context.operation,
            resource=context.resource,
            required_permissions=list(required_permissions)
        )
    
    async def _enforce_policies(self, context: SecurityContext, user: User) -> Dict[str, Any]:
        """Enforce security policies."""
        if not self.policy_engine:
            return {"compliant": True, "applied_policies": [], "violations": []}
        
        policy_context = {
            "user": {
                "id": user.user_id,
                "tenant_id": user.tenant_id,
                "roles": [role.value for role in user.roles]
            },
            "request": {
                "operation": context.operation,
                "resource": context.resource,
                "source_ip": context.source_ip,
                "timestamp": context.timestamp.isoformat()
            },
            "metadata": context.metadata
        }
        
        try:
            # Get applicable policies for tenant
            policies = self.policy_engine.get_policies(context.tenant_id)
            applied_policies = []
            violations = []
            
            for policy in policies:
                is_compliant, policy_violations, actions = await self.policy_engine.evaluate_policy(
                    policy.policy_id, policy_context
                )
                
                applied_policies.append(policy.policy_id)
                
                if not is_compliant:
                    violations.extend(policy_violations)
            
            return {
                "compliant": len(violations) == 0,
                "applied_policies": applied_policies,
                "violations": violations
            }
        
        except Exception as e:
            logger.error(f"Policy enforcement failed: {e}")
            return {"compliant": False, "applied_policies": [], "violations": [str(e)]}
    
    async def _handle_policy_violation(self, context: SecurityContext, user: User, policy_result: Dict[str, Any]):
        """Handle policy violations."""
        for violation in policy_result['violations']:
            # Record violation event
            record_security_event(
                SecurityEvent.POLICY_VIOLATION,
                tenant_id=context.tenant_id,
                user_id=user.user_id,
                source_ip=context.source_ip,
                operation=context.operation,
                policy_id=violation.get('policy_id'),
                violation_type=violation.get('type')
            )
            
            # Create alert for violations
            create_security_alert(
                name="policy_violation",
                severity=AlertSeverity.MEDIUM,
                message=f"Policy violation: {violation.get('message', 'Unknown violation')}",
                tenant_id=context.tenant_id,
                event_type=SecurityEvent.POLICY_VIOLATION,
                user_id=user.user_id,
                policy_id=violation.get('policy_id'),
                violation_details=violation
            )
    
    async def _calculate_confidence_score(self, context: SecurityContext, user: User, result: SecurityResult) -> float:
        """Calculate confidence score for the security decision."""
        base_score = 0.8  # Base confidence
        
        # Adjust based on threats
        if result.threats_detected:
            base_score -= len(result.threats_detected) * 0.1
        
        # Adjust based on policies
        if result.policies_applied:
            base_score += len(result.policies_applied) * 0.05
        
        # Adjust based on user reputation (simplified)
        # In reality, this would look at user history, behavior patterns, etc.
        base_score += 0.1
        
        return max(0.0, min(1.0, base_score))
    
    async def perform_security_audit(self, tenant_id: Optional[str] = None) -> Dict[str, Any]:
        """Perform comprehensive security audit."""
        if not self.initialized:
            await self.initialize()
        
        logger.info(f"Performing security audit for tenant: {tenant_id or 'all'}")
        
        audit_results = {
            "audit_timestamp": datetime.utcnow().isoformat(),
            "tenant_id": tenant_id,
            "components": {},
            "overall_status": "unknown"
        }
        
        # Component audits
        if self.validator and self.integration_level in [SecurityIntegrationLevel.ADVANCED, SecurityIntegrationLevel.MAXIMUM]:
            try:
                validation_results = await self.validator.run_all_tests()
                audit_results["components"]["validation"] = validation_results
            except Exception as e:
                audit_results["components"]["validation"] = {"error": str(e)}
        
        # Security metrics audit
        if self.metrics_collector:
            try:
                dashboard_data = self.metrics_collector.get_security_dashboard_data()
                audit_results["components"]["metrics"] = dashboard_data
            except Exception as e:
                audit_results["components"]["metrics"] = {"error": str(e)}
        
        # Alerts audit
        if self.alerts_manager:
            try:
                alert_stats = self.alerts_manager.get_alert_statistics(24)
                audit_results["components"]["alerts"] = alert_stats
            except Exception as e:
                audit_results["components"]["alerts"] = {"error": str(e)}
        
        # Generate overall status
        audit_results["overall_status"] = self._assess_overall_security_status(audit_results)
        
        return audit_results
    
    def _assess_overall_security_status(self, audit_results: Dict[str, Any]) -> str:
        """Assess overall security status from audit results."""
        issues = 0
        
        # Check validation results
        validation = audit_results["components"].get("validation", {})
        if "summary" in validation:
            pass_rate = validation["summary"].get("pass_rate", 0)
            if pass_rate < 80:
                issues += 2
            elif pass_rate < 95:
                issues += 1
        
        # Check alerts
        alerts = audit_results["components"].get("alerts", {})
        if "by_severity" in alerts:
            critical_alerts = alerts["by_severity"].get("critical", 0)
            high_alerts = alerts["by_severity"].get("high", 0)
            issues += critical_alerts * 2 + high_alerts
        
        # Check metrics
        metrics = audit_results["components"].get("metrics", {})
        if "summary" in metrics:
            active_threats = metrics["summary"].get("active_threats", 0)
            blocked_ips = metrics["summary"].get("blocked_ips_count", 0)
            issues += active_threats + (blocked_ips // 5)
        
        # Determine status
        if issues == 0:
            return "excellent"
        elif issues <= 2:
            return "good"
        elif issues <= 5:
            return "fair"
        elif issues <= 10:
            return "poor"
        else:
            return "critical"
    
    async def generate_comprehensive_report(self, tenant_id: Optional[str] = None, hours: int = 24) -> Dict[str, Any]:
        """Generate comprehensive security report."""
        if not self.initialized:
            await self.initialize()
        
        if not self.report_generator:
            raise RuntimeError("Report generator not available")
        
        # Generate main security report
        security_report = self.report_generator.generate_security_summary_report(tenant_id, hours)
        
        # Add unified manager context
        security_report["unified_manager"] = {
            "integration_level": self.integration_level.value,
            "operation_mode": self.operation_mode.value,
            "components_status": {
                "auth_manager": self.auth_manager is not None,
                "authz_manager": self.authz_manager is not None,
                "policy_engine": self.policy_engine is not None,
                "threat_engine": self.threat_engine is not None,
                "metrics_collector": self.metrics_collector is not None,
                "alerts_manager": self.alerts_manager is not None,
                "validator": self.validator is not None
            }
        }
        
        # Add system state
        security_report["system_state"] = {
            "blocked_ips_count": len(self.security_state['blocked_ips']),
            "active_sessions_count": len(self.security_state['active_sessions']),
            "active_threats_count": len(self.security_state['active_threats']),
            "policy_violations_count": len(self.security_state['policy_violations']),
            "overall_health": self.security_state['system_health']
        }
        
        return security_report
    
    def set_operation_mode(self, mode: SecurityOperationMode):
        """Set security operation mode."""
        logger.info(f"Changing security operation mode from {self.operation_mode.value} to {mode.value}")
        
        self.operation_mode = mode
        
        # Record mode change
        record_security_event(
            SecurityEvent.CONFIG_CHANGE,
            tenant_id="system",
            operation="mode_change",
            old_mode=self.operation_mode.value,
            new_mode=mode.value
        )
        
        # Create alert for mode changes
        if mode in [SecurityOperationMode.HIGH_ALERT, SecurityOperationMode.LOCKDOWN]:
            create_security_alert(
                name="security_mode_change",
                severity=AlertSeverity.HIGH if mode == SecurityOperationMode.HIGH_ALERT else AlertSeverity.CRITICAL,
                message=f"Security operation mode changed to {mode.value}",
                tenant_id="system",
                event_type=SecurityEvent.CONFIG_CHANGE,
                new_mode=mode.value
            )
    
    @asynccontextmanager
    async def security_context(self, context: SecurityContext, required_permissions: Set[str] = None):
        """Async context manager for security operations."""
        start_time = datetime.utcnow()
        
        try:
            # Perform authentication and authorization
            result = await self.authenticate_and_authorize(context, required_permissions)
            
            if not result.allowed:
                raise PermissionError(f"Access denied: {', '.join(result.recommendations)}")
            
            # Yield the security result
            yield result
            
        except Exception as e:
            # Log security exception
            logger.error(f"Security context error: {e}")
            
            # Record security event
            record_security_event(
                SecurityEvent.ANOMALY_DETECTED,
                tenant_id=context.tenant_id,
                user_id=context.user_id,
                source_ip=context.source_ip,
                operation=context.operation,
                error=str(e)
            )
            
            raise
        
        finally:
            # Record operation completion
            execution_time = (datetime.utcnow() - start_time).total_seconds()
            
            # Record timing metric
            if self.metrics_collector:
                self.metrics_collector.record_operation_timing(
                    context.operation,
                    execution_time,
                    tenant_id=context.tenant_id,
                    user_id=context.user_id
                )


# Global unified security manager instance
_unified_security_manager = None


async def get_unified_security_manager(
    integration_level: SecurityIntegrationLevel = SecurityIntegrationLevel.ADVANCED
) -> UnifiedSecurityManager:
    """Get global unified security manager instance."""
    global _unified_security_manager
    
    if _unified_security_manager is None:
        _unified_security_manager = UnifiedSecurityManager(integration_level)
        await _unified_security_manager.initialize()
    
    return _unified_security_manager


# Convenience functions
async def secure_operation(
    operation: str,
    tenant_id: str,
    user_id: Optional[str] = None,
    source_ip: Optional[str] = None,
    required_permissions: Set[str] = None,
    **metadata
):
    """Decorator/context manager for secure operations."""
    manager = await get_unified_security_manager()
    
    context = SecurityContext(
        tenant_id=tenant_id,
        user_id=user_id,
        source_ip=source_ip,
        user_agent=metadata.get('user_agent'),
        session_id=metadata.get('session_id'),
        operation=operation,
        resource=metadata.get('resource'),
        timestamp=datetime.utcnow(),
        metadata=metadata
    )
    
    return manager.security_context(context, required_permissions)


async def perform_security_check(tenant_id: str, **kwargs) -> Dict[str, Any]:
    """Perform quick security check."""
    manager = await get_unified_security_manager()
    return await manager.perform_security_audit(tenant_id)


async def generate_security_report(tenant_id: Optional[str] = None, hours: int = 24) -> Dict[str, Any]:
    """Generate comprehensive security report."""
    manager = await get_unified_security_manager()
    return await manager.generate_comprehensive_report(tenant_id, hours)

