class PodSecurityStandard(Enum):
    """Pod Security Standards levels."""
    PRIVILEGED = "privileged"
    BASELINE = "baseline"
    RESTRICTED = "restricted"

class NetworkPolicyType(Enum):
    """Network policy types."""
    INGRESS = "Ingress"
    EGRESS = "Egress"
    BOTH = "Both"

class WorkloadType(Enum):
    """Kubernetes workload types."""
    DEPLOYMENT = "Deployment"
    STATEFULSET = "StatefulSet"
    DAEMONSET = "DaemonSet"
    JOB = "Job"
    CRONJOB = "CronJob"
    POD = "Pod"

@dataclass
class SecurityPolicy:
    """Kubernetes security policy definition."""
    name: str
    namespace: str
    policy_type: str
    rules: List[Dict[str, Any]]
    labels: Dict[str, str] = field(default_factory=dict)
    annotations: Dict[str, str] = field(default_factory=dict)

@dataclass
class WorkloadSecurityConfig:
    """Security configuration for workloads."""
    security_context: Dict[str, Any]
    pod_security_standard: PodSecurityStandard
    network_policies: List[str]
    resource_quotas: Dict[str, str]
    secrets: List[str] = field(default_factory=list)
    service_account: Optional[str] = None

@dataclass
class SecurityViolation:
    """Security policy violation."""
    violation_id: str
    severity: SecurityLevel
    workload: str
    namespace: str
    policy: str
    description: str
    timestamp: datetime = field(default_factory=datetime.utcnow)
    remediated: bool = False

class KubernetesSecurityManager:
    """
    Ultra-Advanced Kubernetes Security Manager
    
    Comprehensive security manager for Kubernetes environments providing
    enterprise-grade security controls, policy enforcement, and monitoring.
    """
    
    def __init__(self, config: SecurityPlatformConfig):
        """Initialize Kubernetes security manager."""
        if not KUBERNETES_AVAILABLE:
            raise RuntimeError("Kubernetes client library not available")
        
        self.config = config
        self.k8s_client = None
        self.apps_v1 = None
        self.core_v1 = None
        self.networking_v1 = None
        self.rbac_v1 = None
        
        # Security configurations
        self.security_policies: Dict[str, SecurityPolicy] = {}
        self.workload_configs: Dict[str, WorkloadSecurityConfig] = {}
        self.security_violations: List[SecurityViolation] = []
        
        # Pod Security Standards
        self.pss_profiles = {
            PodSecurityStandard.PRIVILEGED: {},  # No restrictions
            PodSecurityStandard.BASELINE: self._get_baseline_pss(),
            PodSecurityStandard.RESTRICTED: self._get_restricted_pss()
        }
        
        # Default security contexts
        self.default_security_contexts = {
            "restrictive": {
                "runAsNonRoot": True,
                "runAsUser": 1000,
                "runAsGroup": 1000,
                "readOnlyRootFilesystem": True,
                "allowPrivilegeEscalation": False,
                "capabilities": {
                    "drop": ["ALL"]
                },
                "seccompProfile": {
                    "type": "RuntimeDefault"
                }
            },
            "moderate": {
                "runAsNonRoot": True,
                "allowPrivilegeEscalation": False,
                "capabilities": {
                    "drop": ["ALL"],
                    "add": ["NET_BIND_SERVICE"]
                }
            }
        }
        
        # Network policy templates
        self.network_policy_templates = {
            "deny_all": self._get_deny_all_template(),
            "allow_same_namespace": self._get_allow_same_namespace_template(),
            "database_access": self._get_database_access_template(),
            "api_gateway": self._get_api_gateway_template()
        }
        
    async def initialize(self) -> None:
        """Initialize Kubernetes security manager."""



        try:
            # Load Kubernetes config
            if os.path.exists('/var/run/secrets/kubernetes.io/serviceaccount'):
                # Running in cluster
                config.load_incluster_config()
            else:
                # Running outside cluster
                config.load_kube_config()
            
            # Initialize API clients
            self.k8s_client = client.ApiClient()
            self.apps_v1 = client.AppsV1Api()
            self.core_v1 = client.CoreV1Api()
            self.networking_v1 = client.NetworkingV1Api()
            self.rbac_v1 = client.RbacAuthorizationV1Api()
            
            # Create default security resources
            await self._create_default_security_resources()
            
            # Start security monitoring
            await self._start_security_monitoring()
            
            logger.info("KubernetesSecurityManager initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize KubernetesSecurityManager: {e}")
            raise
    
    # Pod Security Standards
    
    async def apply_pod_security_standard(self, namespace: str, 
                                        standard: PodSecurityStandard,
                                        enforce: bool = True) -> bool:
        """Apply Pod Security Standard to namespace."""



        try:
            # Get current namespace
            try:
                ns = self.core_v1.read_namespace(name=namespace)
            except ApiException as e:
                if e.status == 404:
                    logger.error(f"Namespace {namespace} not found")
                    return False
                raise
            
            # Update namespace labels for Pod Security Standards
            labels = ns.metadata.labels or {}
            
            if enforce:
                labels[f"pod-security.kubernetes.io/enforce"] = standard.value
                labels[f"pod-security.kubernetes.io/audit"] = standard.value
                labels[f"pod-security.kubernetes.io/warn"] = standard.value
            else:
                labels[f"pod-security.kubernetes.io/audit"] = standard.value
                labels[f"pod-security.kubernetes.io/warn"] = standard.value
            
            # Apply labels
            ns.metadata.labels = labels
            self.core_v1.patch_namespace(name=namespace, body=ns)
            
            logger.info(f"Applied Pod Security Standard {standard.value} to namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to apply Pod Security Standard: {e}")
            return False
    
    async def validate_pod_security(self, pod_spec: Dict[str, Any], 
                                   standard: PodSecurityStandard) -> Tuple[bool, List[str]]:
        """Validate pod specification against security standard."""
        violations = []
        
        try:
            pss_rules = self.pss_profiles[standard]
            
            # Check security context
            security_context = pod_spec.get('securityContext', {})
            
            # Validate runAsNonRoot
            if pss_rules.get('runAsNonRoot') and not security_context.get('runAsNonRoot', False):
                violations.append("Pod must run as non-root user")
            
            # Validate privileged containers
            containers = pod_spec.get('containers', [])
            for i, container in enumerate(containers):
                container_sc = container.get('securityContext', {})
                
                if container_sc.get('privileged', False):
                    violations.append(f"Container {i} cannot run in privileged mode")
                
                if container_sc.get('allowPrivilegeEscalation', True):
                    violations.append(f"Container {i} must disable privilege escalation")
                
                # Check capabilities
                caps = container_sc.get('capabilities', {})
                forbidden_caps = pss_rules.get('forbiddenCapabilities', [])
                if 'add' in caps:
                    for cap in caps['add']:
                        if cap in forbidden_caps:
                            violations.append(f"Container {i} cannot add capability {cap}")
            
            # Check volumes
            volumes = pod_spec.get('volumes', [])
            forbidden_volume_types = pss_rules.get('forbiddenVolumeTypes', [])
            for volume in volumes:
                for vol_type in forbidden_volume_types:
                    if vol_type in volume:
                        violations.append(f"Volume type {vol_type} is forbidden")
            
            return len(violations) == 0, violations
            
        except Exception as e:
            logger.error(f"Pod security validation failed: {e}")
            return False, [f"Validation error: {e}"]
    
    # Network Policies
    
    async def create_network_policy(self, name: str, namespace: str,
                                   policy_type: NetworkPolicyType,
                                   pod_selector: Dict[str, str],
                                   ingress_rules: Optional[List[Dict[str, Any]]] = None,
                                   egress_rules: Optional[List[Dict[str, Any]]] = None) -> bool:
        """Create Kubernetes network policy."""



        try:
            policy_types = []
            if policy_type in [NetworkPolicyType.INGRESS, NetworkPolicyType.BOTH]:
                policy_types.append("Ingress")
            if policy_type in [NetworkPolicyType.EGRESS, NetworkPolicyType.BOTH]:
                policy_types.append("Egress")
            
            network_policy = client.V1NetworkPolicy(
                metadata=client.V1ObjectMeta(
                    name=name,
                    namespace=namespace,
                    labels={
                        "managed-by": "spotify-ai-agent-security",
                        "security-level": "high"
                    }
                ),
                spec=client.V1NetworkPolicySpec(
                    pod_selector=client.V1LabelSelector(
                        match_labels=pod_selector
                    ),
                    policy_types=policy_types,
                    ingress=ingress_rules or [],
                    egress=egress_rules or []
                )
            )
            
            # Apply network policy
            self.networking_v1.create_namespaced_network_policy(
                namespace=namespace,
                body=network_policy
            )
            
            logger.info(f"Created network policy {name} in namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to create network policy: {e}")
            return False
    
    async def apply_network_segmentation(self, namespace: str,
                                       segmentation_config: Dict[str, Any]) -> bool:
        """Apply comprehensive network segmentation."""



        try:
            # Create default deny-all policy
            await self.create_network_policy(
                name=f"{namespace}-deny-all",
                namespace=namespace,
                policy_type=NetworkPolicyType.BOTH,
                pod_selector={},
                ingress_rules=[],
                egress_rules=[]
            )
            
            # Create specific allow policies
            for policy_name, policy_config in segmentation_config.items():
                await self.create_network_policy(
                    name=f"{namespace}-{policy_name}",
                    namespace=namespace,
                    policy_type=NetworkPolicyType(policy_config['type']),
                    pod_selector=policy_config['selector'],
                    ingress_rules=policy_config.get('ingress', []),
                    egress_rules=policy_config.get('egress', [])
                )
            
            logger.info(f"Applied network segmentation to namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to apply network segmentation: {e}")
            return False
    
    # RBAC Integration
    
    async def create_security_role(self, name: str, namespace: str,
                                  permissions: List[Dict[str, Any]]) -> bool:
        """Create Kubernetes role with specific permissions."""



        try:
            # Convert permissions to PolicyRule objects
            rules = []
            for perm in permissions:
                rule = client.V1PolicyRule(
                    api_groups=perm.get('apiGroups', ['']),
                    resources=perm.get('resources', []),
                    verbs=perm.get('verbs', []),
                    resource_names=perm.get('resourceNames', [])
                )
                rules.append(rule)
            
            # Create Role
            role = client.V1Role(
                metadata=client.V1ObjectMeta(
                    name=name,
                    namespace=namespace,
                    labels={
                        "managed-by": "spotify-ai-agent-security",
                        "security-role": "true"
                    }
                ),
                rules=rules
            )
            
            self.rbac_v1.create_namespaced_role(namespace=namespace, body=role)
            
            logger.info(f"Created security role {name} in namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to create security role: {e}")
            return False
    
    async def bind_role_to_service_account(self, role_name: str, 
                                         service_account: str,
                                         namespace: str) -> bool:
        """Bind role to service account."""



        try:
            role_binding = client.V1RoleBinding(
                metadata=client.V1ObjectMeta(
                    name=f"{role_name}-binding",
                    namespace=namespace
                ),
                subjects=[
                    client.V1Subject(
                        kind="ServiceAccount",
                        name=service_account,
                        namespace=namespace
                    )
                ],
                role_ref=client.V1RoleRef(
                    kind="Role",
                    name=role_name,
                    api_group="rbac.authorization.k8s.io"
                )
            )
            
            self.rbac_v1.create_namespaced_role_binding(
                namespace=namespace,
                body=role_binding
            )
            
            logger.info(f"Bound role {role_name} to service account {service_account}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to bind role: {e}")
            return False
    
    # Secrets Management
    
    async def create_secure_secret(self, name: str, namespace: str,
                                  secret_data: Dict[str, str],
                                  secret_type: str = "Opaque") -> bool:
        """Create Kubernetes secret with enhanced security."""



        try:
            # Encode secret data
            encoded_data = {}
            for key, value in secret_data.items():
                encoded_data[key] = base64.b64encode(value.encode()).decode()
            
            secret = client.V1Secret(
                metadata=client.V1ObjectMeta(
                    name=name,
                    namespace=namespace,
                    labels={
                        "managed-by": "spotify-ai-agent-security",
                        "security-level": "high"
                    },
                    annotations={
                        "spotify-ai-agent/created-at": datetime.utcnow().isoformat(),
                        "spotify-ai-agent/encryption": "true"
                    }
                ),
                type=secret_type,
                data=encoded_data
            )
            
            self.core_v1.create_namespaced_secret(namespace=namespace, body=secret)
            
            logger.info(f"Created secure secret {name} in namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to create secure secret: {e}")
            return False
    
    async def rotate_secret(self, secret_name: str, namespace: str,
                           new_data: Dict[str, str]) -> bool:
        """Rotate Kubernetes secret."""



        try:
            # Get existing secret
            secret = self.core_v1.read_namespaced_secret(
                name=secret_name,
                namespace=namespace
            )
            
            # Update data
            encoded_data = {}
            for key, value in new_data.items():
                encoded_data[key] = base64.b64encode(value.encode()).decode()
            
            secret.data = encoded_data
            secret.metadata.annotations = secret.metadata.annotations or {}
            secret.metadata.annotations["spotify-ai-agent/rotated-at"] = datetime.utcnow().isoformat()
            
            # Apply update
            self.core_v1.patch_namespaced_secret(
                name=secret_name,
                namespace=namespace,
                body=secret
            )
            
            logger.info(f"Rotated secret {secret_name} in namespace {namespace}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to rotate secret: {e}")
            return False
    
    # Workload Security
    
    async def secure_deployment(self, deployment_name: str, namespace: str,
                               security_config: WorkloadSecurityConfig) -> bool:
        """Apply security configuration to deployment."""



        try:
            # Get deployment
            deployment = self.apps_v1.read_namespaced_deployment(
                name=deployment_name,
                namespace=namespace
            )
            
            # Apply security context
            if deployment.spec.template.spec.security_context is None:
                deployment.spec.template.spec.security_context = client.V1PodSecurityContext()
            
            # Update pod security context
            for key, value in security_config.security_context.items():
                setattr(deployment.spec.template.spec.security_context, key, value)
            
            # Apply container security contexts
            for container in deployment.spec.template.spec.containers:
                if container.security_context is None:
                    container.security_context = client.V1SecurityContext()
                
                # Apply restrictive defaults
                restrictive_context = self.default_security_contexts["restrictive"]
                for key, value in restrictive_context.items():
                    if key == "capabilities":
                        container.security_context.capabilities = client.V1Capabilities(
                            drop=value.get("drop", []),
                            add=value.get("add", [])
                        )
                    elif key == "seccompProfile":
                        container.security_context.seccomp_profile = client.V1SeccompProfile(
                            type=value["type"]
                        )
                    else:
                        setattr(container.security_context, key, value)
            
            # Set service account
            if security_config.service_account:
                deployment.spec.template.spec.service_account_name = security_config.service_account
            
            # Update deployment
            self.apps_v1.patch_namespaced_deployment(
                name=deployment_name,
                namespace=namespace,
                body=deployment
            )
            
            logger.info(f"Applied security configuration to deployment {deployment_name}")
            return True
            
        except Exception as e:
            logger.error(f"Failed to secure deployment: {e}")
            return False
    
    # Security Monitoring
    
    async def _start_security_monitoring(self) -> None:
        """Start security event monitoring."""



        try:
            # Monitor pod events
            asyncio.create_task(self._monitor_pod_events())
            
            # Monitor network policy violations
            asyncio.create_task(self._monitor_network_violations())
            
            # Monitor RBAC violations
            asyncio.create_task(self._monitor_rbac_violations())
            
            logger.info("Started Kubernetes security monitoring")
            
        except Exception as e:
            logger.error(f"Failed to start security monitoring: {e}")
    
    async def _monitor_pod_events(self) -> None:
        """Monitor pod security events."""



        try:
            w = watch.Watch()
            for event in w.stream(self.core_v1.list_pod_for_all_namespaces):
                event_type = event['type']
                pod = event['object']
                
                if event_type in ['ADDED', 'MODIFIED']:
                    await self._validate_pod_security_realtime(pod)
                    
        except Exception as e:
            logger.error(f"Pod event monitoring failed: {e}")
    
    async def _validate_pod_security_realtime(self, pod: client.V1Pod) -> None:
        """Validate pod security in real-time."""



        try:
            # Check if pod meets security standards
            namespace = pod.metadata.namespace
            
            # Get namespace pod security standard
            try:
                ns = self.core_v1.read_namespace(name=namespace)
                enforce_label = ns.metadata.labels.get('pod-security.kubernetes.io/enforce')
                if enforce_label:
                    standard = PodSecurityStandard(enforce_label)
                    
                    # Convert pod to spec dict for validation
                    pod_spec = self.k8s_client.sanitize_for_serialization(pod.spec)
                    
                    is_valid, violations = await self.validate_pod_security(pod_spec, standard)
                    
                    if not is_valid:
                        await self._create_security_violation(
                            workload=pod.metadata.name,
                            namespace=namespace,
                            policy=f"pod-security-{standard.value}",
                            description=f"Pod security violations: {', '.join(violations)}",
                            severity=SecurityLevel.HIGH
                        )
            except Exception:
                pass  # Ignore if no PSS is configured
                
        except Exception as e:
            logger.error(f"Real-time pod security validation failed: {e}")
    
    # Security Policy Templates
    
    def _get_baseline_pss(self) -> Dict[str, Any]:
        """Get baseline Pod Security Standard configuration."""



        return {
            "runAsNonRoot": False,  # Not required at baseline
            "forbiddenCapabilities": [
                "SYS_ADMIN", "NET_ADMIN", "SYS_TIME", "SYS_PTRACE"
            ],
            "forbiddenVolumeTypes": [
                "hostPath", "hostPID", "hostIPC", "hostNetwork"
            ]
        }
    
    def _get_restricted_pss(self) -> Dict[str, Any]:
        """Get restricted Pod Security Standard configuration."""



        return {
            "runAsNonRoot": True,
            "forbiddenCapabilities": ["ALL"],
            "allowedCapabilities": ["NET_BIND_SERVICE"],
            "forbiddenVolumeTypes": [
                "hostPath", "hostPID", "hostIPC", "hostNetwork",
                "gcePersistentDisk", "awsElasticBlockStore", "azureDisk"
            ],
            "requiredSeccompProfile": "RuntimeDefault",
            "forbiddenPrivilegeEscalation": True
        }
    
    def _get_deny_all_template(self) -> Dict[str, Any]:
        """Get deny-all network policy template."""



        return {
            "policyTypes": ["Ingress", "Egress"],
            "ingress": [],
            "egress": []
        }
    
    def _get_allow_same_namespace_template(self) -> Dict[str, Any]:
        """Get allow same namespace network policy template."""



        return {
            "policyTypes": ["Ingress"],
            "ingress": [{
                "from": [{
                    "namespaceSelector": {
                        "matchLabels": {
                            "name": "{{ namespace }}"
                        }
                    }
                }]
            }]
        }
    
    def _get_database_access_template(self) -> Dict[str, Any]:
        """Get database access network policy template."""



        return {
            "policyTypes": ["Ingress"],
            "ingress": [{
                "from": [{
                    "podSelector": {
                        "matchLabels": {
                            "app": "backend"
                        }
                    }
                }],
                "ports": [{
                    "protocol": "TCP",
                    "port": 5432
                }]
            }]
        }
    
    def _get_api_gateway_template(self) -> Dict[str, Any]:
        """Get API gateway network policy template."""



        return {
            "policyTypes": ["Ingress", "Egress"],
            "ingress": [{
                "from": [],
                "ports": [{
                    "protocol": "TCP",
                    "port": 80
                }, {
                    "protocol": "TCP",
                    "port": 443
                }]
            }],
            "egress": [{
                "to": [{
                    "podSelector": {
                        "matchLabels": {
                            "tier": "backend"
                        }
                    }
                }]
            }]
        }
    
    async def _create_security_violation(self, workload: str, namespace: str,
                                       policy: str, description: str,
                                       severity: SecurityLevel) -> None:
        """Create security violation record."""
        violation = SecurityViolation(
            violation_id=f"k8s-{int(datetime.utcnow().timestamp())}",
            severity=severity,
            workload=workload,
            namespace=namespace,
            policy=policy,
            description=description
        )
        
        self.security_violations.append(violation)
        logger.warning(f"Kubernetes security violation: {description}")
    
    async def _create_default_security_resources(self) -> None:
        """Create default security resources."""
        # This would create default security resources like:
        # - Default network policies
        # - Security roles and service accounts
        # - Pod security policies
        pass
    
    async def shutdown(self) -> None:
        """Gracefully shutdown Kubernetes security manager."""
        if self.k8s_client:
            await self.k8s_client.close()
        
        logger.info("KubernetesSecurityManager shutdown completed")

