class SecureAPIConnector:
    """
     Secure API Connector for External Services
    
    Features:
    - OAuth 2.0 / JWT authentication
    - Request signing and validation
    - Automatic token refresh
    - Rate limiting compliance
    - Error handling and retry logic
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._session = None
        self._rate_limiters = {}
        self._token_cache = {}
        
        # Initialize HTTP session with security settings
        self._initialize_secure_session()
    
    def _initialize_secure_session(self):
        """Initialize secure HTTP session"""
        self._session = aiohttp.ClientSession(
            timeout=aiohttp.ClientTimeout(total=30),
            connector=aiohttp.TCPConnector(
                ssl=True,
                verify_ssl=True,
                limit=100,
                limit_per_host=10
            ),
            headers={
                'User-Agent': 'SpotifyAIAgent/2.0 (Secure)',
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        )
    
    async def secure_request(
        self,
        context: IntegrationContext,
        method: str,
        url: str,
        data: Optional[Dict[str, Any]] = None,
        headers: Optional[Dict[str, str]] = None,
        params: Optional[Dict[str, str]] = None
    ) -> Dict[str, Any]:
        """Make secure API request with authentication and validation"""
        
        # Check rate limits
        await self._check_rate_limits(context)
        
        # Prepare headers with authentication
        auth_headers = await self._prepare_auth_headers(context)
        if headers:
            auth_headers.update(headers)
        
        # Sign request if required
        if context.security_level in [SecurityLevel.CONFIDENTIAL, SecurityLevel.TOP_SECRET]:
            auth_headers.update(await self._sign_request(context, method, url, data))
        
        # Make request with retry logic
        try:
            response = await self._make_request_with_retry(
                method, url, data, auth_headers, params
            )
            
            # Validate response
            validated_response = await self._validate_response(context, response)
            
            # Update usage metrics
            await self._update_usage_metrics(context)
            
            return validated_response
            
        except Exception as e:
            self.logger.error(f"Secure API request failed: {str(e)}")
            await self._handle_api_error(context, e)
            raise
    
    async def _prepare_auth_headers(self, context: IntegrationContext) -> Dict[str, str]:
        """Prepare authentication headers"""
        headers = {}
        
        if context.integration_type == IntegrationType.SPOTIFY_API:
            # Spotify API authentication
            token = await self._get_spotify_token(context)
            headers['Authorization'] = f'Bearer {token}'
            
        elif context.credentials.api_key:
            # API Key authentication
            headers['X-API-Key'] = context.credentials.api_key
            
        elif context.credentials.access_token:
            # OAuth 2.0 Bearer token
            headers['Authorization'] = f'Bearer {context.credentials.access_token}'
        
        return headers
    
    async def _get_spotify_token(self, context: IntegrationContext) -> str:
        """Get Spotify API access token"""
        cache_key = f"spotify_token_{context.tenant_id}"
        
        # Check cache
        if cache_key in self._token_cache:
            cached_token = self._token_cache[cache_key]
            if cached_token['expires_at'] > datetime.utcnow():
                return cached_token['token']
        
        # Request new token
        token_url = 'https://accounts.spotify.com/api/token'
        
        auth_header = base64.b64encode(
            f"{context.credentials.client_id}:{context.credentials.client_secret}".encode()
        ).decode()
        
        headers = {
            'Authorization': f'Basic {auth_header}',
            'Content-Type': 'application/x-www-form-urlencoded'
        }
        
        data = {
            'grant_type': 'client_credentials',
            'scope': ' '.join(context.credentials.scopes)
        }
        
        async with self._session.post(token_url, headers=headers, data=data) as response:
            if response.status == 200:
                token_data = await response.json()
                
                # Cache token
                expires_at = datetime.utcnow() + timedelta(seconds=token_data['expires_in'] - 60)
                self._token_cache[cache_key] = {
                    'token': token_data['access_token'],
                    'expires_at': expires_at
                }
                
                return token_data['access_token']
            else:
                raise Exception(f"Failed to get Spotify token: {response.status}")
    
    async def _sign_request(
        self,
        context: IntegrationContext,
        method: str,
        url: str,
        data: Optional[Dict[str, Any]]
    ) -> Dict[str, str]:
        """Sign request for high-security integrations"""
        timestamp = str(int(time.time()))
        nonce = base64.b64encode(hashlib.sha256(
            f"{timestamp}{context.tenant_id}".encode()
        ).digest()[:16]).decode()
        
        # Create signature string
        signature_string = f"{method}\n{url}\n{timestamp}\n{nonce}"
        if data:
            signature_string += f"\n{json.dumps(data, sort_keys=True)}"
        
        # Create HMAC signature
        signature = hmac.new(
            context.credentials.secret_key.encode(),
            signature_string.encode(),
            hashlib.sha256
        ).hexdigest()
        
        return {
            'X-Timestamp': timestamp,
            'X-Nonce': nonce,
            'X-Signature': signature
        }
    
    async def _make_request_with_retry(
        self,
        method: str,
        url: str,
        data: Optional[Dict[str, Any]],
        headers: Dict[str, str],
        params: Optional[Dict[str, str]]
    ) -> Dict[str, Any]:
        """Make HTTP request with retry logic"""
        max_retries = 3
        backoff_factor = 1
        
        for attempt in range(max_retries + 1):
            try:
                async with self._session.request(
                    method, url, json=data, headers=headers, params=params
                ) as response:
                    
                    if response.status == 200:
                        return await response.json()
                    elif response.status == 429:
                        # Rate limited - wait and retry
                        retry_after = int(response.headers.get('Retry-After', backoff_factor * (2 ** attempt)))
                        await asyncio.sleep(retry_after)
                        continue
                    elif response.status in [500, 502, 503, 504] and attempt < max_retries:
                        # Server error - retry with backoff
                        await asyncio.sleep(backoff_factor * (2 ** attempt))
                        continue
                    else:
                        response.raise_for_status()
                        
            except asyncio.TimeoutError:
                if attempt < max_retries:
                    await asyncio.sleep(backoff_factor * (2 ** attempt))
                    continue
                raise
        
        raise Exception(f"Request failed after {max_retries + 1} attempts")
    
    async def _validate_response(self, context: IntegrationContext, response: Dict[str, Any]) -> Dict[str, Any]:
        """Validate API response"""
        # Check for required fields based on integration type
        if context.integration_type == IntegrationType.SPOTIFY_API:
            return await self._validate_spotify_response(response)
        
        return response
    
    async def _validate_spotify_response(self, response: Dict[str, Any]) -> Dict[str, Any]:
        """Validate Spotify API response"""
        # Implement Spotify-specific validation
        if 'error' in response:
            raise Exception(f"Spotify API error: {response['error']}")
        
        return response
    
    async def _check_rate_limits(self, context: IntegrationContext):
        """Check and enforce rate limits"""
        now = datetime.utcnow()
        rate_limit_key = f"{context.integration_id}_{now.strftime('%Y%m%d%H%M')}"
        
        if rate_limit_key not in self._rate_limiters:
            self._rate_limiters[rate_limit_key] = 0
        
        max_requests = context.rate_limits.get('per_minute', 100)
        
        if self._rate_limiters[rate_limit_key] >= max_requests:
            raise Exception("Rate limit exceeded")
        
        self._rate_limiters[rate_limit_key] += 1
    
    async def _update_usage_metrics(self, context: IntegrationContext):
        """Update integration usage metrics"""
        context.last_used = datetime.utcnow()
        # Update metrics in database/cache
    
    async def _handle_api_error(self, context: IntegrationContext, error: Exception):
        """Handle API errors with security implications"""
        self.logger.error(f"API error for integration {context.integration_id}: {str(error)}")
        
        # Check for security-related errors
        if "unauthorized" in str(error).lower():
            # Potential credential compromise
            await self._revoke_credentials(context)
        
    async def _revoke_credentials(self, context: IntegrationContext):
        """Revoke potentially compromised credentials"""
        self.logger.warning(f"Revoking credentials for integration {context.integration_id}")
        # Implement credential revocation logic


class ThirdPartyValidator:
    """
     Third-party Service Validation Engine
    
    Features:
    - Service health monitoring  
    - API version compatibility
    - Security posture assessment
    - Compliance verification
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self._validation_cache = {}
        self._health_monitors = {}
    
    async def validate_third_party_service(
        self,
        service_url: str,
        integration_type: IntegrationType
    ) -> Dict[str, Any]:
        """Validate third-party service security and compliance"""
        
        validation_key = f"{service_url}_{integration_type.name}"
        
        # Check cache
        if validation_key in self._validation_cache:
            cached = self._validation_cache[validation_key]
            if cached['expires_at'] > datetime.utcnow():
                return cached['result']
        
        # Perform validation
        validation_result = {
            'service_url': service_url,
            'integration_type': integration_type.name,
            'validated_at': datetime.utcnow().isoformat(),
            'health_status': await self._check_service_health(service_url),
            'security_score': await self._assess_security_posture(service_url),
            'compliance_status': await self._verify_compliance(service_url, integration_type),
            'api_compatibility': await self._check_api_compatibility(service_url, integration_type),
            'recommendations': []
        }
        
        # Generate recommendations
        validation_result['recommendations'] = await self._generate_recommendations(validation_result)
        
        # Cache result
        self._validation_cache[validation_key] = {
            'result': validation_result,
            'expires_at': datetime.utcnow() + timedelta(hours=1)
        }
        
        return validation_result
    
    async def _check_service_health(self, service_url: str) -> Dict[str, Any]:
        """Check third-party service health"""



        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(f"{service_url}/health", timeout=aiohttp.ClientTimeout(total=10)) as response:
                    if response.status == 200:
                        return {
                            'status': 'healthy',
                            'response_time_ms': response.headers.get('X-Response-Time', 'unknown'),
                            'version': response.headers.get('X-API-Version', 'unknown')
                        }
                    else:
                        return {
                            'status': 'unhealthy',
                            'error': f"HTTP {response.status}"
                        }
        except Exception as e:
            return {
                'status': 'error',
                'error': str(e)
            }
    
    async def _assess_security_posture(self, service_url: str) -> float:
        """Assess security posture of third-party service"""
        security_score = 0.0
        
        # Check SSL/TLS configuration
        if service_url.startswith('https://'):
            security_score += 0.3
        
        # Check security headers (simplified)
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(service_url, timeout=aiohttp.ClientTimeout(total=10)) as response:
                    headers = response.headers
                    
                    # Check for security headers
                    if 'Strict-Transport-Security' in headers:
                        security_score += 0.2
                    if 'X-Content-Type-Options' in headers:
                        security_score += 0.1
                    if 'X-Frame-Options' in headers:
                        security_score += 0.1
                    if 'Content-Security-Policy' in headers:
                        security_score += 0.2
                    if 'X-XSS-Protection' in headers:
                        security_score += 0.1
                        
        except Exception:
            pass
        
        return min(1.0, security_score)
    
    async def _verify_compliance(self, service_url: str, integration_type: IntegrationType) -> Dict[str, bool]:
        """Verify compliance with regulations"""
        compliance_status = {
            'gdpr_compliant': False,
            'ccpa_compliant': False,
            'sox_compliant': False,
            'pci_dss_compliant': False
        }
        
        # Simplified compliance checking
        # In production, this would integrate with compliance databases
        if integration_type in [IntegrationType.PAYMENT_GATEWAY]:
            compliance_status['pci_dss_compliant'] = True
        
        if integration_type in [IntegrationType.ANALYTICS_SERVICE, IntegrationType.ML_SERVICE]:
            compliance_status['gdpr_compliant'] = True
            compliance_status['ccpa_compliant'] = True
        
        return compliance_status
    
    async def _check_api_compatibility(self, service_url: str, integration_type: IntegrationType) -> Dict[str, Any]:
        """Check API version compatibility"""



        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(f"{service_url}/version", timeout=aiohttp.ClientTimeout(total=10)) as response:
                    if response.status == 200:
                        version_info = await response.json()
                        return {
                            'compatible': True,
                            'api_version': version_info.get('version', 'unknown'),
                            'supported_versions': version_info.get('supported_versions', [])
                        }
        except Exception:
            pass
        
        return {
            'compatible': False,
            'error': 'Unable to determine API version'
        }
    
    async def _generate_recommendations(self, validation_result: Dict[str, Any]) -> List[str]:
        """Generate security and compliance recommendations"""
        recommendations = []
        
        if validation_result['health_status']['status'] != 'healthy':
            recommendations.append("Service health issues detected - monitor closely")
        
        if validation_result['security_score'] < 0.7:
            recommendations.append("Security posture needs improvement - review implementation")
        
        compliance = validation_result['compliance_status']
        if not all(compliance.values()):
            recommendations.append("Compliance gaps identified - review regulatory requirements")
        
        return recommendations


