"""
Rate Limiter - Enterprise Rate Limiting System
==============================================

Ultra-advanced rate limiting system providing intelligent, adaptive rate
limiting for external APIs with Fortune 500-level capabilities.

Features:
- Intelligent adaptive rate limiting
- Multi-tier rate limit policies
- Burst handling and smoothing
- Predictive rate limit management
- Multi-tenant isolation
- Real-time monitoring and analytics
"""

import asyncio
import time
import math
from typing import Dict, List, Any, Optional, Callable
from datetime import datetime, timezone, timedelta
from dataclasses import dataclass, field
from enum import Enum, auto
import structlog

logger = structlog.get_logger(__name__)


# ================== ENUMS AND CONSTANTS ==================

class RateLimitStrategy(Enum):
    """Rate limiting strategies."""
    FIXED_WINDOW = auto()
    SLIDING_WINDOW = auto()
    TOKEN_BUCKET = auto()
    LEAKY_BUCKET = auto()
    ADAPTIVE = auto()
    INTELLIGENT = auto()


class RateLimitTier(Enum):
    """Rate limit tiers for different priority levels."""
    BASIC = auto()
    STANDARD = auto()
    PREMIUM = auto()
    ENTERPRISE = auto()
    UNLIMITED = auto()


class BurstHandling(Enum):
    """Burst traffic handling strategies."""
    REJECT = auto()
    QUEUE = auto()
    SMOOTH = auto()
    ADAPTIVE = auto()


# ================== DATA MODELS ==================

@dataclass
class RateLimitPolicy:
    """Rate limit policy configuration."""
    requests_per_second: float
    requests_per_minute: int
    requests_per_hour: int
    requests_per_day: int
    burst_capacity: int
    burst_duration: int = 60  # seconds
    strategy: RateLimitStrategy = RateLimitStrategy.INTELLIGENT
    tier: RateLimitTier = RateLimitTier.STANDARD
    burst_handling: BurstHandling = BurstHandling.ADAPTIVE
    auto_adjust: bool = True
    priority_multiplier: float = 1.0


@dataclass
class RateLimitStatus:
    """Current rate limit status."""
    remaining_requests: int
    reset_time: datetime
    retry_after: Optional[int] = None
    current_window_requests: int = 0
    total_requests: int = 0
    violations: int = 0
    burst_capacity_remaining: int = 0
    is_throttled: bool = False


@dataclass
class RateLimitViolation:
    """Rate limit violation record."""
    timestamp: datetime
    provider: str
    tenant_id: Optional[str]
    violation_type: str
    requests_attempted: int
    limit_exceeded: int
    retry_after: int


# ================== TOKEN BUCKET IMPLEMENTATION ==================

class TokenBucket:
    """
    Token bucket implementation for rate limiting.
    
    Provides smooth rate limiting with burst capacity handling.
    """
    
    def __init__(
        self,
        capacity: float,
        refill_rate: float,
        initial_tokens: Optional[float] = None
    ):
        self.capacity = capacity
        self.refill_rate = refill_rate  # tokens per second
        self.tokens = initial_tokens if initial_tokens is not None else capacity
        self.last_refill = time.time()
        self._lock = asyncio.Lock()
    
    async def consume(self, tokens: float = 1.0) -> bool:
        """
        Attempt to consume tokens from the bucket.
        
        Returns True if tokens were consumed, False if insufficient tokens.
        """
        async with self._lock:
            await self._refill()
            
            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            return False
    
    async def peek(self) -> float:
        """Get current number of tokens without consuming."""
        async with self._lock:
            await self._refill()
            return self.tokens
    
    async def wait_for_tokens(self, tokens: float = 1.0) -> float:
        """
        Calculate wait time needed for tokens to be available.
        
        Returns wait time in seconds.
        """
        async with self._lock:
            await self._refill()
            
            if self.tokens >= tokens:
                return 0.0
            
            needed_tokens = tokens - self.tokens
            wait_time = needed_tokens / self.refill_rate
            return wait_time
    
    async def _refill(self) -> None:
        """Refill tokens based on elapsed time."""
        now = time.time()
        elapsed = now - self.last_refill
        
        if elapsed > 0:
            new_tokens = elapsed * self.refill_rate
            self.tokens = min(self.capacity, self.tokens + new_tokens)
            self.last_refill = now


# ================== SLIDING WINDOW IMPLEMENTATION ==================

class SlidingWindow:
    """
    Sliding window rate limiter implementation.
    
    Provides precise rate limiting with sliding time windows.
    """
    
    def __init__(self, window_size: int, max_requests: int):
        self.window_size = window_size  # seconds
        self.max_requests = max_requests
        self.requests: List[float] = []
        self._lock = asyncio.Lock()
    
    async def allow_request(self) -> bool:
        """Check if request is allowed under current rate limit."""
        async with self._lock:
            now = time.time()
            
            # Remove expired entries
            cutoff = now - self.window_size
            self.requests = [req_time for req_time in self.requests if req_time > cutoff]
            
            # Check if under limit
            if len(self.requests) < self.max_requests:
                self.requests.append(now)
                return True
            
            return False
    
    async def get_window_info(self) -> Dict[str, Any]:
        """Get current window information."""
        async with self._lock:
            now = time.time()
            cutoff = now - self.window_size
            
            # Clean expired entries
            self.requests = [req_time for req_time in self.requests if req_time > cutoff]
            
            remaining = max(0, self.max_requests - len(self.requests))
            
            # Calculate reset time (when oldest request expires)
            reset_time = None
            if self.requests:
                oldest_request = min(self.requests)
                reset_time = oldest_request + self.window_size
            
            return {
                "current_requests": len(self.requests),
                "max_requests": self.max_requests,
                "remaining_requests": remaining,
                "window_size": self.window_size,
                "reset_time": reset_time
            }


# ================== INTELLIGENT RATE LIMITER ==================

class IntelligentRateLimiter:
    """
    Intelligent rate limiter with adaptive behavior.
    
    Features:
    - ML-based rate prediction
    - Dynamic limit adjustment
    - Burst pattern recognition
    - Performance optimization
    """
    
    def __init__(self, base_policy: RateLimitPolicy):
        self.base_policy = base_policy
        
        # Adaptive parameters
        self.current_limit = base_policy.requests_per_second
        self.adjustment_factor = 1.0
        self.learning_rate = 0.1
        
        # Performance tracking
        self.success_rate_history: List[float] = []
        self.response_time_history: List[float] = []
        self.burst_patterns: List[Dict[str, Any]] = []
        
        # State management
        self.last_adjustment = time.time()
        self.adjustment_interval = 300  # 5 minutes
        
        logger.info("Intelligent rate limiter initialized")
    
    async def should_allow_request(
        self,
        current_rate: float,
        success_rate: float,
        avg_response_time: float
    ) -> Tuple[bool, Dict[str, Any]]:
        """
        Intelligent decision on whether to allow request.
        
        Considers current performance metrics and historical patterns.
        """
        # Basic rate check
        if current_rate > self.current_limit:
            await self._learn_from_rejection(current_rate, success_rate, avg_response_time)
            return False, {"reason": "rate_limit_exceeded", "current_limit": self.current_limit}
        
        # Quality-based decisions
        if success_rate < 0.95 and current_rate > self.current_limit * 0.8:
            await self._learn_from_quality_issue(current_rate, success_rate, avg_response_time)
            return False, {"reason": "quality_protection", "success_rate": success_rate}
        
        # Response time based decisions
        if avg_response_time > 5000 and current_rate > self.current_limit * 0.7:  # 5 seconds
            await self._learn_from_performance_issue(current_rate, success_rate, avg_response_time)
            return False, {"reason": "performance_protection", "avg_response_time": avg_response_time}
        
        # Allow request and learn from success
        await self._learn_from_success(current_rate, success_rate, avg_response_time)
        return True, {"reason": "allowed", "current_limit": self.current_limit}
    
    async def adjust_limits(self) -> None:
        """Adjust rate limits based on learned patterns."""
        now = time.time()
        
        if now - self.last_adjustment < self.adjustment_interval:
            return
        
        if len(self.success_rate_history) < 10:
            return  # Need more data
        
        # Calculate recent performance metrics
        recent_success_rate = sum(self.success_rate_history[-10:]) / 10
        recent_response_time = sum(self.response_time_history[-10:]) / 10
        
        # Determine adjustment
        if recent_success_rate > 0.98 and recent_response_time < 1000:
            # Performance is good, can increase limit
            self.adjustment_factor = min(2.0, self.adjustment_factor * (1 + self.learning_rate))
        elif recent_success_rate < 0.95 or recent_response_time > 3000:
            # Performance is poor, decrease limit
            self.adjustment_factor = max(0.5, self.adjustment_factor * (1 - self.learning_rate))
        
        # Apply adjustment
        self.current_limit = self.base_policy.requests_per_second * self.adjustment_factor
        self.last_adjustment = now
        
        logger.info(
            f"Rate limit adjusted: {self.current_limit:.2f} req/s (factor: {self.adjustment_factor:.2f})",
            success_rate=recent_success_rate,
            avg_response_time=recent_response_time
        )
    
    async def _learn_from_success(self, rate: float, success_rate: float, response_time: float) -> None:
        """Learn from successful requests."""
        self.success_rate_history.append(success_rate)
        self.response_time_history.append(response_time)
        
        # Keep only recent history
        if len(self.success_rate_history) > 100:
            self.success_rate_history = self.success_rate_history[-50:]
        if len(self.response_time_history) > 100:
            self.response_time_history = self.response_time_history[-50:]
    
    async def _learn_from_rejection(self, rate: float, success_rate: float, response_time: float) -> None:
        """Learn from rejected requests."""
        # Record rejection pattern for analysis
        pass
    
    async def _learn_from_quality_issue(self, rate: float, success_rate: float, response_time: float) -> None:
        """Learn from quality-related issues."""
        # Adjust more aggressively for quality issues
        self.adjustment_factor *= 0.9
    
    async def _learn_from_performance_issue(self, rate: float, success_rate: float, response_time: float) -> None:
        """Learn from performance-related issues."""
        # Adjust for performance issues
        self.adjustment_factor *= 0.95


# ================== MAIN RATE LIMITER CLASS ==================

class RateLimiter:
    """
    Enterprise-grade rate limiter with multiple strategies and intelligent behavior.
    
    Features:
    - Multiple rate limiting strategies
    - Multi-tenant isolation
    - Intelligent adaptive behavior
    - Comprehensive monitoring
    - Burst handling and smoothing
    """
    
    def __init__(self):
        # Rate limiting state per provider/tenant
        self.limiters: Dict[str, Dict[str, Any]] = {}
        self.policies: Dict[str, RateLimitPolicy] = {}
        self.violations: List[RateLimitViolation] = []
        
        # Global statistics
        self.total_requests = 0
        self.total_violations = 0
        self.start_time = time.time()
        
        # Intelligent rate limiters
        self.intelligent_limiters: Dict[str, IntelligentRateLimiter] = {}
        
        logger.info("RateLimiter initialized")
    
    async def initialize(self) -> None:
        """Initialize the rate limiter."""



        try:
            # Start background tasks
            asyncio.create_task(self._adjustment_loop())
            logger.info("RateLimiter initialization completed")
        except Exception as e:
            logger.error("Failed to initialize RateLimiter", error=str(e))
            raise
    
    async def configure_policy(
        self,
        provider: str,
        policy: RateLimitPolicy,
        tenant_id: Optional[str] = None
    ) -> None:
        """Configure rate limiting policy for provider/tenant."""
        key = self._get_limiter_key(provider, tenant_id)
        self.policies[key] = policy
        
        # Initialize limiter based on strategy
        if policy.strategy == RateLimitStrategy.TOKEN_BUCKET:
            self.limiters[key] = {
                "type": "token_bucket",
                "bucket": TokenBucket(
                    capacity=policy.burst_capacity,
                    refill_rate=policy.requests_per_second
                ),
                "created_at": time.time()
            }
        elif policy.strategy == RateLimitStrategy.SLIDING_WINDOW:
            self.limiters[key] = {
                "type": "sliding_window",
                "window": SlidingWindow(
                    window_size=60,  # 1 minute window
                    max_requests=policy.requests_per_minute
                ),
                "created_at": time.time()
            }
        elif policy.strategy == RateLimitStrategy.INTELLIGENT:
            intelligent_limiter = IntelligentRateLimiter(policy)
            self.intelligent_limiters[key] = intelligent_limiter
            
            self.limiters[key] = {
                "type": "intelligent",
                "bucket": TokenBucket(
                    capacity=policy.burst_capacity,
                    refill_rate=policy.requests_per_second
                ),
                "intelligent": intelligent_limiter,
                "created_at": time.time(),
                "performance_metrics": {
                    "success_rate": 1.0,
                    "avg_response_time": 100,
                    "current_rate": 0.0
                }
            }
        
        logger.info(f"Rate limit policy configured for {key}: {policy.strategy.name}")
    
    async def acquire(
        self,
        provider: str,
        tenant_id: Optional[str] = None,
        tokens: float = 1.0,
        priority: int = 0
    ) -> bool:
        """
        Acquire rate limit tokens.
        
        Returns True if tokens acquired, False if rate limited.
        """
        key = self._get_limiter_key(provider, tenant_id)
        
        if key not in self.limiters:
            # No rate limiting configured, allow request
            return True
        
        self.total_requests += 1
        limiter_info = self.limiters[key]
        policy = self.policies[key]
        
        # Apply priority multiplier
        effective_tokens = tokens / (1 + priority * 0.1)
        
        try:
            if limiter_info["type"] == "token_bucket":
                allowed = await limiter_info["bucket"].consume(effective_tokens)
                
            elif limiter_info["type"] == "sliding_window":
                allowed = await limiter_info["window"].allow_request()
                
            elif limiter_info["type"] == "intelligent":
                # Get current performance metrics
                metrics = limiter_info["performance_metrics"]
                
                # Check intelligent decision
                intelligent_allowed, decision_info = await limiter_info["intelligent"].should_allow_request(
                    current_rate=metrics["current_rate"],
                    success_rate=metrics["success_rate"],
                    avg_response_time=metrics["avg_response_time"]
                )
                
                if intelligent_allowed:
                    allowed = await limiter_info["bucket"].consume(effective_tokens)
                else:
                    allowed = False
                    logger.debug(f"Intelligent rate limiter blocked request: {decision_info}")
            
            else:
                allowed = True  # Unknown type, allow by default
            
            if not allowed:
                await self._record_violation(provider, tenant_id, tokens, policy)
                self.total_violations += 1
            
            return allowed
            
        except Exception as e:
            logger.error(f"Error in rate limiter acquire: {e}")
            return True  # Allow on error to prevent blocking
    
    async def wait_for_capacity(
        self,
        provider: str,
        tenant_id: Optional[str] = None,
        tokens: float = 1.0
    ) -> float:
        """
        Calculate wait time for capacity to be available.
        
        Returns wait time in seconds.
        """
        key = self._get_limiter_key(provider, tenant_id)
        
        if key not in self.limiters:
            return 0.0
        
        limiter_info = self.limiters[key]
        
        if limiter_info["type"] == "token_bucket":
            return await limiter_info["bucket"].wait_for_tokens(tokens)
        elif limiter_info["type"] == "intelligent":
            return await limiter_info["bucket"].wait_for_tokens(tokens)
        else:
            return 0.0
    
    async def update_performance_metrics(
        self,
        provider: str,
        tenant_id: Optional[str],
        success_rate: float,
        avg_response_time: float,
        current_rate: float
    ) -> None:
        """Update performance metrics for intelligent rate limiting."""
        key = self._get_limiter_key(provider, tenant_id)
        
        if key in self.limiters and self.limiters[key]["type"] == "intelligent":
            metrics = self.limiters[key]["performance_metrics"]
            metrics["success_rate"] = success_rate
            metrics["avg_response_time"] = avg_response_time
            metrics["current_rate"] = current_rate
    
    async def get_status(
        self,
        provider: str,
        tenant_id: Optional[str] = None
    ) -> RateLimitStatus:
        """Get current rate limit status."""
        key = self._get_limiter_key(provider, tenant_id)
        
        if key not in self.limiters:
            return RateLimitStatus(
                remaining_requests=999999,
                reset_time=datetime.now(timezone.utc) + timedelta(hours=1)
            )
        
        limiter_info = self.limiters[key]
        policy = self.policies[key]
        
        if limiter_info["type"] == "token_bucket":
            bucket = limiter_info["bucket"]
            tokens = await bucket.peek()
            
            return RateLimitStatus(
                remaining_requests=int(tokens),
                reset_time=datetime.now(timezone.utc) + timedelta(seconds=60),
                burst_capacity_remaining=int(tokens),
                is_throttled=tokens < 1.0
            )
        
        elif limiter_info["type"] == "sliding_window":
            window_info = await limiter_info["window"].get_window_info()
            
            reset_time = datetime.now(timezone.utc) + timedelta(seconds=60)
            if window_info["reset_time"]:
                reset_time = datetime.fromtimestamp(window_info["reset_time"], timezone.utc)
            
            return RateLimitStatus(
                remaining_requests=window_info["remaining_requests"],
                reset_time=reset_time,
                current_window_requests=window_info["current_requests"],
                is_throttled=window_info["remaining_requests"] <= 0
            )
        
        elif limiter_info["type"] == "intelligent":
            bucket = limiter_info["bucket"]
            tokens = await bucket.peek()
            
            return RateLimitStatus(
                remaining_requests=int(tokens),
                reset_time=datetime.now(timezone.utc) + timedelta(seconds=60),
                burst_capacity_remaining=int(tokens),
                is_throttled=tokens < 1.0
            )
        
        return RateLimitStatus(
            remaining_requests=999999,
            reset_time=datetime.now(timezone.utc) + timedelta(hours=1)
        )
    
    async def get_global_stats(self) -> Dict[str, Any]:
        """Get global rate limiter statistics."""
        uptime = time.time() - self.start_time
        violation_rate = (self.total_violations / max(self.total_requests, 1)) * 100
        
        limiter_stats = {}
        for key, limiter_info in self.limiters.items():
            limiter_stats[key] = {
                "type": limiter_info["type"],
                "created_at": limiter_info["created_at"],
                "age_seconds": time.time() - limiter_info["created_at"]
            }
            
            if limiter_info["type"] in ["token_bucket", "intelligent"]:
                tokens = await limiter_info["bucket"].peek()
                limiter_stats[key]["available_tokens"] = tokens
        
        return {
            "uptime_seconds": uptime,
            "total_requests": self.total_requests,
            "total_violations": self.total_violations,
            "violation_rate_percentage": violation_rate,
            "active_limiters": len(self.limiters),
            "limiters": limiter_stats,
            "recent_violations": len([v for v in self.violations[-100:] if v.timestamp > datetime.now(timezone.utc) - timedelta(hours=1)])
        }
    
    async def health_check(self) -> Dict[str, Any]:
        """Perform health check on rate limiter."""
        healthy_limiters = 0
        total_limiters = len(self.limiters)
        
        for key, limiter_info in self.limiters.items():
            try:
                if limiter_info["type"] in ["token_bucket", "intelligent"]:
                    await limiter_info["bucket"].peek()
                elif limiter_info["type"] == "sliding_window":
                    await limiter_info["window"].get_window_info()
                healthy_limiters += 1
            except Exception:
                pass
        
        is_healthy = (healthy_limiters == total_limiters) and (self.total_violations / max(self.total_requests, 1)) < 0.1
        
        return {
            "healthy": is_healthy,
            "total_limiters": total_limiters,
            "healthy_limiters": healthy_limiters,
            "violation_rate": (self.total_violations / max(self.total_requests, 1)) * 100
        }
    
    async def shutdown(self) -> None:
        """Shutdown the rate limiter."""



        try:
            self.limiters.clear()
            self.policies.clear()
            self.intelligent_limiters.clear()
            logger.info("RateLimiter shutdown completed")
        except Exception as e:
            logger.error("Error during RateLimiter shutdown", error=str(e))
    
    # ================== PRIVATE METHODS ==================
    
    def _get_limiter_key(self, provider: str, tenant_id: Optional[str]) -> str:
        """Generate key for rate limiter."""
        if tenant_id:
            return f"{provider}:{tenant_id}"
        return provider
    
    async def _record_violation(
        self,
        provider: str,
        tenant_id: Optional[str],
        tokens_attempted: float,
        policy: RateLimitPolicy
    ) -> None:
        """Record rate limit violation."""
        violation = RateLimitViolation(
            timestamp=datetime.now(timezone.utc),
            provider=provider,
            tenant_id=tenant_id,
            violation_type="rate_limit_exceeded",
            requests_attempted=int(tokens_attempted),
            limit_exceeded=int(policy.requests_per_second),
            retry_after=60
        )
        
        self.violations.append(violation)
        
        # Keep only recent violations
        if len(self.violations) > 1000:
            self.violations = self.violations[-500:]
        
        logger.warning(
            f"Rate limit violation recorded for {provider}",
            tenant_id=tenant_id,
            tokens_attempted=tokens_attempted
        )
    
    async def _adjustment_loop(self) -> None:
        """Background task for intelligent rate limit adjustments."""
        while True:
            try:
                for key, intelligent_limiter in self.intelligent_limiters.items():
                    await intelligent_limiter.adjust_limits()
                
                await asyncio.sleep(60)  # Adjust every minute
                
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.error("Error in rate limiter adjustment loop", error=str(e))
                await asyncio.sleep(60)

