"""
Security Monitoring Examples Module

This module provides comprehensive security monitoring configurations and examples
for the Spotify AI Agent enterprise security system.

Features:
- Threat detection and analysis
- Vulnerability monitoring
- Compliance tracking and reporting
- Access control monitoring
- Audit trail analysis
- Incident response automation
- Security metrics collection
- Real-time security dashboards
"""

import asyncio
import json
import hashlib
import hmac
from typing import Dict, List, Any, Optional, Union, Set
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from enum import Enum
import logging
import re
from abc import ABC, abstractmethod

logger = logging.getLogger(__name__)

class ThreatLevel(Enum):
    """Threat level enumeration"""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"
    EMERGENCY = "emergency"

class SecurityEventType(Enum):
    """Security event type enumeration"""
    AUTHENTICATION_FAILURE = "authentication_failure"
    AUTHORIZATION_VIOLATION = "authorization_violation"
    SUSPICIOUS_ACTIVITY = "suspicious_activity"
    DATA_BREACH_ATTEMPT = "data_breach_attempt"
    MALWARE_DETECTION = "malware_detection"
    INTRUSION_ATTEMPT = "intrusion_attempt"
    POLICY_VIOLATION = "policy_violation"
    ANOMALOUS_BEHAVIOR = "anomalous_behavior"

class ComplianceFramework(Enum):
    """Compliance framework enumeration"""
    GDPR = "gdpr"
    SOC2 = "soc2"
    ISO27001 = "iso27001"
    HIPAA = "hipaa"
    PCI_DSS = "pci_dss"
    NIST = "nist"

@dataclass
class SecurityEvent:
    """Security event data structure"""
    event_id: str
    event_type: SecurityEventType
    threat_level: ThreatLevel
    timestamp: datetime
    source_ip: str
    user_id: Optional[str] = None
    resource: Optional[str] = None
    description: str = ""
    metadata: Dict[str, Any] = field(default_factory=dict)
    resolved: bool = False
    resolution_notes: Optional[str] = None

@dataclass
class VulnerabilityReport:
    """Vulnerability report structure"""
    vulnerability_id: str
    severity: ThreatLevel
    component: str
    version: str
    description: str
    cve_id: Optional[str] = None
    remediation: str = ""
    discovered_at: datetime = field(default_factory=datetime.now)
    patched: bool = False
    patch_date: Optional[datetime] = None

@dataclass
class ComplianceCheck:
    """Compliance check structure"""
    check_id: str
    framework: ComplianceFramework
    control_id: str
    description: str
    status: str  # compliant, non_compliant, partial, not_applicable
    evidence: List[str] = field(default_factory=list)
    last_assessed: datetime = field(default_factory=datetime.now)
    next_assessment: Optional[datetime] = None

class SecurityMonitor(ABC):
    """Abstract base class for security monitors"""
    
    def __init__(self, name: str):
        self.name = name
        self.is_active = False
        self.events: List[SecurityEvent] = []
        
    @abstractmethod
    async def start_monitoring(self):
        """Start monitoring"""
        pass
        
    @abstractmethod
    async def stop_monitoring(self):
        """Stop monitoring"""
        pass
        
    @abstractmethod
    async def analyze_event(self, event_data: Dict[str, Any]) -> Optional[SecurityEvent]:
        """Analyze event for security implications"""
        pass

class AuthenticationMonitor(SecurityMonitor):
    """Monitor authentication events"""
    
    def __init__(self):
        super().__init__("authentication_monitor")
        self.failed_attempts: Dict[str, List[datetime]] = {}
        self.suspicious_ips: Set[str] = set()
        
    async def start_monitoring(self):
        """Start authentication monitoring"""
        self.is_active = True
        logger.info("Authentication monitoring started")
        
    async def stop_monitoring(self):
        """Stop authentication monitoring"""
        self.is_active = False
        logger.info("Authentication monitoring stopped")
        
    async def analyze_event(self, event_data: Dict[str, Any]) -> Optional[SecurityEvent]:
        """Analyze authentication event"""
        event_type = event_data.get("type")
        source_ip = event_data.get("source_ip", "unknown")
        user_id = event_data.get("user_id")
        
        if event_type == "login_failed":
            # Track failed attempts per IP
            if source_ip not in self.failed_attempts:
                self.failed_attempts[source_ip] = []
                
            self.failed_attempts[source_ip].append(datetime.now())
            
            # Clean old attempts (last hour)
            cutoff = datetime.now() - timedelta(hours=1)
            self.failed_attempts[source_ip] = [
                attempt for attempt in self.failed_attempts[source_ip]
                if attempt > cutoff
            ]
            
            # Check for brute force attack
            if len(self.failed_attempts[source_ip]) > 10:
                self.suspicious_ips.add(source_ip)
                
                event = SecurityEvent(
                    event_id=f"auth_brute_force_{source_ip}_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                    event_type=SecurityEventType.AUTHENTICATION_FAILURE,
                    threat_level=ThreatLevel.HIGH,
                    timestamp=datetime.now(),
                    source_ip=source_ip,
                    user_id=user_id,
                    description=f"Brute force attack detected from IP {source_ip}",
                    metadata={
                        "failed_attempts": len(self.failed_attempts[source_ip]),
                        "time_window": "1 hour"
                    }
                )
                
                self.events.append(event)
                return event
                
        elif event_type == "login_success" and source_ip in self.suspicious_ips:
            # Successful login from suspicious IP
            event = SecurityEvent(
                event_id=f"auth_suspicious_success_{source_ip}_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                event_type=SecurityEventType.SUSPICIOUS_ACTIVITY,
                threat_level=ThreatLevel.MEDIUM,
                timestamp=datetime.now(),
                source_ip=source_ip,
                user_id=user_id,
                description=f"Successful login from previously suspicious IP {source_ip}",
                metadata={
                    "previous_failed_attempts": len(self.failed_attempts.get(source_ip, [])),
                    "suspicious_activity": True
                }
            )
            
            self.events.append(event)
            return event
            
        return None

class AccessControlMonitor(SecurityMonitor):
    """Monitor access control violations"""
    
    def __init__(self):
        super().__init__("access_control_monitor")
        self.permission_violations: List[Dict[str, Any]] = []
        
    async def start_monitoring(self):
        """Start access control monitoring"""
        self.is_active = True
        logger.info("Access control monitoring started")
        
    async def stop_monitoring(self):
        """Stop access control monitoring"""
        self.is_active = False
        logger.info("Access control monitoring stopped")
        
    async def analyze_event(self, event_data: Dict[str, Any]) -> Optional[SecurityEvent]:
        """Analyze access control event"""
        event_type = event_data.get("type")
        user_id = event_data.get("user_id")
        resource = event_data.get("resource")
        action = event_data.get("action")
        result = event_data.get("result")
        
        if event_type == "access_denied":
            # Log permission violation
            violation = {
                "user_id": user_id,
                "resource": resource,
                "action": action,
                "timestamp": datetime.now(),
                "source_ip": event_data.get("source_ip")
            }
            self.permission_violations.append(violation)
            
            # Check for privilege escalation attempts
            recent_violations = [
                v for v in self.permission_violations
                if v["user_id"] == user_id and 
                v["timestamp"] > datetime.now() - timedelta(minutes=15)
            ]
            
            if len(recent_violations) > 5:
                event = SecurityEvent(
                    event_id=f"privilege_escalation_{user_id}_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                    event_type=SecurityEventType.AUTHORIZATION_VIOLATION,
                    threat_level=ThreatLevel.HIGH,
                    timestamp=datetime.now(),
                    source_ip=event_data.get("source_ip", "unknown"),
                    user_id=user_id,
                    resource=resource,
                    description=f"Potential privilege escalation attempt by user {user_id}",
                    metadata={
                        "violation_count": len(recent_violations),
                        "time_window": "15 minutes",
                        "attempted_resources": list(set(v["resource"] for v in recent_violations))
                    }
                )
                
                self.events.append(event)
                return event
                
        return None

class DataAccessMonitor(SecurityMonitor):
    """Monitor data access patterns"""
    
    def __init__(self):
        super().__init__("data_access_monitor")
        self.data_access_patterns: Dict[str, List[Dict[str, Any]]] = {}
        
    async def start_monitoring(self):
        """Start data access monitoring"""
        self.is_active = True
        logger.info("Data access monitoring started")
        
    async def stop_monitoring(self):
        """Stop data access monitoring"""
        self.is_active = False
        logger.info("Data access monitoring stopped")
        
    async def analyze_event(self, event_data: Dict[str, Any]) -> Optional[SecurityEvent]:
        """Analyze data access event"""
        event_type = event_data.get("type")
        user_id = event_data.get("user_id")
        data_type = event_data.get("data_type")
        volume = event_data.get("volume", 0)
        
        if event_type == "data_access":
            if user_id not in self.data_access_patterns:
                self.data_access_patterns[user_id] = []
                
            access_record = {
                "data_type": data_type,
                "volume": volume,
                "timestamp": datetime.now(),
                "source_ip": event_data.get("source_ip")
            }
            
            self.data_access_patterns[user_id].append(access_record)
            
            # Check for unusual data access patterns
            recent_access = [
                record for record in self.data_access_patterns[user_id]
                if record["timestamp"] > datetime.now() - timedelta(hours=1)
            ]
            
            total_volume = sum(record["volume"] for record in recent_access)
            
            # Alert if user accessed large volume of data
            if total_volume > 10000:  # Threshold for large data access
                event = SecurityEvent(
                    event_id=f"data_exfiltration_{user_id}_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                    event_type=SecurityEventType.DATA_BREACH_ATTEMPT,
                    threat_level=ThreatLevel.CRITICAL,
                    timestamp=datetime.now(),
                    source_ip=event_data.get("source_ip", "unknown"),
                    user_id=user_id,
                    description=f"Potential data exfiltration by user {user_id}",
                    metadata={
                        "data_volume": total_volume,
                        "access_count": len(recent_access),
                        "data_types": list(set(record["data_type"] for record in recent_access))
                    }
                )
                
                self.events.append(event)
                return event
                
        return None

class AnomalyDetector:
    """AI-powered anomaly detection for security"""
    
    def __init__(self):
        self.baseline_patterns: Dict[str, Any] = {}
        self.anomaly_threshold = 0.8
        
    async def learn_baseline(self, historical_data: List[Dict[str, Any]]):
        """Learn baseline patterns from historical data"""
        # Simplified ML-based pattern learning
        user_patterns = {}
        
        for record in historical_data:
            user_id = record.get("user_id")
            if user_id not in user_patterns:
                user_patterns[user_id] = {
                    "login_times": [],
                    "access_patterns": [],
                    "ip_addresses": set()
                }
                
            if record.get("type") == "login":
                login_time = record.get("timestamp", datetime.now())
                user_patterns[user_id]["login_times"].append(login_time.hour)
                user_patterns[user_id]["ip_addresses"].add(record.get("source_ip"))
                
        # Calculate baseline patterns
        for user_id, patterns in user_patterns.items():
            self.baseline_patterns[user_id] = {
                "typical_login_hours": self._calculate_typical_hours(patterns["login_times"]),
                "known_ips": patterns["ip_addresses"],
                "activity_level": len(patterns["login_times"]) / 30  # per day average
            }
            
        logger.info(f"Learned baseline patterns for {len(self.baseline_patterns)} users")
        
    def _calculate_typical_hours(self, login_times: List[int]) -> List[int]:
        """Calculate typical login hours for a user"""
        if not login_times:
            return []
            
        # Simple clustering of login hours
        hour_counts = {}
        for hour in login_times:
            hour_counts[hour] = hour_counts.get(hour, 0) + 1
            
        # Return hours that represent 80% of logins
        total_logins = len(login_times)
        threshold = total_logins * 0.8
        
        sorted_hours = sorted(hour_counts.items(), key=lambda x: x[1], reverse=True)
        typical_hours = []
        count = 0
        
        for hour, freq in sorted_hours:
            typical_hours.append(hour)
            count += freq
            if count >= threshold:
                break
                
        return typical_hours
        
    async def detect_anomaly(self, event_data: Dict[str, Any]) -> Optional[float]:
        """Detect anomaly in event data"""
        user_id = event_data.get("user_id")
        
        if user_id not in self.baseline_patterns:
            return None  # No baseline for this user
            
        baseline = self.baseline_patterns[user_id]
        anomaly_score = 0.0
        
        # Check login time anomaly
        if event_data.get("type") == "login":
            login_hour = event_data.get("timestamp", datetime.now()).hour
            if login_hour not in baseline["typical_login_hours"]:
                anomaly_score += 0.3
                
        # Check IP address anomaly
        source_ip = event_data.get("source_ip")
        if source_ip and source_ip not in baseline["known_ips"]:
            anomaly_score += 0.4
            
        # Check activity level anomaly
        # This would be more sophisticated in a real implementation
        
        return anomaly_score if anomaly_score > 0 else None

class ComplianceTracker:
    """Track compliance with various frameworks"""
    
    def __init__(self):
        self.compliance_checks: Dict[ComplianceFramework, List[ComplianceCheck]] = {
            framework: [] for framework in ComplianceFramework
        }
        self.compliance_scores: Dict[ComplianceFramework, float] = {}
        
    def add_compliance_check(self, check: ComplianceCheck):
        """Add a compliance check"""
        self.compliance_checks[check.framework].append(check)
        self._calculate_compliance_score(check.framework)
        
    def _calculate_compliance_score(self, framework: ComplianceFramework):
        """Calculate compliance score for a framework"""
        checks = self.compliance_checks[framework]
        if not checks:
            self.compliance_scores[framework] = 0.0
            return
            
        compliant_count = sum(1 for check in checks if check.status == "compliant")
        total_checks = len(checks)
        
        self.compliance_scores[framework] = (compliant_count / total_checks) * 100
        
    def get_compliance_report(self, framework: ComplianceFramework) -> Dict[str, Any]:
        """Get compliance report for a framework"""
        checks = self.compliance_checks[framework]
        score = self.compliance_scores.get(framework, 0.0)
        
        non_compliant = [check for check in checks if check.status == "non_compliant"]
        
        return {
            "framework": framework.value,
            "score": score,
            "total_checks": len(checks),
            "compliant_checks": len(checks) - len(non_compliant),
            "non_compliant_checks": len(non_compliant),
            "critical_issues": [
                {
                    "control_id": check.control_id,
                    "description": check.description,
                    "last_assessed": check.last_assessed.isoformat()
                }
                for check in non_compliant
            ]
        }

class SecurityMetricsCollector:
    """Collect security-specific metrics"""
    
    def __init__(self):
        self.metrics: Dict[str, Any] = {}
        
    async def collect_metrics(self, security_events: List[SecurityEvent],
                            vulnerability_reports: List[VulnerabilityReport],
                            compliance_tracker: ComplianceTracker) -> Dict[str, Any]:
        """Collect comprehensive security metrics"""
        
        # Threat level distribution
        threat_distribution = {}
        for level in ThreatLevel:
            threat_distribution[level.value] = sum(
                1 for event in security_events if event.threat_level == level
            )
            
        # Event type distribution
        event_type_distribution = {}
        for event_type in SecurityEventType:
            event_type_distribution[event_type.value] = sum(
                1 for event in security_events if event.event_type == event_type
            )
            
        # Vulnerability metrics
        vulnerability_metrics = {
            "total_vulnerabilities": len(vulnerability_reports),
            "critical_vulnerabilities": sum(
                1 for vuln in vulnerability_reports 
                if vuln.severity == ThreatLevel.CRITICAL
            ),
            "patched_vulnerabilities": sum(
                1 for vuln in vulnerability_reports if vuln.patched
            ),
            "mean_time_to_patch": self._calculate_mean_time_to_patch(vulnerability_reports)
        }
        
        # Compliance metrics
        compliance_metrics = {}
        for framework in ComplianceFramework:
            score = compliance_tracker.compliance_scores.get(framework, 0.0)
            compliance_metrics[f"{framework.value}_score"] = score
            
        self.metrics = {
            "security_events": {
                "total_events": len(security_events),
                "threat_distribution": threat_distribution,
                "event_type_distribution": event_type_distribution,
                "resolved_events": sum(1 for event in security_events if event.resolved)
            },
            "vulnerabilities": vulnerability_metrics,
            "compliance": compliance_metrics,
            "collected_at": datetime.now().isoformat()
        }
        
        return self.metrics
        
    def _calculate_mean_time_to_patch(self, vulnerability_reports: List[VulnerabilityReport]) -> float:
        """Calculate mean time to patch vulnerabilities"""
        patched_vulnerabilities = [
            vuln for vuln in vulnerability_reports 
            if vuln.patched and vuln.patch_date
        ]
        
        if not patched_vulnerabilities:
            return 0.0
            
        total_time = sum(
            (vuln.patch_date - vuln.discovered_at).total_seconds()
            for vuln in patched_vulnerabilities
        )
        
        return total_time / len(patched_vulnerabilities) / 3600  # Convert to hours

