"""
Blockchain Security Manager
==========================

This module provides comprehensive blockchain security, smart contract auditing,
transaction validation, and MEV protection for the Spotify AI Agent platform.

Features:
- Smart contract security auditing
- Transaction validation and monitoring
- Anti-MEV (Maximal Extractable Value) protection
- Real-time threat detection
- Security compliance checks
- Vulnerability assessment and reporting

Author: Fahed Mlaiel
Date: 2025-01-28
"""

import asyncio
import logging
import hashlib
import json
from typing import Dict, List, Optional, Any, Union, Tuple, Set
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from decimal import Decimal
from enum import Enum
import re
import aiohttp

logger = logging.getLogger(__name__)


class SecurityThreatLevel(str, Enum):
    """Security threat severity levels."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class VulnerabilityType(str, Enum):
    """Types of security vulnerabilities."""
    REENTRANCY = "reentrancy"
    INTEGER_OVERFLOW = "integer_overflow"
    ACCESS_CONTROL = "access_control"
    UNCHECKED_CALL = "unchecked_call"
    DENIAL_OF_SERVICE = "denial_of_service"
    FRONT_RUNNING = "front_running"
    TIMESTAMP_DEPENDENCE = "timestamp_dependence"
    SHORT_ADDRESS = "short_address"
    UNINITIALIZED_STORAGE = "uninitialized_storage"
    DELEGATECALL = "delegatecall"


class TransactionStatus(str, Enum):
    """Transaction validation status."""
    VALID = "valid"
    SUSPICIOUS = "suspicious"
    BLOCKED = "blocked"
    PENDING_REVIEW = "pending_review"


@dataclass
class SecurityVulnerability:
    """Security vulnerability report."""
    vulnerability_id: str
    vulnerability_type: VulnerabilityType
    severity: SecurityThreatLevel
    contract_address: str
    function_name: Optional[str]
    line_number: Optional[int]
    description: str
    recommendation: str
    discovered_at: datetime = field(default_factory=datetime.utcnow)
    status: str = "open"
    cve_id: Optional[str] = None


@dataclass
class TransactionAnalysis:
    """Transaction security analysis result."""
    transaction_hash: str
    from_address: str
    to_address: str
    value: Decimal
    gas_limit: int
    gas_price: int
    data: str
    status: TransactionStatus
    risk_score: float
    threat_indicators: List[str]
    mev_risk: float
    analyzed_at: datetime = field(default_factory=datetime.utcnow)


@dataclass
class ContractAuditReport:
    """Smart contract audit report."""
    contract_address: str
    contract_name: str
    audit_id: str
    vulnerabilities: List[SecurityVulnerability]
    overall_score: float
    compliance_score: float
    gas_optimization_score: float
    recommendations: List[str]
    audited_at: datetime = field(default_factory=datetime.utcnow)
    auditor: str = "BlockchainSecurityManager"


class BlockchainSecurityManager:
    """Comprehensive blockchain security management system."""
    
    def __init__(self, config: Dict[str, Any]):
        """Initialize security manager."""
        self.config = config
        self.vulnerability_database: Dict[str, SecurityVulnerability] = {}
        self.audit_reports: Dict[str, ContractAuditReport] = {}
        self.transaction_analyses: Dict[str, TransactionAnalysis] = {}
        self.threat_patterns: Dict[str, List[str]] = {}
        self.blacklisted_addresses: Set[str] = set()
        self.whitelisted_addresses: Set[str] = set()
        
        # Initialize security patterns
        self._initialize_threat_patterns()
        self._load_blacklisted_addresses()
    
    def _initialize_threat_patterns(self):
        """Initialize known threat patterns."""
        self.threat_patterns = {
            "reentrancy": [
                r"call\.value\(.*\)\(\)",
                r"send\(.*\)",
                r"transfer\(.*\)",
                r"external.*call.*before.*state.*change"
            ],
            "integer_overflow": [
                r"unchecked.*\+",
                r"unchecked.*\-",
                r"unchecked.*\*",
                r"SafeMath.*not.*used"
            ],
            "access_control": [
                r"onlyOwner.*missing",
                r"require.*msg\.sender.*missing",
                r"unauthorized.*access",
                r"privilege.*escalation"
            ],
            "front_running": [
                r"commit.*reveal.*missing",
                r"order.*dependency",
                r"mev.*vulnerable",
                r"sandwich.*attack"
            ],
            "timestamp_dependence": [
                r"block\.timestamp.*used.*incorrectly",
                r"now.*dependency",
                r"time.*manipulation"
            ]
        }
    
    def _load_blacklisted_addresses(self):
        """Load known malicious addresses."""
        # In production, this would load from a threat intelligence database
        self.blacklisted_addresses = {
            "0x0000000000000000000000000000000000000000",  # Null address
            "0x000000000000000000000000000000000000dead",  # Burn address
            # Add known malicious addresses
        }
    
    async def audit_smart_contract(self,
                                 contract_address: str,
                                 contract_code: str,
                                 contract_name: str = "Unknown") -> ContractAuditReport:
        """Perform comprehensive smart contract security audit."""



        try:
            audit_id = f"audit_{int(datetime.utcnow().timestamp())}"
            
            logger.info(f"Starting security audit for contract {contract_address}")
            
            # Perform various security checks
            vulnerabilities = []
            
            # Static analysis
            static_vulns = await self._perform_static_analysis(contract_code, contract_address)
            vulnerabilities.extend(static_vulns)
            
            # Pattern matching for known vulnerabilities
            pattern_vulns = await self._detect_vulnerability_patterns(contract_code, contract_address)
            vulnerabilities.extend(pattern_vulns)
            
            # Gas optimization analysis
            gas_issues = await self._analyze_gas_optimization(contract_code, contract_address)
            vulnerabilities.extend(gas_issues)
            
            # Access control analysis
            access_issues = await self._analyze_access_control(contract_code, contract_address)
            vulnerabilities.extend(access_issues)
            
            # Calculate scores
            overall_score = self._calculate_overall_security_score(vulnerabilities)
            compliance_score = self._calculate_compliance_score(vulnerabilities)
            gas_optimization_score = self._calculate_gas_score(vulnerabilities)
            
            # Generate recommendations
            recommendations = self._generate_security_recommendations(vulnerabilities)
            
            # Create audit report
            audit_report = ContractAuditReport(
                contract_address=contract_address,
                contract_name=contract_name,
                audit_id=audit_id,
                vulnerabilities=vulnerabilities,
                overall_score=overall_score,
                compliance_score=compliance_score,
                gas_optimization_score=gas_optimization_score,
                recommendations=recommendations
            )
            
            # Store audit report
            self.audit_reports[contract_address] = audit_report
            
            # Store vulnerabilities
            for vuln in vulnerabilities:
                self.vulnerability_database[vuln.vulnerability_id] = vuln
            
            logger.info(f"Completed security audit for {contract_address}: {overall_score}/100")
            return audit_report
            
        except Exception as e:
            logger.error(f"Error auditing smart contract {contract_address}: {e}")
            raise
    
    async def _perform_static_analysis(self,
                                     contract_code: str,
                                     contract_address: str) -> List[SecurityVulnerability]:
        """Perform static code analysis."""
        vulnerabilities = []
        
        try:
            # Check for reentrancy vulnerabilities
            if self._check_reentrancy_vulnerability(contract_code):
                vuln = SecurityVulnerability(
                    vulnerability_id=f"vuln_{len(self.vulnerability_database) + 1}",
                    vulnerability_type=VulnerabilityType.REENTRANCY,
                    severity=SecurityThreatLevel.HIGH,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description="Potential reentrancy vulnerability detected",
                    recommendation="Use reentrancy guards or checks-effects-interactions pattern"
                )
                vulnerabilities.append(vuln)
            
            # Check for integer overflow/underflow
            if self._check_integer_overflow(contract_code):
                vuln = SecurityVulnerability(
                    vulnerability_id=f"vuln_{len(self.vulnerability_database) + 2}",
                    vulnerability_type=VulnerabilityType.INTEGER_OVERFLOW,
                    severity=SecurityThreatLevel.MEDIUM,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description="Potential integer overflow/underflow vulnerability",
                    recommendation="Use SafeMath library or Solidity 0.8+ built-in checks"
                )
                vulnerabilities.append(vuln)
            
            # Check for access control issues
            if self._check_access_control_issues(contract_code):
                vuln = SecurityVulnerability(
                    vulnerability_id=f"vuln_{len(self.vulnerability_database) + 3}",
                    vulnerability_type=VulnerabilityType.ACCESS_CONTROL,
                    severity=SecurityThreatLevel.HIGH,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description="Access control vulnerabilities detected",
                    recommendation="Implement proper access control modifiers and checks"
                )
                vulnerabilities.append(vuln)
            
            # Check for unchecked external calls
            if self._check_unchecked_calls(contract_code):
                vuln = SecurityVulnerability(
                    vulnerability_id=f"vuln_{len(self.vulnerability_database) + 4}",
                    vulnerability_type=VulnerabilityType.UNCHECKED_CALL,
                    severity=SecurityThreatLevel.MEDIUM,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description="Unchecked external calls detected",
                    recommendation="Always check return values of external calls"
                )
                vulnerabilities.append(vuln)
            
        except Exception as e:
            logger.error(f"Error in static analysis: {e}")
        
        return vulnerabilities
    
    def _check_reentrancy_vulnerability(self, code: str) -> bool:
        """Check for reentrancy vulnerabilities."""
        reentrancy_patterns = [
            r"call\.value\(.*\)\(\)",
            r"send\(.*\)",
            r"transfer\(.*\).*before.*balance.*update",
        ]
        
        for pattern in reentrancy_patterns:
            if re.search(pattern, code, re.IGNORECASE):
                return True
        
        return False
    
    def _check_integer_overflow(self, code: str) -> bool:
        """Check for integer overflow vulnerabilities."""
        # Check if SafeMath is used
        if "SafeMath" not in code and "pragma solidity" in code:
            # Check version
            version_match = re.search(r"pragma solidity\s*([<>=]*)\s*([0-9.]+)", code)
            if version_match and version_match.group(2) < "0.8.0":
                return True
        
        return False
    
    def _check_access_control_issues(self, code: str) -> bool:
        """Check for access control issues."""
        # Look for functions without proper access control
        function_pattern = r"function\s+(\w+).*public"
        functions = re.findall(function_pattern, code)
        
        protected_functions = ["onlyOwner", "require", "modifier"]
        
        for func in functions:
            if not any(protection in code for protection in protected_functions):
                return True
        
        return False
    
    def _check_unchecked_calls(self, code: str) -> bool:
        """Check for unchecked external calls."""
        call_patterns = [
            r"\.call\(",
            r"\.delegatecall\(",
            r"\.staticcall\("
        ]
        
        for pattern in call_patterns:
            matches = re.finditer(pattern, code)
            for match in matches:
                # Check if return value is checked
                context = code[match.start():match.start() + 100]
                if "require(" not in context and "if(" not in context:
                    return True
        
        return False
    
    async def _detect_vulnerability_patterns(self,
                                           contract_code: str,
                                           contract_address: str) -> List[SecurityVulnerability]:
        """Detect vulnerabilities using pattern matching."""
        vulnerabilities = []
        
        for vuln_type, patterns in self.threat_patterns.items():
            for pattern in patterns:
                if re.search(pattern, contract_code, re.IGNORECASE | re.MULTILINE):
                    vuln = SecurityVulnerability(
                        vulnerability_id=f"pattern_{vuln_type}_{len(vulnerabilities)}",
                        vulnerability_type=VulnerabilityType(vuln_type.lower()),
                        severity=self._get_pattern_severity(vuln_type),
                        contract_address=contract_address,
                        function_name=None,
                        line_number=None,
                        description=f"Pattern-based detection: {vuln_type}",
                        recommendation=f"Review and fix {vuln_type} vulnerability"
                    )
                    vulnerabilities.append(vuln)
        
        return vulnerabilities
    
    def _get_pattern_severity(self, pattern_type: str) -> SecurityThreatLevel:
        """Get severity level for vulnerability pattern."""
        severity_map = {
            "reentrancy": SecurityThreatLevel.HIGH,
            "integer_overflow": SecurityThreatLevel.MEDIUM,
            "access_control": SecurityThreatLevel.HIGH,
            "front_running": SecurityThreatLevel.MEDIUM,
            "timestamp_dependence": SecurityThreatLevel.LOW
        }
        return severity_map.get(pattern_type, SecurityThreatLevel.MEDIUM)
    
    async def _analyze_gas_optimization(self,
                                      contract_code: str,
                                      contract_address: str) -> List[SecurityVulnerability]:
        """Analyze gas optimization opportunities."""
        issues = []
        
        # Check for gas-inefficient patterns
        gas_patterns = {
            "loop_optimization": r"for\s*\(.*\)\s*\{.*\}",
            "storage_reads": r"storage.*multiple.*reads",
            "external_calls": r"multiple.*external.*calls"
        }
        
        for issue_type, pattern in gas_patterns.items():
            if re.search(pattern, contract_code, re.IGNORECASE):
                vuln = SecurityVulnerability(
                    vulnerability_id=f"gas_{issue_type}_{int(datetime.utcnow().timestamp())}",
                    vulnerability_type=VulnerabilityType.DENIAL_OF_SERVICE,
                    severity=SecurityThreatLevel.LOW,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description=f"Gas optimization opportunity: {issue_type}",
                    recommendation=f"Optimize {issue_type} for better gas efficiency"
                )
                issues.append(vuln)
        
        return issues
    
    async def _analyze_access_control(self,
                                    contract_code: str,
                                    contract_address: str) -> List[SecurityVulnerability]:
        """Analyze access control implementation."""
        issues = []
        
        # Check for missing access control
        sensitive_functions = ["mint", "burn", "transfer", "approve", "withdraw"]
        
        for func in sensitive_functions:
            if func in contract_code.lower():
                if not re.search(rf"function\s+{func}.*onlyOwner", contract_code, re.IGNORECASE):
                    vuln = SecurityVulnerability(
                        vulnerability_id=f"access_{func}_{int(datetime.utcnow().timestamp())}",
                        vulnerability_type=VulnerabilityType.ACCESS_CONTROL,
                        severity=SecurityThreatLevel.HIGH,
                        contract_address=contract_address,
                        function_name=func,
                        line_number=None,
                        description=f"Missing access control for {func} function",
                        recommendation=f"Add proper access control to {func} function"
                    )
                    issues.append(vuln)
        
        return issues
    
    def _calculate_overall_security_score(self, vulnerabilities: List[SecurityVulnerability]) -> float:
        """Calculate overall security score."""
        if not vulnerabilities:
            return 100.0
        
        severity_weights = {
            SecurityThreatLevel.CRITICAL: 25,
            SecurityThreatLevel.HIGH: 15,
            SecurityThreatLevel.MEDIUM: 8,
            SecurityThreatLevel.LOW: 3
        }
        
        total_deduction = sum(severity_weights.get(vuln.severity, 0) for vuln in vulnerabilities)
        score = max(0, 100 - total_deduction)
        
        return score
    
    def _calculate_compliance_score(self, vulnerabilities: List[SecurityVulnerability]) -> float:
        """Calculate compliance score."""
        compliance_vulns = [v for v in vulnerabilities 
                          if v.vulnerability_type in [VulnerabilityType.ACCESS_CONTROL,
                                                     VulnerabilityType.UNCHECKED_CALL]]
        
        if not compliance_vulns:
            return 100.0
        
        deduction = len(compliance_vulns) * 10
        return max(0, 100 - deduction)
    
    def _calculate_gas_score(self, vulnerabilities: List[SecurityVulnerability]) -> float:
        """Calculate gas optimization score."""
        gas_vulns = [v for v in vulnerabilities 
                    if v.vulnerability_type == VulnerabilityType.DENIAL_OF_SERVICE]
        
        if not gas_vulns:
            return 100.0
        
        deduction = len(gas_vulns) * 5
        return max(0, 100 - deduction)
    
    def _generate_security_recommendations(self, vulnerabilities: List[SecurityVulnerability]) -> List[str]:
        """Generate security recommendations."""
        recommendations = []
        
        vuln_types = set(v.vulnerability_type for v in vulnerabilities)
        
        if VulnerabilityType.REENTRANCY in vuln_types:
            recommendations.append("Implement reentrancy guards using OpenZeppelin's ReentrancyGuard")
        
        if VulnerabilityType.INTEGER_OVERFLOW in vuln_types:
            recommendations.append("Use Solidity 0.8+ or SafeMath library for arithmetic operations")
        
        if VulnerabilityType.ACCESS_CONTROL in vuln_types:
            recommendations.append("Implement proper access control using OpenZeppelin's Ownable or AccessControl")
        
        if VulnerabilityType.UNCHECKED_CALL in vuln_types:
            recommendations.append("Always check return values of external calls")
        
        recommendations.append("Regular security audits and testing")
        recommendations.append("Implement circuit breakers for emergency stops")
        recommendations.append("Use formal verification tools for critical functions")
        
        return recommendations
    
    async def validate_transaction(self,
                                 transaction_data: Dict[str, Any]) -> TransactionAnalysis:
        """Validate transaction for security threats."""



        try:
            tx_hash = transaction_data.get("hash", "")
            from_address = transaction_data.get("from", "")
            to_address = transaction_data.get("to", "")
            value = Decimal(str(transaction_data.get("value", 0)))
            gas_limit = transaction_data.get("gas", 0)
            gas_price = transaction_data.get("gasPrice", 0)
            data = transaction_data.get("data", "")
            
            # Calculate risk score
            risk_score = 0.0
            threat_indicators = []
            
            # Check blacklisted addresses
            if from_address in self.blacklisted_addresses or to_address in self.blacklisted_addresses:
                risk_score += 50.0
                threat_indicators.append("blacklisted_address")
            
            # Check for suspicious patterns
            if self._is_suspicious_value(value):
                risk_score += 20.0
                threat_indicators.append("suspicious_value")
            
            if self._is_suspicious_gas(gas_limit, gas_price):
                risk_score += 15.0
                threat_indicators.append("suspicious_gas")
            
            if self._contains_malicious_data(data):
                risk_score += 30.0
                threat_indicators.append("malicious_data")
            
            # MEV risk assessment
            mev_risk = await self._assess_mev_risk(transaction_data)
            if mev_risk > 0.7:
                risk_score += 25.0
                threat_indicators.append("high_mev_risk")
            
            # Determine transaction status
            if risk_score >= 70:
                status = TransactionStatus.BLOCKED
            elif risk_score >= 40:
                status = TransactionStatus.SUSPICIOUS
            elif risk_score >= 20:
                status = TransactionStatus.PENDING_REVIEW
            else:
                status = TransactionStatus.VALID
            
            # Create analysis result
            analysis = TransactionAnalysis(
                transaction_hash=tx_hash,
                from_address=from_address,
                to_address=to_address,
                value=value,
                gas_limit=gas_limit,
                gas_price=gas_price,
                data=data,
                status=status,
                risk_score=risk_score,
                threat_indicators=threat_indicators,
                mev_risk=mev_risk
            )
            
            # Store analysis
            self.transaction_analyses[tx_hash] = analysis
            
            logger.info(f"Transaction validation completed: {tx_hash} - {status} (risk: {risk_score})")
            return analysis
            
        except Exception as e:
            logger.error(f"Error validating transaction: {e}")
            raise
    
    def _is_suspicious_value(self, value: Decimal) -> bool:
        """Check if transaction value is suspicious."""
        # Very high values might be suspicious
        if value > Decimal("1000000"):  # 1M tokens
            return True
        
        # Micro-transactions might be spam
        if Decimal("0") < value < Decimal("0.000001"):
            return True
        
        return False
    
    def _is_suspicious_gas(self, gas_limit: int, gas_price: int) -> bool:
        """Check if gas parameters are suspicious."""
        # Extremely high gas prices (potential MEV)
        if gas_price > 500000000000:  # 500 Gwei
            return True
        
        # Unusual gas limits
        if gas_limit > 10000000:  # 10M gas
            return True
        
        return False
    
    def _contains_malicious_data(self, data: str) -> bool:
        """Check if transaction data contains malicious patterns."""
        malicious_patterns = [
            "0xdeadbeef",  # Common test pattern
            "selfdestruct",
            "delegatecall",
            # Add more malicious patterns
        ]
        
        data_lower = data.lower()
        for pattern in malicious_patterns:
            if pattern in data_lower:
                return True
        
        return False
    
    async def _assess_mev_risk(self, transaction_data: Dict[str, Any]) -> float:
        """Assess MEV (Maximal Extractable Value) risk."""
        mev_risk = 0.0
        
        # High gas price indicates potential front-running
        gas_price = transaction_data.get("gasPrice", 0)
        if gas_price > 200000000000:  # 200 Gwei
            mev_risk += 0.3
        
        # Large value transactions are MEV targets
        value = Decimal(str(transaction_data.get("value", 0)))
        if value > Decimal("100000"):  # 100K tokens
            mev_risk += 0.2
        
        # DEX interaction patterns
        data = transaction_data.get("data", "")
        if "swap" in data.lower() or "exchange" in data.lower():
            mev_risk += 0.4
        
        # Time-sensitive transactions
        # (Would need mempool analysis in production)
        mev_risk += 0.1
        
        return min(mev_risk, 1.0)
    
    async def get_security_status(self, contract_address: str) -> Dict[str, Any]:
        """Get security status for a contract."""



        try:
            if contract_address not in self.audit_reports:
                return {"error": "No audit report found for this contract"}
            
            audit_report = self.audit_reports[contract_address]
            
            # Count vulnerabilities by severity
            vuln_count = {
                "critical": len([v for v in audit_report.vulnerabilities 
                               if v.severity == SecurityThreatLevel.CRITICAL]),
                "high": len([v for v in audit_report.vulnerabilities 
                           if v.severity == SecurityThreatLevel.HIGH]),
                "medium": len([v for v in audit_report.vulnerabilities 
                             if v.severity == SecurityThreatLevel.MEDIUM]),
                "low": len([v for v in audit_report.vulnerabilities 
                          if v.severity == SecurityThreatLevel.LOW])
            }
            
            return {
                "contract_address": contract_address,
                "overall_score": audit_report.overall_score,
                "compliance_score": audit_report.compliance_score,
                "gas_optimization_score": audit_report.gas_optimization_score,
                "vulnerability_count": vuln_count,
                "total_vulnerabilities": len(audit_report.vulnerabilities),
                "last_audit": audit_report.audited_at.isoformat(),
                "recommendations_count": len(audit_report.recommendations),
                "status": "secure" if audit_report.overall_score >= 80 else "needs_attention"
            }
            
        except Exception as e:
            logger.error(f"Error getting security status: {e}")
            return {"error": str(e)}
    
    async def generate_security_report(self, 
                                     time_period_days: int = 30) -> Dict[str, Any]:
        """Generate comprehensive security report."""



        try:
            end_date = datetime.utcnow()
            start_date = end_date - timedelta(days=time_period_days)
            
            # Filter recent audits and transactions
            recent_audits = [
                report for report in self.audit_reports.values()
                if report.audited_at >= start_date
            ]
            
            recent_transactions = [
                analysis for analysis in self.transaction_analyses.values()
                if analysis.analyzed_at >= start_date
            ]
            
            # Calculate statistics
            total_contracts_audited = len(recent_audits)
            avg_security_score = np.mean([audit.overall_score for audit in recent_audits]) if recent_audits else 0
            
            total_transactions_analyzed = len(recent_transactions)
            blocked_transactions = len([tx for tx in recent_transactions 
                                      if tx.status == TransactionStatus.BLOCKED])
            suspicious_transactions = len([tx for tx in recent_transactions 
                                         if tx.status == TransactionStatus.SUSPICIOUS])
            
            # Threat analysis
            top_threats = self._analyze_top_threats(recent_audits)
            
            security_report = {
                "report_period": {
                    "start_date": start_date.isoformat(),
                    "end_date": end_date.isoformat(),
                    "days": time_period_days
                },
                "contract_security": {
                    "total_audits": total_contracts_audited,
                    "average_security_score": round(avg_security_score, 2),
                    "contracts_with_critical_vulns": len([a for a in recent_audits 
                                                        if any(v.severity == SecurityThreatLevel.CRITICAL 
                                                             for v in a.vulnerabilities)])
                },
                "transaction_security": {
                    "total_analyzed": total_transactions_analyzed,
                    "blocked": blocked_transactions,
                    "suspicious": suspicious_transactions,
                    "valid": total_transactions_analyzed - blocked_transactions - suspicious_transactions,
                    "block_rate": round(blocked_transactions / max(total_transactions_analyzed, 1) * 100, 2)
                },
                "threat_analysis": {
                    "top_threats": top_threats,
                    "blacklisted_addresses": len(self.blacklisted_addresses),
                    "total_vulnerabilities": len(self.vulnerability_database)
                },
                "generated_at": datetime.utcnow().isoformat()
            }
            
            logger.info(f"Generated security report for {time_period_days} days")
            return security_report
            
        except Exception as e:
            logger.error(f"Error generating security report: {e}")
            return {"error": str(e)}
    
    def _analyze_top_threats(self, audits: List[ContractAuditReport]) -> List[Dict[str, Any]]:
        """Analyze top security threats from audits."""
        threat_counts = {}
        
        for audit in audits:
            for vuln in audit.vulnerabilities:
                threat_type = vuln.vulnerability_type.value
                if threat_type not in threat_counts:
                    threat_counts[threat_type] = {"count": 0, "severity_sum": 0}
                
                threat_counts[threat_type]["count"] += 1
                severity_weight = {
                    SecurityThreatLevel.CRITICAL: 4,
                    SecurityThreatLevel.HIGH: 3,
                    SecurityThreatLevel.MEDIUM: 2,
                    SecurityThreatLevel.LOW: 1
                }.get(vuln.severity, 1)
                
                threat_counts[threat_type]["severity_sum"] += severity_weight
        
        # Sort by impact (count * average severity)
        top_threats = []
        for threat_type, data in threat_counts.items():
            avg_severity = data["severity_sum"] / data["count"]
            impact_score = data["count"] * avg_severity
            
            top_threats.append({
                "threat_type": threat_type,
                "count": data["count"],
                "average_severity": round(avg_severity, 2),
                "impact_score": round(impact_score, 2)
            })
        
        return sorted(top_threats, key=lambda x: x["impact_score"], reverse=True)[:5]


class SmartContractAuditor:
    """Specialized smart contract auditing system."""
    
    def __init__(self, security_manager: BlockchainSecurityManager):
        """Initialize contract auditor."""
        self.security_manager = security_manager
        self.audit_history: List[ContractAuditReport] = []
    
    async def perform_deep_audit(self,
                               contract_address: str,
                               contract_code: str,
                               contract_name: str = "Unknown") -> ContractAuditReport:
        """Perform deep security audit with advanced analysis."""



        try:
            # Basic audit first
            basic_audit = await self.security_manager.audit_smart_contract(
                contract_address, contract_code, contract_name
            )
            
            # Additional deep analysis
            additional_vulns = await self._perform_advanced_analysis(contract_code, contract_address)
            basic_audit.vulnerabilities.extend(additional_vulns)
            
            # Recalculate scores
            basic_audit.overall_score = self.security_manager._calculate_overall_security_score(
                basic_audit.vulnerabilities
            )
            
            self.audit_history.append(basic_audit)
            
            logger.info(f"Completed deep audit for {contract_address}")
            return basic_audit
            
        except Exception as e:
            logger.error(f"Error in deep audit: {e}")
            raise
    
    async def _perform_advanced_analysis(self,
                                       contract_code: str,
                                       contract_address: str) -> List[SecurityVulnerability]:
        """Perform advanced security analysis."""
        vulnerabilities = []
        
        # Formal verification checks
        formal_issues = await self._formal_verification_check(contract_code, contract_address)
        vulnerabilities.extend(formal_issues)
        
        # Economic attack vectors
        economic_risks = await self._analyze_economic_attacks(contract_code, contract_address)
        vulnerabilities.extend(economic_risks)
        
        # Protocol-specific checks
        protocol_issues = await self._protocol_specific_checks(contract_code, contract_address)
        vulnerabilities.extend(protocol_issues)
        
        return vulnerabilities
    
    async def _formal_verification_check(self,
                                       contract_code: str,
                                       contract_address: str) -> List[SecurityVulnerability]:
        """Perform formal verification checks."""
        # Mock implementation - would use tools like Certora, KEVM, etc.
        issues = []
        
        # Check for state invariants
        if "invariant" not in contract_code.lower():
            issue = SecurityVulnerability(
                vulnerability_id=f"formal_invariant_{int(datetime.utcnow().timestamp())}",
                vulnerability_type=VulnerabilityType.ACCESS_CONTROL,
                severity=SecurityThreatLevel.MEDIUM,
                contract_address=contract_address,
                function_name=None,
                line_number=None,
                description="Missing state invariants for formal verification",
                recommendation="Add state invariants and formal specifications"
            )
            issues.append(issue)
        
        return issues
    
    async def _analyze_economic_attacks(self,
                                      contract_code: str,
                                      contract_address: str) -> List[SecurityVulnerability]:
        """Analyze potential economic attack vectors."""
        issues = []
        
        # Flash loan attack potential
        if "flashloan" in contract_code.lower() or "borrow" in contract_code.lower():
            issue = SecurityVulnerability(
                vulnerability_id=f"economic_flashloan_{int(datetime.utcnow().timestamp())}",
                vulnerability_type=VulnerabilityType.FRONT_RUNNING,
                severity=SecurityThreatLevel.HIGH,
                contract_address=contract_address,
                function_name=None,
                line_number=None,
                description="Potential flash loan attack vector",
                recommendation="Implement flash loan protection mechanisms"
            )
            issues.append(issue)
        
        return issues
    
    async def _protocol_specific_checks(self,
                                      contract_code: str,
                                      contract_address: str) -> List[SecurityVulnerability]:
        """Perform protocol-specific security checks."""
        issues = []
        
        # ERC-20/ERC-721 specific checks
        if "ERC20" in contract_code or "ERC721" in contract_code:
            # Check for proper event emissions
            if "emit Transfer" not in contract_code:
                issue = SecurityVulnerability(
                    vulnerability_id=f"protocol_events_{int(datetime.utcnow().timestamp())}",
                    vulnerability_type=VulnerabilityType.ACCESS_CONTROL,
                    severity=SecurityThreatLevel.LOW,
                    contract_address=contract_address,
                    function_name=None,
                    line_number=None,
                    description="Missing proper event emissions",
                    recommendation="Ensure all state changes emit appropriate events"
                )
                issues.append(issue)
        
        return issues


class TransactionValidator:
    """Advanced transaction validation system."""
    
    def __init__(self, security_manager: BlockchainSecurityManager):
        """Initialize transaction validator."""
        self.security_manager = security_manager
        self.validation_rules: Dict[str, Any] = {}
        self._initialize_validation_rules()
    
    def _initialize_validation_rules(self):
        """Initialize transaction validation rules."""
        self.validation_rules = {
            "max_gas_price": 1000000000000,  # 1000 Gwei
            "max_gas_limit": 10000000,  # 10M gas
            "max_value": Decimal("1000000000"),  # 1B tokens
            "min_value": Decimal("0.000001"),  # Minimum non-zero value
            "blacklist_check": True,
            "mev_threshold": 0.8,
            "pattern_check": True
        }
    
    async def validate_batch_transactions(self,
                                        transactions: List[Dict[str, Any]]) -> List[TransactionAnalysis]:
        """Validate a batch of transactions."""
        results = []
        
        for tx in transactions:
            try:
                analysis = await self.security_manager.validate_transaction(tx)
                results.append(analysis)
            except Exception as e:
                logger.error(f"Error validating transaction {tx.get('hash', 'unknown')}: {e}")
        
        return results
    
    async def update_validation_rules(self, new_rules: Dict[str, Any]) -> bool:
        """Update validation rules."""



        try:
            self.validation_rules.update(new_rules)
            logger.info("Updated transaction validation rules")
            return True
        except Exception as e:
            logger.error(f"Error updating validation rules: {e}")
            return False


class AntiMEVProtection:
    """Anti-MEV (Maximal Extractable Value) protection system."""
    
    def __init__(self):
        """Initialize MEV protection system."""
        self.protected_transactions: Dict[str, Dict[str, Any]] = {}
        self.mev_patterns: List[str] = []
        self._initialize_mev_patterns()
    
    def _initialize_mev_patterns(self):
        """Initialize known MEV patterns."""
        self.mev_patterns = [
            "sandwich_attack",
            "front_running",
            "back_running",
            "arbitrage_extraction",
            "liquidation_mev"
        ]
    
    async def protect_transaction(self,
                                transaction_data: Dict[str, Any],
                                protection_type: str = "commit_reveal") -> Dict[str, Any]:
        """Apply MEV protection to a transaction."""



        try:
            tx_hash = transaction_data.get("hash", "")
            
            if protection_type == "commit_reveal":
                # Implement commit-reveal scheme
                protected_tx = await self._apply_commit_reveal(transaction_data)
            elif protection_type == "private_mempool":
                # Use private mempool
                protected_tx = await self._use_private_mempool(transaction_data)
            elif protection_type == "delayed_execution":
                # Implement delayed execution
                protected_tx = await self._apply_delayed_execution(transaction_data)
            else:
                protected_tx = transaction_data
            
            self.protected_transactions[tx_hash] = {
                "original": transaction_data,
                "protected": protected_tx,
                "protection_type": protection_type,
                "timestamp": datetime.utcnow()
            }
            
            logger.info(f"Applied MEV protection to transaction {tx_hash}")
            return protected_tx
            
        except Exception as e:
            logger.error(f"Error applying MEV protection: {e}")
            return transaction_data
    
    async def _apply_commit_reveal(self, tx_data: Dict[str, Any]) -> Dict[str, Any]:
        """Apply commit-reveal MEV protection."""
        # Mock implementation
        commitment = hashlib.sha256(json.dumps(tx_data, sort_keys=True).encode()).hexdigest()
        
        protected_tx = tx_data.copy()
        protected_tx["commitment"] = commitment
        protected_tx["reveal_delay"] = 60  # 60 seconds
        
        return protected_tx
    
    async def _use_private_mempool(self, tx_data: Dict[str, Any]) -> Dict[str, Any]:
        """Route transaction through private mempool."""
        # Mock implementation
        protected_tx = tx_data.copy()
        protected_tx["private_mempool"] = True
        protected_tx["miner_tip"] = "0.001"  # Additional tip for private inclusion
        
        return protected_tx
    
    async def _apply_delayed_execution(self, tx_data: Dict[str, Any]) -> Dict[str, Any]:
        """Apply delayed execution MEV protection."""
        # Mock implementation
        protected_tx = tx_data.copy()
        protected_tx["execution_delay"] = 30  # 30 seconds delay
        protected_tx["scheduled_execution"] = (datetime.utcnow() + timedelta(seconds=30)).isoformat()
        
        return protected_tx
    
    async def detect_mev_attack(self, transactions: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Detect potential MEV attacks in transaction batch."""
        mev_indicators = {
            "sandwich_detected": False,
            "front_running_detected": False,
            "arbitrage_detected": False,
            "total_mev_risk": 0.0,
            "affected_transactions": []
        }
        
        # Simple MEV detection logic
        for i, tx in enumerate(transactions):
            # Check for sandwich attacks (similar transactions around target)
            if i > 0 and i < len(transactions) - 1:
                prev_tx = transactions[i-1]
                next_tx = transactions[i+1]
                
                if (prev_tx.get("to") == next_tx.get("to") and
                    prev_tx.get("from") == next_tx.get("from")):
                    mev_indicators["sandwich_detected"] = True
                    mev_indicators["affected_transactions"].append(tx.get("hash"))
        
        return mev_indicators

