class SecurityLevel(Enum):
    """Security validation levels."""
    LOW = "low"              # Basic checks only
    MEDIUM = "medium"        # Standard validation
    HIGH = "high"           # Comprehensive security
    PARANOID = "paranoid"   # Maximum security


class ThreatLevel(Enum):
    """Threat severity levels."""
    NONE = "none"
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class ViolationType(Enum):
    """Types of security violations."""
    MALWARE = "malware"
    VIRUS = "virus"
    SUSPICIOUS_CONTENT = "suspicious_content"
    PII_EXPOSURE = "pii_exposure"
    COPYRIGHT_VIOLATION = "copyright_violation"
    INAPPROPRIATE_CONTENT = "inappropriate_content"
    DATA_LEAK = "data_leak"
    PRIVACY_VIOLATION = "privacy_violation"
    COMPLIANCE_VIOLATION = "compliance_violation"
    UNAUTHORIZED_ACCESS = "unauthorized_access"
    SUSPICIOUS_METADATA = "suspicious_metadata"
    SECURITY_RISK = "security_risk"


class ComplianceStandard(Enum):
    """Compliance standards to validate against."""
    GDPR = "gdpr"           # General Data Protection Regulation
    CCPA = "ccpa"           # California Consumer Privacy Act
    HIPAA = "hipaa"         # Health Insurance Portability and Accountability Act
    COPPA = "coppa"         # Children's Online Privacy Protection Act
    SOX = "sox"             # Sarbanes-Oxley Act
    DMCA = "dmca"           # Digital Millennium Copyright Act
    ISO27001 = "iso27001"   # ISO 27001 Information Security
    NIST = "nist"           # NIST Cybersecurity Framework


@dataclass
class SecurityViolation:
    """Security violation details."""
    violation_type: ViolationType
    threat_level: ThreatLevel
    description: str
    location: Optional[str] = None
    evidence: Optional[Dict[str, Any]] = None
    remediation: Optional[str] = None
    compliance_impact: List[ComplianceStandard] = field(default_factory=list)
    timestamp: datetime = field(default_factory=lambda: datetime.now(timezone.utc))


