class ContentScanner:
    """Content analysis and threat detection."""
    
    async def scan(self, file_path: str, media_type: MediaType) -> Dict[str, Any]:
        """Scan file content for security issues."""
        result = {
            'scan_completed': True,
            'pattern_matches': {},
            'content_analysis': {},
            'risk_score': 0.0
        }
        
        try:
            if media_type in [MediaType.TEXT, MediaType.DOCUMENT]:
                await self._scan_text_content(file_path, result)
            elif media_type == MediaType.IMAGE:
                await self._scan_image_content(file_path, result)
            elif media_type in [MediaType.AUDIO, MediaType.VIDEO]:
                await self._scan_media_content(file_path, result)
            
        except Exception as e:
            logger.error(f"Content scan error: {e}")
            result['scan_completed'] = False
            result['error'] = str(e)
        
        return result
    
    async def _scan_text_content(self, file_path: str, result: Dict[str, Any]):
        """Scan text content for suspicious patterns."""



        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read(100000)  # Read first 100KB
            
            # Pattern matching
            from .security_validator import SecurityValidator
            validator = SecurityValidator()
            
            for pattern_type, patterns in validator.security_patterns.items():
                matches = []
                for pattern in patterns:
                    pattern_matches = pattern.findall(content)
                    if pattern_matches:
                        matches.extend(pattern_matches)
                
                if matches:
                    result['pattern_matches'][pattern_type] = matches
                    result['risk_score'] += len(matches) * 0.1
            
            # Content analysis
            result['content_analysis'] = {
                'length': len(content),
                'suspicious_keywords': self._count_suspicious_keywords(content),
                'encoded_content': self._detect_encoded_content(content)
            }
            
        except Exception as e:
            logger.error(f"Text content scan error: {e}")
    
    def _count_suspicious_keywords(self, content: str) -> int:
        """Count suspicious keywords in content."""
        suspicious_keywords = [
            'malware', 'virus', 'trojan', 'backdoor', 'rootkit',
            'exploit', 'payload', 'shellcode', 'injection',
            'password', 'secret', 'token', 'key', 'auth'
        ]
        
        content_lower = content.lower()
        count = sum(content_lower.count(keyword) for keyword in suspicious_keywords)
        return count
    
    def _detect_encoded_content(self, content: str) -> bool:
        """Detect potentially encoded/obfuscated content."""
        # Check for base64-like strings
        base64_pattern = re.compile(r'[A-Za-z0-9+/]{20,}={0,2}')
        base64_matches = base64_pattern.findall(content)
        
        # Check for hex-encoded strings
        hex_pattern = re.compile(r'[0-9a-fA-F]{40,}')
        hex_matches = hex_pattern.findall(content)
        
        return len(base64_matches) > 5 or len(hex_matches) > 3
    
    async def _scan_image_content(self, file_path: str, result: Dict[str, Any]):
        """Scan image content for suspicious elements."""
        # This would implement image analysis for embedded content, steganography, etc.
        result['content_analysis'] = {'image_scan': 'placeholder'}
    
    async def _scan_media_content(self, file_path: str, result: Dict[str, Any]):
        """Scan audio/video content for suspicious elements."""
