import asyncio
import logging
import hashlib
from datetime import datetime, timedelta
from typing import Dict, List, Optional, Any, Set
from dataclasses import dataclass
from enum import Enum
import statistics
from prometheus_client import Counter, Gauge

logger = logging.getLogger(__name__)

class ThreatLevel(Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"

class AttackType(Enum):
    FIFTY_ONE_PERCENT = "51_percent_attack"
    DOUBLE_SPENDING = "double_spending"
    NOTHING_AT_STAKE = "nothing_at_stake"
    LONG_RANGE = "long_range_attack"
    ECLIPSE = "eclipse_attack"
    SYBIL = "sybil_attack"
    DDOS = "ddos_attack"

@dataclass
class SecurityEvent:
    event_id: str
    timestamp: datetime
    attack_type: AttackType
    threat_level: ThreatLevel
    source_address: Optional[str]
    target_nodes: List[str]
    description: str
    evidence: Dict[str, Any]
    resolved: bool = False
    mitigation_actions: List[str] = None

@dataclass
class SecurityMetrics:
    timestamp: datetime
    attack_attempts: int
    blocked_attempts: int
    suspicious_activities: int
    validator_misbehavior: int
    network_anomalies: int
    consensus_deviations: int
    security_score: float

class SecurityMetrics:
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.is_running = False
        
        # Security events storage
        self.security_events: List[SecurityEvent] = []
        self.security_metrics_history: List[SecurityMetrics] = []
        self.known_malicious_addresses: Set[str] = set()
        
        # Prometheus metrics
        self.attack_attempts_total = Counter('security_attack_attempts_total', 'Total attack attempts', ['type'])
        self.blocked_attacks_total = Counter('security_blocked_attacks_total', 'Total blocked attacks', ['type'])
        self.security_score_gauge = Gauge('security_score', 'Overall security score')
        self.suspicious_activities = Counter('security_suspicious_activities_total', 'Suspicious activities', ['category'])
        
        # Security thresholds
        self.thresholds = {
            'max_failed_validations': 10,
            'max_double_sign_attempts': 3,
            'min_security_score': 0.8,
            'max_consensus_deviation': 0.1
        }

    async def start_monitoring(self):
        """Start security monitoring."""
        self.is_running = True
        
        tasks = [
            asyncio.create_task(self._monitor_attack_patterns()),
            asyncio.create_task(self._monitor_validator_behavior()),
            asyncio.create_task(self._monitor_network_anomalies()),
            asyncio.create_task(self._calculate_security_scores()),
            asyncio.create_task(self._detect_consensus_attacks())
        ]
        
        await asyncio.gather(*tasks, return_exceptions=True)

    async def stop_monitoring(self):
        """Stop security monitoring."""
        self.is_running = False

    async def _monitor_attack_patterns(self):
        """Monitor for known attack patterns."""
        while self.is_running:
            try:
                # Check for 51% attack patterns
                stake_distribution = await self._get_stake_distribution()
                if await self._detect_51_percent_attack(stake_distribution):
                    await self._record_security_event(
                        AttackType.FIFTY_ONE_PERCENT,
                        ThreatLevel.CRITICAL,
                        "Potential 51% attack detected",
                        {"stake_distribution": stake_distribution}
                    )
                
                # Check for double spending attempts
                double_spend_attempts = await self._detect_double_spending()
                for attempt in double_spend_attempts:
                    await self._record_security_event(
                        AttackType.DOUBLE_SPENDING,
                        ThreatLevel.HIGH,
                        f"Double spending attempt detected: {attempt['transaction_id']}",
                        attempt
                    )
                
                # Check for eclipse attacks
                eclipse_attempts = await self._detect_eclipse_attacks()
                for attempt in eclipse_attempts:
                    await self._record_security_event(
                        AttackType.ECLIPSE,
                        ThreatLevel.MEDIUM,
                        f"Eclipse attack attempt: {attempt['target_node']}",
                        attempt
                    )
                
                await asyncio.sleep(60)  # Check every minute
                
            except Exception as e:
                logger.error(f"Error monitoring attack patterns: {e}")
                await asyncio.sleep(120)

    async def _monitor_validator_behavior(self):
        """Monitor validator behavior for suspicious activity."""
        while self.is_running:
            try:
                validators = await self._get_active_validators()
                
                for validator in validators:
                    # Check for double signing
                    double_signs = await self._check_double_signing(validator['id'])
                    if double_signs > self.thresholds['max_double_sign_attempts']:
                        await self._record_security_event(
                            AttackType.DOUBLE_SPENDING,
                            ThreatLevel.HIGH,
                            f"Validator {validator['id']} exceeded double signing threshold",
                            {"validator_id": validator['id'], "double_signs": double_signs}
                        )
                    
                    # Check for Byzantine behavior
                    byzantine_score = await self._calculate_byzantine_score(validator['id'])
                    if byzantine_score > 0.5:  # Threshold for suspicious behavior
                        self.suspicious_activities.labels(category='byzantine_behavior').inc()
                
                await asyncio.sleep(300)  # Check every 5 minutes
                
            except Exception as e:
                logger.error(f"Error monitoring validator behavior: {e}")
                await asyncio.sleep(600)

    async def _monitor_network_anomalies(self):
        """Monitor network for anomalous patterns."""
        while self.is_running:
            try:
                # Check for unusual traffic patterns
                traffic_anomalies = await self._detect_traffic_anomalies()
                for anomaly in traffic_anomalies:
                    if anomaly['severity'] == 'high':
                        await self._record_security_event(
                            AttackType.DDOS,
                            ThreatLevel.HIGH,
                            f"Unusual traffic pattern: {anomaly['description']}",
                            anomaly
                        )
                
                # Check for Sybil attacks
                sybil_indicators = await self._detect_sybil_attacks()
                for indicator in sybil_indicators:
                    await self._record_security_event(
                        AttackType.SYBIL,
                        ThreatLevel.MEDIUM,
                        f"Potential Sybil attack: {indicator['description']}",
                        indicator
                    )
                
                await asyncio.sleep(180)  # Check every 3 minutes
                
            except Exception as e:
                logger.error(f"Error monitoring network anomalies: {e}")
                await asyncio.sleep(360)

    async def _calculate_security_scores(self):
        """Calculate overall security scores."""
        while self.is_running:
            try:
                # Calculate various security factors
                attack_resistance = await self._calculate_attack_resistance()
                network_decentralization = await self._calculate_decentralization_score()
                validator_trustworthiness = await self._calculate_validator_trust_score()
                consensus_integrity = await self._calculate_consensus_integrity()
                
                # Weighted security score
                security_score = (
                    attack_resistance * 0.3 +
                    network_decentralization * 0.25 +
                    validator_trustworthiness * 0.25 +
                    consensus_integrity * 0.2
                )
                
                # Record metrics
                metrics = SecurityMetrics(
                    timestamp=datetime.utcnow(),
                    attack_attempts=len([e for e in self.security_events if not e.resolved]),
                    blocked_attempts=len([e for e in self.security_events if e.resolved]),
                    suspicious_activities=await self._count_suspicious_activities(),
                    validator_misbehavior=await self._count_validator_misbehavior(),
                    network_anomalies=await self._count_network_anomalies(),
                    consensus_deviations=await self._count_consensus_deviations(),
                    security_score=security_score
                )
                
                self.security_metrics_history.append(metrics)
                self.security_score_gauge.set(security_score)
                
                # Alert if security score drops below threshold
                if security_score < self.thresholds['min_security_score']:
                    await self._trigger_security_alert(
                        f"Security score dropped to {security_score:.2f}",
                        ThreatLevel.HIGH
                    )
                
                await asyncio.sleep(300)  # Calculate every 5 minutes
                
            except Exception as e:
                logger.error(f"Error calculating security scores: {e}")
                await asyncio.sleep(600)

    async def _detect_consensus_attacks(self):
        """Detect attacks on consensus mechanisms."""
        while self.is_running:
            try:
                # Check for nothing-at-stake attacks
                nas_indicators = await self._detect_nothing_at_stake()
                for indicator in nas_indicators:
                    await self._record_security_event(
                        AttackType.NOTHING_AT_STAKE,
                        ThreatLevel.MEDIUM,
                        f"Nothing-at-stake detected: {indicator['description']}",
                        indicator
                    )
                
                # Check for long-range attacks
                lr_indicators = await self._detect_long_range_attacks()
                for indicator in lr_indicators:
                    await self._record_security_event(
                        AttackType.LONG_RANGE,
                        ThreatLevel.HIGH,
                        f"Long-range attack detected: {indicator['description']}",
                        indicator
                    )
                
                await asyncio.sleep(240)  # Check every 4 minutes
                
            except Exception as e:
                logger.error(f"Error detecting consensus attacks: {e}")
                await asyncio.sleep(480)

    async def _record_security_event(self, attack_type: AttackType, threat_level: ThreatLevel,
                                   description: str, evidence: Dict[str, Any]):
        """Record a security event."""
        event = SecurityEvent(
            event_id=hashlib.sha256(f"{datetime.utcnow()}{description}".encode()).hexdigest()[:16],
            timestamp=datetime.utcnow(),
            attack_type=attack_type,
            threat_level=threat_level,
            source_address=evidence.get('source_address'),
            target_nodes=evidence.get('target_nodes', []),
            description=description,
            evidence=evidence,
            mitigation_actions=[]
        )
        
        self.security_events.append(event)
        
        # Update Prometheus metrics
        self.attack_attempts_total.labels(type=attack_type.value).inc()
        
        logger.warning(f"Security event recorded: {attack_type.value} - {threat_level.value} - {description}")

    # Placeholder methods for security detection logic
    async def _detect_51_percent_attack(self, stake_distribution: Dict[str, float]) -> bool:
        """Detect potential 51% attacks."""
        if not stake_distribution:
            return False
        
        max_stake = max(stake_distribution.values())
        total_stake = sum(stake_distribution.values())
        
        return max_stake / total_stake > 0.51

    async def _detect_double_spending(self) -> List[Dict[str, Any]]:
        """Detect double spending attempts."""
        # Placeholder implementation
        return []

    async def _detect_eclipse_attacks(self) -> List[Dict[str, Any]]:
        """Detect eclipse attack attempts."""
        # Placeholder implementation
        return []

    async def _calculate_attack_resistance(self) -> float:
        """Calculate network's resistance to attacks."""
        # Placeholder implementation
        return 0.9

    async def _calculate_decentralization_score(self) -> float:
        """Calculate network decentralization score."""
        # Placeholder implementation
        return 0.85

    async def get_security_events(self, duration: timedelta = timedelta(hours=24)) -> List[SecurityEvent]:
        """Get security events for specified duration."""
        cutoff_time = datetime.utcnow() - duration
        return [e for e in self.security_events if e.timestamp > cutoff_time]

    async def get_security_summary(self) -> Dict[str, Any]:
        """Get security monitoring summary."""
        recent_events = await self.get_security_events(timedelta(hours=24))
        
        return {
            'total_events_24h': len(recent_events),
            'critical_events': len([e for e in recent_events if e.threat_level == ThreatLevel.CRITICAL]),
            'high_events': len([e for e in recent_events if e.threat_level == ThreatLevel.HIGH]),
            'unresolved_events': len([e for e in recent_events if not e.resolved]),
            'current_security_score': self.security_metrics_history[-1].security_score if self.security_metrics_history else 0.0,
            'attack_types_detected': list(set([e.attack_type.value for e in recent_events]))
        }

