class ContentScanner:
    """Content analysis and threat detection."""
    
    async def scan(self, file_path: str, media_type: MediaType) -> Dict[str, Any]:
        """Scan file content for security issues."""
        result = {
            'scan_completed': True,
            'pattern_matches': {},
            'content_analysis': {},
            'risk_score': 0.0
        }
        
        try:
            if media_type in [MediaType.TEXT, MediaType.DOCUMENT]:
                await self._scan_text_content(file_path, result)
            elif media_type == MediaType.IMAGE:
                await self._scan_image_content(file_path, result)
            elif media_type in [MediaType.AUDIO, MediaType.VIDEO]:
                await self._scan_media_content(file_path, result)
            
        except Exception as e:
            logger.error(f"Content scan error: {e}")
            result['scan_completed'] = False
            result['error'] = str(e)
        
        return result
    
    async def _scan_text_content(self, file_path: str, result: Dict[str, Any]):
        """Scan text content for suspicious patterns."""



        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read(100000)  # Read first 100KB
            
            # Pattern matching
            from .security_validator import SecurityValidator
            validator = SecurityValidator()
            
            for pattern_type, patterns in validator.security_patterns.items():
                matches = []
                for pattern in patterns:
                    pattern_matches = pattern.findall(content)
                    if pattern_matches:
                        matches.extend(pattern_matches)
                
                if matches:
                    result['pattern_matches'][pattern_type] = matches
                    result['risk_score'] += len(matches) * 0.1
            
            # Content analysis
            result['content_analysis'] = {
                'length': len(content),
                'suspicious_keywords': self._count_suspicious_keywords(content),
                'encoded_content': self._detect_encoded_content(content)
            }
            
        except Exception as e:
            logger.error(f"Text content scan error: {e}")
    
    def _count_suspicious_keywords(self, content: str) -> int:
        """Count suspicious keywords in content."""
        suspicious_keywords = [
            'malware', 'virus', 'trojan', 'backdoor', 'rootkit',
            'exploit', 'payload', 'shellcode', 'injection',
            'password', 'secret', 'token', 'key', 'auth'
        ]
        
        content_lower = content.lower()
        count = sum(content_lower.count(keyword) for keyword in suspicious_keywords)
        return count
    
    def _detect_encoded_content(self, content: str) -> bool:
        """Detect potentially encoded/obfuscated content."""
        # Check for base64-like strings
        base64_pattern = re.compile(r'[A-Za-z0-9+/]{20,}={0,2}')
        base64_matches = base64_pattern.findall(content)
        
        # Check for hex-encoded strings
        hex_pattern = re.compile(r'[0-9a-fA-F]{40,}')
        hex_matches = hex_pattern.findall(content)
        
        return len(base64_matches) > 5 or len(hex_matches) > 3
    
    async def _scan_image_content(self, file_path: str, result: Dict[str, Any]):
        """Scan image content for suspicious elements."""
        # This would implement image analysis for embedded content, steganography, etc.
        result['content_analysis'] = {'image_scan': 'placeholder'}
    
    async def _scan_media_content(self, file_path: str, result: Dict[str, Any]):
        """Scan audio/video content for suspicious elements."""
        # This would implement media analysis for embedded content, hidden data, etc.
        result['content_analysis'] = {'media_scan': 'placeholder'}


class PrivacyScanner:
    """Privacy and PII detection component."""
    
    async def scan(self, file_path: str, media_type: MediaType) -> Dict[str, Any]:
        """Scan for privacy violations and PII."""
        result = {
            'scan_completed': True,
            'pii_found': False,
            'pii_types': [],
            'location_data': False,
            'device_fingerprinting': False,
            'privacy_score': 0.0
        }
        
        try:
            # Extract and analyze metadata
            metadata_result = await extract_metadata(file_path)
            
            # Check metadata for privacy violations
            await self._analyze_metadata_privacy(metadata_result, result)
            
            # Content-based PII detection
            if media_type in [MediaType.TEXT, MediaType.DOCUMENT]:
                await self._scan_text_pii(file_path, result)
            
        except Exception as e:
            logger.error(f"Privacy scan error: {e}")
            result['scan_completed'] = False
            result['error'] = str(e)
        
        return result
    
    async def _analyze_metadata_privacy(self, metadata_result, result: Dict[str, Any]):
        """Analyze metadata for privacy violations."""
        if metadata_result.privacy_report['contains_pii']:
            result['pii_found'] = True
            result['privacy_score'] += 0.5
        
        if metadata_result.privacy_report['location_data']:
            result['location_data'] = True
            result['pii_types'].append('location')
            result['privacy_score'] += 0.3
        
        if metadata_result.privacy_report['device_fingerprinting']:
            result['device_fingerprinting'] = True
            result['pii_types'].append('device_info')
            result['privacy_score'] += 0.2
        
        for identifier in metadata_result.privacy_report['personal_identifiers']:
            if identifier not in result['pii_types']:
                result['pii_types'].append(identifier)
                result['privacy_score'] += 0.1
    
    async def _scan_text_pii(self, file_path: str, result: Dict[str, Any]):
        """Scan text content for PII."""



        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read(50000)  # Read first 50KB
            
            # PII patterns
            pii_patterns = {
                'email': re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'),
                'phone': re.compile(r'\b(?:\+?1[-.\s]?)?\(?[0-9]{3}\)?[-.\s]?[0-9]{3}[-.\s]?[0-9]{4}\b'),
                'ssn': re.compile(r'\b\d{3}-?\d{2}-?\d{4}\b'),
                'credit_card': re.compile(r'\b(?:\d{4}[-\s]?){3}\d{4}\b')
            }
            
            for pii_type, pattern in pii_patterns.items():
                if pattern.search(content):
                    result['pii_found'] = True
                    if pii_type not in result['pii_types']:
                        result['pii_types'].append(pii_type)
                    result['privacy_score'] += 0.2
            
        except Exception as e:
            logger.error(f"Text PII scan error: {e}")


class ComplianceChecker:
    """Compliance validation component."""
    
    async def check(
        self, 
        file_path: str, 
        media_type: MediaType, 
        standards: Set[ComplianceStandard],
        user_context: Optional[Dict[str, Any]]
    ) -> Dict[str, Any]:
        """Check compliance with various standards."""
        result = {
            'compliance_score': 1.0,
            'violations': {},
            'recommendations': []
        }
        
        try:
            for standard in standards:
                violations = await self._check_standard(file_path, media_type, standard, user_context)
                if violations:
                    result['violations'][standard.value] = violations
                    result['compliance_score'] -= 0.2 * len(violations)
            
            result['compliance_score'] = max(0.0, result['compliance_score'])
            
        except Exception as e:
            logger.error(f"Compliance check error: {e}")
            result['error'] = str(e)
        
        return result
    
    async def _check_standard(
        self, 
        file_path: str, 
        media_type: MediaType, 
        standard: ComplianceStandard,
        user_context: Optional[Dict[str, Any]]
    ) -> List[Dict[str, Any]]:
        """Check specific compliance standard."""
        violations = []
        
        if standard == ComplianceStandard.GDPR:
            violations.extend(await self._check_gdpr(file_path, media_type, user_context))
        elif standard == ComplianceStandard.CCPA:
            violations.extend(await self._check_ccpa(file_path, media_type, user_context))
        elif standard == ComplianceStandard.DMCA:
            violations.extend(await self._check_dmca(file_path, media_type, user_context))
        # Add other standards as needed
        
        return violations
    
    async def _check_gdpr(self, file_path: str, media_type: MediaType, user_context: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Check GDPR compliance."""
        violations = []
        
        # Extract metadata to check for personal data
        try:
            metadata_result = await extract_metadata(file_path)
            
            if metadata_result.privacy_report['contains_pii']:
                # Check if user has provided consent
                if not user_context or not user_context.get('gdpr_consent', False):
                    violations.append({
                        'rule': 'Article 6 - Lawful basis for processing',
                        'description': 'Personal data detected without explicit consent',
                        'severity': 'high'
                    })
                
                # Check if data subject rights are respected
                if not user_context or not user_context.get('data_subject_rights_info', False):
                    violations.append({
                        'rule': 'Article 12-14 - Information and access',
                        'description': 'Data subject rights information not provided',
                        'severity': 'medium'
                    })
            
        except Exception as e:
            logger.error(f"GDPR check error: {e}")
        
        return violations
    
    async def _check_ccpa(self, file_path: str, media_type: MediaType, user_context: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Check CCPA compliance."""
        violations = []
        
        # Check if user is California resident and has opt-out rights
        if user_context and user_context.get('california_resident', False):
            if not user_context.get('ccpa_opt_out_available', False):
                violations.append({
                    'rule': 'Right to Opt-Out',
                    'description': 'California resident not provided opt-out option',
                    'severity': 'high'
                })
        
        return violations
    
    async def _check_dmca(self, file_path: str, media_type: MediaType, user_context: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Check DMCA compliance."""
        violations = []
        
        # Check for copyright information
        try:
            metadata_result = await extract_metadata(file_path)
            
            # Look for copyright metadata
            copyright_info = metadata_result.content_metadata.rights_metadata
            
            if not copyright_info or not any('copyright' in key.lower() for key in copyright_info.keys()):
                if media_type in [MediaType.AUDIO, MediaType.VIDEO, MediaType.IMAGE]:
                    violations.append({
                        'rule': 'Copyright Notice',
                        'description': 'No copyright information found in media file',
                        'severity': 'medium'
                    })
            
        except Exception as e:
            logger.error(f"DMCA check error: {e}")
        
        return violations


class MetadataScanner:
    """Metadata security analysis component."""
    
    async def scan(self, file_path: str) -> Dict[str, Any]:
        """Scan metadata for security issues."""
        result = {
            'scan_completed': True,
            'suspicious_metadata': False,
            'suspicious_fields': [],
            'metadata_score': 1.0
        }
        
        try:
            metadata_result = await extract_metadata(file_path)
            
            # Check for suspicious metadata patterns
            all_metadata = {}
            all_metadata.update(metadata_result.content_metadata.technical_metadata)
            all_metadata.update(metadata_result.content_metadata.content_metadata)
            all_metadata.update(metadata_result.content_metadata.creator_metadata)
            all_metadata.update(metadata_result.content_metadata.device_metadata)
            
            suspicious_patterns = [
                r'(?:admin|root|system)',
                r'(?:hack|crack|exploit)',
                r'(?:malware|virus|trojan)',
                r'(?:backdoor|shell|payload)'
            ]
            
            for key, value in all_metadata.items():
                if isinstance(value, dict):
                    value_str = str(value.get('value', ''))
                else:
                    value_str = str(value)
                
                for pattern in suspicious_patterns:
                    if re.search(pattern, value_str, re.IGNORECASE):
                        result['suspicious_metadata'] = True
                        result['suspicious_fields'].append(key)
                        result['metadata_score'] -= 0.1
            
            result['metadata_score'] = max(0.0, result['metadata_score'])
            
        except Exception as e:
            logger.error(f"Metadata scan error: {e}")
            result['scan_completed'] = False
            result['error'] = str(e)
        
        return result


# Utility functions
async def validate_file_security(
    file_path: str, 
    security_level: SecurityLevel = SecurityLevel.MEDIUM,
    user_context: Optional[Dict[str, Any]] = None
) -> SecurityScanResult:
    """Convenience function to validate file security."""
    config = ValidationConfig(security_level=security_level)
    validator = SecurityValidator(config)
    return await validator.validate_file(file_path, user_context)

async def batch_validate_security(
    file_paths: List[str],
    security_level: SecurityLevel = SecurityLevel.MEDIUM
) -> List[SecurityScanResult]:
    """Validate security for multiple files in parallel."""
    config = ValidationConfig(security_level=security_level)
    validator = SecurityValidator(config)
    
    tasks = [validator.validate_file(path) for path in file_paths]
    return await asyncio.gather(*tasks, return_exceptions=True)

def is_file_safe(scan_result: SecurityScanResult) -> bool:
    """Check if file is safe based on scan results."""



    return scan_result.is_safe and scan_result.threat_level in [ThreatLevel.NONE, ThreatLevel.LOW]

def get_security_summary(scan_result: SecurityScanResult) -> Dict[str, Any]:
    """Get security summary for reporting."""



    return {
        'file_path': scan_result.file_path,
        'is_safe': scan_result.is_safe,
        'threat_level': scan_result.threat_level.value,
        'violation_count': len(scan_result.violations),
        'critical_violations': len([v for v in scan_result.violations if v.threat_level == ThreatLevel.CRITICAL]),
        'high_violations': len([v for v in scan_result.violations if v.threat_level == ThreatLevel.HIGH]),
        'scan_duration': scan_result.scan_duration,
        'recommendations_count': len(scan_result.recommendations),
        'required_actions_count': len(scan_result.required_actions)
    }

