@dataclass
class SecurityConfiguration:
    """Main security configuration class."""
    # Component configurations
    authentication: AuthenticationConfiguration = field(default_factory=AuthenticationConfiguration)
    authorization: AuthorizationConfiguration = field(default_factory=AuthorizationConfiguration)
    encryption: EncryptionConfiguration = field(default_factory=EncryptionConfiguration)
    threat_protection: ThreatProtectionConfiguration = field(default_factory=ThreatProtectionConfiguration)
    audit: AuditConfiguration = field(default_factory=AuditConfiguration)
    data_protection: DataProtectionConfiguration = field(default_factory=DataProtectionConfiguration)
    compliance: ComplianceConfiguration = field(default_factory=ComplianceConfiguration)
    
    # Global security settings
    security_level: str = "high"  # low, medium, high, maximum
    enable_security_headers: bool = True
    enable_content_security_policy: bool = True
    enable_cors_protection: bool = True
    
    # Security feature flags
    enable_advanced_threat_protection: bool = True
    enable_zero_trust_architecture: bool = True
    enable_continuous_monitoring: bool = True
    enable_automated_incident_response: bool = True
    
    # Emergency settings
    enable_security_lockdown: bool = True
    lockdown_trigger_threshold: int = 10  # Critical incidents
    emergency_contact_email: str = field(default_factory=lambda: os.getenv("SECURITY_EMERGENCY_EMAIL", ""))
    
    def validate_security_configuration(self) -> List[str]:
        """Validate security configuration settings."""
        errors = []
        
        # Validate authentication
        if not self.authentication.jwt_secret_key:
            errors.append("JWT secret key is required")
        
        if self.authentication.password_min_length < 8:
            errors.append("Password minimum length should be at least 8 characters")
        
        # Validate encryption
        if not self.encryption.encryption_key:
            errors.append("Encryption key is required")
        
        # Validate threat protection
        if self.threat_protection.fraud_detection_threshold < 0 or \
           self.threat_protection.fraud_detection_threshold > 1:
            errors.append("Fraud detection threshold must be between 0 and 1")
        
        # Validate audit settings
        if self.audit.audit_log_retention_days < 1:
            errors.append("Audit log retention must be at least 1 day")
        
        return errors
    
    def get_security_level_config(self) -> Dict[str, Any]:
        """Get security configuration based on security level."""
        configs = {
            "low": {
                "enable_2fa": False,
                "session_timeout_minutes": 480,  # 8 hours
                "enable_advanced_threat_protection": False,
                "audit_log_retention_days": 30
            },
            "medium": {
                "enable_2fa": True,
                "session_timeout_minutes": 240,  # 4 hours
                "enable_advanced_threat_protection": True,
                "audit_log_retention_days": 90
            },
            "high": {
                "enable_2fa": True,
                "require_2fa_for_admins": True,
                "session_timeout_minutes": 120,  # 2 hours
                "enable_advanced_threat_protection": True,
                "audit_log_retention_days": 365
            },
            "maximum": {
                "enable_2fa": True,
                "require_2fa_for_admins": True,
                "session_timeout_minutes": 60,  # 1 hour
                "enable_advanced_threat_protection": True,
                "enable_zero_trust_architecture": True,
                "audit_log_retention_days": 2555  # 7 years
            }
        }
        
        return configs.get(self.security_level, configs["high"])


