"""
External API Integration Hub

Advanced external API integration capabilities with rate limiting,
circuit breakers, and comprehensive monitoring.
"""

import asyncio
import aiohttp
import logging
from typing import Dict, List, Optional, Any
from datetime import datetime
from dataclasses import dataclass
from enum import Enum
import json
import time

logger = logging.getLogger(__name__)

class APIStatus(Enum):
    """API connection status"""
    HEALTHY = "healthy"
    DEGRADED = "degraded"  
    UNHEALTHY = "unhealthy"
    MAINTENANCE = "maintenance"

class AuthType(Enum):
    """Authentication types"""
    API_KEY = "api_key"
    BEARER_TOKEN = "bearer_token"
    BASIC_AUTH = "basic_auth"
    OAUTH2 = "oauth2"

@dataclass
class APICredentials:
    """API credentials configuration"""
    auth_type: AuthType
    api_key: Optional[str] = None
    bearer_token: Optional[str] = None
    username: Optional[str] = None
    password: Optional[str] = None

@dataclass
class APIRequest:
    """API request definition"""
    method: str
    url: str
    headers: Dict[str, str] = None
    params: Dict[str, Any] = None
    data: Optional[Any] = None
    timeout: float = 30.0

@dataclass
class APIResponse:
    """API response wrapper"""
    status_code: int
    headers: Dict[str, str]
    data: Any
    response_time: float
    success: bool
    error_message: Optional[str] = None

class RateLimiter:
    """Token bucket rate limiter"""
    
    def __init__(self, requests_per_second: float = 10.0, burst_capacity: int = 50):
        self.requests_per_second = requests_per_second
        self.tokens = burst_capacity
        self.capacity = burst_capacity
        self.last_refill = time.time()
        self.lock = asyncio.Lock()
        
    async def acquire(self, tokens: int = 1) -> bool:
        """Acquire tokens from rate limiter"""
        async with self.lock:
            now = time.time()
            time_passed = now - self.last_refill
            
            # Refill tokens
            tokens_to_add = time_passed * self.requests_per_second
            self.tokens = min(self.capacity, self.tokens + tokens_to_add)
            self.last_refill = now
            
            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            
            return False
    
    async def wait_for_token(self):
        """Wait until token is available"""
        while not await self.acquire():
            await asyncio.sleep(0.1)

class BaseAPIConnector:
    """Base API connector with common functionality"""
    
    def __init__(self, name: str, base_url: str, credentials: APICredentials):
        self.name = name
        self.base_url = base_url.rstrip('/')
        self.credentials = credentials
        self.session = None
        self.rate_limiter = RateLimiter()
        self.status = APIStatus.HEALTHY
        self.metrics = {
            'total_requests': 0,
            'successful_requests': 0,
            'failed_requests': 0,
            'total_response_time': 0.0
        }
        
    async def initialize(self):
        """Initialize connector"""
        timeout = aiohttp.ClientTimeout(total=60)
        self.session = aiohttp.ClientSession(timeout=timeout)
        
    async def cleanup(self):
        """Cleanup resources"""
        if self.session:
            await self.session.close()
    
    async def make_request(self, request: APIRequest) -> APIResponse:
        """Make API request with rate limiting"""
        await self.rate_limiter.wait_for_token()
        
        # Prepare headers
        headers = self._get_auth_headers()
        if request.headers:
            headers.update(request.headers)
        
        # Build full URL
        url = f"{self.base_url}{request.url}" if not request.url.startswith('http') else request.url
        
        start_time = time.time()
        
        try:
            async with self.session.request(
                method=request.method,
                url=url,
                headers=headers,
                params=request.params,
                json=request.data if isinstance(request.data, dict) else None,
                data=request.data if not isinstance(request.data, dict) else None,
                timeout=aiohttp.ClientTimeout(total=request.timeout)
            ) as response:
                
                response_time = time.time() - start_time
                
                # Read response
                try:
                    if response.content_type == 'application/json':
                        data = await response.json()
                    else:
                        data = await response.text()
                except Exception:
                    data = await response.read()
                
                # Update metrics
                self._update_metrics(response.status, response_time, success=True)
                
                return APIResponse(
                    status_code=response.status,
                    headers=dict(response.headers),
                    data=data,
                    response_time=response_time,
                    success=200 <= response.status < 300
                )
                
        except Exception as e:
            response_time = time.time() - start_time
            self._update_metrics(0, response_time, success=False)
            
            return APIResponse(
                status_code=0,
                headers={},
                data=None,
                response_time=response_time,
                success=False,
                error_message=str(e)
            )
    
    def _get_auth_headers(self) -> Dict[str, str]:
        """Get authentication headers"""
        headers = {}
        
        if self.credentials.auth_type == AuthType.API_KEY:
            headers['X-API-Key'] = self.credentials.api_key
        elif self.credentials.auth_type == AuthType.BEARER_TOKEN:
            headers['Authorization'] = f"Bearer {self.credentials.bearer_token}"
        elif self.credentials.auth_type == AuthType.BASIC_AUTH:
            import base64
            credentials = base64.b64encode(f"{self.credentials.username}:{self.credentials.password}".encode()).decode()
            headers['Authorization'] = f"Basic {credentials}"
        
        return headers
    
    def _update_metrics(self, status_code: int, response_time: float, success: bool):
        """Update connector metrics"""
        self.metrics['total_requests'] += 1
        self.metrics['total_response_time'] += response_time
        
        if success:
            self.metrics['successful_requests'] += 1
        else:
            self.metrics['failed_requests'] += 1
    
    def get_metrics(self) -> Dict[str, Any]:
        """Get connector metrics"""
        total = self.metrics['total_requests']
        if total == 0:
            return self.metrics
        
        return {
            **self.metrics,
            'success_rate': self.metrics['successful_requests'] / total,
            'average_response_time': self.metrics['total_response_time'] / total,
            'status': self.status.value
        }

class SlackConnector(BaseAPIConnector):
    """Slack API connector"""
    
    def __init__(self, token: str):
        credentials = APICredentials(
            auth_type=AuthType.BEARER_TOKEN,
            bearer_token=token
        )
        super().__init__("Slack", "https://slack.com/api", credentials)
        
    async def send_message(self, channel: str, text: str, attachments: Optional[List] = None) -> APIResponse:
        """Send message to Slack channel"""
        data = {
            'channel': channel,
            'text': text
        }
        
        if attachments:
            data['attachments'] = attachments
        
        request = APIRequest(
            method="POST",
            url="/chat.postMessage",
            data=data
        )
        
        return await self.make_request(request)

class WebhookConnector(BaseAPIConnector):
    """Generic webhook connector"""
    
    def __init__(self, webhook_url: str):
        from urllib.parse import urlparse
        parsed = urlparse(webhook_url)
        base_url = f"{parsed.scheme}://{parsed.netloc}"
        
        credentials = APICredentials(auth_type=AuthType.BEARER_TOKEN)  # Placeholder
        super().__init__("Webhook", base_url, credentials)
        self.webhook_path = parsed.path
        
    async def send_webhook(self, data: Dict[str, Any]) -> APIResponse:
        """Send webhook payload"""
        request = APIRequest(
            method="POST",
            url=self.webhook_path,
            data=data
        )
        
        return await self.make_request(request)

class ExternalAPIManager:
    """Manager for external API integrations"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.connectors: Dict[str, BaseAPIConnector] = {}
        
    async def initialize(self):
        """Initialize all connectors"""
        # Initialize Slack if configured
        slack_config = self.config.get('slack')
        if slack_config and slack_config.get('token'):
            slack_connector = SlackConnector(slack_config['token'])
            await slack_connector.initialize()
            self.connectors['slack'] = slack_connector
            
        # Initialize webhooks if configured
        webhooks_config = self.config.get('webhooks', {})
        for name, webhook_config in webhooks_config.items():
            if webhook_config.get('url'):
                webhook_connector = WebhookConnector(webhook_config['url'])
                await webhook_connector.initialize()
                self.connectors[f'webhook_{name}'] = webhook_connector
        
        logger.info(f"Initialized {len(self.connectors)} API connectors")
    
    async def get_connector(self, name: str) -> Optional[BaseAPIConnector]:
        """Get connector by name"""



        return self.connectors.get(name)
    
    async def send_notification(self, connector_name: str, data: Dict[str, Any]) -> APIResponse:
        """Send notification via connector"""
        connector = self.connectors.get(connector_name)
        if not connector:
            raise ValueError(f"Connector {connector_name} not found")
        
        if isinstance(connector, SlackConnector):
            return await connector.send_message(
                channel=data.get('channel'),
                text=data.get('text'),
                attachments=data.get('attachments')
            )
        elif isinstance(connector, WebhookConnector):
            return await connector.send_webhook(data)
        else:
            raise ValueError(f"Unsupported connector type: {type(connector)}")
    
    async def get_all_metrics(self) -> Dict[str, Dict[str, Any]]:
        """Get metrics from all connectors"""



        return {name: connector.get_metrics() for name, connector in self.connectors.items()}
    
    async def cleanup(self):
        """Cleanup all connectors"""
        for connector in self.connectors.values():
            await connector.cleanup()

__all__ = [
    'APIStatus',
    'AuthType',
    'APICredentials',
    'APIRequest',
    'APIResponse',
    'RateLimiter',
    'BaseAPIConnector',
    'SlackConnector',
    'WebhookConnector',
    'ExternalAPIManager'
]

