"""
Advanced Encryption Management System for Spotify AI Agent

This module provides comprehensive encryption capabilities including:
- AES-256-GCM encryption for data at rest
- TLS 1.3 for data in transit
- Key derivation and rotation
- Hardware Security Module (HSM) integration
- Field-level encryption for sensitive data
- Secure key storage and management
"""

import asyncio
import os
import secrets
import hashlib
import logging
from datetime import datetime, timedelta
from typing import Dict, Optional, Any, Union, List, Tuple
from dataclasses import dataclass
from enum import Enum
import base64
import json

from cryptography.fernet import Fernet, MultiFernet
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives.kdf.scrypt import Scrypt
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.backends import default_backend
import redis.asyncio as aioredis
from pydantic import BaseModel

logger = logging.getLogger(__name__)

class EncryptionAlgorithm(Enum):
    """Supported encryption algorithms"""
    AES_256_GCM = "aes_256_gcm"
    AES_256_CBC = "aes_256_cbc"
    CHACHA20_POLY1305 = "chacha20_poly1305"
    RSA_OAEP = "rsa_oaep"
    FERNET = "fernet"

class KeyType(Enum):
    """Types of encryption keys"""
    DATA_ENCRYPTION = "data_encryption"
    KEY_ENCRYPTION = "key_encryption"
    MASTER_KEY = "master_key"
    SESSION_KEY = "session_key"
    API_KEY = "api_key"
    DATABASE_KEY = "database_key"

@dataclass
class EncryptionKey:
    """Encryption key metadata and data"""
    key_id: str
    key_type: KeyType
    algorithm: EncryptionAlgorithm
    key_data: bytes
    created_at: datetime
    expires_at: Optional[datetime]
    version: int
    is_active: bool
    metadata: Dict[str, Any]

class EncryptionRequest(BaseModel):
    """Request for data encryption"""
    data: Union[str, bytes]
    algorithm: EncryptionAlgorithm = EncryptionAlgorithm.AES_256_GCM
    key_id: Optional[str] = None
    context: Dict[str, Any] = {}
    
class DecryptionRequest(BaseModel):
    """Request for data decryption"""
    encrypted_data: str
    key_id: Optional[str] = None
    context: Dict[str, Any] = {}

class EncryptionResult(BaseModel):
    """Result of encryption operation"""
    encrypted_data: str
    key_id: str
    algorithm: str
    nonce: Optional[str] = None
    tag: Optional[str] = None
    metadata: Dict[str, Any] = {}

class EncryptionManager:
    """Advanced encryption management system"""
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.redis_client: Optional[aioredis.Redis] = None
        
        # Encryption settings
        self.default_algorithm = EncryptionAlgorithm(
            config.get("default_algorithm", "aes_256_gcm")
        )
        self.key_rotation_interval = config.get("key_rotation_interval", 86400)  # 24 hours
        self.key_retention_period = config.get("key_retention_period", 86400 * 30)  # 30 days
        self.hsm_enabled = config.get("hsm_enabled", False)
        self.hsm_config = config.get("hsm_config", {})
        
        # Key derivation settings
        self.kdf_iterations = config.get("kdf_iterations", 100000)
        self.salt_length = config.get("salt_length", 32)
        
        # Master key for key encryption
        self.master_key = self._derive_master_key(
            config.get("master_password", "default_master_password"),
            config.get("master_salt", b"spotify_ai_agent_master_salt")
        )
        
        # In-memory key cache
        self._key_cache: Dict[str, EncryptionKey] = {}
        self._cache_ttl = config.get("key_cache_ttl", 300)  # 5 minutes
    
    async def initialize(self):
        """Initialize encryption manager"""



        try:
            # Initialize Redis connection
            redis_url = self.config.get("redis_url", "redis://localhost:6379")
            self.redis_client = aioredis.from_url(redis_url, decode_responses=True)
            await self.redis_client.ping()
            
            # Initialize HSM if enabled
            if self.hsm_enabled:
                await self._initialize_hsm()
            
            # Create default encryption keys
            await self._create_default_keys()
            
            # Start key rotation scheduler
            asyncio.create_task(self._key_rotation_scheduler())
            
            logger.info("Encryption manager initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize encryption manager: {e}")
            raise
    
    def _derive_master_key(self, password: str, salt: bytes) -> bytes:
        """Derive master key from password and salt"""
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=self.kdf_iterations,
            backend=default_backend()
        )
        return kdf.derive(password.encode())
    
    async def _initialize_hsm(self):
        """Initialize Hardware Security Module"""
        # HSM initialization would go here
        # This is a placeholder for HSM integration
        logger.info("HSM integration placeholder - would initialize HSM here")
    
    async def _create_default_keys(self):
        """Create default encryption keys"""



        try:
            # Create data encryption key
            await self.create_key(
                key_type=KeyType.DATA_ENCRYPTION,
                algorithm=EncryptionAlgorithm.AES_256_GCM,
                expires_in_days=30
            )
            
            # Create database encryption key
            await self.create_key(
                key_type=KeyType.DATABASE_KEY,
                algorithm=EncryptionAlgorithm.AES_256_GCM,
                expires_in_days=90
            )
            
            # Create session encryption key
            await self.create_key(
                key_type=KeyType.SESSION_KEY,
                algorithm=EncryptionAlgorithm.FERNET,
                expires_in_days=7
            )
            
            logger.info("Default encryption keys created")
            
        except Exception as e:
            logger.error(f"Failed to create default keys: {e}")
    
    async def create_key(self, key_type: KeyType, algorithm: EncryptionAlgorithm,
                        expires_in_days: Optional[int] = None) -> str:
        """Create a new encryption key"""



        try:
            # Generate key ID
            key_id = self._generate_key_id(key_type, algorithm)
            
            # Generate key data based on algorithm
            key_data = self._generate_key_data(algorithm)
            
            # Set expiration
            expires_at = None
            if expires_in_days:
                expires_at = datetime.utcnow() + timedelta(days=expires_in_days)
            
            # Create key object
            encryption_key = EncryptionKey(
                key_id=key_id,
                key_type=key_type,
                algorithm=algorithm,
                key_data=key_data,
                created_at=datetime.utcnow(),
                expires_at=expires_at,
                version=1,
                is_active=True,
                metadata={"created_by": "system"}
            )
            
            # Store key securely
            await self._store_key(encryption_key)
            
            # Add to cache
            self._key_cache[key_id] = encryption_key
            
            logger.info(f"Created encryption key {key_id} for {key_type.value}")
            return key_id
            
        except Exception as e:
            logger.error(f"Failed to create key: {e}")
            raise
    
    def _generate_key_id(self, key_type: KeyType, algorithm: EncryptionAlgorithm) -> str:
        """Generate unique key ID"""
        timestamp = int(datetime.utcnow().timestamp())
        random_suffix = secrets.token_hex(8)
        return f"{key_type.value}_{algorithm.value}_{timestamp}_{random_suffix}"
    
    def _generate_key_data(self, algorithm: EncryptionAlgorithm) -> bytes:
        """Generate key data for specified algorithm"""
        if algorithm in [EncryptionAlgorithm.AES_256_GCM, EncryptionAlgorithm.AES_256_CBC]:
            return secrets.token_bytes(32)  # 256 bits
        elif algorithm == EncryptionAlgorithm.CHACHA20_POLY1305:
            return secrets.token_bytes(32)  # 256 bits
        elif algorithm == EncryptionAlgorithm.FERNET:
            return Fernet.generate_key()
        elif algorithm == EncryptionAlgorithm.RSA_OAEP:
            # Generate RSA key pair
            private_key = rsa.generate_private_key(
                public_exponent=65537,
                key_size=2048,
                backend=default_backend()
            )
            return private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.PKCS8,
                encryption_algorithm=serialization.NoEncryption()
            )
        else:
            raise ValueError(f"Unsupported algorithm: {algorithm}")
    
    async def _store_key(self, encryption_key: EncryptionKey):
        """Store encryption key securely"""



        try:
            # Encrypt key data with master key
            encrypted_key_data = self._encrypt_with_master_key(encryption_key.key_data)
            
            # Prepare key metadata for storage
            key_metadata = {
                "key_id": encryption_key.key_id,
                "key_type": encryption_key.key_type.value,
                "algorithm": encryption_key.algorithm.value,
                "encrypted_key_data": base64.b64encode(encrypted_key_data).decode(),
                "created_at": encryption_key.created_at.isoformat(),
                "expires_at": encryption_key.expires_at.isoformat() if encryption_key.expires_at else "",
                "version": str(encryption_key.version),
                "is_active": str(encryption_key.is_active),
                "metadata": json.dumps(encryption_key.metadata)
            }
            
            # Store in Redis
            key_storage_key = f"encryption:key:{encryption_key.key_id}"
            await self.redis_client.hset(key_storage_key, mapping=key_metadata)
            
            # Set expiration if specified
            if encryption_key.expires_at:
                ttl = int((encryption_key.expires_at - datetime.utcnow()).total_seconds())
                await self.redis_client.expire(key_storage_key, ttl)
            
            # Add to active keys index
            active_keys_key = f"encryption:active_keys:{encryption_key.key_type.value}"
            await self.redis_client.sadd(active_keys_key, encryption_key.key_id)
            
        except Exception as e:
            logger.error(f"Failed to store key {encryption_key.key_id}: {e}")
            raise
    
    def _encrypt_with_master_key(self, data: bytes) -> bytes:
        """Encrypt data with master key"""
        # Use AES-256-GCM with master key
        iv = secrets.token_bytes(12)  # 96-bit IV for GCM
        cipher = Cipher(
            algorithms.AES(self.master_key),
            modes.GCM(iv),
            backend=default_backend()
        )
        encryptor = cipher.encryptor()
        ciphertext = encryptor.update(data) + encryptor.finalize()
        
        # Return IV + tag + ciphertext
        return iv + encryptor.tag + ciphertext
    
    def _decrypt_with_master_key(self, encrypted_data: bytes) -> bytes:
        """Decrypt data with master key"""
        # Extract IV, tag, and ciphertext
        iv = encrypted_data[:12]
        tag = encrypted_data[12:28]
        ciphertext = encrypted_data[28:]
        
        cipher = Cipher(
            algorithms.AES(self.master_key),
            modes.GCM(iv, tag),
            backend=default_backend()
        )
        decryptor = cipher.decryptor()
        return decryptor.update(ciphertext) + decryptor.finalize()
    
    async def encrypt(self, request: EncryptionRequest) -> EncryptionResult:
        """Encrypt data using specified algorithm and key"""



        try:
            # Get or create encryption key
            if request.key_id:
                encryption_key = await self._get_key(request.key_id)
                if not encryption_key:
                    raise ValueError(f"Key {request.key_id} not found")
            else:
                # Use default key for algorithm
                encryption_key = await self._get_default_key(request.algorithm)
            
            # Validate key is active and not expired
            if not encryption_key.is_active:
                raise ValueError(f"Key {encryption_key.key_id} is not active")
            
            if encryption_key.expires_at and datetime.utcnow() > encryption_key.expires_at:
                raise ValueError(f"Key {encryption_key.key_id} has expired")
            
            # Convert data to bytes if needed
            if isinstance(request.data, str):
                data_bytes = request.data.encode('utf-8')
            else:
                data_bytes = request.data
            
            # Encrypt based on algorithm
            if encryption_key.algorithm == EncryptionAlgorithm.AES_256_GCM:
                result = self._encrypt_aes_gcm(data_bytes, encryption_key.key_data)
            elif encryption_key.algorithm == EncryptionAlgorithm.FERNET:
                result = self._encrypt_fernet(data_bytes, encryption_key.key_data)
            elif encryption_key.algorithm == EncryptionAlgorithm.CHACHA20_POLY1305:
                result = self._encrypt_chacha20_poly1305(data_bytes, encryption_key.key_data)
            else:
                raise ValueError(f"Encryption not implemented for {encryption_key.algorithm}")
            
            return EncryptionResult(
                encrypted_data=result["encrypted_data"],
                key_id=encryption_key.key_id,
                algorithm=encryption_key.algorithm.value,
                nonce=result.get("nonce"),
                tag=result.get("tag"),
                metadata={
                    "timestamp": datetime.utcnow().isoformat(),
                    "context": request.context
                }
            )
            
        except Exception as e:
            logger.error(f"Encryption failed: {e}")
            raise
    
    async def decrypt(self, request: DecryptionRequest) -> str:
        """Decrypt data"""



        try:
            # Parse encrypted data to extract metadata
            encrypted_parts = request.encrypted_data.split(":")
            if len(encrypted_parts) < 3:
                raise ValueError("Invalid encrypted data format")
            
            algorithm = EncryptionAlgorithm(encrypted_parts[0])
            key_id = request.key_id or encrypted_parts[1]
            encrypted_payload = encrypted_parts[2]
            
            # Get decryption key
            encryption_key = await self._get_key(key_id)
            if not encryption_key:
                raise ValueError(f"Decryption key {key_id} not found")
            
            # Decrypt based on algorithm
            if algorithm == EncryptionAlgorithm.AES_256_GCM:
                decrypted_data = self._decrypt_aes_gcm(encrypted_payload, encryption_key.key_data)
            elif algorithm == EncryptionAlgorithm.FERNET:
                decrypted_data = self._decrypt_fernet(encrypted_payload, encryption_key.key_data)
            elif algorithm == EncryptionAlgorithm.CHACHA20_POLY1305:
                decrypted_data = self._decrypt_chacha20_poly1305(encrypted_payload, encryption_key.key_data)
            else:
                raise ValueError(f"Decryption not implemented for {algorithm}")
            
            return decrypted_data.decode('utf-8')
            
        except Exception as e:
            logger.error(f"Decryption failed: {e}")
            raise
    
    def _encrypt_aes_gcm(self, data: bytes, key: bytes) -> Dict[str, str]:
        """Encrypt data using AES-256-GCM"""
        iv = secrets.token_bytes(12)  # 96-bit IV
        cipher = Cipher(algorithms.AES(key), modes.GCM(iv), backend=default_backend())
        encryptor = cipher.encryptor()
        ciphertext = encryptor.update(data) + encryptor.finalize()
        
        # Combine IV + tag + ciphertext and encode
        combined = iv + encryptor.tag + ciphertext
        encrypted_data = base64.b64encode(combined).decode()
        
        return {
            "encrypted_data": f"aes_256_gcm:::{encrypted_data}",
            "nonce": base64.b64encode(iv).decode(),
            "tag": base64.b64encode(encryptor.tag).decode()
        }
    
    def _decrypt_aes_gcm(self, encrypted_data: str, key: bytes) -> bytes:
        """Decrypt data using AES-256-GCM"""
        combined = base64.b64decode(encrypted_data)
        iv = combined[:12]
        tag = combined[12:28]
        ciphertext = combined[28:]
        
        cipher = Cipher(algorithms.AES(key), modes.GCM(iv, tag), backend=default_backend())
        decryptor = cipher.decryptor()
        return decryptor.update(ciphertext) + decryptor.finalize()
    
    def _encrypt_fernet(self, data: bytes, key: bytes) -> Dict[str, str]:
        """Encrypt data using Fernet"""
        f = Fernet(key)
        encrypted = f.encrypt(data)
        return {
            "encrypted_data": f"fernet:::{base64.b64encode(encrypted).decode()}"
        }
    
    def _decrypt_fernet(self, encrypted_data: str, key: bytes) -> bytes:
        """Decrypt data using Fernet"""
        f = Fernet(key)
        encrypted_bytes = base64.b64decode(encrypted_data)
        return f.decrypt(encrypted_bytes)
    
    def _encrypt_chacha20_poly1305(self, data: bytes, key: bytes) -> Dict[str, str]:
        """Encrypt data using ChaCha20-Poly1305"""
        from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305
        
        algorithm = ChaCha20Poly1305(key)
        nonce = secrets.token_bytes(12)
        ciphertext = algorithm.encrypt(nonce, data, None)
        
        # Combine nonce + ciphertext
        combined = nonce + ciphertext
        encrypted_data = base64.b64encode(combined).decode()
        
        return {
            "encrypted_data": f"chacha20_poly1305:::{encrypted_data}",
            "nonce": base64.b64encode(nonce).decode()
        }
    
    def _decrypt_chacha20_poly1305(self, encrypted_data: str, key: bytes) -> bytes:
        """Decrypt data using ChaCha20-Poly1305"""
        from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305
        
        combined = base64.b64decode(encrypted_data)
        nonce = combined[:12]
        ciphertext = combined[12:]
        
        algorithm = ChaCha20Poly1305(key)
        return algorithm.decrypt(nonce, ciphertext, None)
    
    async def _get_key(self, key_id: str) -> Optional[EncryptionKey]:
        """Get encryption key by ID"""
        # Check cache first
        if key_id in self._key_cache:
            return self._key_cache[key_id]
        
        # Load from storage
        key_storage_key = f"encryption:key:{key_id}"
        key_data = await self.redis_client.hgetall(key_storage_key)
        
        if not key_data:
            return None
        
        # Decrypt key data
        encrypted_key_data = base64.b64decode(key_data["encrypted_key_data"])
        decrypted_key_data = self._decrypt_with_master_key(encrypted_key_data)
        
        # Create EncryptionKey object
        encryption_key = EncryptionKey(
            key_id=key_data["key_id"],
            key_type=KeyType(key_data["key_type"]),
            algorithm=EncryptionAlgorithm(key_data["algorithm"]),
            key_data=decrypted_key_data,
            created_at=datetime.fromisoformat(key_data["created_at"]),
            expires_at=datetime.fromisoformat(key_data["expires_at"]) if key_data["expires_at"] else None,
            version=int(key_data["version"]),
            is_active=key_data["is_active"] == "True",
            metadata=json.loads(key_data["metadata"])
        )
        
        # Add to cache
        self._key_cache[key_id] = encryption_key
        
        return encryption_key
    
    async def _get_default_key(self, algorithm: EncryptionAlgorithm) -> EncryptionKey:
        """Get default key for algorithm"""
        # Find active key for algorithm
        if algorithm == EncryptionAlgorithm.AES_256_GCM:
            key_type = KeyType.DATA_ENCRYPTION
        elif algorithm == EncryptionAlgorithm.FERNET:
            key_type = KeyType.SESSION_KEY
        else:
            key_type = KeyType.DATA_ENCRYPTION
        
        active_keys_key = f"encryption:active_keys:{key_type.value}"
        active_keys = await self.redis_client.smembers(active_keys_key)
        
        if not active_keys:
            # Create new key if none exists
            key_id = await self.create_key(key_type, algorithm, expires_in_days=30)
            return await self._get_key(key_id)
        
        # Return first active key (in production, implement proper key selection)
        return await self._get_key(list(active_keys)[0])
    
    async def rotate_key(self, key_id: str) -> str:
        """Rotate an encryption key"""



        try:
            # Get existing key
            old_key = await self._get_key(key_id)
            if not old_key:
                raise ValueError(f"Key {key_id} not found")
            
            # Create new key with same properties
            new_key_id = await self.create_key(
                key_type=old_key.key_type,
                algorithm=old_key.algorithm,
                expires_in_days=30
            )
            
            # Mark old key as inactive
            await self._deactivate_key(key_id)
            
            logger.info(f"Rotated key {key_id} to {new_key_id}")
            return new_key_id
            
        except Exception as e:
            logger.error(f"Key rotation failed for {key_id}: {e}")
            raise
    
    async def _deactivate_key(self, key_id: str):
        """Deactivate an encryption key"""
        key_storage_key = f"encryption:key:{key_id}"
        await self.redis_client.hset(key_storage_key, "is_active", "False")
        
        # Remove from cache
        if key_id in self._key_cache:
            del self._key_cache[key_id]
    
    async def _key_rotation_scheduler(self):
        """Background task for automatic key rotation"""
        while True:
            try:
                await asyncio.sleep(3600)  # Check every hour
                
                # Get all active keys
                all_key_types = [kt.value for kt in KeyType]
                for key_type in all_key_types:
                    active_keys_key = f"encryption:active_keys:{key_type}"
                    active_keys = await self.redis_client.smembers(active_keys_key)
                    
                    for key_id in active_keys:
                        key = await self._get_key(key_id)
                        if key and key.expires_at:
                            # Check if key needs rotation (24 hours before expiry)
                            time_until_expiry = key.expires_at - datetime.utcnow()
                            if time_until_expiry.total_seconds() < 86400:  # 24 hours
                                await self.rotate_key(key_id)
                
            except Exception as e:
                logger.error(f"Key rotation scheduler error: {e}")
                await asyncio.sleep(300)  # Wait 5 minutes before retry
    
    async def get_key_info(self, key_id: str) -> Optional[Dict[str, Any]]:
        """Get information about an encryption key"""
        key = await self._get_key(key_id)
        if not key:
            return None
        
        return {
            "key_id": key.key_id,
            "key_type": key.key_type.value,
            "algorithm": key.algorithm.value,
            "created_at": key.created_at.isoformat(),
            "expires_at": key.expires_at.isoformat() if key.expires_at else None,
            "version": key.version,
            "is_active": key.is_active,
            "metadata": key.metadata
        }
    
    async def list_keys(self, key_type: Optional[KeyType] = None) -> List[Dict[str, Any]]:
        """List all encryption keys"""
        keys = []
        
        if key_type:
            key_types = [key_type.value]
        else:
            key_types = [kt.value for kt in KeyType]
        
        for kt in key_types:
            active_keys_key = f"encryption:active_keys:{kt}"
            active_keys = await self.redis_client.smembers(active_keys_key)
            
            for key_id in active_keys:
                key_info = await self.get_key_info(key_id)
                if key_info:
                    keys.append(key_info)
        
        return keys

