class AdvancedEncryption:
    """
    Advanced encryption service with key rotation and secure key management
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.encryption_algorithm = config.get('algorithm', 'AES-256-GCM')
        self.key_rotation_interval = config.get('key_rotation_hours', 24)
        
        # Initialize encryption keys
        self.master_key = self._load_or_generate_master_key()
        self.current_key = self._derive_encryption_key()
        self.key_history = []
        
        # Key rotation scheduler
        self._start_key_rotation_scheduler()
        
        logger.info(f"AdvancedEncryption initialized with {self.encryption_algorithm}")

    def encrypt(self, data: Union[str, bytes], context: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        """Encrypt data with current key"""



        try:
            if isinstance(data, str):
                data = data.encode('utf-8')
            
            # Generate unique nonce
            nonce = secrets.token_bytes(12)
            
            # Create AEAD cipher
            aesgcm = AESGCM(self.current_key)
            
            # Prepare additional authenticated data
            aad = json.dumps(context or {}, sort_keys=True).encode('utf-8')
            
            # Encrypt data
            ciphertext = aesgcm.encrypt(nonce, data, aad)
            
            # Create encrypted package
            encrypted_package = {
                'ciphertext': base64.b64encode(ciphertext).decode('utf-8'),
                'nonce': base64.b64encode(nonce).decode('utf-8'),
                'aad': base64.b64encode(aad).decode('utf-8'),
                'key_id': self._get_current_key_id(),
                'algorithm': self.encryption_algorithm,
                'timestamp': datetime.now().isoformat()
            }
            
            return encrypted_package
            
        except Exception as e:
            logger.error(f"Encryption failed: {e}")
            raise SecurityException(f"Encryption failed: {str(e)}")

    def decrypt(self, encrypted_package: Dict[str, Any]) -> bytes:
        """Decrypt data using appropriate key"""



        try:
            ciphertext = base64.b64decode(encrypted_package['ciphertext'])
            nonce = base64.b64decode(encrypted_package['nonce'])
            aad = base64.b64decode(encrypted_package['aad'])
            key_id = encrypted_package['key_id']
            
            # Get appropriate decryption key
            decryption_key = self._get_key_by_id(key_id)
            
            if not decryption_key:
                raise SecurityException(f"Decryption key not found: {key_id}")
            
            # Decrypt data
            aesgcm = AESGCM(decryption_key)
            plaintext = aesgcm.decrypt(nonce, ciphertext, aad)
            
            return plaintext
            
        except Exception as e:
            logger.error(f"Decryption failed: {e}")
            raise SecurityException(f"Decryption failed: {str(e)}")

    def encrypt_file(self, file_path: Path, output_path: Optional[Path] = None) -> Path:
        """Encrypt file and save to output path"""



        try:
            with open(file_path, 'rb') as f:
                file_data = f.read()
            
            # Encrypt file data
            encrypted_package = self.encrypt(file_data, {'file_path': str(file_path)})
            
            # Determine output path
            if output_path is None:
                output_path = file_path.with_suffix(file_path.suffix + '.encrypted')
            
            # Save encrypted file
            with open(output_path, 'w') as f:
                json.dump(encrypted_package, f, indent=2)
            
            logger.info(f"File encrypted: {file_path} -> {output_path}")
            return output_path
            
        except Exception as e:
            logger.error(f"File encryption failed: {e}")
            raise SecurityException(f"File encryption failed: {str(e)}")

    def rotate_keys(self) -> str:
        """Rotate encryption keys"""



        try:
            # Store current key in history
            self.key_history.append({
                'key_id': self._get_current_key_id(),
                'key': self.current_key,
                'created_at': datetime.now(),
                'status': 'archived'
            })
            
            # Generate new key
            self.current_key = self._derive_encryption_key()
            
            new_key_id = self._get_current_key_id()
            logger.info(f"Encryption key rotated: {new_key_id}")
            
            return new_key_id
            
        except Exception as e:
            logger.error(f"Key rotation failed: {e}")
            raise SecurityException(f"Key rotation failed: {str(e)}")

    def _load_or_generate_master_key(self) -> bytes:
        """Load or generate master encryption key"""
        key_file = Path(self.config.get('master_key_file', 'master.key'))
        
        if key_file.exists():
            with open(key_file, 'rb') as f:
                return f.read()
        else:
            # Generate new master key
            master_key = secrets.token_bytes(32)
            
            # Save master key securely
            key_file.parent.mkdir(parents=True, exist_ok=True)
            with open(key_file, 'wb') as f:
                f.write(master_key)
            
            # Set secure permissions
            key_file.chmod(0o600)
            
            logger.info("New master key generated")
            return master_key

    def _derive_encryption_key(self) -> bytes:
        """Derive encryption key from master key"""
        salt = secrets.token_bytes(16)
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        return kdf.derive(self.master_key)

    def _get_current_key_id(self) -> str:
        """Get current key identifier"""
        key_hash = hashlib.sha256(self.current_key).digest()
        return base64.b64encode(key_hash[:16]).decode('utf-8')

    def _get_key_by_id(self, key_id: str) -> Optional[bytes]:
        """Get encryption key by ID"""
        # Check current key
        if self._get_current_key_id() == key_id:
            return self.current_key
        
        # Check key history
        for key_info in self.key_history:
            if key_info['key_id'] == key_id:
                return key_info['key']
        
        return None

    def _start_key_rotation_scheduler(self):
        """Start automatic key rotation scheduler"""
        def rotate_keys_periodic():
            while True:
                time.sleep(self.key_rotation_interval * 3600)  # Convert hours to seconds
                try:
                    self.rotate_keys()
                except Exception as e:
                    logger.error(f"Automatic key rotation failed: {e}")
        
        import threading
        rotation_thread = threading.Thread(target=rotate_keys_periodic, daemon=True)
        rotation_thread.start()


class ThreatDetector:
    """
    Advanced threat detection and prevention system
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.redis_client = redis.Redis.from_url(config.get('redis_url', 'redis://localhost:6379'))
        
        # Threat detection rules
        self.max_login_attempts = config.get('max_login_attempts', 5)
        self.login_window_minutes = config.get('login_window_minutes', 15)
        self.max_requests_per_minute = config.get('max_requests_per_minute', 100)
        self.suspicious_patterns = config.get('suspicious_patterns', [])
        
        # Known threat indicators
        self.threat_ips = set()
        self.threat_user_agents = set()
        self.honeypot_endpoints = set()
        
        logger.info("ThreatDetector initialized")

    async def analyze_request(self, request_data: Dict[str, Any]) -> Tuple[ThreatLevel, List[str]]:
        """Analyze request for threats"""
        threat_indicators = []
        threat_score = 0.0
        
        ip_address = request_data.get('ip_address')
        user_agent = request_data.get('user_agent', '')
        endpoint = request_data.get('endpoint', '')
        user_id = request_data.get('user_id')
        
        # Check IP reputation
        if await self._is_malicious_ip(ip_address):
            threat_indicators.append("Known malicious IP")
            threat_score += 0.8
        
        # Check rate limiting
        if await self._check_rate_limit_exceeded(ip_address):
            threat_indicators.append("Rate limit exceeded")
            threat_score += 0.6
        
        # Check login attempts
        if user_id and await self._check_excessive_login_attempts(user_id, ip_address):
            threat_indicators.append("Excessive login attempts")
            threat_score += 0.7
        
        # Check user agent patterns
        if self._is_suspicious_user_agent(user_agent):
            threat_indicators.append("Suspicious user agent")
            threat_score += 0.4
        
        # Check for honeypot access
        if endpoint in self.honeypot_endpoints:
            threat_indicators.append("Honeypot endpoint accessed")
            threat_score += 0.9
        
        # Check for SQL injection patterns
        if self._detect_sql_injection(request_data):
            threat_indicators.append("SQL injection attempt")
            threat_score += 0.9
        
        # Check for XSS patterns
        if self._detect_xss(request_data):
            threat_indicators.append("XSS attempt")
            threat_score += 0.8
        
        # Determine threat level
        if threat_score >= 0.9:
            threat_level = ThreatLevel.CRITICAL
        elif threat_score >= 0.7:
            threat_level = ThreatLevel.HIGH
        elif threat_score >= 0.4:
            threat_level = ThreatLevel.MEDIUM
        elif threat_score > 0:
            threat_level = ThreatLevel.LOW
        else:
            threat_level = ThreatLevel.NONE
        
        return threat_level, threat_indicators

    async def block_threat(self, ip_address: str, duration_minutes: int = 60, reason: str = "Security threat detected"):
        """Block IP address for specified duration"""



        try:
            block_key = f"blocked_ip:{ip_address}"
            block_data = {
                'blocked_at': datetime.now().isoformat(),
                'duration_minutes': duration_minutes,
                'reason': reason
            }
            
            await self.redis_client.setex(
                block_key,
                duration_minutes * 60,
                json.dumps(block_data)
            )
            
            logger.warning(f"IP blocked: {ip_address} for {duration_minutes} minutes - {reason}")
            
        except Exception as e:
            logger.error(f"Failed to block IP {ip_address}: {e}")

    async def is_ip_blocked(self, ip_address: str) -> bool:
        """Check if IP address is blocked"""



        try:
            block_key = f"blocked_ip:{ip_address}"
            blocked_data = await self.redis_client.get(block_key)
            return blocked_data is not None
            
        except Exception as e:
            logger.error(f"Failed to check IP block status: {e}")
            return False

    async def _is_malicious_ip(self, ip_address: str) -> bool:
        """Check if IP is in threat database"""



        return ip_address in self.threat_ips

    async def _check_rate_limit_exceeded(self, ip_address: str) -> bool:
        """Check if IP has exceeded rate limit"""



        try:
            key = f"rate_limit:{ip_address}"
            current_requests = await self.redis_client.get(key)
            
            if current_requests is None:
                await self.redis_client.setex(key, 60, 1)
                return False
            
            return int(current_requests) > self.max_requests_per_minute
            
        except Exception as e:
            logger.error(f"Rate limit check failed: {e}")
            return False

    async def _check_excessive_login_attempts(self, user_id: str, ip_address: str) -> bool:
        """Check for excessive login attempts"""



        try:
            key = f"login_attempts:{user_id}:{ip_address}"
            attempts = await self.redis_client.get(key)
            
            if attempts is None:
                return False
            
            return int(attempts) > self.max_login_attempts
            
        except Exception as e:
            logger.error(f"Login attempt check failed: {e}")
            return False

    def _is_suspicious_user_agent(self, user_agent: str) -> bool:
        """Check for suspicious user agent patterns"""
        suspicious_patterns = [
            r'bot', r'crawler', r'spider', r'scraper',
            r'curl', r'wget', r'python-requests',
            r'sqlmap', r'nmap', r'nikto'
        ]
        
        user_agent_lower = user_agent.lower()
        return any(re.search(pattern, user_agent_lower) for pattern in suspicious_patterns)

    def _detect_sql_injection(self, request_data: Dict[str, Any]) -> bool:
        """Detect SQL injection attempts"""
        sql_patterns = [
            r"(\b(select|insert|update|delete|drop|union|alter)\b)",
            r"(\b(or|and)\s+\w+\s*=\s*\w+)",
            r"(-{2}|#|\*\/|\*)",
            r"(\b(exec|execute|sp_|xp_)\w*)",
            r"(\b(union\s+select|union\s+all\s+select)\b)"
        ]
        
        # Check all string values in request
        for value in self._extract_string_values(request_data):
            value_lower = value.lower()
            if any(re.search(pattern, value_lower, re.IGNORECASE) for pattern in sql_patterns):
                return True
        
        return False

    def _detect_xss(self, request_data: Dict[str, Any]) -> bool:
        """Detect XSS attempts"""
        xss_patterns = [
            r"<script[^>]*>.*?</script>",
            r"javascript:",
            r"on\w+\s*=",
            r"<iframe[^>]*>",
            r"eval\s*\(",
            r"document\.cookie",
            r"window\.location"
        ]
        
        # Check all string values in request
        for value in self._extract_string_values(request_data):
            if any(re.search(pattern, value, re.IGNORECASE) for pattern in xss_patterns):
                return True
        
        return False

    def _extract_string_values(self, data: Any) -> List[str]:
        """Extract all string values from nested data structure"""
        string_values = []
        
        if isinstance(data, str):
            string_values.append(data)
        elif isinstance(data, dict):
            for value in data.values():
                string_values.extend(self._extract_string_values(value))
        elif isinstance(data, list):
            for item in data:
                string_values.extend(self._extract_string_values(item))
        
        return string_values


class AuditLogger:
    """
    Comprehensive audit logging system for compliance and security monitoring
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.log_file = Path(config.get('audit_log_file', 'audit.log'))
        self.retention_days = config.get('retention_days', 365)
        self.compliance_standards = config.get('compliance_standards', ['SOC2', 'GDPR', 'HIPAA'])
        
        # Initialize audit log file
        self.log_file.parent.mkdir(parents=True, exist_ok=True)
        
        # Configure audit logger
        self.audit_logger = logging.getLogger('audit')
        self.audit_logger.setLevel(logging.INFO)
        
        # File handler for audit logs
        file_handler = logging.FileHandler(self.log_file)
        file_handler.setFormatter(logging.Formatter(
            '%(asctime)s - %(levelname)s - %(message)s'
        ))
        self.audit_logger.addHandler(file_handler)
        
        logger.info(f"AuditLogger initialized with {len(self.compliance_standards)} compliance standards")

    async def log_event(self, event: AuditEvent):
        """Log audit event"""



        try:
            # Create structured log entry
            log_entry = {
                'audit_id': secrets.token_hex(16),
                'compliance_level': self._determine_compliance_level(event),
                **event.to_dict()
            }
            
            # Log to file
            self.audit_logger.info(json.dumps(log_entry))
            
            # Store in database for compliance reporting
            await self._store_audit_event(log_entry)
            
            # Check for security alerts
            await self._check_security_alerts(event)
            
        except Exception as e:
            logger.error(f"Audit logging failed: {e}")

    async def log_authentication(self, user_id: str, tenant_id: str, 
                               ip_address: str, success: bool, method: str = "password"):
        """Log authentication event"""
        event = AuditEvent(
            timestamp=datetime.now(),
            event_type=AuditEventType.LOGIN if success else AuditEventType.AUTHENTICATION_FAILURE,
            user_id=user_id,
            tenant_id=tenant_id,
            ip_address=ip_address,
            user_agent="",
            resource="authentication",
            action=f"{method}_authentication",
            result="success" if success else "failure",
            threat_level=ThreatLevel.NONE if success else ThreatLevel.MEDIUM,
            metadata={'authentication_method': method}
        )
        
        await self.log_event(event)

    async def log_data_access(self, user_id: str, tenant_id: str, 
                            resource: str, action: str, ip_address: str):
        """Log data access event"""
        event = AuditEvent(
            timestamp=datetime.now(),
            event_type=AuditEventType.DATA_ACCESS,
            user_id=user_id,
            tenant_id=tenant_id,
            ip_address=ip_address,
            user_agent="",
            resource=resource,
            action=action,
            result="success",
            threat_level=ThreatLevel.NONE,
            metadata={'data_classification': self._classify_data(resource)}
        )
        
        await self.log_event(event)

    async def generate_compliance_report(self, start_date: datetime, 
                                       end_date: datetime, 
                                       standard: str = "SOC2") -> Dict[str, Any]:
        """Generate compliance report for specified period"""



        try:
            # Query audit events for period
            events = await self._query_audit_events(start_date, end_date)
            
            # Generate compliance metrics
            report = {
                'period': {
                    'start': start_date.isoformat(),
                    'end': end_date.isoformat()
                },
                'compliance_standard': standard,
                'total_events': len(events),
                'event_breakdown': self._analyze_events(events),
                'security_incidents': self._count_security_incidents(events),
                'authentication_metrics': self._analyze_authentication(events),
                'data_access_patterns': self._analyze_data_access(events),
                'compliance_score': self._calculate_compliance_score(events, standard)
            }
            
            return report
            
        except Exception as e:
            logger.error(f"Compliance report generation failed: {e}")
            raise

    def _determine_compliance_level(self, event: AuditEvent) -> str:
        """Determine compliance level for event"""
        if event.threat_level in [ThreatLevel.HIGH, ThreatLevel.CRITICAL]:
            return "HIGH"
        elif event.event_type in [AuditEventType.DATA_ACCESS, AuditEventType.DATA_MODIFICATION]:
            return "MEDIUM"
        else:
            return "LOW"

    async def _store_audit_event(self, log_entry: Dict[str, Any]):
        """Store audit event in database for compliance reporting"""
        # Implementation would store in database
        pass

    async def _check_security_alerts(self, event: AuditEvent):
        """Check if event triggers security alerts"""
        if event.threat_level in [ThreatLevel.HIGH, ThreatLevel.CRITICAL]:
            # Trigger security alert
            logger.critical(f"Security alert: {event.event_type.value} - {event.threat_level.value}")

    def _classify_data(self, resource: str) -> str:
        """Classify data sensitivity level"""
        sensitive_resources = ['user_data', 'payment_info', 'personal_info']
        if any(sensitive in resource.lower() for sensitive in sensitive_resources):
            return "SENSITIVE"
        return "STANDARD"

    async def _query_audit_events(self, start_date: datetime, end_date: datetime) -> List[Dict[str, Any]]:
        """Query audit events for date range"""
        # Implementation would query database
        return []

    def _analyze_events(self, events: List[Dict[str, Any]]) -> Dict[str, int]:
        """Analyze event distribution"""
        breakdown = {}
        for event in events:
            event_type = event.get('event_type', 'unknown')
            breakdown[event_type] = breakdown.get(event_type, 0) + 1
        return breakdown

    def _count_security_incidents(self, events: List[Dict[str, Any]]) -> int:
        """Count security incidents"""



        return sum(1 for event in events if event.get('threat_level') in ['high', 'critical'])

    def _analyze_authentication(self, events: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze authentication patterns"""
        auth_events = [e for e in events if e.get('event_type') in ['login', 'authentication_failure']]
        
        return {
            'total_attempts': len(auth_events),
            'successful_logins': len([e for e in auth_events if e.get('result') == 'success']),
            'failed_attempts': len([e for e in auth_events if e.get('result') == 'failure'])
        }

    def _analyze_data_access(self, events: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyze data access patterns"""
        data_events = [e for e in events if e.get('event_type') == 'data_access']
        
        return {
            'total_accesses': len(data_events),
            'unique_users': len(set(e.get('user_id') for e in data_events)),
            'sensitive_data_accesses': len([e for e in data_events 
                                          if e.get('metadata', {}).get('data_classification') == 'SENSITIVE'])
        }

    def _calculate_compliance_score(self, events: List[Dict[str, Any]], standard: str) -> float:
        """Calculate compliance score based on events"""
        if not events:
            return 100.0
        
        # Calculate score based on security incidents and compliance violations
        security_incidents = self._count_security_incidents(events)
        total_events = len(events)
        
        incident_ratio = security_incidents / total_events
        compliance_score = max(0.0, 100.0 - (incident_ratio * 100))
        
        return round(compliance_score, 2)


class TokenManager:
    """
    Advanced JWT and OAuth2 token management system
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.secret_key = config.get('secret_key', secrets.token_urlsafe(32))
        self.algorithm = config.get('algorithm', 'HS256')
        self.access_token_expire_minutes = config.get('access_token_expire_minutes', 15)
        self.refresh_token_expire_days = config.get('refresh_token_expire_days', 30)
        
        # Token blacklist for invalidated tokens
        self.redis_client = redis.Redis.from_url(config.get('redis_url', 'redis://localhost:6379'))
        
        logger.info("TokenManager initialized")

    def create_access_token(self, subject: str, claims: Dict[str, Any] = None) -> str:
        """Create JWT access token"""



        try:
            now = datetime.utcnow()
            expire = now + timedelta(minutes=self.access_token_expire_minutes)
            
            payload = {
                'sub': subject,
                'iat': now,
                'exp': expire,
                'type': 'access',
                'jti': secrets.token_hex(16)  # Unique token ID
            }
            
            if claims:
                payload.update(claims)
            
            token = jwt.encode(payload, self.secret_key, algorithm=self.algorithm)
            return token
            
        except Exception as e:
            logger.error(f"Access token creation failed: {e}")
            raise SecurityException(f"Token creation failed: {str(e)}")

    def create_refresh_token(self, subject: str) -> str:
        """Create JWT refresh token"""



        try:
            now = datetime.utcnow()
            expire = now + timedelta(days=self.refresh_token_expire_days)
            
            payload = {
                'sub': subject,
                'iat': now,
                'exp': expire,
                'type': 'refresh',
                'jti': secrets.token_hex(16)
            }
            
            token = jwt.encode(payload, self.secret_key, algorithm=self.algorithm)
            return token
            
        except Exception as e:
            logger.error(f"Refresh token creation failed: {e}")
            raise SecurityException(f"Token creation failed: {str(e)}")

    def verify_token(self, token: str) -> Dict[str, Any]:
        """Verify and decode JWT token"""



        try:
            # Check if token is blacklisted
            if self._is_token_blacklisted(token):
                raise SecurityException("Token has been revoked")
            
            # Decode and verify token
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm])
            
            # Additional validation
            if payload.get('type') not in ['access', 'refresh']:
                raise SecurityException("Invalid token type")
            
            return payload
            
        except jwt.ExpiredSignatureError:
            raise SecurityException("Token has expired")
        except jwt.InvalidTokenError as e:
            raise SecurityException(f"Invalid token: {str(e)}")

    def revoke_token(self, token: str):
        """Revoke token by adding to blacklist"""



        try:
            # Decode token to get expiration
            payload = jwt.decode(token, self.secret_key, algorithms=[self.algorithm], options={"verify_exp": False})
            
            # Calculate TTL for blacklist entry
            exp_timestamp = payload.get('exp')
            if exp_timestamp:
                ttl = max(0, exp_timestamp - int(datetime.utcnow().timestamp()))
                
                # Add to blacklist with TTL
                blacklist_key = f"blacklisted_token:{payload.get('jti')}"
                self.redis_client.setex(blacklist_key, ttl, "revoked")
                
                logger.info(f"Token revoked: {payload.get('jti')}")
            
        except Exception as e:
            logger.error(f"Token revocation failed: {e}")

    def refresh_access_token(self, refresh_token: str) -> Tuple[str, str]:
        """Refresh access token using refresh token"""



        try:
            # Verify refresh token
            payload = self.verify_token(refresh_token)
            
            if payload.get('type') != 'refresh':
                raise SecurityException("Invalid token type for refresh")
            
            subject = payload.get('sub')
            
            # Create new access token
            new_access_token = self.create_access_token(subject)
            
            # Optionally create new refresh token for rotation
            new_refresh_token = self.create_refresh_token(subject)
            
            # Revoke old refresh token
            self.revoke_token(refresh_token)
            
            return new_access_token, new_refresh_token
            
        except Exception as e:
            logger.error(f"Token refresh failed: {e}")
            raise SecurityException(f"Token refresh failed: {str(e)}")

    def _is_token_blacklisted(self, token: str) -> bool:
        """Check if token is in blacklist"""



        try:
            # Decode token to get JTI without verification
            payload = jwt.decode(token, options={"verify_signature": False})
            jti = payload.get('jti')
            
            if jti:
                blacklist_key = f"blacklisted_token:{jti}"
                return self.redis_client.exists(blacklist_key)
            
            return False
            
        except Exception:
            return False


class PasswordManager:
    """
    Secure password hashing and validation
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
        self.min_length = config.get('min_length', 12)
        self.require_uppercase = config.get('require_uppercase', True)
        self.require_lowercase = config.get('require_lowercase', True)
        self.require_digits = config.get('require_digits', True)
        self.require_symbols = config.get('require_symbols', True)
        
        logger.info("PasswordManager initialized")

    def hash_password(self, password: str) -> str:
        """Hash password securely"""
        if not self.validate_password_strength(password):
            raise SecurityException("Password does not meet security requirements")
        
        return self.pwd_context.hash(password)

    def verify_password(self, plain_password: str, hashed_password: str) -> bool:
        """Verify password against hash"""



        return self.pwd_context.verify(plain_password, hashed_password)

    def validate_password_strength(self, password: str) -> bool:
        """Validate password strength"""
        if len(password) < self.min_length:
            return False
        
        if self.require_uppercase and not re.search(r'[A-Z]', password):
            return False
        
        if self.require_lowercase and not re.search(r'[a-z]', password):
            return False
        
        if self.require_digits and not re.search(r'\d', password):
            return False
        
        if self.require_symbols and not re.search(r'[!@#$%^&*(),.?":{}|<>]', password):
            return False
        
        return True

    def generate_secure_password(self, length: int = 16) -> str:
        """Generate cryptographically secure password"""
        import string
        
        # Ensure we have characters from each required category
        password_chars = []
        
        if self.require_uppercase:
            password_chars.extend(secrets.choice(string.ascii_uppercase) for _ in range(2))
        
        if self.require_lowercase:
            password_chars.extend(secrets.choice(string.ascii_lowercase) for _ in range(2))
        
        if self.require_digits:
            password_chars.extend(secrets.choice(string.digits) for _ in range(2))
        
        if self.require_symbols:
            symbols = "!@#$%^&*(),.?\":{}|<>"
            password_chars.extend(secrets.choice(symbols) for _ in range(2))
        
        # Fill remaining length with random characters
        all_chars = string.ascii_letters + string.digits + "!@#$%^&*(),.?\":{}|<>"
        remaining_length = length - len(password_chars)
        password_chars.extend(secrets.choice(all_chars) for _ in range(remaining_length))
        
        # Shuffle the password characters
        secrets.SystemRandom().shuffle(password_chars)
        
        return ''.join(password_chars)


class MFAManager:
    """
    Multi-Factor Authentication manager
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.issuer_name = config.get('issuer_name', 'Spotify AI Agent')
        
        logger.info("MFAManager initialized")

    def generate_totp_secret(self, user_id: str) -> str:
        """Generate TOTP secret for user"""



        return pyotp.random_base32()

    def generate_qr_code(self, user_email: str, secret: str) -> bytes:
        """Generate QR code for TOTP setup"""
        totp_uri = pyotp.totp.TOTP(secret).provisioning_uri(
            name=user_email,
            issuer_name=self.issuer_name
        )
        
        qr = qrcode.QRCode(version=1, box_size=10, border=5)
        qr.add_data(totp_uri)
        qr.make(fit=True)
        
        img = qr.make_image(fill_color="black", back_color="white")
        
        import io
        img_buffer = io.BytesIO()
        img.save(img_buffer, format='PNG')
        
        return img_buffer.getvalue()

    def verify_totp_code(self, secret: str, code: str, window: int = 1) -> bool:
        """Verify TOTP code"""
        totp = pyotp.TOTP(secret)
        return totp.verify(code, valid_window=window)

    def generate_backup_codes(self, count: int = 10) -> List[str]:
        """Generate backup codes for MFA"""



        return [secrets.token_hex(4).upper() for _ in range(count)]


class SecurityException(Exception):
    """Custom security exception"""
    pass


# Utility functions for easy access
def encrypt_data(data: Union[str, bytes], encryption_key: str) -> str:
    """Quick encryption utility"""
    f = Fernet(encryption_key.encode())
    if isinstance(data, str):
        data = data.encode()
    return f.encrypt(data).decode()


def decrypt_data(encrypted_data: str, encryption_key: str) -> str:
    """Quick decryption utility"""
    f = Fernet(encryption_key.encode())
    return f.decrypt(encrypted_data.encode()).decode()


def generate_secure_token(length: int = 32) -> str:
    """Generate secure random token"""



    return secrets.token_urlsafe(length)


def hash_string(data: str, algorithm: str = 'sha256') -> str:
    """Hash string with specified algorithm"""
    hash_func = getattr(hashlib, algorithm)
    return hash_func(data.encode()).hexdigest()


def verify_hash(data: str, hash_value: str, algorithm: str = 'sha256') -> bool:
    """Verify string against hash"""



    return hash_string(data, algorithm) == hash_value

