class RateLimiter:
    """
    Advanced rate limiter with token bucket algorithm
    and burst handling capabilities.
    """
    
    def __init__(self, rate: float, burst: int = None):
        self.rate = rate  # requests per second
        self.burst = burst or int(rate * 2)  # burst capacity
        self.tokens = self.burst
        self.last_update = time.time()
        self.lock = asyncio.Lock()
    
    async def acquire(self) -> bool:
        """Acquire a token for making a request."""
        async with self.lock:
            now = time.time()
            
            # Add tokens based on elapsed time
            elapsed = now - self.last_update
            tokens_to_add = elapsed * self.rate
            self.tokens = min(self.burst, self.tokens + tokens_to_add)
            self.last_update = now
            
            # Check if we have tokens available
            if self.tokens >= 1:
                self.tokens -= 1
                return True
            
            return False
    
    async def wait_for_token(self) -> None:
        """Wait until a token is available."""
        while not await self.acquire():
            await asyncio.sleep(0.1)


class CircuitBreaker:
    """
    Circuit breaker pattern implementation for API resilience.
    """
    
    def __init__(self, failure_threshold: int = 5, timeout: float = 60.0):
        self.failure_threshold = failure_threshold
        self.timeout = timeout
        self.failure_count = 0
        self.last_failure_time = None
        self.state = "closed"  # closed, open, half-open
        self.lock = asyncio.Lock()
    
    async def call(self, func: Callable, *args, **kwargs):
        """Execute function with circuit breaker protection."""
        async with self.lock:
            if self.state == "open":
                if time.time() - self.last_failure_time < self.timeout:
                    raise Exception("Circuit breaker is open")
                else:
                    self.state = "half-open"
            
            try:
                result = await func(*args, **kwargs)
                
                # Success - reset circuit breaker
                if self.state == "half-open":
                    self.state = "closed"
                self.failure_count = 0
                
                return result
                
            except Exception as e:
                self.failure_count += 1
                self.last_failure_time = time.time()
                
                if self.failure_count >= self.failure_threshold:
                    self.state = "open"
                
                raise e


class APICache:
    """
    Advanced caching system for API responses with TTL and LRU eviction.
    """
    
    def __init__(self, max_size: int = 1000):
        self.max_size = max_size
        self.cache = {}
        self.access_times = {}
        self.lock = asyncio.Lock()
    
    async def get(self, key: str) -> Optional[APIResponse]:
        """Get cached response."""
        async with self.lock:
            if key in self.cache:
                response, expires_at = self.cache[key]
                
                if time.time() < expires_at:
                    self.access_times[key] = time.time()
                    response.cached = True
                    return response
                else:
                    # Expired, remove from cache
                    del self.cache[key]
                    del self.access_times[key]
            
            return None
    
    async def set(self, key: str, response: APIResponse, ttl: int) -> None:
        """Cache response with TTL."""
        async with self.lock:
            # Remove oldest entries if cache is full
            if len(self.cache) >= self.max_size:
                oldest_key = min(self.access_times.keys(), key=self.access_times.get)
                del self.cache[oldest_key]
                del self.access_times[oldest_key]
            
            expires_at = time.time() + ttl
            self.cache[key] = (response, expires_at)
            self.access_times[key] = time.time()
    
    async def clear(self) -> None:
        """Clear all cached responses."""
        async with self.lock:
            self.cache.clear()
            self.access_times.clear()


class ExternalAPIClient:
    """
    Ultra-sophisticated external API client with authentication,
    rate limiting, caching, circuit breaking, and comprehensive error handling.
    """
    
    def __init__(
        self,
        base_url: str,
        credentials: APICredentials,
        default_timeout: float = 30.0,
        max_retries: int = 3,
        cache_size: int = 1000
    ):
        self.base_url = base_url.rstrip('/')
        self.credentials = credentials
        self.default_timeout = default_timeout
        self.max_retries = max_retries
        
        # Initialize components
        self.session: Optional[aiohttp.ClientSession] = None
        self.rate_limiters: Dict[str, RateLimiter] = {}
        self.circuit_breakers: Dict[str, CircuitBreaker] = {}
        self.cache = APICache(max_size=cache_size)
        self.endpoints: Dict[str, APIEndpoint] = {}
        
        # Metrics
        self.request_count = 0
        self.error_count = 0
        self.cache_hit_count = 0
        self.last_request_time = None
    
    async def initialize(self) -> None:
        """Initialize the API client."""



        try:
            logger.info("Initializing ExternalAPIClient")
            
            # Create aiohttp session with default config
            timeout = aiohttp.ClientTimeout(total=self.default_timeout)
            connector = aiohttp.TCPConnector(
                limit=100,
                limit_per_host=10,
                ttl_dns_cache=300,
                use_dns_cache=True
            )
            
            self.session = aiohttp.ClientSession(
                timeout=timeout,
                connector=connector,
                headers={"User-Agent": "Analytics-Engine/1.0"}
            )
            
            # Refresh credentials if needed
            await self._refresh_credentials()
            
            logger.info("ExternalAPIClient initialized successfully")
            
        except Exception as e:
            logger.error(f"Failed to initialize ExternalAPIClient: {e}")
            raise
    
    async def close(self) -> None:
        """Close the API client and cleanup resources."""
        if self.session:
            await self.session.close()
    
    def register_endpoint(self, endpoint: APIEndpoint) -> None:
        """Register an API endpoint."""
        self.endpoints[endpoint.name] = endpoint
        
        # Initialize rate limiter if needed
        if endpoint.rate_limit:
            self.rate_limiters[endpoint.name] = RateLimiter(endpoint.rate_limit)
        
        # Initialize circuit breaker
        self.circuit_breakers[endpoint.name] = CircuitBreaker()
    
    async def request(
        self,
        endpoint_name: str,
        **kwargs
    ) -> APIResponse:
        """Make an API request to a registered endpoint."""
        if endpoint_name not in self.endpoints:
            raise ValueError(f"Unknown endpoint: {endpoint_name}")
        
        endpoint = self.endpoints[endpoint_name]
        request = APIRequest(endpoint=endpoint, **kwargs)
        
        return await self._execute_request(request)
    
    async def get(self, endpoint_name: str, **kwargs) -> APIResponse:
        """Make a GET request."""



        return await self.request(endpoint_name, **kwargs)
    
    async def post(self, endpoint_name: str, **kwargs) -> APIResponse:
        """Make a POST request."""



        return await self.request(endpoint_name, **kwargs)
    
    async def put(self, endpoint_name: str, **kwargs) -> APIResponse:
        """Make a PUT request."""



        return await self.request(endpoint_name, **kwargs)
    
    async def delete(self, endpoint_name: str, **kwargs) -> APIResponse:
        """Make a DELETE request."""



        return await self.request(endpoint_name, **kwargs)
    
    async def get_metrics(self) -> Dict[str, Any]:
        """Get client metrics."""



        return {
            "request_count": self.request_count,
            "error_count": self.error_count,
            "cache_hit_count": self.cache_hit_count,
            "error_rate": self.error_count / max(self.request_count, 1),
            "cache_hit_rate": self.cache_hit_count / max(self.request_count, 1),
            "last_request_time": self.last_request_time
        }
    
    # ================== PRIVATE METHODS ==================
    
    async def _execute_request(self, request: APIRequest) -> APIResponse:
        """Execute an API request with all middleware."""
        request_id = str(uuid.uuid4())
        start_time = time.time()
        
        try:
            # Check cache first
            if request.endpoint.cache_ttl > 0:
                cache_key = self._generate_cache_key(request)
                cached_response = await self.cache.get(cache_key)
                
                if cached_response:
                    self.cache_hit_count += 1
                    cached_response.request_id = request_id
                    return cached_response
            
            # Apply rate limiting
            if request.endpoint.name in self.rate_limiters:
                rate_limiter = self.rate_limiters[request.endpoint.name]
                await rate_limiter.wait_for_token()
            
            # Execute with circuit breaker
            circuit_breaker = self.circuit_breakers[request.endpoint.name]
            response = await circuit_breaker.call(self._make_http_request, request, request_id)
            
            # Cache response if configured
            if request.endpoint.cache_ttl > 0:
                await self.cache.set(cache_key, response, request.endpoint.cache_ttl)
            
            # Update metrics
            self.request_count += 1
            self.last_request_time = time.time()
            
            return response
            
        except Exception as e:
            self.error_count += 1
            logger.error(f"API request failed: {e}", request_id=request_id)
            raise
    
    async def _make_http_request(self, request: APIRequest, request_id: str) -> APIResponse:
        """Make the actual HTTP request."""
        if not self.session:
            raise RuntimeError("Client not initialized")
        
        # Build URL
        url = urljoin(self.base_url, request.endpoint.url)
        
        # Prepare query parameters
        query_params = {**request.endpoint.query_params, **request.query_params}
        if query_params:
            url += "?" + urlencode(query_params)
        
        # Prepare headers
        headers = await self._prepare_headers(request)
        
        # Prepare body
        json_data = None
        data = None
        
        if request.body:
            if request.endpoint.method in [HTTPMethod.POST, HTTPMethod.PUT, HTTPMethod.PATCH]:
                json_data = request.body
        
        # Set timeout
        timeout = request.timeout or request.endpoint.timeout
        
        start_time = time.time()
        
        # Make request with retries
        for attempt in range(request.endpoint.retries + 1):
            try:
                async with self.session.request(
                    method=request.endpoint.method.value,
                    url=url,
                    headers=headers,
                    json=json_data,
                    data=data,
                    timeout=aiohttp.ClientTimeout(total=timeout)
                ) as response:
                    response_time = time.time() - start_time
                    raw_response = await response.read()
                    
                    # Parse response data
                    try:
                        if response.content_type == 'application/json':
                            response_data = await response.json()
                        else:
                            response_data = raw_response.decode('utf-8', errors='ignore')
                    except Exception:
                        response_data = raw_response
                    
                    # Create response object
                    api_response = APIResponse(
                        status_code=response.status,
                        headers=dict(response.headers),
                        data=response_data,
                        raw_response=raw_response,
                        request_id=request_id,
                        response_time=response_time,
                        endpoint_name=request.endpoint.name
                    )
                    
                    # Check for HTTP errors
                    if response.status >= 400:
                        error_msg = f"HTTP {response.status}: {response_data}"
                        raise aiohttp.ClientResponseError(
                            request_info=response.request_info,
                            history=response.history,
                            status=response.status,
                            message=error_msg
                        )
                    
                    return api_response
                    
            except (aiohttp.ClientError, asyncio.TimeoutError) as e:
                if attempt < request.endpoint.retries:
                    wait_time = request.endpoint.retry_delay * (2 ** attempt)
                    logger.warning(f"Request failed, retrying in {wait_time}s: {e}")
                    await asyncio.sleep(wait_time)
                else:
                    raise
    
    async def _prepare_headers(self, request: APIRequest) -> Dict[str, str]:
        """Prepare request headers with authentication."""
        headers = {
            "Content-Type": "application/json",
            **request.endpoint.headers,
            **request.headers
        }
        
        # Add authentication headers
        if request.endpoint.auth_required:
            auth_headers = await self._get_auth_headers()
            headers.update(auth_headers)
        
        # Add custom headers from credentials
        headers.update(self.credentials.custom_headers)
        
        return headers
    
    async def _get_auth_headers(self) -> Dict[str, str]:
        """Get authentication headers based on credentials type."""
        headers = {}
        
        if self.credentials.auth_type == AuthType.API_KEY:
            if self.credentials.api_key:
                headers["X-API-Key"] = self.credentials.api_key
        
        elif self.credentials.auth_type == AuthType.BEARER_TOKEN:
            if self.credentials.access_token:
                headers["Authorization"] = f"Bearer {self.credentials.access_token}"
        
        elif self.credentials.auth_type == AuthType.BASIC_AUTH:
            if self.credentials.username and self.credentials.password:
                import base64
                credentials = base64.b64encode(
                    f"{self.credentials.username}:{self.credentials.password}".encode()
                ).decode()
                headers["Authorization"] = f"Basic {credentials}"
        
        elif self.credentials.auth_type == AuthType.JWT:
            if self.credentials.jwt_secret:
                token = self._generate_jwt_token()
                headers["Authorization"] = f"Bearer {token}"
        
        elif self.credentials.auth_type == AuthType.OAUTH2:
            # Check if token needs refresh
            if self._needs_token_refresh():
                await self._refresh_oauth_token()
            
            if self.credentials.access_token:
                headers["Authorization"] = f"Bearer {self.credentials.access_token}"
        
        return headers
    
    def _generate_cache_key(self, request: APIRequest) -> str:
        """Generate cache key for request."""
        import hashlib
        
        key_data = {
            "endpoint": request.endpoint.name,
            "params": request.params,
            "query_params": request.query_params,
            "body": request.body
        }
        
        key_string = json.dumps(key_data, sort_keys=True)
        return hashlib.md5(key_string.encode()).hexdigest()
    
    def _generate_jwt_token(self) -> str:
        """Generate JWT token for authentication."""
        payload = {
            "iat": time.time(),
            "exp": time.time() + 3600,  # 1 hour expiry
            "iss": "analytics-engine"
        }
        
        return jwt.encode(payload, self.credentials.jwt_secret, algorithm="HS256")
    
    def _needs_token_refresh(self) -> bool:
        """Check if OAuth token needs refresh."""
        if not self.credentials.expires_at:
            return False
        
        # Refresh if expires within 5 minutes
        buffer_time = timedelta(minutes=5)
        return datetime.now() + buffer_time >= self.credentials.expires_at
    
    async def _refresh_oauth_token(self) -> None:
        """Refresh OAuth access token."""
        if not self.credentials.refresh_token:
            raise ValueError("No refresh token available")
        
        # Implementation depends on OAuth provider
        # This is a generic example
        token_url = urljoin(self.base_url, "/oauth/token")
        
        data = {
            "grant_type": "refresh_token",
            "refresh_token": self.credentials.refresh_token,
            "client_id": self.credentials.client_id,
            "client_secret": self.credentials.client_secret
        }
        
        async with self.session.post(token_url, data=data) as response:
            if response.status == 200:
                token_data = await response.json()
                
                self.credentials.access_token = token_data["access_token"]
                if "refresh_token" in token_data:
                    self.credentials.refresh_token = token_data["refresh_token"]
                
                if "expires_in" in token_data:
                    expires_in = token_data["expires_in"]
                    self.credentials.expires_at = datetime.now() + timedelta(seconds=expires_in)
            else:
                raise Exception(f"Failed to refresh token: {response.status}")
    
    async def _refresh_credentials(self) -> None:
        """Refresh credentials if needed."""
        if self.credentials.auth_type == AuthType.OAUTH2:
            if self._needs_token_refresh():
                await self._refresh_oauth_token()


class APIIntegrationManager:
    """
    Manager for multiple external API integrations with
    centralized configuration and monitoring.
    """
    
    def __init__(self):
        self.clients: Dict[str, ExternalAPIClient] = {}
        self.configurations: Dict[str, Dict[str, Any]] = {}
        self.health_status: Dict[str, bool] = {}
        self.last_health_check: Dict[str, datetime] = {}
    
    async def initialize(self) -> None:
        """Initialize all registered API clients."""
        logger.info("Initializing APIIntegrationManager")
        
        for name, client in self.clients.items():
            try:
                await client.initialize()
                self.health_status[name] = True
                logger.info(f"Initialized API client: {name}")
            except Exception as e:
                self.health_status[name] = False
                logger.error(f"Failed to initialize API client {name}: {e}")
    
    async def close(self) -> None:
        """Close all API clients."""
        for client in self.clients.values():
            await client.close()
    
    def register_client(
        self,
        name: str,
        client: ExternalAPIClient,
        config: Dict[str, Any] = None
    ) -> None:
        """Register an API client."""
        self.clients[name] = client
        self.configurations[name] = config or {}
        self.health_status[name] = False
    
    async def get_client(self, name: str) -> ExternalAPIClient:
        """Get API client by name."""
        if name not in self.clients:
            raise ValueError(f"Unknown API client: {name}")
        
        client = self.clients[name]
        
        # Check health status
        if not self.health_status.get(name, False):
            try:
                await client.initialize()
                self.health_status[name] = True
            except Exception as e:
                logger.error(f"Failed to initialize API client {name}: {e}")
                raise
        
        return client
    
    async def health_check(self) -> Dict[str, Dict[str, Any]]:
        """Perform health check on all API clients."""
        results = {}
        
        for name, client in self.clients.items():
            try:
                # Simple connectivity test
                start_time = time.time()
                # This would be a ping endpoint or health check endpoint
                # For now, we'll just check if client is initialized
                
                if client.session and not client.session.closed:
                    response_time = time.time() - start_time
                    status = True
                    error = None
                else:
                    response_time = 0
                    status = False
                    error = "Client not initialized or session closed"
                
                results[name] = {
                    "status": status,
                    "response_time": response_time,
                    "error": error,
                    "last_check": datetime.now().isoformat()
                }
                
                self.health_status[name] = status
                self.last_health_check[name] = datetime.now()
                
            except Exception as e:
                results[name] = {
                    "status": False,
                    "response_time": 0,
                    "error": str(e),
                    "last_check": datetime.now().isoformat()
                }
                
                self.health_status[name] = False
        
        return results
    
    async def get_metrics(self) -> Dict[str, Dict[str, Any]]:
        """Get metrics from all API clients."""
        metrics = {}
        
        for name, client in self.clients.items():
            try:
                client_metrics = await client.get_metrics()
                metrics[name] = client_metrics
            except Exception as e:
                logger.error(f"Failed to get metrics for client {name}: {e}")
                metrics[name] = {"error": str(e)}
        
        return metrics

