    # Security Validators  
    async def _validate_encryption_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate encryption configuration"""
        issues = []
        
        security = config.get('security', {})
        encryption = security.get('encryption', {})
        
        # Check encryption is enabled
        if not encryption.get('providers', {}).get('software', {}).get('enabled', False):
            issues.append(ValidationIssue(
                level=ValidationResult.CRITICAL,
                component="encryption",
                message="Software encryption provider is disabled",
                fix_suggestion="Enable software encryption provider",
                compliance_impact=['GDPR', 'HIPAA', 'PCI_DSS']
            ))
        
        # Check key rotation
        key_mgmt = encryption.get('key_management', {})
        if not key_mgmt.get('rotation', {}).get('enabled', False):
            issues.append(ValidationIssue(
                level=ValidationResult.ERROR,
                component="encryption",
                message="Key rotation is disabled",
                fix_suggestion="Enable automatic key rotation",
                compliance_impact=['PCI_DSS', 'HIPAA']
            ))
        
        # Check key strength
        algorithms = encryption.get('providers', {}).get('software', {}).get('algorithms', [])
        weak_algorithms = ['des', 'md5', 'sha1']
        
        for alg in algorithms:
            if alg.lower() in weak_algorithms:
                issues.append(ValidationIssue(
                    level=ValidationResult.CRITICAL,
                    component="encryption",
                    message=f"Weak encryption algorithm detected: {alg}",
                    fix_suggestion="Use strong encryption algorithms like AES-256-GCM",
                    compliance_impact=['GDPR', 'HIPAA', 'PCI_DSS']
                ))
        
        return issues
    
    async def _validate_authentication_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate authentication configuration"""
        issues = []
        
        access_control = config.get('access_control', {})
        session_mgmt = access_control.get('session_management', {})
        
        # Check MFA requirement
        if not session_mgmt.get('require_mfa', False):
            issues.append(ValidationIssue(
                level=ValidationResult.WARNING,
                component="authentication",
                message="Multi-factor authentication not required",
                fix_suggestion="Enable MFA requirement for enhanced security",
                compliance_impact=['HIPAA', 'PCI_DSS']
            ))
        
        # Check password policy
        password_policy = access_control.get('password_policy', {})
        min_length = password_policy.get('min_length', 0)
        
        if min_length < 12:
            issues.append(ValidationIssue(
                level=ValidationResult.ERROR,
                component="authentication",
                message=f"Password minimum length too short: {min_length}",
                fix_suggestion="Set minimum password length to at least 12 characters",
                compliance_impact=['GDPR', 'HIPAA']
            ))
        
        return issues
    
    async def _validate_authorization_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate authorization configuration"""
        issues = []
        
        access_control = config.get('access_control', {})
        rbac = access_control.get('rbac', {})
        
        # Check default deny
        if not rbac.get('default_deny', True):
            issues.append(ValidationIssue(
                level=ValidationResult.CRITICAL,
                component="authorization",
                message="Default deny policy not enabled",
                fix_suggestion="Enable default deny policy for zero-trust security",
                compliance_impact=['SOX', 'PCI_DSS']
            ))
        
        return issues
    
    async def _validate_network_security(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate network security configuration"""
        issues = []
        
        security = config.get('security', {})
        network = security.get('network_security', {})
        
        # Check firewall configuration
        firewall = network.get('firewall', {})
        if not firewall.get('enabled', False):
            issues.append(ValidationIssue(
                level=ValidationResult.CRITICAL,
                component="network_security",
                message="Firewall is disabled",
                fix_suggestion="Enable firewall protection",
                compliance_impact=['PCI_DSS']
            ))
        
        return issues
    
    async def _validate_secrets_management(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate secrets management configuration"""
        issues = []
        
        # Check for hardcoded secrets in configuration
        config_str = json.dumps(config, default=str).lower()
        
        secret_patterns = [
            r'password\s*[=:]\s*["\']?[^"\'\s]{8,}',
            r'api_?key\s*[=:]\s*["\']?[^"\'\s]{16,}',
            r'secret\s*[=:]\s*["\']?[^"\'\s]{16,}',
            r'token\s*[=:]\s*["\']?[^"\'\s]{16,}'
        ]
        
        for pattern in secret_patterns:
            if re.search(pattern, config_str):
                issues.append(ValidationIssue(
                    level=ValidationResult.CRITICAL,
                    component="secrets_management",
                    message="Potential hardcoded secret detected in configuration",
                    fix_suggestion="Use environment variables or secret management service",
                    compliance_impact=['GDPR', 'HIPAA', 'PCI_DSS', 'SOX']
                ))
                break
        
        return issues
    
    async def _validate_audit_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate audit configuration"""
        issues = []
        
        monitoring = config.get('monitoring', {})
        logging = monitoring.get('logging', {})
        
        # Check audit log retention
        retention = logging.get('retention', {})
        audit_retention = retention.get('audit_logs_days', 0)
        
        if audit_retention < 90:
            issues.append(ValidationIssue(
                level=ValidationResult.ERROR,
                component="audit",
                message=f"Audit log retention too short: {audit_retention} days",
                fix_suggestion="Set audit log retention to at least 90 days",
                compliance_impact=['SOX', 'HIPAA']
            ))
        
        return issues
    
    # Performance Validators
    async def _validate_resource_limits(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate resource limit configurations"""
        issues = []
        
        multi_tenant = config.get('multi_tenant', {})
        limits = multi_tenant.get('tenant_limits', {})
        
        max_users = limits.get('max_users_per_tenant', 0)
        max_storage = limits.get('max_storage_gb', 0)
        
        if max_users == 0:
            issues.append(ValidationIssue(
                level=ValidationResult.WARNING,
                component="performance",
                message="No user limit set per tenant",
                fix_suggestion="Set reasonable user limits to prevent resource exhaustion"
            ))
        
        if max_storage == 0:
            issues.append(ValidationIssue(
                level=ValidationResult.WARNING,
                component="performance",
                message="No storage limit set per tenant",
                fix_suggestion="Set storage limits to prevent disk exhaustion"
            ))
        
        return issues
    
    async def _validate_caching_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate caching configuration"""
        issues = []
        
        performance = config.get('performance', {})
        caching = performance.get('caching', {})
        redis = caching.get('redis', {})
        
        if redis.get('enabled') and redis.get('memory_mb', 0) < 1024:
            issues.append(ValidationIssue(
                level=ValidationResult.WARNING,
                component="performance",
                message="Redis memory allocation too low",
                fix_suggestion="Allocate at least 1GB memory for Redis cache"
            ))
        
        return issues
    
    async def _validate_database_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate database configuration"""
        issues = []
        
        performance = config.get('performance', {})
        database = performance.get('database', {})
        pooling = database.get('connection_pooling', {})
        
        max_connections = pooling.get('max_connections', 0)
        min_connections = pooling.get('min_connections', 0)
        
        if max_connections > 0 and min_connections > max_connections:
            issues.append(ValidationIssue(
                level=ValidationResult.ERROR,
                component="performance",
                message="Minimum connections greater than maximum connections",
                fix_suggestion="Set min_connections <= max_connections"
            ))
        
        return issues
    
    async def _validate_scaling_config(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate auto-scaling configuration"""
        issues = []
        
        performance = config.get('performance', {})
        scaling = performance.get('auto_scaling', {})
        
        if scaling.get('enabled'):
            min_instances = scaling.get('min_instances', 0)
            max_instances = scaling.get('max_instances', 0)
            
            if min_instances >= max_instances:
                issues.append(ValidationIssue(
                    level=ValidationResult.ERROR,
                    component="performance",
                    message="Minimum instances >= maximum instances",
                    fix_suggestion="Set min_instances < max_instances"
                ))
        
        return issues
    
    # Compliance Validators
    async def _validate_gdpr_compliance(self, config: Dict[str, Any]) -> List[ValidationIssue]:
        """Validate GDPR compliance"""
        issues = []
        
        compliance = config.get('compliance', {})
        gdpr = compliance.get('gdpr', {})
        
        if gdpr.get('enabled'):
            # Check data protection measures
            data_protection = gdpr.get('data_protection', {})
            
            if not data_protection.get('encryption_at_rest'):
                issues.append(ValidationIssue(
                    level=ValidationResult.CRITICAL,
                    component="gdpr_compliance",
                    message="GDPR requires encryption at rest",
                    fix_suggestion="Enable encryption at rest for GDPR compliance",
                    compliance_impact=['GDPR']
                ))
            
            # Check user rights implementation
            user_rights = gdpr.get('user_rights', {})
