    def _calculate_overall_status(self, issues: List[ValidationIssue]) -> ValidationResult:
        """Calculate overall validation status"""
        if not issues:
            return ValidationResult.PASS
        
        # Check for critical issues
        if any(issue.level == ValidationResult.CRITICAL for issue in issues):
            return ValidationResult.CRITICAL
        
        # Check for error issues
        if any(issue.level == ValidationResult.ERROR for issue in issues):
            return ValidationResult.ERROR
        
        # Check for warnings
        if any(issue.level == ValidationResult.WARNING for issue in issues):
            return ValidationResult.WARNING
        
        return ValidationResult.PASS
    
    def _generate_compliance_status(self, config: Dict[str, Any], issues: List[ValidationIssue]) -> Dict[str, bool]:
        """Generate compliance status summary"""
        compliance_standards = ['GDPR', 'HIPAA', 'PCI_DSS', 'SOX']
        status = {}
        
        for standard in compliance_standards:
            # Check if compliance is enabled
            compliance_config = config.get('compliance', {})
            standard_config = compliance_config.get(standard.lower(), {})
            enabled = standard_config.get('enabled', False)
            
            if not enabled:
                status[standard] = True  # N/A - not enabled
                continue
            
            # Check for compliance-related issues
            compliance_issues = [
                issue for issue in issues 
                if issue.compliance_impact and standard in issue.compliance_impact
                and issue.level in [ValidationResult.ERROR, ValidationResult.CRITICAL]
            ]
            
            status[standard] = len(compliance_issues) == 0
        
        return status
    
    def _generate_recommendations(self, issues: List[ValidationIssue], config: Dict[str, Any]) -> List[str]:
        """Generate configuration improvement recommendations"""
        recommendations = []
        
        # Add fix suggestions from issues
        for issue in issues:
            if issue.fix_suggestion and issue.fix_suggestion not in recommendations:
                recommendations.append(issue.fix_suggestion)
        
        # Add general recommendations based on configuration
        if not config.get('security', {}).get('encryption', {}).get('providers', {}).get('hsm', {}).get('enabled'):
            recommendations.append("Consider enabling HSM for production environments")
        
        if not config.get('monitoring', {}).get('threat_detection', {}).get('ml_enabled'):
            recommendations.append("Enable ML-powered threat detection for advanced security")
        
        return recommendations[:10]  # Limit to top 10 recommendations

