# Validation report exporters
class ValidationReportExporter:
    """Export validation reports in various formats"""
    
    @staticmethod
    def export_to_json(report: ValidationReport, file_path: str) -> None:
        """Export report as JSON"""
        report_dict = {
            'config_path': report.config_path,
            'validation_time': report.validation_time.isoformat(),
            'validation_level': report.validation_level.value,
            'overall_status': report.overall_status.value,
            'issues': [
                {
                    'level': issue.level.value,
                    'component': issue.component,
                    'message': issue.message,
                    'details': issue.details,
                    'fix_suggestion': issue.fix_suggestion,
                    'compliance_impact': issue.compliance_impact
                }
                for issue in report.issues
            ],
            'performance_metrics': report.performance_metrics,
            'compliance_status': report.compliance_status,
            'recommendations': report.recommendations
        }
        
        with open(file_path, 'w') as f:
            json.dump(report_dict, f, indent=2)
    
    @staticmethod
    def export_to_html(report: ValidationReport, file_path: str) -> None:
        """Export report as HTML"""
        html_content = f"""
        <!DOCTYPE html>
        <html>
        <head>
            <title>Configuration Validation Report</title>
            <style>
                body {{ font-family: Arial, sans-serif; margin: 20px; }}
                .status-pass {{ color: green; }}
                .status-warning {{ color: orange; }}
                .status-error {{ color: red; }}
                .status-critical {{ color: darkred; font-weight: bold; }}
                .issue {{ margin: 10px 0; padding: 10px; border-left: 4px solid #ccc; }}
                .issue.warning {{ border-color: orange; }}
                .issue.error {{ border-color: red; }}
                .issue.critical {{ border-color: darkred; }}
            </style>
        </head>
        <body>
            <h1>Configuration Validation Report</h1>
            <p><strong>Configuration:</strong> {report.config_path}</p>
            <p><strong>Validation Time:</strong> {report.validation_time}</p>
            <p><strong>Overall Status:</strong> <span class="status-{report.overall_status.value}">{report.overall_status.value.upper()}</span></p>
            
            <h2>Issues ({len(report.issues)})</h2>
            {''.join([f'<div class="issue {issue.level.value}"><strong>{issue.component}:</strong> {issue.message}</div>' for issue in report.issues])}
            
            <h2>Compliance Status</h2>
            {''.join([f'<p><strong>{standard}:</strong> {" Compliant" if status else " Non-compliant"}</p>' for standard, status in report.compliance_status.items()])}
            
            <h2>Recommendations</h2>
            <ul>{''.join([f'<li>{rec}</li>' for rec in report.recommendations])}</ul>
        </body>
        </html>
        """
        
        with open(file_path, 'w') as f:
            f.write(html_content)

