"""
Unified Template Validator - Validateur Unifié (DÉDUPLICUÉ)
==========================================================

Validateur unifié fusionnant template_validator.py + validator.py
pour éliminer les doublons et créer une validation centralisée.

 DÉDUPLICATION: Fusion de 2 validateurs similaires  
 OPTIMISATION: Validation unifiée et performante
 SÉCURITÉ: Règles de sécurité consolidées

Features:
- Validation syntaxique et sémantique
- Validation de sécurité avancée  
- Support multi-format (Slack, Email, Webhook)
- Règles personnalisées par tenant
- Rapports détaillés avec suggestions

Author: Expert Validation Architecture Team
Version: 2.0.0-unified
"""

import json
import re
import logging
from typing import Dict, Any, List, Optional, Set, Tuple
from datetime import datetime
from dataclasses import dataclass
from enum import Enum
import jsonschema
from jsonschema import validate, ValidationError
import bleach
from urllib.parse import urlparse

logger = logging.getLogger(__name__)

# =============================================================================
# ENUMS ET TYPES (UNIFIÉS)
# =============================================================================

class ValidationLevel(Enum):
    """Niveaux de validation."""
    ERROR = "error"
    WARNING = "warning"
    INFO = "info"


class SecurityLevel(Enum):
    """Niveaux de sécurité."""
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class ValidationType(Enum):
    """Types de validation."""
    SYNTAX = "syntax"
    SEMANTIC = "semantic"
    SECURITY = "security"
    PERFORMANCE = "performance"
    BUSINESS = "business"


@dataclass
class ValidationResult:
    """Résultat unifié de validation."""
    is_valid: bool
    errors: List[str]
    warnings: List[str]
    suggestions: List[str]
    security_issues: List[str]
    performance_warnings: List[str]
    validation_score: float = 0.0
    
    def add_error(self, message: str, validation_type: ValidationType = ValidationType.SYNTAX):
        """Ajoute une erreur."""
        self.errors.append(f"[{validation_type.value.upper()}] {message}")
        self.is_valid = False
    
    def add_warning(self, message: str, validation_type: ValidationType = ValidationType.SYNTAX):
        """Ajoute un avertissement."""
        self.warnings.append(f"[{validation_type.value.upper()}] {message}")
    
    def add_security_issue(self, message: str, severity: SecurityLevel = SecurityLevel.MEDIUM):
        """Ajoute un problème de sécurité."""
        self.security_issues.append(f"[{severity.value.upper()}] {message}")
        if severity in [SecurityLevel.HIGH, SecurityLevel.CRITICAL]:
            self.is_valid = False


# =============================================================================
# VALIDATEUR UNIFIÉ
# =============================================================================

class UnifiedTemplateValidator:
    """
    Validateur de templates unifié enterprise.
    
    Fusion intelligente de tous les validateurs pour:
    - Éliminer les doublons de validation
    - Centraliser les règles de sécurité
    - Optimiser les performances
    - Supporter tous les formats
    """
    
    def __init__(self, security_level: SecurityLevel = SecurityLevel.MEDIUM):
        self.security_level = security_level
        self.validation_rules = {}
        self.security_rules = {}
        self.custom_validators = {}
        
        # Initialisation des règles par défaut
        self._setup_default_rules()
        self._setup_security_rules()
        
        logger.info(f"UnifiedTemplateValidator initialized with security_level: {security_level}")
    
    def validate_template(
        self,
        template_content: str,
        template_type: str = "slack",
        validation_types: List[ValidationType] = None
    ) -> ValidationResult:
        """Valide un template avec tous les types de validation."""
        if validation_types is None:
            validation_types = [
                ValidationType.SYNTAX,
                ValidationType.SEMANTIC,
                ValidationType.SECURITY
            ]
        
        result = ValidationResult(is_valid=True, errors=[], warnings=[], 
                                suggestions=[], security_issues=[], performance_warnings=[])
        
        # Validation syntaxique
        if ValidationType.SYNTAX in validation_types:
            self._validate_syntax(template_content, template_type, result)
        
        # Validation sémantique
        if ValidationType.SEMANTIC in validation_types:
            self._validate_semantics(template_content, template_type, result)
        
        # Validation de sécurité
        if ValidationType.SECURITY in validation_types:
            self._validate_security(template_content, result)
        
        # Validation de performance
        if ValidationType.PERFORMANCE in validation_types:
            self._validate_performance(template_content, result)
        
        # Validation business
        if ValidationType.BUSINESS in validation_types:
            self._validate_business_rules(template_content, template_type, result)
        
        # Calculer le score de validation
        result.validation_score = self._calculate_validation_score(result)
        
        return result
    
    def validate_template_data(self, data: Dict[str, Any], schema_name: str = None) -> ValidationResult:
        """Valide les données d'un template."""
        result = ValidationResult(is_valid=True, errors=[], warnings=[],
                                suggestions=[], security_issues=[], performance_warnings=[])
        
        # Validation basique des données
        if not isinstance(data, dict):
            result.add_error("Template data must be a dictionary", ValidationType.SYNTAX)
            return result
        
        # Validation avec schéma si fourni
        if schema_name and schema_name in self.validation_rules:
            try:
                schema = self.validation_rules[schema_name]
                jsonschema.validate(data, schema)
            except ValidationError as e:
                result.add_error(f"Schema validation failed: {e.message}", ValidationType.SEMANTIC)
        
        # Validation de sécurité des données
        self._validate_data_security(data, result)
        
        return result
    
    def register_custom_validator(
        self,
        name: str,
        validator_func: callable,
        validation_type: ValidationType = ValidationType.BUSINESS
    ):
        """Enregistre un validateur personnalisé."""
        self.custom_validators[name] = {
            'func': validator_func,
            'type': validation_type
        }
    
    def add_validation_rule(self, rule_name: str, rule_schema: Dict[str, Any]):
        """Ajoute une règle de validation."""
        self.validation_rules[rule_name] = rule_schema
    
    def add_security_rule(self, rule_name: str, rule_func: callable):
        """Ajoute une règle de sécurité."""
        self.security_rules[rule_name] = rule_func
    
    # =============================================================================
    # MÉTHODES DE VALIDATION PRIVÉES
    # =============================================================================
    
    def _validate_syntax(self, content: str, template_type: str, result: ValidationResult):
        """Validation syntaxique."""



        try:
            # Validation JSON si applicable
            if template_type in ['slack', 'webhook']:
                json.loads(content)
        except json.JSONDecodeError as e:
            result.add_error(f"Invalid JSON syntax: {e}", ValidationType.SYNTAX)
        
        # Validation de la longueur
        if len(content) > 10000:
            result.add_warning("Template content is very long (>10KB)", ValidationType.PERFORMANCE)
    
    def _validate_semantics(self, content: str, template_type: str, result: ValidationResult):
        """Validation sémantique."""
        # Vérifier les variables non définies
        undefined_vars = re.findall(r'\{\{\s*(\w+)\s*\}\}', content)
        if undefined_vars:
            result.add_warning(f"Potentially undefined variables: {', '.join(set(undefined_vars))}", 
                             ValidationType.SEMANTIC)
        
        # Validation spécifique au type
        if template_type == 'slack':
            self._validate_slack_semantics(content, result)
        elif template_type == 'email':
            self._validate_email_semantics(content, result)
    
    def _validate_security(self, content: str, result: ValidationResult):
        """Validation de sécurité."""
        # Détection d'injection de scripts
        script_patterns = [
            r'<script[^>]*>.*?</script>',
            r'javascript:',
            r'on\w+\s*=',
            r'eval\s*\(',
            r'setTimeout\s*\(',
            r'setInterval\s*\('
        ]
        
        for pattern in script_patterns:
            if re.search(pattern, content, re.IGNORECASE | re.DOTALL):
                result.add_security_issue("Potential script injection detected", SecurityLevel.HIGH)
        
        # Détection d'URLs suspicieuses
        urls = re.findall(r'https?://[^\s<>"]+', content)
        for url in urls:
            if not self._is_safe_url(url):
                result.add_security_issue(f"Suspicious URL detected: {url}", SecurityLevel.MEDIUM)
        
        # Vérification du niveau de sécurité
        if self.security_level == SecurityLevel.CRITICAL:
            self._apply_critical_security_checks(content, result)
    
    def _validate_performance(self, content: str, result: ValidationResult):
        """Validation de performance."""
        # Vérifier la complexité du template
        complexity_score = len(re.findall(r'\{[%{].*?[%}]\}', content))
        if complexity_score > 50:
            result.add_warning("Template has high complexity (>50 expressions)", 
                             ValidationType.PERFORMANCE)
        
        # Vérifier les boucles potentiellement coûteuses
        loops = re.findall(r'\{\%\s*for\s+.*?\%\}', content)
        if len(loops) > 5:
            result.add_warning("Template has many loops (>5), consider optimization", 
                             ValidationType.PERFORMANCE)
    
    def _validate_business_rules(self, content: str, template_type: str, result: ValidationResult):
        """Validation des règles business."""
        # Appliquer les validateurs personnalisés
        for name, validator in self.custom_validators.items():
            try:
                is_valid, message = validator['func'](content, template_type)
                if not is_valid:
                    if validator['type'] == ValidationType.BUSINESS:
                        result.add_error(f"Business rule '{name}': {message}", ValidationType.BUSINESS)
                    else:
                        result.add_warning(f"Custom rule '{name}': {message}", validator['type'])
            except Exception as e:
                result.add_warning(f"Custom validator '{name}' failed: {e}", ValidationType.BUSINESS)
    
    def _validate_slack_semantics(self, content: str, result: ValidationResult):
        """Validation sémantique spécifique à Slack."""



        try:
            data = json.loads(content)
            
            # Vérifier les champs requis pour Slack
            if 'text' not in data and 'blocks' not in data and 'attachments' not in data:
                result.add_error("Slack template must have 'text', 'blocks', or 'attachments'", 
                               ValidationType.SEMANTIC)
            
            # Vérifier la longueur du texte
            if 'text' in data and len(data['text']) > 4000:
                result.add_warning("Slack text message is too long (>4000 chars)", 
                                 ValidationType.SEMANTIC)
                
        except json.JSONDecodeError:
            pass  # Déjà géré dans la validation syntaxique
    
    def _validate_email_semantics(self, content: str, result: ValidationResult):
        """Validation sémantique spécifique aux emails."""
        # Vérifier la présence d'un sujet
        if 'subject' not in content.lower():
            result.add_warning("Email template should include a subject", ValidationType.SEMANTIC)
    
    def _validate_data_security(self, data: Dict[str, Any], result: ValidationResult):
        """Validation de sécurité des données."""
        for key, value in data.items():
            if isinstance(value, str):
                # Vérifier les patterns dangereux
                if any(pattern in value.lower() for pattern in ['<script', 'javascript:', 'eval(']):
                    result.add_security_issue(f"Dangerous content in field '{key}'", SecurityLevel.HIGH)
            elif isinstance(value, dict):
                self._validate_data_security(value, result)
    
    def _is_safe_url(self, url: str) -> bool:
        """Vérifie si une URL est sûre."""



        try:
            parsed = urlparse(url)
            # Vérifier le domaine
            dangerous_domains = ['malware.com', 'phishing.net']  # Liste à étendre
            return parsed.netloc.lower() not in dangerous_domains
        except Exception:
            return False
    
    def _apply_critical_security_checks(self, content: str, result: ValidationResult):
        """Applique les vérifications de sécurité critiques."""
        # Vérifications supplémentaires pour niveau critique
        if len(content) > 100000:  # 100KB
            result.add_security_issue("Template content exceeds critical size limit", 
                                    SecurityLevel.CRITICAL)
    
    def _calculate_validation_score(self, result: ValidationResult) -> float:
        """Calcule un score de validation (0-100)."""
        score = 100.0
        
        # Pénalités pour les erreurs
        score -= len(result.errors) * 20
        score -= len(result.warnings) * 5
        score -= len(result.security_issues) * 15
        score -= len(result.performance_warnings) * 3
        
        return max(0.0, score)
    
    def _setup_default_rules(self):
        """Configure les règles de validation par défaut."""
        # Schéma Slack basique
